window.BASAIR_QUESTIONS=(window.BASAIR_QUESTIONS||[]).concat([{"id":"s41-2","number":2,"surah":41,"verses":[1],"references":[{"surah":41,"verses":[1]}],"verseLabel":"عنوان السورة","question":"ما دلالة تسمية السورة أيضًا بـ«حم السجدة»؟","answer":"يجمع الاسم بين افتتاحها بـ﴿حم﴾ وموضع السجدة فيها، فيميزها من سائر السور المفتتحة بالحرفين. ويصل ذكر السجدة اسم السورة بمشهد الخضوع لله الذي تقابله مواقف المعرضين عن آياته.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص108–109، تحت عنوان «أسماء السورة ومناسبة تسميتها»","url":""}]},{"id":"s41-3","number":3,"surah":41,"verses":[1],"references":[{"surah":41,"verses":[1]}],"verseLabel":"بناء السورة","question":"ما الخصيصة الأسلوبية في تكرر الحديث عن السآمة في سورة فصلت؟","answer":"تكرر الحديث عن السآمة في موضعين من السورة، وهو تكرار يرتبط بمحورها في كشف حال الإنسان حين يعرض عن الهدى أو يملّ؛ فيلفت القارئ إلى أثر الاستجابة للوحي في علاج هذا الاضطراب.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص113، تحت عنوان «الخصائص الأسلوبية لسورة فصلت»","url":""}]},{"id":"s41-4","number":4,"surah":41,"verses":[1,2,3],"references":[{"surah":41,"verses":[1,2,3]}],"verseLabel":"فصلت: 1–3","question":"ماذا يفيد التعبير بالمصدر ﴿تَنْزِيلٌ﴾ في مطلع سورة فصلت؟","answer":"يجعل التنزيل كأنه حقيقة قائمة بذاتها مشحونة بالعظمة، ويؤكد أن القرآن منزل من الرحمن الرحيم؛ فتجتمع في اللفظ مهابة الوحي وصدق مصدره ورحمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص118، تحت عنوان «دلالة التعبير بالمصدر ﴿تنزيل﴾»","url":""}]},{"id":"s41-5","number":5,"surah":41,"verses":[2],"references":[{"surah":41,"verses":[2]}],"verseLabel":"فصلت: 2","question":"لماذا خُصَّ الاسمان ﴿الرَّحْمَنِ الرَّحِيمِ﴾ بالذكر عند الحديث عن تنزيل القرآن؟","answer":"لأن إنزال القرآن من أعظم آثار رحمة الله: به يخرج الناس من ظلمات الجهل والضلال إلى نور الهداية، فناسب أن يُنسب التنزيل إلى الاسمين الدالين على الرحمة العامة والخاصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص122، تحت عنوان «توجيه تخصيص صفتي ﴿الرحمن الرحيم﴾ بالذكر»","url":""}]},{"id":"s41-6","number":6,"surah":41,"verses":[3],"references":[{"surah":41,"verses":[3]}],"verseLabel":"فصلت: 3","question":"ما سر اختيار ﴿فُصِّلَتْ آيَاتُهُ﴾ بدل «بُيّنت آياته»؟","answer":"التفصيل يزيد على أصل البيان بإظهار تميز المعاني والأحكام وترتيبها في مقاطع واضحة؛ فالآيات تبين القصص والمواعظ والتشريع دون اختلاط. وفي الصيغة معنى الإحكام وإعطاء كل معنى موضعه، فيجتمع وضوح الدلالة وحسن التنظيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص124–125، تحت عنوان «بلاغة اختيار مفردة ﴿فصلت﴾ دون (بينت)»","url":""}]},{"id":"s41-7","number":7,"surah":41,"verses":[3],"references":[{"surah":41,"verses":[3]}],"verseLabel":"فصلت: 3","question":"لماذا جمع القرآن بين وصفه بأنه ﴿كِتَابٌ﴾ وأنه ﴿قُرْآنًا﴾؟","answer":"للدلالة على أنه محفوظ بطريقين متكاملين: مكتوب في السطور بوصفه كتابًا، ومتلوّ محفوظ في الصدور بوصفه قرآنًا؛ فتتآزر الكتابة والقراءة في حفظه وتبليغه.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص123، تحت عنوان «بلاغة الجمع بين لفظي ﴿كتاب﴾ و﴿قرآنًا﴾»","url":""}]},{"id":"s41-8","number":8,"surah":41,"verses":[3],"references":[{"surah":41,"verses":[3]}],"verseLabel":"فصلت: 3","question":"ماذا تضيف صيغة المضارع في قوله ﴿لِقَوْمٍ يَعْلَمُونَ﴾؟","answer":"تصور العلم صفة متجددة مستمرة فيهم، وتفتح باب الانتفاع لكل من يدخل في طريق التعلم والتدبر، لا لفئة انقضى علمها في زمن مضى.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص128، تحت عنوان «نكتة التعبير بصيغة المضارع ﴿يعلمون﴾»","url":""}]},{"id":"s41-9","number":9,"surah":41,"verses":[4],"references":[{"surah":41,"verses":[4]}],"verseLabel":"فصلت: 4","question":"لماذا قُدّمت البشارة على النذارة في وصف القرآن ﴿بَشِيرًا وَنَذِيرًا﴾؟","answer":"لأن القرآن وُصف بأنه تنزيل من الرحمن الرحيم؛ فناسب مقتضى الرحمة أن تُفتح البشارة أولًا لترغيب العباد، ثم يأتي الإنذار لمن أعرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص130–131، تحت عنوان «نكتة تقديم ﴿بشيرًا﴾ على ﴿نذيرًا﴾»","url":""}]},{"id":"s41-10","number":10,"surah":41,"verses":[4],"references":[{"surah":41,"verses":[4]}],"verseLabel":"فصلت: 4","question":"ما دلالة قوله ﴿فَأَعْرَضَ أَكْثَرُهُمْ﴾ دون تعميم الإعراض عليهم جميعًا؟","answer":"يقيد الحكم بالأكثر فيثبت أن الإعراض لم يشمل الجميع، ويحفظ للمؤمنين موقعهم وإن قل عددهم. كما يمنع الاغترار بالكثرة؛ فقد يكون الحق مع القلة، فلا يجعل كثرة المعرضين دليلًا على صحة موقفهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص132–133، تحت عنوان «دلالة التعبير بلفظ (أكثر)»","url":""}]},{"id":"s41-11","number":11,"surah":41,"verses":[4],"references":[{"surah":41,"verses":[4]}],"verseLabel":"فصلت: 4","question":"كيف نُفي السماع عن المعرضين في ﴿فَهُمْ لَا يَسْمَعُونَ﴾ مع سلامة آذانهم؟","answer":"نُفي عنهم سماع الانتفاع والقبول، لا وصول الصوت؛ لأنهم عطّلوا ثمرة السمع حتى صاروا كمن لا يسمع، وفي ذلك توبيخ لهم على الإعراض.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص134، تحت عنوان «بلاغة الكناية ودلالتها»","url":""}]},{"id":"s41-12","number":12,"surah":41,"verses":[5],"references":[{"surah":41,"verses":[5]}],"verseLabel":"فصلت: 5","question":"لماذا رتّب المعرضون موانعهم من أكنّة القلوب إلى وقر الآذان ثم الحجاب؟","answer":"رتبوها بحسب طريق وصول الوحي: القلب محل الفهم، والأذن سبيل الاستماع، والحجاب يمنع المواجهة والرؤية؛ فزعموا انسداد منافذ الإدراك كلها ليبالغوا في إعلان القطيعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص146–147، تحت عنوان «براعة ترتيب ذكر القلوب فالأسماع فالأبصار»","url":""}]},{"id":"s41-13","number":13,"surah":41,"verses":[5],"references":[{"surah":41,"verses":[5]}],"verseLabel":"فصلت: 5","question":"ما دلالة قول المعرضين ﴿فَاعْمَلْ﴾ بعد دعوى الحجاب بينهم وبين الرسول ﷺ؟","answer":"ليس أمرًا حقيقيًا، بل تهديد وتخلية: امضِ في دعوتك فسنبقى على طريقنا ونقابلك بالرفض، وفيه إعلان العناد بدل طلب البرهان.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص148، تحت عنوان «غرض الأمر ومقصده الدلالي»","url":""}]},{"id":"s41-123","number":123,"surah":41,"verses":[5],"references":[{"surah":41,"verses":[5]}],"verseLabel":"فصلت: 5","question":"لماذا أكّد المعرضون قولهم ﴿إِنَّنَا عَامِلُونَ﴾؟","answer":"ليظهروا شدة إصرارهم وثباتهم على موقفهم، وليجعلوا الجملة تحديًا في مقابلة دعوة الرسول ﷺ، لا مجرد إخبار عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص149، تحت عنوان «بلاغة توكيد الخبر»","url":""}]},{"id":"s41-14","number":14,"surah":41,"verses":[6],"references":[{"surah":41,"verses":[6]}],"verseLabel":"فصلت: 6","question":"ما الذي يحترز منه قوله بعد إثبات البشرية ﴿يُوحَى إِلَيَّ﴾؟","answer":"يمنع أن تُفهم المماثلة على الإطلاق؛ فهو يماثلهم في جنس البشرية، لكنه اختص عنهم بالوحي والرسالة، فتثبت البشرية من غير أن تُلغى منزلته النبوية.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص155–156، تحت عنوان «بلاغة الاحتراس بالوصف»","url":""}]},{"id":"s41-15","number":15,"surah":41,"verses":[6],"references":[{"surah":41,"verses":[6]}],"verseLabel":"فصلت: 6","question":"لماذا فُرّع الأمر ﴿فَاسْتَقِيمُوا إِلَيْهِ﴾ على تقرير وحدانية الله؟","answer":"لأن الإقرار بإله واحد يقتضي توجيه العبادة والقصد إليه وحده؛ فجاءت الفاء لتجعل الاستقامة أثرًا عمليًا مباشرًا للتوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص157–158، تحت عنوان «نوع الفاء ودلالتها»","url":""}]},{"id":"s41-16","number":16,"surah":41,"verses":[6],"references":[{"surah":41,"verses":[6]}],"verseLabel":"فصلت: 6","question":"لماذا عُطف الاستغفار على الاستقامة في ﴿فَاسْتَقِيمُوا إِلَيْهِ وَاسْتَغْفِرُوهُ﴾؟","answer":"لأن الاستقامة تصلح الطريق المقبل، والاستغفار يمحو تقصير الماضي وما يعرض في السير من زلل؛ فجمع الأمران بين الثبات على الحق وتنقية آثاره مما يشوبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص159، تحت عنوان «دلالة عطف الاستغفار على الاستقامة»","url":""}]},{"id":"s41-17","number":17,"surah":41,"verses":[7],"references":[{"surah":41,"verses":[7]}],"verseLabel":"فصلت: 7","question":"لماذا قُرن منع الزكاة بالكفر بالآخرة في وصف المشركين؟","answer":"لأن الإيمان بالجزاء هو الذي يدفع إلى البذل ومراقبة حق الله في المال؛ فمن جحد الآخرة هان عليه الشح ومنع الحقوق، فجمع الوصفان بين فساد الاعتقاد وأثره في السلوك.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص163، تحت عنوان «نكتة قرن منع الزكاة بالكفر بالآخرة»","url":""}]},{"id":"s41-18","number":18,"surah":41,"verses":[7],"references":[{"surah":41,"verses":[7]}],"verseLabel":"فصلت: 7","question":"ما فائدة تكرار ضمير ﴿هُمْ﴾ في ﴿وَهُمْ بِالْآخِرَةِ هُمْ كَافِرُونَ﴾؟","answer":"يقوي الحكم ويؤكد ذمهم، ويبرز شدة تعنتهم واختصاصهم الراسخ بالكفر بالآخرة؛ فكأن الوصف صار سمة ثابتة لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص164، تحت عنوان «فائدة استعمال ضمير ﴿هم﴾ وتكراره»","url":""}]},{"id":"s41-19","number":19,"surah":41,"verses":[8],"references":[{"surah":41,"verses":[8]}],"verseLabel":"فصلت: 8","question":"ما سر وصف أجر المؤمنين بأنه ﴿غَيْرُ مَمْنُونٍ﴾؟","answer":"على التوجيه الذي يربط المن بالأذى في العطاء، يصف الأجر بأنه خال من الإذلال والتكدير. فالمؤمنون ينالون جزاءً يكرمهم، وتأتي العبارة في سياق ذم البخل لتقابل عطاء الناس الذي قد يصحبه المن بعطاء الله المكرم لعباده.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص171، تحت عنوان «بلاغة ذكر مفردة ﴿ممنون﴾»","url":""}]},{"id":"s41-20","number":20,"surah":41,"verses":[9],"references":[{"surah":41,"verses":[9]}],"verseLabel":"فصلت: 9","question":"ما أثر اجتماع الاستفهام والتوكيد في قوله ﴿أَئِنَّكُمْ لَتَكْفُرُونَ﴾؟","answer":"يجعل الاستفهام إنكارًا وتعجيبًا من كفرهم، ثم يأتي التوكيد لا لتقوية خبر محتمل بل لتثبيت الفعل الشنيع الذي يُوبَّخون عليه؛ فكأن وقوعه مع وضوح دلائل الخالق أمر لا يكاد يُصدَّق.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص175، تحت عنوان «دلالة التوكيد ونكتة إدخال الاستفهام عليه»","url":""}]},{"id":"s41-21","number":21,"surah":41,"verses":[9],"references":[{"surah":41,"verses":[9]}],"verseLabel":"فصلت: 9","question":"لماذا بدأ تفصيل الخلق بذكر الأرض قبل السماء؟","answer":"لأن الأرض أقرب إلى الإنسان وأظهر اتصالًا بمعاشه، فبدئ بالدليل المحسوس الذي يشاهده المخاطبون ثم ارتقي إلى خلق السماء، فتكون الحجة أقرب إلى إدراكهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص177، تحت عنوان «علة تقديم ذكر خلق الأرض»","url":""}]},{"id":"s41-124","number":124,"surah":41,"verses":[9],"references":[{"surah":41,"verses":[9]}],"verseLabel":"فصلت: 9","question":"ما الذي توحي به عبارة ﴿خَلَقَ الْأَرْضَ فِي يَوْمَيْنِ﴾ مع قدرة الله على خلقها في لحظة؟","answer":"تدل على أن الخلق جرى بتقدير وحكمة وتدرج، لا لعجز أو احتياج إلى زمن؛ فذكر اليومين يعلّم أن الإحكام قد يظهر في ترتيب الأسباب والمراحل.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص178، تحت عنوان «بلاغة الكناية في الظرف»","url":""}]},{"id":"s41-22","number":22,"surah":41,"verses":[10],"references":[{"surah":41,"verses":[10]}],"verseLabel":"فصلت: 10","question":"ما سر التعبير بالجعل مع الرواسي وبالخلق مع الأرض؟","answer":"الخلق يدل هنا على إنشاء الأرض، والجعل على تهيئة ما فيها وتحويله إلى هيئة تحقق الغرض منه. فاختير الجعل للرواسي لأنها تفصيل في إعداد الأرض لوظيفتها بعد ذكر أصل خلقها.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص184–185، تحت عنوان «نكتة استعمال الجعل دون الخلق»","url":""}]},{"id":"s41-23","number":23,"surah":41,"verses":[10],"references":[{"surah":41,"verses":[10]}],"verseLabel":"فصلت: 10","question":"ما دلالة التصريح بأن الرواسي جُعلت ﴿مِنْ فَوْقِهَا﴾ مع أن ذلك مشاهد؟","answer":"لا يكتفي التعبير بإثبات الجبال، بل يصور ارتفاعها ظاهرًا فوق الأرض. وحرف ﴿من﴾ يستحضر ابتداء هذا العلو منها، فيلفت النظر إلى هيئة الرواسي المشاهدة بوصفها مظهرًا من مظاهر القدرة والنعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص186، تحت عنوان «براعة دخول حرف ﴿من﴾ على الظرف»","url":""}]},{"id":"s41-24","number":24,"surah":41,"verses":[10],"references":[{"surah":41,"verses":[10]}],"verseLabel":"فصلت: 10","question":"لماذا قُدّمت البركة في الأرض على تقدير أقواتها؟","answer":"لأن البركة أصل عام لنماء الخيرات واستمرارها، ثم جاء تقدير الأقوات أثرًا مفصلًا من آثارها؛ فقدم الأساس الشامل قبل ما يتفرع عنه من أرزاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص186، تحت عنوان «دلالة تقديم ذكر البركة على تقدير الأقوات»","url":""}]},{"id":"s41-125","number":125,"surah":41,"verses":[10],"references":[{"surah":41,"verses":[10]}],"verseLabel":"فصلت: 10","question":"ماذا تضيف كلمة ﴿قَدَّرَ﴾ في قوله ﴿وَقَدَّرَ فِيهَا أَقْوَاتَهَا﴾؟","answer":"تفيد أن الأقوات وُزعت بمقادير محسوبة تفي بحاجات المخلوقات، فلا تجري الأرزاق عبثًا بل وفق علم وتدبير وإحكام.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص187، تحت عنوان «دلالة استعمال مفردة ﴿قدّر﴾»","url":""}]},{"id":"s41-25","number":25,"surah":41,"verses":[9,10],"references":[{"surah":41,"verses":[9,10]}],"verseLabel":"فصلت: 9–10","question":"ما سر التعبير بأربعة أيام في تقدير الأقوات مع سبق ذكر خلق الأرض في يومين؟","answer":"الأربعة إجمال للمدة كلها، يدخل فيها اليومان المذكوران أولًا، وليست أربعة مضافة إليهما. وهذه فذلكة تجمع المراحل بعد تفصيل بعضها، ويدل عليها اتصال أعمال التهيئة بخلق الأرض وإتمام العدد.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص190–191، تحت عنوان «بلاغة الفذلكة ودلالتها»","url":""}]},{"id":"s41-26","number":26,"surah":41,"verses":[10],"references":[{"surah":41,"verses":[10]}],"verseLabel":"فصلت: 10","question":"ماذا تفيد كلمة ﴿سَوَاءً﴾ بعد ذكر خلق الأرض وتقدير أقواتها؟","answer":"تفيد تمام الأيام الأربعة واستواءها بلا زيادة ولا نقص: يومان لخلق الأرض ويومان لتقدير ما فيها، فتزيل توهم أن الأزمنة المذكورة متراكمة إلى أكثر من ذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص191، تحت عنوان «دلالة لفظ ﴿سواء﴾»","url":""}]},{"id":"s41-126","number":126,"surah":41,"verses":[10],"references":[{"surah":41,"verses":[10]}],"verseLabel":"فصلت: 10","question":"لماذا خُتم تقدير الأقوات بقوله ﴿لِلسَّائِلِينَ﴾؟","answer":"يشمل اللفظ من يسأل رزقه طلبًا، ومن يتطلع إلى معرفة كيفية الخلق؛ فيصور الأقوات مهيأة لحاجات الخلق، ويجعل البيان جوابًا لمن يتدبر ويسأل.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص191–192، تحت عنوان «بلاغة اختيار مفردة ﴿للسائلين﴾»","url":""}]},{"id":"s41-27","number":27,"surah":41,"verses":[11],"references":[{"surah":41,"verses":[11]}],"verseLabel":"فصلت: 11","question":"ما سر التعبير عن السماء بأنها كانت ﴿دُخَانٌ﴾؟","answer":"على التوجيه البلاغي الذي تعرضه الموسوعة، يشبه الدخان هيئة المادة قبل إحكامها، لما في صورته من لطف وتفرق. ثم يأتي إتمام السماوات ليبرز الانتقال من هذه الهيئة إلى خلق محكم مقدر، فتقرب الصورة معنى التكوين إلى الحس.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص193–194، تحت عنوان «بلاغة التشبيه في لفظ ﴿دخان﴾»","url":""}]},{"id":"s41-28","number":28,"surah":41,"verses":[11],"references":[{"surah":41,"verses":[11]}],"verseLabel":"فصلت: 11","question":"ما الصورة التي يرسمها قوله للسماء والأرض ﴿ائْتِيَا﴾؟","answer":"يمثلهما بمخاطبَين يسمعان أمر خالقهما ويجيبان، فتجسد الصورة انقياد الكون كله وسرعة امتثاله لإرادة الله من غير عجز ولا امتناع.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص194، تحت عنوان «توجيه الاستعارة والتمثيل في لفظ الإتيان»","url":""}]},{"id":"s41-127","number":127,"surah":41,"verses":[11],"references":[{"surah":41,"verses":[11]}],"verseLabel":"فصلت: 11","question":"لماذا قيل للسماء والأرض ﴿طَوْعًا أَوْ كَرْهًا﴾؟","answer":"للتعريض بالمشركين: فالسماء والأرض، على عظم خلقهما، منقادتان لأمر الله في كل حال، فكيف يتخلف الإنسان الضعيف عن طاعته؟ كما تؤكد العبارة أن إرادته نافذة لا يخرج عنها شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص195، تحت عنوان «بلاغة التعريض بلفظ الكره والطوع»","url":""}]},{"id":"s41-29","number":29,"surah":41,"verses":[11],"references":[{"surah":41,"verses":[11]}],"verseLabel":"فصلت: 11","question":"لماذا قالت السماء والأرض ﴿أَتَيْنَا طَائِعِينَ﴾ بصيغة جمع العقلاء لا «طائعتين»؟","answer":"لأن الخطاب صوّرهما كعاقلين يسمعان الأمر ويجيبان عنه، فناسب أن يأتي جوابهما بصيغة جمع العقلاء؛ وفي ذلك تجسيد لكمال انقيادهما وسرعة امتثالهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص197، تحت عنوان «نكتة صيغة جمع الجماد بجمع العقلاء»","url":""}]},{"id":"s41-30","number":30,"surah":41,"verses":[11,12],"references":[{"surah":41,"verses":[11,12]}],"verseLabel":"فصلت: 11–12","question":"لماذا عادت السماء المفردة في قوله ﴿وَهِيَ دُخَانٌ﴾ ضميرَ جمع في ﴿فَقَضَاهُنَّ سَبْعَ سَمَاوَاتٍ﴾؟","answer":"ذُكرت السماء أولًا اسمَ جنسٍ للمادة العلوية وهي دخان، فلما قُضيت وفُصلت طبقاتها ظهرت حقيقتها المعدودة سبع سماوات، فعاد الضمير جمعًا إلى ما آل إليه ذلك الجنس بعد التفصيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص202–203، تحت عنوان «عود الضمير في فعل القضاء»","url":""}]},{"id":"s41-31","number":31,"surah":41,"verses":[12],"references":[{"surah":41,"verses":[12]}],"verseLabel":"فصلت: 12","question":"لماذا عبّر عن تدبير كل سماء بقوله ﴿وَأَوْحَى﴾؟","answer":"لأن الوحي يدل على إلقاء خفي سريع؛ فصوّر ما أودعه الله في كل سماء من نظام وتكاليف وتدبير كأمر نافذ يصل إليها بلا إبطاء، ويشمل ما أوحاه إلى ملائكتها وما أجراه في أجرامها.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص204، تحت عنوان «دلالة فعل الوحي مادة وصيغة»","url":""}]},{"id":"s41-128","number":128,"surah":41,"verses":[12],"references":[{"surah":41,"verses":[12]}],"verseLabel":"فصلت: 12","question":"ماذا تضيف كلمة ﴿كُلِّ﴾ في قوله ﴿فِي كُلِّ سَمَاءٍ﴾؟","answer":"تفيد استغراق السماوات جميعًا: لكل سماء نظامها وأمرها الخاص، فلا تُترك واحدة منها بلا تدبير يناسب خلقها ووظيفتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص205، تحت عنوان «دلالة ﴿كل﴾ مضافًا إلى السماء»","url":""}]},{"id":"s41-129","number":129,"surah":41,"verses":[12],"references":[{"surah":41,"verses":[12]}],"verseLabel":"فصلت: 12","question":"ماذا يشمل لفظ ﴿أَمْرَهَا﴾ في قوله ﴿وَأَوْحَى فِي كُلِّ سَمَاءٍ أَمْرَهَا﴾؟","answer":"يشمل ما خص الله به كل سماء من الشؤون والتدبير، وما فيها من أوامر الملائكة وتكاليفهم، وما أودعه في أجرامها من نظام؛ فجاء اللفظ جامعًا لأسرارها ووظائفها.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص205، تحت عنوان «نكتة التعبير بلفظ الأمر»","url":""}]},{"id":"s41-32","number":32,"surah":41,"verses":[12],"references":[{"surah":41,"verses":[12]}],"verseLabel":"فصلت: 12","question":"لماذا جمع قوله ﴿وَزَيَّنَّا السَّمَاءَ الدُّنْيَا بِمَصَابِيحَ وَحِفْظًا﴾ بين الزينة والحفظ؟","answer":"ليبين أن لهذه المصابيح وظيفتين متكاملتين: فهي جمال للناظرين وحراسة للسماء من استراق الشياطين؛ فاجتمع الحسن والمنفعة في خلق واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص208، تحت عنوان «دلالة عطف الحفظ بالواو»","url":""}]},{"id":"s41-33","number":33,"surah":41,"verses":[12],"references":[{"surah":41,"verses":[12]}],"verseLabel":"فصلت: 12","question":"لماذا خُتم وصف خلق السماوات والأرض بقوله ﴿ذَلِكَ تَقْدِيرُ الْعَزِيزِ الْعَلِيمِ﴾؟","answer":"لأن هذا النظام الهائل يحتاج قدرة لا تُغلب وعلمًا يحيط بكل تفصيل؛ فالعزة تناسب إحكام السلطان والتنفيذ، والعلم يناسب دقة المقادير والسنن التي جرى عليها الكون.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص210، تحت عنوان «سر إيثار لفظي ﴿العزيز العليم﴾»","url":""}]},{"id":"s41-34","number":34,"surah":41,"verses":[13],"references":[{"surah":41,"verses":[13]}],"verseLabel":"فصلت: 13","question":"كيف سُمّي عذاب عاد ﴿صَاعِقَةً﴾ مع أن الذي أهلكهم ريح؟","answer":"استعيرت الصاعقة لكل عذاب شديد مهلك يأتي بغتة؛ فالمراد هنا هول الريح المدمرة وأثرها الصاعق، لا الصاعقة الكهربائية خاصة، وبذلك يجتمع عذاب عاد وثمود تحت صورة الهلاك المفاجئ.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص216–217، تحت عنوان «بلاغة الاستعارة في لفظ الصاعقة»","url":""}]},{"id":"s41-35","number":35,"surah":41,"verses":[13],"references":[{"surah":41,"verses":[13]}],"verseLabel":"فصلت: 13","question":"لماذا جُمعت عاد وثمود في إنذار واحد بـ﴿صَاعِقَةً مِثْلَ صَاعِقَةِ عَادٍ وَثَمُودَ﴾ مع اختلاف أداة هلاكهما؟","answer":"لأن التشبيه في جنس العذاب المهلك المفاجئ لا في أداته؛ فالريح صعقت عادًا، والصيحة صعقت ثمود، واتحدت العاقبة التي ينبغي أن يخافها المكذبون.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص217، تحت عنوان «علة الوصف بـ﴿مثل﴾»","url":""}]},{"id":"s41-36","number":36,"surah":41,"verses":[14],"references":[{"surah":41,"verses":[14]}],"verseLabel":"فصلت: 14","question":"ما الصورة التي يرسمها مجيء الرسل ﴿مِنْ بَيْنِ أَيْدِيهِمْ وَمِنْ خَلْفِهِمْ﴾؟","answer":"تصور الرسل وقد أحاطوا بأقوامهم دعوةً وإنذارًا من كل جهة، فلم يتركوا سبيلًا للنصح إلا سلكوه؛ وتشمل كذلك تتابع الرسل في حاضرهم ومن مضى قبلهم، فتقوم الحجة من الجهات والأزمنة كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص226، تحت عنوان «بلاغة الاستعارة في الجملة»","url":""}]},{"id":"s41-37","number":37,"surah":41,"verses":[14],"references":[{"surah":23,"verses":[24]},{"surah":41,"verses":[14]}],"verseLabel":"فصلت: 14؛ المؤمنون: 24","question":"لماذا قال المكذبون ﴿لَوْ شَاءَ رَبُّنَا لَأَنْزَلَ مَلَائِكَةً﴾ باسم الرب مضافًا إليهم؟","answer":"أرادوا أن يوهموا أن ربهم الذي يتولاهم لو أراد هدايتهم لاختار لهم ملائكة، فاتخذوا معنى الربوبية حجة على اعتراضهم، مع أن من تمام ربوبيته أن يختار لرسالته من يشاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص230، تحت عنوان «وجه إيثار اسم الرب مضافًا»","url":""}]},{"id":"s41-38","number":38,"surah":41,"verses":[15],"references":[{"surah":41,"verses":[15]}],"verseLabel":"فصلت: 15","question":"ما أثر الرد على تفاخر عاد ﴿مَنْ أَشَدُّ مِنَّا قُوَّةً﴾ بقوله ﴿هُوَ أَشَدُّ مِنْهُمْ قُوَّةً﴾؟","answer":"جاء الرد من جنس عبارتهم ليقلب الموازنة عليهم: إن كانوا يزعمون القوة، فالذي خلقهم أشد منهم قوة بلا قياس؛ فاستعمال التفضيل يجاري دعواهم ثم يهدم غرورهم من داخله.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص247، تحت عنوان «توجيه استخدام أفعل التفضيل»","url":""}]},{"id":"s41-39","number":39,"surah":41,"verses":[16],"references":[{"surah":41,"verses":[16]}],"verseLabel":"فصلت: 16","question":"لماذا وُصفت الريح التي أهلكت عاد بأنها ﴿صَرْصَرًا﴾؟","answer":"لأن الكلمة تستحضر ريحًا شديدة البرودة والصوت، وتكرار حروفها يحاكي صريرها وقسوتها؛ فكانت عقوبة تناسب قومًا اغتروا بقوتهم، إذ حطمتهم قوة لا يملكون دفعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص254، تحت عنوان «سر الوصف بـ﴿صرصرًا﴾»","url":""}]},{"id":"s41-40","number":40,"surah":41,"verses":[16],"references":[{"surah":41,"verses":[16]},{"surah":54,"verses":[19]}],"verseLabel":"فصلت: 16؛ القمر: 19","question":"لماذا وُصفت أيام عذاب عاد في فصلت بأنها ﴿أَيَّامٍ نَحِسَاتٍ﴾؟","answer":"لأن الشؤم أحاط بهم في تلك الأيام بما نزل فيها من عذاب متتابع، فوصف الأيام بالنحس من جهة ما وقع فيها، وكانت أيامًا متعددة لأن الريح استمرت عليهم زمنًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص255، تحت عنوان «سر وصف الأيام بالنحسات»","url":""}]},{"id":"s41-130","number":130,"surah":41,"verses":[16],"references":[{"surah":41,"verses":[16]},{"surah":54,"verses":[19]}],"verseLabel":"فصلت: 16؛ القمر: 19","question":"ماذا يضيف وصف يوم عذاب عاد في سورة القمر بأنه ﴿نَحْسٍ مُسْتَمِرٍّ﴾؟","answer":"يصور النحس ممتدًا لا ينقطع خلال اليوم، أو متصل الأثر حتى يبلغ العذاب غايته؛ فليس شؤمًا عابرًا بل زمنًا استمر عليهم بالهلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج58، ص504–505، تحت عنوان «بلاغة الوصف في قوله ﴿مستمر﴾»","url":""}]},{"id":"s41-41","number":41,"surah":41,"verses":[16],"references":[{"surah":41,"verses":[16]}],"verseLabel":"فصلت: 16","question":"لماذا قيل عن عذاب الآخرة بعد خزي الدنيا إنه ﴿أَخْزَى﴾؟","answer":"لأن خزي الآخرة أشد وأدوم: يجمع انكشاف الذل أمام الخلق مع العذاب الذي لا ينقطع، فجاء اسم التفضيل ليبين أن ما ذاقوه في الدنيا أهون من الفضيحة الباقية.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص259، تحت عنوان «سر التعبير بصيغة التفضيل»","url":""}]},{"id":"s41-42","number":42,"surah":41,"verses":[17],"references":[{"surah":41,"verses":[17]}],"verseLabel":"فصلت: 17","question":"كيف يصوّر قوله ﴿فَاسْتَحَبُّوا الْعَمَى عَلَى الْهُدَى﴾ اختيار ثمود للضلال؟","answer":"يجعل الضلال عمًى يحجب الحق، ويجعل الإيمان هدى يُبصر به الطريق؛ ثم يصورهم وكأنهم وازنوا بين النور والعمى فاختاروا العمى عن قصد، فتظهر بشاعة قرارهم ومسؤوليتهم عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص268، تحت عنوان «بلاغة الاستعارة في الجملة»","url":""}]},{"id":"s41-43","number":43,"surah":41,"verses":[17],"references":[{"surah":41,"verses":[17]}],"verseLabel":"فصلت: 17","question":"لماذا وُصف عذاب ثمود بأنه ﴿عَذَابِ الْهُونِ﴾ بعد استحبابهم العمى؟","answer":"لأنهم تكبروا على الهدى واختاروا الضلال عمدًا، فجاء عذابهم مهينًا مذلًا؛ فالهون لا يصف الألم وحده، بل يضيف إليه الخزي المقابل لاستعلائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص270، تحت عنوان «بلاغة وصف العذاب بالهون»","url":""}]},{"id":"s41-44","number":44,"surah":41,"verses":[16,17,18],"references":[{"surah":41,"verses":[16,17,18]}],"verseLabel":"فصلت: 16–18","question":"لماذا أعقب عذاب عاد وثمود بقوله ﴿وَنَجَّيْنَا الَّذِينَ آمَنُوا وَكَانُوا يَتَّقُونَ﴾؟","answer":"ليكتمل مشهد العدل: فالعذاب لا يعم الجميع بلا تمييز، بل يهلك المكذبين وينجي المؤمنين؛ فجاء العطف بعد قصة الهلاك ليبرز المصير المقابل مباشرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص275، تحت عنوان «بلاغة العطف بالواو»","url":""}]},{"id":"s41-45","number":45,"surah":41,"verses":[19],"references":[{"surah":41,"verses":[19]}],"verseLabel":"فصلت: 19","question":"لماذا سُمّي المحشورون إلى النار ﴿أَعْدَاءَ اللَّهِ﴾؟","answer":"لأنهم عارضوا رسله وآياته واتخذوا الشيطان وليًا، فجمعهم الاسم في معسكر واحد من العداوة مهما اختلفت أقوامهم، وأضافهم إلى اسم الله لتفظيع من عادوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص282، تحت عنوان «سر إيثار لفظ الأعداء جمعًا مضافًا»","url":""}]},{"id":"s41-46","number":46,"surah":41,"verses":[20],"references":[{"surah":41,"verses":[20]}],"verseLabel":"فصلت: 20","question":"ما سر إفراد ﴿سَمْعُهُمْ﴾ وجمع ﴿أَبْصَارُهُمْ﴾ و﴿جُلُودُهُمْ﴾؟","answer":"السمع مصدر، والمصدر لا يجمع على نحو جمع أسماء الأعضاء، بخلاف الأبصار والجلود. وتذكر الموسوعة أيضًا أن وظيفة السمع تتقارب بين الناس، بينما تختلف الأنظار، فناسب ذلك الإفراد في الأول والجمع في الآخرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص291–292، تحت عنوان «نكتة إفراد السمع»","url":""}]},{"id":"s41-47","number":47,"surah":41,"verses":[20],"references":[{"surah":41,"verses":[20]}],"verseLabel":"فصلت: 20","question":"ما دلالة ذكر الجلود مع السمع والأبصار في الشهادة عليهم؟","answer":"ذكرت هذه الجوارح لأن شهادتها تستوعب ما باشره الإنسان من أعمال؛ فالجلود متصلة باللمس، ويدخل إدراك الذوق في جملة ذلك على التوجيه المذكور. وذكرها مع السمع والأبصار يجعل الشهادة من بدن الإنسان نفسه على ما اجترحه.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص290–291، تحت عنوان «دلالة اصطفاء بعض الجوارح»","url":""}]},{"id":"s41-48","number":48,"surah":41,"verses":[20,21],"references":[{"surah":41,"verses":[20,21]}],"verseLabel":"فصلت: 20–21","question":"ما سر تخصيصهم الجلود بالسؤال ﴿لِمَ شَهِدْتُمْ عَلَيْنَا﴾ دون السمع والأبصار؟","answer":"لأن الجلود أعم اتصالًا بما باشرته الأعضاء من أعمال؛ وهي غطاء الجسد، وقد تكون شاهدة على أعمال اشترك فيها السمع والبصر. وتذكر الموسوعة توجيهًا آخر على القول بأن الجلود كناية عن الفروج، فتخصيصها بالعتاب راجع إلى شدة جناية ما كُنّي عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص298–299، تحت عنوان «بلاغة الكناية في جلودهم، وسر تخصيصها بالعتاب»","url":""}]},{"id":"s41-49","number":49,"surah":41,"verses":[21],"references":[{"surah":41,"verses":[21]}],"verseLabel":"فصلت: 21","question":"لماذا لم تجب الجلود عن سؤال ﴿لِمَ شَهِدْتُمْ عَلَيْنَا﴾ بذكر السبب، بل قالت ﴿أَنْطَقَنَا اللَّهُ﴾؟","answer":"لأنهم سألوا عن الدافع إلى الشهادة، فصرفهم الجواب إلى الحقيقة الأهم: الجلود لا تملك الامتناع أصلًا، وإنما نطقت بقدرة الله؛ فصحح جوابها وهمهم قبل أن يجيب توقعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص302، تحت عنوان «بلاغة الأسلوب الحكيم في تلقي المخاطب بغير ما يترقبه»","url":""}]},{"id":"s41-131","number":131,"surah":41,"verses":[21],"references":[{"surah":41,"verses":[21]}],"verseLabel":"فصلت: 21","question":"لماذا قالت الجلود ﴿أَنْطَقَنَا اللَّهُ الَّذِي أَنْطَقَ كُلَّ شَيْءٍ﴾ بالاسم الموصول؟","answer":"لتجعل صلته دليل الجواب: الذي تتعلق قدرته بإنطاق كل شيء لا يعجزه إنطاق الجلود، وفي ذلك توبيخ لهم وتعريض بأن إنكارهم شهادة جوارحهم إنكار لسعة قدرة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص303، تحت عنوان «سر وصف الاسم الجليل بالاسم الموصول ﴿الذي﴾»","url":""}]},{"id":"s41-50","number":50,"surah":41,"verses":[21],"references":[{"surah":41,"verses":[21]}],"verseLabel":"فصلت: 21","question":"ما صلة التذكير بخلقهم ﴿أَوَّلَ مَرَّةٍ﴾ بإنطاق جلودهم وشهادتها؟","answer":"ينقلهم من دهشة نطق الجلود إلى أصل أجسادهم: فالذي أنشأها أول مرة قادر على إعادتها وعلى أن يجعلها تتكلم، فتجتمع في العبارة حجة البعث وحجة إمكان شهادة الجوارح.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص306، تحت عنوان «سر التقييد بالظرف ﴿أول مرة﴾، وسر التعبير به مضافًا»","url":""}]},{"id":"s41-51","number":51,"surah":41,"verses":[22],"references":[{"surah":41,"verses":[22]}],"verseLabel":"فصلت: 22","question":"لماذا أعيد ذكر السمع والأبصار والجلود بعد أن شهدت عليهم؟","answer":"لتجديد استحضار الجوارح التي توهموا أنها تستر أعمالهم، وتأكيد أن الشهادة أحاطت بأدوات الإدراك والفعل التي باشرت المعصية؛ فتتكرر الصدمة بتسمية الشهود مرة أخرى.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص314، تحت عنوان «فائدة الإطناب بإعادة ذكر السمع والأبصار والجلود»","url":""}]},{"id":"s41-52","number":52,"surah":41,"verses":[22],"references":[{"surah":41,"verses":[22]}],"verseLabel":"فصلت: 22","question":"ما سر التعبير بـ﴿وَمَا كُنْتُمْ تَسْتَتِرُونَ﴾ عن ظنهم أن جوارحهم لا تشهد؟","answer":"الاستتار طلب الستر، ويبين النفي أنهم لم يتحفظوا من أعمالهم مخافة شهادة الجوارح؛ إذ لم يحسبوا لهذه الشهادة حسابًا. ويحتمل التركيب أنهم كانوا يستترون من الناس، لكن ذلك لا يسترهم عن سمعهم وأبصارهم وجلودهم التي تشهد عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص312، تحت عنوان «دلالة التعبير بـ﴿تستترون﴾، وسر صوغه مضارعًا»","url":""}]},{"id":"s41-53","number":53,"surah":41,"verses":[23],"references":[{"surah":41,"verses":[23]}],"verseLabel":"فصلت: 23","question":"لماذا أُشير إلى ظنهم الباطل بقول الله ﴿وَذَلِكُمْ ظَنُّكُمُ﴾؟","answer":"جيء باسم الإشارة للبعيد لتهويل ذلك الظن وإبعاده عن الحق، وجُمِع خطابهم لأن هذا الوهم كان جماعيًا؛ فالإشارة تستحضر أمامهم السبب الذي أوقعهم في الهلاك وتوبخهم عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص322، تحت عنوان «الغرض من التعبير باسم الإشارة للبعيد، وضمير الجمع»","url":""}]},{"id":"s41-132","number":132,"surah":41,"verses":[23],"references":[{"surah":41,"verses":[23]}],"verseLabel":"فصلت: 23","question":"لماذا وُصف ظنهم بقوله ﴿الَّذِي ظَنَنْتُمْ بِرَبِّكُمْ﴾ بعد ذكره؟","answer":"ليعيّن الظن المذموم الذي صار سبب هلاكهم، ويعيد نسبته إليهم توبيخًا؛ فلم يكن خاطرًا عابرًا، بل اعتقادًا سيئًا بالله بنوا عليه أمنهم من الحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص323، تحت عنوان «سر التقييد بالصفة ﴿الذي ظننتم﴾ اسمًا موصولًا»","url":""}]},{"id":"s41-54","number":54,"surah":41,"verses":[23],"references":[{"surah":41,"verses":[23]}],"verseLabel":"فصلت: 23","question":"كيف صوّر قوله ﴿أَرْدَاكُمْ﴾ أثر سوء الظن بالله؟","answer":"صوّر الظن كأنه قوة ألقت أصحابه في الهلاك، فنُسب الإرداء إليه لأنه السبب الذي جرأهم على المعاصي وأمّنهم من العقاب حتى أوقعهم في الخسران.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص324، تحت عنوان «الاستعارة والمجاز في قوله ﴿أرداكم﴾»","url":""}]},{"id":"s41-133","number":133,"surah":41,"verses":[23],"references":[{"surah":41,"verses":[23]}],"verseLabel":"فصلت: 23","question":"ماذا يفيد قوله ﴿فَأَصْبَحْتُمْ مِنَ الْخَاسِرِينَ﴾ بعد ﴿أَرْدَاكُمْ﴾؟","answer":"تفيد الفاء أن الخسران نتيجة مباشرة لذلك الظن، ويصوّر فعل ﴿أصبحتم﴾ انتقالهم إلى حال انكشف فيها الهلاك وصار وصفًا ثابتًا لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص324، تحت عنوان «دلالة التعبير بالفعل ﴿فأصبحتم﴾»","url":""}]},{"id":"s41-55","number":55,"surah":41,"verses":[24],"references":[{"surah":41,"verses":[24]}],"verseLabel":"فصلت: 24","question":"لماذا كان جواب ﴿فَإِنْ يَصْبِرُوا﴾ هو ﴿فَالنَّارُ مَثْوًى لَهُمْ﴾؟","answer":"لأن صبرهم في الآخرة لا يغيّر مصيرهم ولا يخفف العقوبة؛ فالجملة الاسمية تثبت أن النار مقرهم في كل حال، صبروا على ألمها أو جزعوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص331، تحت عنوان «مناسبة جواب الشرط لفعل الشرط، ودلالة التعبير به اسمية»","url":""}]},{"id":"s41-134","number":134,"surah":41,"verses":[24],"references":[{"surah":41,"verses":[24]}],"verseLabel":"فصلت: 24","question":"لماذا قيل في طلبهم العتبى ﴿فَمَا هُمْ مِنَ الْمُعْتَبِينَ﴾؟","answer":"لنفي قبول معذرتهم نفيًا ثابتًا قاطعًا؛ فطلب الرضا بعد فوات زمن التوبة لا يخرجهم من النار، ولا يجعلهم ممن تُزال عنهم المؤاخذة.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص334، تحت عنوان «سر التعبير بالجملة الشرطية المنفية جملة اسمية ﴿فما هم من المعتبين﴾»","url":""}]},{"id":"s41-56","number":56,"surah":41,"verses":[25],"references":[{"surah":41,"verses":[25]}],"verseLabel":"فصلت: 25","question":"لماذا أُسند تقييض قرناء السوء إلى ضمير العظمة في ﴿وَقَيَّضْنَا لَهُمْ﴾؟","answer":"لتهويل ما ينشأ عن هذا الجزاء من إحاطة الشر بهم، وتصوير الفعل الإلهي في مقام الجلال والهيبة؛ فيحذر السامع من الإعراض الذي يستجلب تسليط القرناء.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص341، تحت عنوان «سر الإسناد إلى الضمير الدال على التعظيم»","url":""}]},{"id":"s41-57","number":57,"surah":41,"verses":[25],"references":[{"surah":41,"verses":[25]}],"verseLabel":"فصلت: 25","question":"ما دلالة قوله ﴿فَزَيَّنُوا لَهُمْ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ﴾؟","answer":"يصور ذكر ما بين الأيدي وما خلف شمول التزيين وإحاطته بهم؛ فهم يصرفونهم إلى الشهوات ويزينون الباطل من جهات متعددة. ومن بيان ذلك أنهم هونوا شأن الآخرة مع تزيين الدنيا، فاجتمعت غواية العمل وفساد الاعتقاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص344، تحت عنوان «الغرض من الإطناب بذكر ﴿أيديهم﴾، ﴿خلفهم﴾»","url":""}]},{"id":"s41-58","number":58,"surah":41,"verses":[25],"references":[{"surah":41,"verses":[25]}],"verseLabel":"فصلت: 25","question":"ما سر تقديم الجن على الإنس في الأمم التي حقت عليها كلمة العذاب؟","answer":"قدّم الجن لأنهم أعرق في الإغواء على التوجيه المذكور، ولأن تقديمهم أبلغ في بيان أن قدرتهم الخفية لا تعصمهم من الحكم الإلهي. وفي ذلك أيضًا إبطال لتعظيم المشركين شأن الجن والاستعاذة بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص348، تحت عنوان «نكتة تقديم ﴿الجن﴾ على (الإنس)»","url":""}]},{"id":"s41-59","number":59,"surah":41,"verses":[26],"references":[{"surah":41,"verses":[26]}],"verseLabel":"فصلت: 26","question":"ماذا يكشف نهي الكافرين ﴿لَا تَسْمَعُوا لِهَذَا الْقُرْآنِ﴾؟","answer":"يكشف خوفهم من أثر القرآن وعجزهم عن مقارعته بالحجة؛ فانتقلوا من الإعراض الشخصي إلى صد الناس عن الاستماع كيلا يصل البيان إلى قلوبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص354، تحت عنوان «الغرض من التعبير بالنهي في مقول القول ﴿لا تسمعوا﴾»","url":""}]},{"id":"s41-135","number":135,"surah":41,"verses":[26],"references":[{"surah":41,"verses":[26]}],"verseLabel":"فصلت: 26","question":"لماذا لم يكتفوا بقولهم ﴿لَا تَسْمَعُوا﴾ بل أضافوا ﴿وَالْغَوْا فِيهِ﴾؟","answer":"لأن غرضهم لم يكن ترك السماع وحده، بل التشويش وقت التلاوة حتى يمنعوا غيرهم أيضًا من الفهم؛ فعطفوا إحداث الضجيج على الإعراض ليجمعوا بين صد أنفسهم وصد الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص356، تحت عنوان «دلالة العطف في ﴿والغوا فيه﴾»","url":""}]},{"id":"s41-60","number":60,"surah":41,"verses":[26],"references":[{"surah":41,"verses":[26]}],"verseLabel":"فصلت: 26","question":"ماذا تكشف كلمة ﴿لَعَلَّكُمْ﴾ في قولهم ﴿لَعَلَّكُمْ تَغْلِبُونَ﴾؟","answer":"تكشف أنهم لم يكونوا واثقين بالغلبة، وإنما يرجون أن يحقق لهم التشويش ما عجزت عنه الحجة؛ فتفضح الكلمة ضعف موقفهم وخوفهم من نفاذ القرآن إلى السامعين.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص358، تحت عنوان «الغرض من التعبير بـ(لعل)»","url":""}]},{"id":"s41-61","number":61,"surah":41,"verses":[27],"references":[{"surah":41,"verses":[27]}],"verseLabel":"فصلت: 27","question":"ما دلالة قوله ﴿وَلَنَجْزِيَنَّهُمْ أَسْوَأَ الَّذِي كَانُوا يَعْمَلُونَ﴾؟","answer":"في ﴿أسوأ﴾ تغليظ وتقبيح لأعمالهم؛ وقد يراد بها أعمالهم السيئة من غير مفاضلة، أو أسوأ أعمالهم الذي استوجب الوعيد، فيتأكد أن الجزاء مطابق لجنايتهم لا ظلم فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص365–366، تحت عنوان «نكتة التعبير باسم التفضيل ﴿أسوأ﴾، ودلالة إضافته»","url":""}]},{"id":"s41-62","number":62,"surah":41,"verses":[28],"references":[{"surah":41,"verses":[28]}],"verseLabel":"فصلت: 28","question":"ما فائدة تفسير الجزاء بقوله ﴿النَّارُ لَهُمْ﴾ بعد قوله ﴿ذَلِكَ جَزَاءُ أَعْدَاءِ اللَّهِ﴾؟","answer":"يبدأ السياق بالإشارة إلى الجزاء لتهويله، ثم يعيّنه بقوله ﴿النار لهم﴾ حتى ينكشف بعد الإبهام؛ فتجتمع رهبة الانتظار مع التصريح بالمصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص368، تحت عنوان «فصل قوله ﴿النار لهم﴾ عما قبلها»","url":""}]},{"id":"s41-63","number":63,"surah":41,"verses":[28],"references":[{"surah":41,"verses":[28]}],"verseLabel":"فصلت: 28","question":"لماذا قيل ﴿لَهُمْ فِيهَا دَارُ الْخُلْدِ﴾ بدل التصريح بأنهم خالدون؟","answer":"صُوّر الخلود كأن له دارًا مستقلة داخل النار، وهو تجريد يبالغ في ثبات الإقامة؛ فليست النار ممرًا عابرًا، بل مقر دائم لا انفصال لهم عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص369، تحت عنوان «الغرض من التعبير بأسلوب التجريد في ﴿لهم فيها دار الخلد﴾»","url":""}]},{"id":"s41-64","number":64,"surah":41,"verses":[29],"references":[{"surah":41,"verses":[29]}],"verseLabel":"فصلت: 29","question":"لماذا يقول أهل النار ﴿أَرِنَا الَّذَيْنِ أَضَلَّانَا﴾؟","answer":"لأنهم يريدون تعيين المضلين وتمكينهم منهم ليفرغوا فيهم غضبهم؛ فالطلب ليس معرفة مجردة، بل طلب إحضار ومواجهة بعد أن انقلب الاتباع عداوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص378، تحت عنوان «الغرض من الزيادة في ﴿أرنا﴾»","url":""}]},{"id":"s41-136","number":136,"surah":41,"verses":[29],"references":[{"surah":41,"verses":[29]}],"verseLabel":"فصلت: 29","question":"ما الذي يصوره قولهم عن المضلين ﴿نَجْعَلْهُمَا تَحْتَ أَقْدَامِنَا﴾؟","answer":"هو كناية عن غاية الإذلال والقهر؛ فالذين كانوا أتباعًا يريدون وضع قادتهم في أسفل منزلة، والانتقام ممن يرون أنهم جرّوهم إلى العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص381، تحت عنوان «الغرض من التعبير بالكناية في ﴿نجعلهما تحت أقدامنا﴾»","url":""}]},{"id":"s41-65","number":65,"surah":41,"verses":[29],"references":[{"surah":41,"verses":[29]}],"verseLabel":"فصلت: 29","question":"ما سر تقديم الجن على الإنس عند تحديد المضلين؟","answer":"يراعي التقديم سبق الجن في الإضلال على هذا التوجيه، ويبين شمول القدرة الإلهية لهم مع خفائهم. ويرد كذلك على عادة الكافرين في تعظيم الجن والاستعاذة بهم، إذ لا يمنعهم ذلك من العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص380، تحت عنوان «الغرض من البدء بالجن»","url":""}]},{"id":"s41-66","number":66,"surah":41,"verses":[30],"references":[{"surah":41,"verses":[30]}],"verseLabel":"فصلت: 30","question":"لماذا جمع قول المؤمنين ﴿رَبُّنَا اللَّهُ﴾ بين اسمي الربوبية والألوهية؟","answer":"لأن وصف الرب يذكّر بالتربية والرعاية والإحسان، واسم الله يقرر استحقاق العبادة وحده؛ فجمع الإقرار بين معرفة المنعم وإخلاص العبودية له.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص389، تحت عنوان «دلالة التعبير باسمي الربوبية والألوهية»","url":""}]},{"id":"s41-67","number":67,"surah":41,"verses":[30],"references":[{"surah":41,"verses":[30]}],"verseLabel":"فصلت: 30","question":"ماذا تضيف صيغة ﴿تَتَنَزَّلُ﴾ في تنزل الملائكة على المستقيمين؟","answer":"تصور تنزلًا متكررًا متدرجًا بحسب المواطن والحاجات؛ فالملائكة تتعاهد المؤمنين بالبشرى والتثبيت ولا يكون نزولها حادثة منقطعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص394، تحت عنوان «بدعة التعبير بالفعل في قوله ﴿تتنزل﴾ دون (تنزل)»","url":""}]},{"id":"s41-68","number":68,"surah":41,"verses":[30],"references":[{"surah":41,"verses":[30]}],"verseLabel":"فصلت: 30","question":"ما سر تقديم نفي الخوف على نفي الحزن في بشارة الملائكة؟","answer":"يتعلق الخوف بما يستقبلونه من أهوال، ويتعلق الحزن بما خلفوه وما مضى. فبدأت البشارة بتأمينهم مما يواجههم، ثم أتبعت ذلك بتسكين حزنهم على ما تركوه، وجمعت لهم الطمأنينة من الجهتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص397، تحت عنوان «سر الترتيب بالنهي بين الخوف والحزن في قوله ﴿ألا تخافوا ولا تحزنوا﴾»","url":""}]},{"id":"s41-69","number":69,"surah":41,"verses":[30],"references":[{"surah":41,"verses":[30]}],"verseLabel":"فصلت: 30","question":"ما دلالة الجمع بين نفي الخوف والحزن والبشارة بالجنة؟","answer":"نفي الخوف والحزن يرفع أسباب الضرر والغم، ثم تأتي البشارة بالجنة لتثبت الخير والنعيم. وهذا الترتيب يقدم إزالة ما يكدر النفس، حتى تتلقى البشارة وقد اطمأنت، فيكتمل لها الأمن والفرح.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص398–399، تحت عنوان «دلالة ذكر البشارة بعد النهي عن الخوف والحزن»","url":""}]},{"id":"s41-70","number":70,"surah":41,"verses":[31],"references":[{"surah":41,"verses":[31]}],"verseLabel":"فصلت: 31","question":"ماذا تعني بشارة الملائكة للمؤمنين ﴿نَحْنُ أَوْلِيَاؤُكُمْ﴾؟","answer":"تعني القرب والنصرة والرعاية؛ فهم يتولون المؤمنين بما يأذن الله به من التثبيت والبشرى والمعونة، فتبدد الكلمة وحشة الانتقال إلى الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص403، تحت عنوان «دلالة التعبير بالأولياء»","url":""}]},{"id":"s41-137","number":137,"surah":41,"verses":[31],"references":[{"surah":41,"verses":[31]}],"verseLabel":"فصلت: 31","question":"لماذا قالت الملائكة ﴿فِي الْحَيَاةِ الدُّنْيَا وَفِي الْآخِرَةِ﴾؟","answer":"لتأكيد أن ولايتهم للمؤمنين ممتدة لا تنقطع بالموت؛ تبدأ بما يكون في الدنيا من التثبيت والحفظ، وتستمر في الآخرة بالبشرى والأمن، فأعيد حرف الجر لتستقل كل مرحلة بعنايتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص407، تحت عنوان «دلالة الواو في قوله ﴿وفي الآخرة﴾»","url":""}]},{"id":"s41-71","number":71,"surah":41,"verses":[31],"references":[{"surah":41,"verses":[31]}],"verseLabel":"فصلت: 31","question":"ماذا توحي صيغة ﴿مَا تَشْتَهِي أَنْفُسُكُمْ﴾ في نعيم الجنة؟","answer":"تجعل الشهوة جامعة لكل ما تميل إليه النفوس من اللذات المتنوعة، وتصور الرغبات متجددة لا يحدها نوع ولا تنغصها حسرة أو حرمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص410، تحت عنوان «دلالة التعبير بـ﴿تشتهي﴾»","url":""}]},{"id":"s41-138","number":138,"surah":41,"verses":[31],"references":[{"surah":41,"verses":[31]}],"verseLabel":"فصلت: 31","question":"لماذا قُدّم ﴿مَا تَشْتَهِي أَنْفُسُكُمْ﴾ على ﴿مَا تَدَّعُونَ﴾؟","answer":"لأن الاشتهاء أعم: يشمل ما يخطر بالقلب قبل أن يطلبه صاحبه، ثم يجيء الادعاء ليضمن ما يطلبونه صراحة؛ فانتقل التعبير من الرغبة الباطنة إلى السؤال الظاهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص413، تحت عنوان «دلالة الترتيب بين ما يشتهون ويدعون»","url":""}]},{"id":"s41-72","number":72,"surah":41,"verses":[32],"references":[{"surah":41,"verses":[32]}],"verseLabel":"فصلت: 32","question":"لماذا نُسب هذا النزل إلى ﴿غَفُورٍ رَحِيمٍ﴾؟","answer":"لأن بلوغ الجنة يبدأ بمغفرة التقصير ويكتمل بالرحمة التي تمنح الفضل والنعيم؛ فاجتماع الوصفين يطمئن المؤمن إلى ستر الذنب ثم دوام الإحسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص418–419، تحت عنوان «سر إيثار وصفي ﴿غفور رحيم﴾ دون غيرهما من الصفات»","url":""}]},{"id":"s41-73","number":73,"surah":41,"verses":[33],"references":[{"surah":41,"verses":[33]}],"verseLabel":"فصلت: 33","question":"ما دلالة الاستفهام في ﴿وَمَنْ أَحْسَنُ قَوْلًا﴾؟","answer":"هو استفهام يراد به النفي؛ فلا أحد أحسن قولًا ممن دعا إلى الله، وفي صيغة السؤال إشراك للسامع في الإقرار بهذه المنزلة وإثارة للتطلع إلى صفات صاحبها.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص423، تحت عنوان «دلالة التعبير بالاستفهام في قوله ﴿ومن﴾»","url":""}]},{"id":"s41-139","number":139,"surah":41,"verses":[33],"references":[{"surah":41,"verses":[33]}],"verseLabel":"فصلت: 33","question":"لماذا جمع صاحب أحسن القول بين الدعوة إلى الله والعمل الصالح؟","answer":"لأن صدق الدعوة يظهر في موافقة العمل للقول؛ فالداعي يهدي غيره بكلامه ويزكي نفسه بفعله، وبهذا تجتمع قدوة البيان وقدوة السلوك.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص429–430، تحت عنوان «دلالة الواو في قوله ﴿وعمل﴾»","url":""}]},{"id":"s41-74","number":74,"surah":41,"verses":[33],"references":[{"surah":41,"verses":[33]}],"verseLabel":"فصلت: 33","question":"لماذا أكّد الداعي قوله ﴿إِنَّنِي مِنَ الْمُسْلِمِينَ﴾؟","answer":"ليعلن انتماءه إلى الإسلام اعتزازًا وثباتًا، ويرد على من قد يشكك في صدقه؛ فالدعوة والعمل الصالح صادران عن هوية إيمانية يصرح بها ولا يخفيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص433، تحت عنوان «دلالة التأكيد بـ(إن) في قوله ﴿إنني﴾»","url":""}]},{"id":"s41-140","number":140,"surah":41,"verses":[33],"references":[{"surah":41,"verses":[33]}],"verseLabel":"فصلت: 33","question":"لماذا قال ﴿مِنَ الْمُسْلِمِينَ﴾ بدل أن يقول: مسلم؟","answer":"ليجعل نفسه فردًا من جماعة المسلمين لا طالب تميز شخصي، وفيه تواضع وانتساب إلى الطريق الجامع الذي سلكه الأنبياء والمؤمنون.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص433، تحت عنوان «دلالة التعبير بقوله ﴿من المسلمين﴾»","url":""}]},{"id":"s41-75","number":75,"surah":41,"verses":[34],"references":[{"surah":41,"verses":[34]}],"verseLabel":"فصلت: 34","question":"ما دلالة نفي استواء الحسنة والسيئة مع وضوح تفاوتهما؟","answer":"نفي الاستواء يراد به تقرير تفضيل الحسنة على السيئة، ثم توجيه المخاطب إلى ما يقتضيه ذلك في المعاملة. فهو يثبت ميزان التفاضل الذي يبنى عليه الأمر بالدفع بالأحسن، ويؤكد أن العملين لا يستويان في القدر والأثر.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص440، تحت عنوان «دلالة التعبير بنفي الاستواء في قوله ﴿ولا تستوي﴾»","url":""}]},{"id":"s41-76","number":76,"surah":41,"verses":[34],"references":[{"surah":41,"verses":[34]}],"verseLabel":"فصلت: 34","question":"ما سر التعبير بـ﴿ادْفَعْ بِالَّتِي هِيَ أَحْسَنُ﴾ بدل «ادفع بالحسنة»؟","answer":"صيغة التفضيل تدعو إلى اختيار أعلى مراتب الإحسان عند مقابلة الإساءة، فلا يكتفى بأدنى حسنة ممكنة. وتبرز الموسوعة من ذلك مقابلة الجهل بالحلم والأذى بالعفو، لما لهذا الفضل الزائد من أثر في تهدئة العداوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص447، تحت عنوان «دلالة التعبير بصيغة التفضيل ﴿أحسن﴾»","url":""}]},{"id":"s41-77","number":77,"surah":41,"verses":[34],"references":[{"surah":41,"verses":[34]}],"verseLabel":"فصلت: 34","question":"كيف يصور قوله ﴿كَأَنَّهُ وَلِيٌّ حَمِيمٌ﴾ أثر دفع السيئة بالحسنة؟","answer":"يشبه التحول المتوقع من العداوة إلى المودة بحال عدو صار صديقًا شديد القرب؛ فتجعل ﴿كأن﴾ النتيجة الحاصلة في قوة المشهد المشاهد، من غير أن تزعم زوال العداوة فورًا في كل حالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص452، تحت عنوان «بلاغة التشبيه في قوله ﴿كأنه ولي حميم﴾»","url":""}]},{"id":"s41-141","number":141,"surah":41,"verses":[34],"references":[{"surah":41,"verses":[34]}],"verseLabel":"فصلت: 34","question":"لماذا جُمع في الصديق المتحوّل بين ﴿وَلِيٌّ﴾ و﴿حَمِيمٌ﴾؟","answer":"لأن الولي يفيد النصرة والقرب، والحميم يفيد صفاء المودة وشدتها؛ فالجمع يصور انقلاب العداوة إلى صداقة كاملة في الموقف والشعور.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص453، تحت عنوان «دلالة الجمع بين ﴿ولي﴾ و﴿حميم﴾»","url":""}]},{"id":"s41-78","number":78,"surah":41,"verses":[35],"references":[{"surah":41,"verses":[35]}],"verseLabel":"فصلت: 35","question":"لماذا قُصر نيل خصلة دفع السيئة بالحسنة على الصابرين؟","answer":"لأن مقابلة الإساءة بالإحسان تحتاج إلى كبح الغضب واحتمال الأذى ومجاهدة النفس؛ فجاء القصر ليبين أن هذه المرتبة لا تُنال بالتمني، بل بصبر متين.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص459، تحت عنوان «براعة أسلوب القصر في الموضعين في الآية»","url":""}]},{"id":"s41-142","number":142,"surah":41,"verses":[35],"references":[{"surah":41,"verses":[35]}],"verseLabel":"فصلت: 35","question":"لماذا أضيف بعد الصابرين قوله ﴿وَمَا يُلَقَّاهَا إِلَّا ذُو حَظٍّ عَظِيمٍ﴾؟","answer":"ليبين أن الصبر المؤهل لهذه الخصلة توفيق ونصيب عظيم من الخير؛ فمن قدر على تحويل الإساءة إلى إحسان فقد جمع قوة النفس وحسن العاقبة، وهي منزلة نادرة رفيعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص464، تحت عنوان «دلالة ذكر ﴿ذو حظ عظيم﴾ بعد الصبر في قوله ﴿إلا الذين صبروا﴾»","url":""}]},{"id":"s41-79","number":79,"surah":41,"verses":[35],"references":[{"surah":41,"verses":[35]}],"verseLabel":"فصلت: 35","question":"ما سر الانتقال من جمع الصابرين إلى إفراد ﴿ذُو حَظٍّ عَظِيمٍ﴾؟","answer":"يفيد الانتقال من الجمع إلى الإفراد ندرة من يستوفي هذه المرتبة العالية؛ فالصابرون جماعة، أما من بلغ حظه العظيم من هذه الفضيلة فمتميز بينهم. وفي ذلك تنويه بكمال مرتبته في التوفيق والفضل.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص463، تحت عنوان «سر اختلاف التعبير في قوله ﴿إلا ذو﴾ عن سابقتها ﴿إلا الذين﴾»","url":""}]},{"id":"s41-80","number":80,"surah":41,"verses":[36],"references":[{"surah":41,"verses":[36]}],"verseLabel":"فصلت: 36","question":"ما مناسبة الأمر بالاستعاذة بالله بعد الأمر بدفع السيئة بالتي هي أحسن؟","answer":"بعد الأمر بكبح الغضب ومقابلة الإساءة بالإحسان، يوجه إلى الاستعاذة مما يثيره الشيطان من نزغ يصد عن هذا الخلق. فالصبر على أذى البشر والدفع بالأحسن يقترنان بالاعتصام بالله من وسوسة الشيطان.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص468، تحت عنوان «دلالة التعبير بالواو في قوله ﴿وإما ينزغنك﴾»","url":""}]},{"id":"s41-81","number":81,"surah":41,"verses":[36],"references":[{"surah":7,"verses":[200]},{"surah":41,"verses":[36]}],"verseLabel":"فصلت: 36؛ الأعراف: 200","question":"ما سر التعبير هنا بـ﴿إِنَّهُ هُوَ السَّمِيعُ الْعَلِيمُ﴾، وفي الأعراف ﴿إِنَّهُ سَمِيعٌ عَلِيمٌ﴾؟","answer":"زاد موضع فصلت ضمير الفصل وتعريف الصفتين لتقوية التوكيد والاختصاص، ومقامه تكليف بدفع السيئة بالتي هي أحسن وما يحتاج إليه من مقاومة دواعي الغضب. أما الأعراف فجاءت فيه الصفتان منكرتين دون ضمير الفصل في سياق الأمر بالعفو والإعراض عن الجاهلين؛ فالاختلاف يراعي مقدار التوكيد الذي يقتضيه كل مقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص480–481، تحت عنوان «دلالة الاتفاق والاختلاف مع الآية 200 من سورة الأعراف»","url":""}]},{"id":"s41-82","number":82,"surah":41,"verses":[37],"references":[{"surah":41,"verses":[37]}],"verseLabel":"فصلت: 37","question":"لماذا قُدّم الليل والنهار على الشمس والقمر في عداد آيات الله؟","answer":"لأن الليل والنهار آيتان لا يتجه إليهما وهم العبادة، فبدأ بهما لتقرير معنى الآية المخلوقة، ثم ألحق الشمس والقمر بهما لينزع عنهما ما توهمه المشركون من استحقاق السجود.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص487، تحت عنوان «سر تقديم ﴿الليل والنهار﴾ على (الشمس والقمر)»","url":""}]},{"id":"s41-83","number":83,"surah":41,"verses":[37],"references":[{"surah":41,"verses":[37]}],"verseLabel":"فصلت: 37","question":"لماذا أُعيد النفي في ﴿وَلَا لِلْقَمَرِ﴾ بعد النهي عن السجود للشمس؟","answer":"لتأكيد منع السجود لكل واحد منهما استقلالًا، فلا يتوهم أن المنع مقصور على الجمع بينهما أو على الشمس وحدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص490، تحت عنوان «سر إعادة حرف النفي في قوله ﴿ولا للقمر﴾»","url":""}]},{"id":"s41-149","number":149,"surah":41,"verses":[37],"references":[{"surah":41,"verses":[37]}],"verseLabel":"فصلت: 37","question":"ماذا يحقق الأمر ﴿وَاسْجُدُوا لِلَّهِ الَّذِي خَلَقَهُنَّ﴾ بعد النهي؟","answer":"ينقل النظر من الآيات المخلوقة إلى خالقها، ويقرر أن التعظيم الحق لا يقف عند الشمس والقمر بل يتجه إلى من أوجدهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص491، تحت عنوان «دلالة الأمر في قوله ﴿واسجدوا﴾»","url":""}]},{"id":"s41-84","number":84,"surah":41,"verses":[37],"references":[{"surah":41,"verses":[37]}],"verseLabel":"فصلت: 37","question":"لماذا قيل ﴿لِلَّهِ الَّذِي خَلَقَهُنَّ﴾ ولم يقل «للخالق»؟","answer":"لأن الصلة تستحضر فعل الخلق نفسه أمام السامع، فتقيم الحجة مباشرة على استحقاق الله للسجود: من خلق الشمس والقمر وسائر الآيات هو وحده الذي يعبد.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص494، تحت عنوان «سر التعبير بالصلة والموصول ﴿الذي خلقهن﴾ دون الخالق»","url":""}]},{"id":"s41-85","number":85,"surah":41,"verses":[38],"references":[{"surah":41,"verses":[38]}],"verseLabel":"فصلت: 38","question":"هل يقتصر تسبيح الملائكة على الليل والنهار المذكورين؟","answer":"لا؛ فذكر طرفي الزمن كناية عن استمرارهم في التسبيح دائمًا، لأن عبادتهم لا يحصرها ليل أو نهار، وإنما يراد استغراق الأوقات كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص504، تحت عنوان «بلاغة الكناية في ذكر الليل والنهار»","url":""}]},{"id":"s41-143","number":143,"surah":41,"verses":[38],"references":[{"surah":41,"verses":[38]}],"verseLabel":"فصلت: 38","question":"لماذا نُفيت السآمة عن تسبيح الملائكة في قوله ﴿لَا يَسْأَمُونَ﴾؟","answer":"لبيان أنهم لا يملون العبادة ولا يفترون عنها مهما دامت، بل يؤدونها برضا وإقبال؛ فتظهر عبوديتهم الكاملة ويصغر بجانبها استكبار المعرضين.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص505، تحت عنوان «سر التعبير بنفي السآمة في قوله ﴿لا يسأمون﴾»","url":""}]},{"id":"s41-86","number":86,"surah":41,"verses":[39],"references":[{"surah":41,"verses":[39]}],"verseLabel":"فصلت: 39","question":"ما دلالة تصوير الأرض قبل المطر بأنها ﴿خَاشِعَةً﴾؟","answer":"شبهت الأرض اليابسة الساكنة بإنسان خاشع منخفض، فاستعير لها وصف الخشوع لإبراز ذلها وسكونها قبل المطر. ثم يهيئ هذا التصوير لمقابلة حالها بما يظهر فيها من الحركة والنماء بعد نزوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص515–516، تحت عنوان «بلاغة الاستعارة في ﴿خاشعة﴾»","url":""}]},{"id":"s41-87","number":87,"surah":41,"verses":[39],"references":[{"surah":41,"verses":[39]}],"verseLabel":"فصلت: 39","question":"ما الصورة التي يرسمها قوله عن الأرض ﴿اهْتَزَّتْ﴾ بعد نزول الماء؟","answer":"يصورها ككائن حي دبّت فيه الحركة بعد السكون؛ فالماء يوقظ ما خفي فيها من أسباب النبات، ويجعل بدء الحياة مشهدًا محسوسًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص516، تحت عنوان «بلاغة الاستعارة في ﴿اهتزت﴾»","url":""}]},{"id":"s41-144","number":144,"surah":41,"verses":[39],"references":[{"surah":41,"verses":[39]}],"verseLabel":"فصلت: 39","question":"ما الصورة التي يرسمها قوله عن الأرض ﴿وَرَبَتْ﴾؟","answer":"يصورها وهي تنتفخ وتعلو بما تشقه البذور وتنميه من النبات؛ فبعد حركة الحياة يظهر أثرها في الزيادة والارتفاع والنماء.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص516–517، تحت عنوان «بلاغة الاستعارة في ﴿وربت﴾»","url":""}]},{"id":"s41-88","number":88,"surah":41,"verses":[39],"references":[{"surah":41,"verses":[39]}],"verseLabel":"فصلت: 39","question":"لماذا خُتم دليل إحياء الأرض بقوله ﴿إِنَّهُ عَلَى كُلِّ شَيْءٍ قَدِيرٌ﴾؟","answer":"ليعمم الحكم بعد المثال، فيقرر أن البعث فرد من قدرة لا يخرج عنها شيء، فلا يبقى مجال لتوهم العجز عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص523، تحت عنوان «موقع جملة ﴿إنه على كل شيء قدير﴾»","url":""}]},{"id":"s41-89","number":89,"surah":41,"verses":[40],"references":[{"surah":41,"verses":[40]}],"verseLabel":"فصلت: 40","question":"ما سر التعبير بالإلحاد في آيات الله، وما الصورة التي يرسمها اللفظ؟","answer":"أصل الإلحاد الميل والانحراف، فاستعير هنا للعدول عن الحق في الآيات بتحريفها وتكذيبها. وبذلك تتحول المخالفة المعنوية إلى صورة محسوسة لمن يميل عن الطريق المستقيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص528–529، تحت عنوان «بلاغة الاستعارة في ﴿يلحدون﴾»","url":""}]},{"id":"s41-90","number":90,"surah":41,"verses":[40],"references":[{"surah":41,"verses":[40]}],"verseLabel":"فصلت: 40","question":"لماذا جُعل ﴿آمِنًا﴾ في مقابل من ﴿يُلْقَى فِي النَّارِ﴾ يوم القيامة؟","answer":"لإظهار التفاوت التام بين المصيرين؛ فالأمن لا يعني مجرد النجاة من النار، بل يشمل الطمأنينة والتكريم ودخول الجنة، فيقابل خوف الكافر وعذابه بحال المؤمن الآمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص538، تحت عنوان «نكتة جعل الأمن في مقابل الإلقاء في النار»","url":""}]},{"id":"s41-91","number":91,"surah":41,"verses":[40],"references":[{"surah":41,"verses":[40]}],"verseLabel":"فصلت: 40","question":"لماذا قيل للمعاندين ﴿اعملوا ما شئتم﴾؟","answer":"ليس الأمر إذنًا بالمعصية، بل تهديد بعد قيام الحجة ووضوح المصير؛ فقد تُرك لهم ظاهر الاختيار ليعلموا أنهم سيتحملون عاقبة ما اختاروه، فاشتد الوعيد بدل أن يكون في الكلام إباحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص541، تحت عنوان «غرض فعل الأمر ﴿اعملوا ما شئتم﴾»","url":""}]},{"id":"s41-92","number":92,"surah":41,"verses":[41],"references":[{"surah":41,"verses":[41]}],"verseLabel":"فصلت: 41","question":"ماذا يكشف وصف القرآن بأنه ﴿كتاب عزيز﴾؟","answer":"يكشف علو شأنه ومناعته المطلقة؛ فهو عزيز في مكانته وبيانه وهدايته وأثره، لا تنقصه معارضة ولا يستطيع أحد الإتيان بمثله. وجاء الوصف منكرًا لتفخيم هذه العزة وفتح النظر في وجوهها الكثيرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص549، تحت عنوان «الغرض من تنكير ﴿عزيز﴾»","url":""}]},{"id":"s41-93","number":93,"surah":41,"verses":[42],"references":[{"surah":41,"verses":[42]}],"verseLabel":"فصلت: 42","question":"لماذا عُبّر عن عصمة القرآن بقوله ﴿من بين يديه ولا من خلفه﴾؟","answer":"لأن ذكر الأمام والخلف كناية عن جميع الجهات، فيصور أن الباطل لا يجد إلى القرآن منفذًا من أي ناحية. واختيرت الجهتان الأظهر في حركة الإنسان ونظره لتقوما مقام سائر الجهات في عبارة موجزة قوية.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص555، تحت عنوان «تعليل الكناية في ﴿من بين يديه ولا من خلفه﴾»","url":""}]},{"id":"s41-94","number":94,"surah":41,"verses":[42],"references":[{"surah":41,"verses":[42]}],"verseLabel":"فصلت: 42","question":"ما دلالة وصف منزّل الكتاب بأنه ﴿حكيم حميد﴾؟","answer":"وصف المنزّل بالحكمة يلائم إحكام الكتاب وتنزهه عن الخلل، ووصفه بالحمد يلائم كماله وما في تنزيله من وجوه الخير التي يحمد عليها. فيربط الوصفان صفات القرآن بكمال مصدره، ويؤكدان عزته وتنزهه عن الباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص558–559، تحت عنوان «نكتة اصطفاء ﴿حكيم حميد﴾ للفاصلة»","url":""}]},{"id":"s41-95","number":95,"surah":41,"verses":[43],"references":[{"surah":41,"verses":[43]}],"verseLabel":"فصلت: 43","question":"كيف تسلّي الآية الرسول ﷺ بقولها ﴿ما يقال لك إلا ما قد قيل للرسل من قبلك﴾؟","answer":"تحصر ما يواجهه في سنة سبقت مع الرسل: فليس التكذيب والأذى أمرًا جديدًا خاصًا به. وهذا يثبت قلبه ويهوّن عليه قول المعاندين، إذ يسير في طريق إخوانه من الرسل وتتشابه مواقف المكذبين منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص562، تحت عنوان «غرض التعبير بأسلوب القصر في ﴿ما يقال لك﴾»","url":""}]},{"id":"s41-96","number":96,"surah":41,"verses":[43],"references":[{"surah":41,"verses":[43]}],"verseLabel":"فصلت: 43","question":"كيف يرتبط قوله ﴿إن ربك لذو مغفرة وذو عقاب أليم﴾ بتسلية الرسول قبله؟","answer":"جاء تعليلًا لما قبله: فإذا كان الرسول يلقى ما لقيه الرسل فليصبر، لأن ربه يغفر لأوليائه وينصرهم، ويعاقب أعداءه وينتقم منهم. وهكذا يطمئنه الختام إلى أن مصير الفريقين بيد ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص567، تحت عنوان «موقع جملة ﴿إن ربك لذو مغفرة﴾ مما قبلها»","url":""}]},{"id":"s41-145","number":145,"surah":41,"verses":[43],"references":[{"surah":41,"verses":[43]}],"verseLabel":"فصلت: 43","question":"لماذا وُصف العقاب بأنه ﴿أليم﴾ لا شديد؟","answer":"لأن ﴿أليم﴾ تستحضر أثر العقاب في النفس والجسد معًا وعمق ما يحدثه من وجع؛ فهي لا تكتفي بوصف قوته، بل تنقل أثره الحسي والمعنوي في المعاقَب، ويلزم من ذلك شدة العقاب أيضًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص570، تحت عنوان «نكتة اصطفاء ﴿أليم﴾»","url":""}]},{"id":"s41-97","number":97,"surah":41,"verses":[44],"references":[{"surah":41,"verses":[44]}],"verseLabel":"فصلت: 44","question":"ماذا يكشف افتراض ﴿ولو جعلناه قرآنًا أعجميًا﴾ عن حقيقة اعتراض المكذبين؟","answer":"يكشف أن اعتراضهم قائم على العناد لا على طلب البيان؛ فلو تحقق الفرض المخالف وجاء القرآن أعجميًا لاعترضوا على عدم تفصيله، كما اعترضوا عليه وهو عربي. وبذلك يصور الشرط تناقض حججهم وأنهم سيبحثون عن شبهة أيًّا كانت لغة الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص573–574، تحت عنوان «دلالة التعبير بـ(لو) في ﴿ولو جعلناه﴾»","url":""}]},{"id":"s41-98","number":98,"surah":41,"verses":[44],"references":[{"surah":41,"verses":[44]}],"verseLabel":"فصلت: 44","question":"ما سر جمع القرآن للمؤمنين بين الهدى والشفاء، وتقديم الهدى؟","answer":"الهدى يرشد إلى الحق ويقي من الانحراف، والشفاء يعالج أمراض القلب وما أصابه من الشبه والشهوات. فتقديم الهدى يلائم الدلالة على العلاج قبل الانتفاع به، والجمع بين الوصفين يبين تكامل الإرشاد والإصلاح، دون أن تقتضي الواو وحدها ترتيبًا زمنيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص586–587، تحت عنوان «دلالة العطف في ﴿وشفاء﴾»","url":""}]},{"id":"s41-99","number":99,"surah":41,"verses":[44],"references":[{"surah":41,"verses":[44]}],"verseLabel":"فصلت: 44","question":"لماذا عُبِّر عن ضلالهم بقوله ﴿وَهُوَ عَلَيْهِمْ عَمًى﴾ بدل «وهو عليهم ضلال»؟","answer":"لأن العمى يحول المعنى المجرد إلى صورة محسوسة؛ فكما يحرم الأعمى رؤية الطريق، حرم هؤلاء أنفسهم إدراك نور القرآن بسبب عنادهم. وفي اللفظ مقابلة ظاهرة مع كونه هدى للمؤمنين، وزيادة في تصوير شدة حرمان الكافرين وتحقير حالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص589، تحت عنوان «بلاغة الاستعارة التصريحية في لفظ ﴿عمى﴾»","url":""}]},{"id":"s41-100","number":100,"surah":41,"verses":[44],"references":[{"surah":41,"verses":[44]}],"verseLabel":"فصلت: 44","question":"ما وجه تمثيل غير المنتفعين بالقرآن بقوم ﴿يُنَادَوْنَ مِنْ مَكَانٍ بَعِيدٍ﴾؟","answer":"يشبّه حالهم في الإعراض وعدم الفهم بحال من ينادى من مسافة بعيدة فلا يعي الكلام ولا يستجيب له. فالمسافة تمثل الفجوة التي أحدثوها بينهم وبين القرآن، مع أن بيانه حاضر قريب.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص591–592، تحت عنوان «بلاغة التمثيل في ﴿أولئك ينادون من مكان بعيد﴾»","url":""}]},{"id":"s41-101","number":101,"surah":41,"verses":[45],"references":[{"surah":41,"verses":[45]}],"verseLabel":"فصلت: 45","question":"لماذا وُصفت الكلمة بأنها ﴿سَبَقَتْ مِنْ رَبِّكَ﴾؟","answer":"وصفها بالسبق يبين أنها قضاء ثابت نافذ لا يتخلف ولا يتبدل. ونسبتها إلى الرب تستحضر معاني العناية واللطف؛ فإمهال المختلفين رحمة تفتح لهم زمن التوبة قبل الحساب، مع تعظيم مصدر الكلمة وتأكيد سلطانها على الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص599، تحت عنوان «سر وصف ﴿كلمة﴾ بالجملة ﴿سبقت من ربك﴾»","url":""}]},{"id":"s41-102","number":102,"surah":41,"verses":[46],"references":[{"surah":41,"verses":[46]}],"verseLabel":"فصلت: 46","question":"ما دلالة مقابلة اللام في ﴿فَلِنَفْسِهِ﴾ بـ﴿فَعَلَيْهَا﴾ في قاعدة الجزاء؟","answer":"اللام تفيد اختصاص العامل بنفع عمله الصالح واستحقاقه ثوابه، وأما على فتصور تبعة الإساءة محمولة على صاحبها. فاختلاف الحرفين يلائم اختلاف الأثرين: نفع يعود إلى النفس وضرر يثقلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص611، تحت عنوان «بلاغة الطباق مع العدول في النظم»","url":""}]},{"id":"s41-103","number":103,"surah":41,"verses":[46],"references":[{"surah":41,"verses":[46]}],"verseLabel":"فصلت: 46","question":"ما سر التعبير بـ﴿الْعَبِيدِ﴾ في قوله ﴿وَمَا رَبُّكَ بِظَلَّامٍ لِلْعَبِيدِ﴾؟","answer":"وصفهم بالعبيد يبرز ملك الله لهم وافتقارهم إليه، مع غناه عن ظلمهم؛ فهو يدبر شؤونهم ويقوم بمصالحهم. فتجيء إضافة نفي الظلم إليهم تقريرًا لعدله، وتذكيرًا بما تقتضيه عبوديتهم من الاعتراف بفضله.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص615، تحت عنوان «سر التقييد بالجار والمجرور ﴿للعبيد﴾»","url":""}]},{"id":"s41-104","number":104,"surah":41,"verses":[47],"references":[{"surah":41,"verses":[47]}],"verseLabel":"فصلت: 47","question":"لماذا ذُكر خروج الثمرات والحمل والوضع بعد رد علم الساعة إلى الله؟","answer":"لأنها كلها أمور مستقبلية خفية لا يستطيع أحد أن يجزم بتفاصيل وقوعها؛ فكما اختص الله بعلم الساعة، أحاط وحده بموعد خروج كل ثمرة وما تحمل كل أنثى ومتى تضع. وبهذا ينتقل السياق من أعظم الغيب إلى دقائق تتكرر أمام الناس ليقرر شمول العلم الإلهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص626، تحت عنوان «وجه العطف بالواو»","url":""}]},{"id":"s41-105","number":105,"surah":41,"verses":[47],"references":[{"surah":41,"verses":[47]}],"verseLabel":"فصلت: 47","question":"لماذا أضيف الشركاء إلى الله في قوله يوم القيامة ﴿أَيْنَ شُرَكَائِي﴾؟","answer":"الإضافة جرت على زعم المشركين، لا على إثبات شريك لله؛ فهي تهكم وتقريع لهم على أن جعلوا من لا يستحق شريكًا لله. والمعنى: أين الذين زعمتم أنهم يشفعون لكم ويحفظونكم من العذاب؟","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص633، تحت عنوان «نكتة الإضافة إلى ياء المتكلم»","url":""}]},{"id":"s41-146","number":146,"surah":41,"verses":[47],"references":[{"surah":41,"verses":[47]}],"verseLabel":"فصلت: 47","question":"ما الذي يتضمنه قول المشركين يوم القيامة ﴿آذَنَّاكَ﴾؟","answer":"يتضمن إعلانهم وإقرارهم الصريح بأن لا أحد منهم يشهد بوجود شريك لله، بعد أن شهدت أحوالهم بعجز معبوداتهم. وجاء الفعل بصيغة الماضي في مقام الإقرار الحاضر ليؤكد تحققه من غير شك، فكان اعترافًا علنيًا ممزوجًا بالحسرة والندم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص634، تحت عنوان «نكتة التعبير بقوله ﴿آذناك﴾ مادة وصيغة»","url":""}]},{"id":"s41-106","number":106,"surah":41,"verses":[48],"references":[{"surah":41,"verses":[48]}],"verseLabel":"فصلت: 48","question":"لماذا اختير لفظ ﴿مَحِيصٍ﴾ دون «مفر» أو «مهرب»؟","answer":"المحيص هو المكان الضيق الذي يُلجأ إليه فرارًا ممزوجًا بالخوف والنفور، ولذلك يصور ذعرهم وبحثهم المحموم عن موضع ينجيهم. وهو أنسب من المفر أو المهرب؛ لأنهما لا يستلزمان هذا الذعر دائمًا، ثم جاء اللفظ نكرة في سياق النفي ليعم كل مكان محتمل للنجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص644، تحت عنوان «دلالة التعبير بلفظ ﴿محيص﴾ مادة وصيغة»","url":""}]},{"id":"s41-107","number":107,"surah":41,"verses":[49],"references":[{"surah":41,"verses":[49]}],"verseLabel":"فصلت: 49","question":"ما دلالة الجمع بين عدم سآمة الإنسان من دعاء الخير وشدة يأسه عند مس الشر؟","answer":"تقابل الآية بين إلحاح الإنسان في طلب الخير وعدم اكتفائه به، وبين سرعة انكساره إذا أصابه الشر. فتفضح ضعف صبره وتعلقه بالعطاء؛ يطول أمله عند النعمة وينقطع رجاؤه عند البلاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص652، تحت عنوان «بلاغة المقابلة في الآية»","url":""}]},{"id":"s41-108","number":108,"surah":41,"verses":[49],"references":[{"surah":11,"verses":[9]},{"surah":41,"verses":[49]}],"verseLabel":"فصلت: 49؛ هود: 9","question":"لماذا أُتبع وصف الإنسان بأنه ﴿يَئُوسٌ﴾ بقوله ﴿قَنُوطٌ﴾؟","answer":"ليجمع بين انقطاع الرجاء في باطنه وظهور أثره عليه انكسارًا وتضاؤلًا؛ فالقنوط يكمل صورة اليأس ويكشف شدته.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص653، تحت عنوان «براعة إتباع اليأس بالقنوط»","url":""}]},{"id":"s41-109","number":109,"surah":41,"verses":[50],"references":[{"surah":41,"verses":[50]}],"verseLabel":"فصلت: 50","question":"ماذا يكشف التعبير بالماضي في ﴿أَذَقْنَاهُ رَحْمَةً﴾ عن اغترار الإنسان بالنعمة؟","answer":"يكشف أن ما ذاقه قد يكون قليل المدة سريع الانصرام، ولا برهان له على بقائه؛ ومع ذلك يسارع إلى الغرور والجحود كأن النعمة دائمة مضمونة، فتفضح الصيغة تناقض ثقته بنفسه مع هشاشة ما بين يديه.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص660، تحت عنوان «وجه التعبير بفعل الإذاقة ماضيًا»","url":""}]},{"id":"s41-110","number":110,"surah":41,"verses":[50],"references":[{"surah":41,"verses":[50]}],"verseLabel":"فصلت: 50","question":"ماذا يكشف قوله ﴿وَمَا أَظُنُّ السَّاعَةَ قَائِمَةً﴾ عن أثر النعمة في الإنسان المغرور؟","answer":"يكشف أن كثرة النعم لا تقوده إلى الشكر، بل تجدّد في نفسه وهم نفي البعث وتثبته عليه؛ فلا يستجيب لمن يذكّره بالآخرة، لأنه يقيس المستقبل على رخائه الحاضر.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص664، تحت عنوان «سر التعبير بفعل الظن مضارعًا»","url":""}]},{"id":"s41-111","number":111,"surah":41,"verses":[50],"references":[{"surah":41,"verses":[50]}],"verseLabel":"فصلت: 50","question":"لماذا قال المغتر بالنعمة ﴿إِلَى رَبِّي﴾ ثم توقّع لنفسه الحسنى؟","answer":"لأنه فهم إحسان الله إليه في الدنيا على أنه دليل منزلة خاصة له عند ربه، فتوهم أن عنايته الدنيوية تضمن له حالًا أفضل في الآخرة إن وقع البعث؛ وبذلك حوّل النعمة من داعٍ للشكر إلى حجة موهومة على استحقاقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص666، تحت عنوان «سر إيثار لفظ الربوبية وإضافته إلى الياء»","url":""}]},{"id":"s41-112","number":112,"surah":41,"verses":[50],"references":[{"surah":41,"verses":[50]}],"verseLabel":"فصلت: 50","question":"لماذا وُصف العذاب بأنه ﴿غَلِيظٍ﴾؟","answer":"ليصور شدته وثقله وقسوته تصويرًا محسوسًا، فيقابل ما توهمه الكافر من الحسنى والكرامة بعاقبة بالغة الإيلام.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص672–673، تحت عنوان «نكتة وصف العذاب بالغليظ»","url":""}]},{"id":"s41-113","number":113,"surah":41,"verses":[51],"references":[{"surah":41,"verses":[51]}],"verseLabel":"فصلت: 51","question":"ما الذي تصوّره الكناية في قوله ﴿وَنَأَى بِجَانِبِهِ﴾؟","answer":"تصوّر إنسانًا يعطي النعمة جانبه وينصرف عن شكر المنعم في هيئة متكبر لا يكترث بما أُسدي إليه؛ فالإشاحة بالجانب تجعل الإعراض موقفًا مشاهدًا من الإهمال والغرور.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص680، تحت عنوان «بلاغة الكناية في ﴿بجانبه﴾»","url":""}]},{"id":"s41-114","number":114,"surah":41,"verses":[51],"references":[{"surah":41,"verses":[51]}],"verseLabel":"فصلت: 51","question":"لماذا وُصف دعاء الإنسان عند الضر بأنه ﴿عَرِيضٍ﴾؟","answer":"ليصوّر كثرة دعائه وتكراره بلا حد؛ فالعرض يستلزم امتدادًا وطولًا، وجاءت صيغة ﴿عريض﴾ مبالغةً تزيد صورة الإلحاح والتضرع عند الشدة وضوحًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص683، تحت عنوان «سر الوصف بلفظ ﴿عريض﴾ دلالة وصيغة»","url":""}]},{"id":"s41-115","number":115,"surah":41,"verses":[52],"references":[{"surah":41,"verses":[52]}],"verseLabel":"فصلت: 52","question":"لماذا سيقت الحجة للمكذبين على فرض: ﴿إِنْ كَانَ مِنْ عِنْدِ اللَّهِ ثُمَّ كَفَرْتُمْ بِهِ﴾؟","answer":"لأن الخطاب يجاري إنكارهم مؤقتًا ليستنزلهم إلى النظر في دلائل صدق القرآن؛ فيراجعون موقفهم بدل الإصرار عليه. فالفرض وسيلة لإلزامهم بالتأمل، لا تعبير عن شك في مصدر القرآن.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص690، تحت عنوان «وجه التعبير بـ﴿إن﴾ الشرطية»","url":""}]},{"id":"s41-147","number":147,"surah":41,"verses":[52],"references":[{"surah":41,"verses":[52]}],"verseLabel":"فصلت: 52","question":"ماذا يحقق السؤال: ﴿مَنْ أَضَلُّ مِمَّنْ هُوَ فِي شِقَاقٍ بَعِيدٍ﴾؟","answer":"ينفي أن يوجد أحد أشد ضلالًا ممن عادى القرآن بعد قيام دلائله، ويطرح الحكم في صورة سؤال يدعوهم إلى التفكير مع أنفسهم والرجوع عن غيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص692–693، تحت عنوان «بلاغة الاستفهام بـ﴿من﴾»","url":""}]},{"id":"s41-116","number":116,"surah":41,"verses":[52],"references":[{"surah":41,"verses":[52]}],"verseLabel":"فصلت: 52","question":"لماذا وُصفت معاداة الكافرين للقرآن بأنها ﴿شِقَاقٍ﴾؟","answer":"لأن الشقاق يجعل كل طرف في شق مقابل، فيصورهم وقد اختاروا جانب الخصومة والانفصال عن الحق وأهله.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص694، تحت عنوان «وجه التعبير بمفردة ﴿شقاق﴾»","url":""}]},{"id":"s41-117","number":117,"surah":41,"verses":[53],"references":[{"surah":41,"verses":[53]}],"verseLabel":"فصلت: 53","question":"لماذا عُبِّر عن دلائل الكون بلفظ ﴿الْآفَاقِ﴾ جمعًا؟","answer":"ليستوعب نواحي الكون وجهاته كلها وما فيها من آيات، فلا تُحصر الدلائل في مكان واحد أو فيما حول مكة؛ وبذلك يكون ظهورها أعم وأقوى في إقامة البرهان.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص700، تحت عنوان «وجه التعبير بلفظ ﴿الآفاق﴾ جمعًا»","url":""}]},{"id":"s41-148","number":148,"surah":41,"verses":[53],"references":[{"surah":41,"verses":[53]}],"verseLabel":"فصلت: 53","question":"لماذا ذُكرت آيات الآفاق قبل آيات الأنفس؟","answer":"لأن آيات الآفاق تعرض الدليل العام في الكون كله، ثم تُلحق بها الآيات الخاصة القريبة التي يجدها الإنسان في نفسه؛ فينتقل النظر من الشاهد الواسع إلى الشاهد المحسوس الملازم له.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص700، تحت عنوان «توجيه العطف بالواو»","url":""}]},{"id":"s41-118","number":118,"surah":41,"verses":[53],"references":[{"surah":41,"verses":[53]}],"verseLabel":"فصلت: 53","question":"إلى أي غاية ستظهر لهم آيات الله في الآفاق والأنفس؟","answer":"ستتتابع الآيات حتى يتضح لهم بلا موضع للشك أن ما جاء به الرسول هو الحق؛ فالمقصود أن تقود كثرة الدلائل ووضوحها إلى زوال الارتياب والتصديق بالوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص701–702، تحت عنوان «معنى ﴿حتى﴾»","url":""}]},{"id":"s41-119","number":119,"surah":41,"verses":[53],"references":[{"surah":41,"verses":[53]}],"verseLabel":"فصلت: 53","question":"ماذا يحقق الاستفهام في قوله تعالى: ﴿أَوَلَمْ يَكْفِ بِرَبِّكَ أَنَّهُ عَلَى كُلِّ شَيْءٍ شَهِيدٌ﴾؟","answer":"يقرر أن شهادة الله كافية في إثبات صدق رسوله، فيثبته على اليقين ولا يترك لتكذيب المشركين وزنًا. ويحمل الاستفهام أيضًا إنكار طلبهم دليلًا بعد شهادة الله المحيطة بكل شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص703، تحت عنوان «بلاغة الاستفهام بالهمزة»","url":""}]},{"id":"s41-120","number":120,"surah":41,"verses":[54],"references":[{"surah":41,"verses":[54]}],"verseLabel":"فصلت: 54","question":"لماذا افتُتحت خاتمة سورة فصلت بقوله ﴿أَلَا﴾؟","answer":"لإيقاظ السامع وجذب انتباهه إلى حقيقتين ختاميتين خطيرتين: شك المكذبين في لقاء ربهم، وإحاطة الله بكل شيء. فليست الآية خبرًا عابرًا، بل تذييل يجمع التحذير والتقرير.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص709، تحت عنوان «سر التعبير بـ﴿ألا﴾»","url":""}]},{"id":"s41-121","number":121,"surah":41,"verses":[54],"references":[{"surah":41,"verses":[54]}],"verseLabel":"فصلت: 54","question":"ما الصورة التي يرسمها قوله عن المكذبين ﴿فِي مِرْيَةٍ﴾؟","answer":"يصور شكهم وجدالهم كحفرة عميقة ألقوا أنفسهم فيها حتى أحاطت بهم وتعذر عليهم الخروج منها؛ وفي ذلك بيان لتمكن الشك من نفوسهم وبلوغه مبلغًا بعيدًا في إنكار البعث والحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص710، تحت عنوان «نوع المجاز وبلاغته في قوله ﴿في مرية﴾»","url":""}]},{"id":"s41-122","number":122,"surah":41,"verses":[54],"references":[{"surah":41,"verses":[54]}],"verseLabel":"فصلت: 54","question":"كيف يرد ﴿أَلَا إِنَّهُ بِكُلِّ شَيْءٍ مُحِيطٌ﴾ على شكهم في لقاء ربهم؟","answer":"إذا كان علم الله وقدرته محيطين بكل شيء فلا يخفى عليه مكذب، ولا يعجزه بعث أو جزاء؛ فتسقط شبهة الإفلات من لقائه وحسابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص713–714، تحت عنوان «سر التعبير بلفظ ﴿محيط﴾ مادة وصيغة»","url":""}]},{"id":"s42-1","number":1,"surah":42,"verses":[1],"references":[{"surah":42,"verses":[1]}],"verseLabel":"عنوان السورة","question":"ما مناسبة تسمية السورة بـ«الشورى» مع أن لفظ الشورى لم يرد فيها إلا مرة واحدة؟","answer":"لا تتوقف مناسبة الاسم على كثرة تكرار اللفظ؛ فالشورى علامة بارزة على بناء الجماعة المؤمنة واجتماعها على الدين. وتصل الموسوعة الاسم بوحدة الأمة ومرجعيتها في الوحي، وبما تقتضيه الشورى من اجتماع وتوافق يمنع التفرق.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص717–718، تحت عنوان «اسم السورة الكريمة ومناسبة تسميتها»","url":""}]},{"id":"s42-2","number":2,"surah":42,"verses":[1],"references":[{"surah":42,"verses":[1]}],"verseLabel":"مقدمة السورة","question":"ما دلالة اجتماع الوحي ووحدة الدين والشورى في بناء سورة واحدة؟","answer":"يجمع بناء السورة بين مصدر الهداية وهو الوحي، ومقصدها وهو وحدة الدين، والمنهج العملي لاجتماع المؤمنين وهو الشورى. فالرجوع إلى الوحي يضبط الحكم، والشورى تعين على وحدة الجماعة، ويؤكد البعث مسؤولية الناس عن استجابتهم لهذا المنهج.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص718–719، تحت عنوان «المحور العام للسورة»","url":""}]},{"id":"s42-3","number":3,"surah":42,"verses":[1],"references":[{"surah":42,"verses":[1]}],"verseLabel":"مقدمة السورة","question":"ما سر افتتاح السورة بالوحي وختمها به؟","answer":"يربط الافتتاح والخاتمة السورة بقضية الوحي: تبدأ ببيان أن الله يوحي إلى نبيه كما أوحى إلى السابقين، وتختم ببيان طرائق الوحي وما أوحاه إلى رسوله. فتعود الخاتمة إلى الأصل الذي قامت عليه دعوتها إلى الهداية ووحدة الدين.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص722، تحت عنوان «مناسبة مطلع السورة لخواتيمها»","url":""}]},{"id":"s42-4","number":4,"surah":42,"verses":[1,2],"references":[{"surah":42,"verses":[1,2]}],"verseLabel":"الشورى: 1–2","question":"لماذا اختص مطلع سورة الشورى بزيادة ﴿عسق﴾ بعد ﴿حم﴾؟","answer":"شاركت السورة سائر الحواميم في ﴿حم﴾، ثم تميزت عنها بزيادة ﴿عسق﴾؛ وفي زيادة الحروف مزيد تنبيه إلى تحدي العرب بالقرآن المؤلف من الحروف التي ينطقون بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص726–727، تحت عنوان «سر اختصاص السورة دون الحواميم بـ﴿عسق﴾»","url":""}]},{"id":"s42-5","number":5,"surah":42,"verses":[1,2,3],"references":[{"surah":42,"verses":[1,2,3]}],"verseLabel":"الشورى: 1–3","question":"لماذا جاء قوله: ﴿كَذَلِكَ يُوحِي إِلَيْكَ﴾ مباشرة بعد ﴿حم عسق﴾؟","answer":"لأن المطلع بالحروف نبه إلى شأن القرآن، ثم استؤنف الكلام ببيان مصدره وغرض السورة: أنه وحي من الله متصل برسالات الأنبياء ودعوتهم إلى التوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص729، تحت عنوان «علة فصل قوله ﴿كذلك يوحي﴾ عما قبله»","url":""}]},{"id":"s42-146","number":146,"surah":42,"verses":[1,2,3],"references":[{"surah":42,"verses":[1,2,3]}],"verseLabel":"الشورى: 1–3","question":"ما دلالة التشبيه في قوله: ﴿كَذَلِكَ يُوحِي إِلَيْكَ﴾؟","answer":"يشبه هذا الوحي بما أوحاه الله إلى الأنبياء من قبل في أصل الدعوة إلى توحيده؛ فيقرر وحدة مصدر الرسالات وينوه بعظمة ما يوحى إلى النبي ﷺ.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص730، تحت عنوان «بيان التشبيه وغرضه في ﴿كذلك يوحي إليك﴾»","url":""}]},{"id":"s42-6","number":6,"surah":42,"verses":[3],"references":[{"surah":42,"verses":[3]}],"verseLabel":"الشورى: 3","question":"لماذا قيل: ﴿يُوحِي إِلَيْكَ﴾ بالمضارع؟","answer":"ليصور الوحي متجددًا مستمرًا، لا واقعة انقضت؛ وفي ذلك تثبيت للرسول ﷺ وتنويه بتتابع ما يوحى إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص731، تحت عنوان «دلالة التعبير بالفعل المضارع في ﴿يوحي﴾»","url":""}]},{"id":"s42-7","number":7,"surah":42,"verses":[3],"references":[{"surah":42,"verses":[3]}],"verseLabel":"الشورى: 3","question":"لماذا خُتم خبر الوحي باسمي الله ﴿الْعَزِيزُ الْحَكِيمُ﴾؟","answer":"لأن العزيز لا يعجزه إنفاذ وحيه، والحكيم يضع الرسالة في موضعها ويشرع ما يصلح عباده؛ فالاسمان يقرران قوة مصدر الوحي وإحكامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص734، تحت عنوان «سر إيثار الاسمين الكريمين ﴿العزيز الحكيم﴾»","url":""}]},{"id":"s42-8","number":8,"surah":42,"verses":[3,4],"references":[{"surah":42,"verses":[3,4]}],"verseLabel":"الشورى: 3–4","question":"ما دلالة الانتقال من الوحي إلى تقرير ملك الله لما في السماوات والأرض؟","answer":"تقرير ملكه الشامل يثبت ما دل عليه وصفه بالعزيز الحكيم؛ فمن له السماوات والأرض لا تعجزه إرادة ولا يخرج شيء عن سلطانه. فالجملة تعلل كمال قدرته وحكمته، وتقرر أن الوحي صادر عن المالك المتصرف في الجميع.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص737، تحت عنوان «موقع جملة ﴿له ما في السماوات وما في الأرض﴾ مما قبلها، ودلالتها»","url":""}]},{"id":"s42-9","number":9,"surah":42,"verses":[4],"references":[{"surah":42,"verses":[4]}],"verseLabel":"الشورى: 4","question":"لماذا وُصف مالك السماوات والأرض بأنه ﴿الْعَلِيُّ الْعَظِيمُ﴾؟","answer":"لأن كمال ملكه يقتضي تنزهه عن أن يشبهه شيء؛ فالعلي منزه عن مماثلة خلقه، والعظيم مستحق لكل إجلال، وفي ذلك تعظيم لمصدر الوحي السابق ذكره.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص739، تحت عنوان «سر اصطفاء الاسمين الجليلين واقترانهما»","url":""}]},{"id":"s42-10","number":10,"surah":42,"verses":[4,5],"references":[{"surah":42,"verses":[4,5]}],"verseLabel":"الشورى: 4–5","question":"لماذا انتقل من وصف الله بـ﴿الْعَلِيُّ الْعَظِيمُ﴾ إلى قوله: ﴿تَكَادُ السَّمَاوَاتُ يَتَفَطَّرْنَ﴾؟","answer":"جاء مشهد تفطر السماوات تقريرًا محسوسًا لعظمته؛ فبعد أن ذكر العظمة وصفًا أرى أثرها في أعظم المخلوقات، وهي تكاد تتشقق هيبةً وإجلالًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص741، تحت عنوان «علة فصل قوله ﴿تكاد السماوات﴾»","url":""}]},{"id":"s42-11","number":11,"surah":42,"verses":[5],"references":[{"surah":42,"verses":[5]}],"verseLabel":"الشورى: 5","question":"ماذا تضيف كلمة ﴿تَكَادُ﴾ إلى مشهد تفطر السماوات؟","answer":"تقرب التفطر من الوقوع من غير أن تخبر بوقوعه؛ فتجعل السماوات في حال مستمرة من شدة الهيبة أمام عظمة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص741–742، تحت عنوان «دلالة التعبير بالفعل ﴿تكاد﴾ مادة وصيغة»","url":""}]},{"id":"s42-12","number":12,"surah":42,"verses":[5],"references":[{"surah":42,"verses":[5]}],"verseLabel":"الشورى: 5","question":"لماذا جمع الملائكة بين تسبيح الله والاستغفار لمن في الأرض؟","answer":"لأنهم ينزهون الله إجلالًا لعظمته، ثم يستغفرون لعباده لما يرونه من تقصيرهم؛ فيجتمع تعظيم الخالق والشفقة على المخلوق في مشهد واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص746، تحت عنوان «دلالة الواو في ﴿ويستغفرون﴾»","url":""}]},{"id":"s42-13","number":13,"surah":42,"verses":[5],"references":[{"surah":42,"verses":[5]}],"verseLabel":"الشورى: 5","question":"لماذا قيل: ﴿وَيَسْتَغْفِرُونَ لِمَنْ فِي الْأَرْضِ﴾ ولم يقل: للمؤمنين؟","answer":"جيء بالموصول العام ليتسع المعنى: فالاستغفار للمؤمنين، ويشمل العصاة منهم بطلب المغفرة، ويمكن أن يكون لغير المؤمن بطلب ما يوصله إلى أسباب المغفرة من الإيمان والتوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص747، تحت عنوان «الغرض من التعبير بالاسم الموصول (من)»","url":""}]},{"id":"s42-14","number":14,"surah":42,"verses":[5],"references":[{"surah":42,"verses":[5]}],"verseLabel":"الشورى: 5","question":"ماذا يضيف قوله: ﴿أَلَا إِنَّ اللَّهَ هُوَ الْغَفُورُ الرَّحِيمُ﴾ بعد استغفار الملائكة؟","answer":"يقرر أن قبول الاستغفار والمغفرة والرحمة كلها بيد الله، ويبشر بأن رحمته تزيد عباده فوق ما طلبته الملائكة لهم؛ فجاء التذييل تثبيتًا للرجاء بعد مشهد الهيبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص747–748، تحت عنوان «موقع جملة ﴿ألا إن الله﴾ مما قبلها، ودلالتها»","url":""}]},{"id":"s42-15","number":15,"surah":42,"verses":[6],"references":[{"surah":42,"verses":[6]}],"verseLabel":"الشورى: 6","question":"لماذا وُصف الله بأنه ﴿حَفِيظٌ عَلَيْهِمْ﴾؟","answer":"لأن ﴿حفيظ﴾ صيغة مبالغة تصور إحاطته بكثرة المعبودين والعابدين وأعمالهم جميعًا؛ فلا يفوته شيء منها وسيجازي كلًا بما عمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص755، تحت عنوان «دلالة التعبير بلفظ ﴿حفيظ﴾»","url":""}]},{"id":"s42-147","number":147,"surah":42,"verses":[6],"references":[{"surah":42,"verses":[6]}],"verseLabel":"الشورى: 6","question":"لماذا قوبل ﴿اللَّهُ حَفِيظٌ عَلَيْهِمْ﴾ بقوله للنبي ﷺ: ﴿وَمَا أَنْتَ عَلَيْهِمْ بِوَكِيلٍ﴾؟","answer":"ليثبت أن حسابهم وحفظ أعمالهم لله وحده، ويُسلي الرسول ﷺ بأن وظيفته البلاغ لا إجبارهم على الإيمان ولا تحمل تبعة إعراضهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص755–756، تحت عنوان «معنى الواو ودلالتها في ﴿وما أنت عليهم﴾»","url":""}]},{"id":"s42-16","number":16,"surah":42,"verses":[3,7],"references":[{"surah":42,"verses":[3,7]}],"verseLabel":"الشورى: 3، 7","question":"لماذا قيل هنا: ﴿أَوْحَيْنَا إِلَيْكَ﴾ بالماضي بعد قوله أول السورة: ﴿يُوحِي إِلَيْكَ﴾؟","answer":"المضارع في المطلع يصور تجدد الوحي، أما الماضي هنا فيقرر تحقق إنزال هذا القرآن وثبوته، وإسناده إلى ضمير العظمة يعظم الوحي والموحي به.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص761، تحت عنوان «دلالة التعبير بالماضي ﴿أوحينا﴾، وإسناده إلى ضمير العظمة»","url":""}]},{"id":"s42-17","number":17,"surah":42,"verses":[7],"references":[{"surah":42,"verses":[7]}],"verseLabel":"الشورى: 7","question":"لماذا قُيّد القرآن بوصف ﴿عَرَبِيًّا﴾ في خطاب النبي ﷺ؟","answer":"لتعظيم شأن القرآن وبيان وضوحه وفصاحته للمخاطبين الأولين، وليكون أنسب بحال المنذَرين الذين يتلقونه بلغتهم ثم يبلغونه سائر الأمم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص762، تحت عنوان «الغرض من تنكير المفعول به، وسر تقييده بالوصف ﴿عربيًا﴾»","url":""}]},{"id":"s42-18","number":18,"surah":42,"verses":[7],"references":[{"surah":42,"verses":[7]}],"verseLabel":"الشورى: 7","question":"لماذا تكرر فعل الإنذار في قوله: ﴿وَتُنْذِرَ يَوْمَ الْجَمْعِ﴾؟","answer":"لإفراد يوم القيامة بعناية وتهويل بعد الإنذار العام لأهل مكة ومن حولها؛ فإعادة الفعل تجعل ذلك اليوم مقصدًا مستقلًا للإنذار وتلفت إلى عظم أهواله.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص765–766، تحت عنوان «دلالة تكرار فعل الإنذار»","url":""}]},{"id":"s42-19","number":19,"surah":42,"verses":[7],"references":[{"surah":42,"verses":[7]}],"verseLabel":"الشورى: 7","question":"لماذا سميت القيامة ﴿يَوْمَ الْجَمْعِ﴾؟","answer":"لأنها تجمع الخلائق كلهم للحساب، وتجتمع فيها الأرواح بالأجساد وأهل الأرض بأهل السماء؛ فالإضافة تهول اليوم بما يحشده من الخلق والمصائر.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص766–767، تحت عنوان «الغرض من الإضافة في ﴿يوم الجمع﴾»","url":""}]},{"id":"s42-148","number":148,"surah":42,"verses":[7],"references":[{"surah":42,"verses":[7]}],"verseLabel":"الشورى: 7","question":"لماذا أعقب ﴿يَوْمَ الْجَمْعِ﴾ بقوله: ﴿فَرِيقٌ فِي الْجَنَّةِ وَفَرِيقٌ فِي السَّعِيرِ﴾؟","answer":"لبيان نتيجة ذلك الجمع: يجتمع الناس في الموقف ثم لا تتساوى مصائرهم، بل ينقسمون فريقين بحسب الإيمان والعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص768، تحت عنوان «موقع جملة ﴿فريق في الجنة﴾ مما قبلها، ودلالته»","url":""}]},{"id":"s42-20","number":20,"surah":42,"verses":[7,8],"references":[{"surah":42,"verses":[7,8]}],"verseLabel":"الشورى: 7–8","question":"لماذا قيل: ﴿لَجَعَلَهُمْ أُمَّةً وَاحِدَةً﴾ ولم يقل: لخلقهم؟","answer":"لأن الخلق إيجادهم من العدم، أما الجعل هنا فتصييرهم بعد وجودهم مجتمعين على ملة واحدة؛ فاختير اللفظ الأدق لإظهار القدرة على توجيههم معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص773، تحت عنوان «دلالة التعبير بالجعل مادة وصيغة»","url":""}]},{"id":"s42-21","number":21,"surah":42,"verses":[8],"references":[{"surah":42,"verses":[8]}],"verseLabel":"الشورى: 8","question":"ما سر التعبير بدخول من يشاء الله ﴿فِي رَحْمَتِهِ﴾؟","answer":"الرحمة هنا يراد بها الجنة على التوجيه المذكور، فأطلق اسم الرحمة وأريد محلها. وتصويرهم داخلين فيها، بدل الاكتفاء بذكر نيلها، يوحي بتمكنهم من النعيم وإحاطته بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص775، تحت عنوان «بلاغة المجاز في الآية»","url":""}]},{"id":"s42-22","number":22,"surah":42,"verses":[8],"references":[{"surah":42,"verses":[8]}],"verseLabel":"الشورى: 8","question":"لماذا أُظهر وصف ﴿الظَّالِمُونَ﴾ بدل أن يقال: وهم ما لهم من ولي؟","answer":"لتسجيل سبب حرمانهم والوعيد عليهم؛ فوضع وصف الظلم مكان الضمير يعلن أن ظلمهم هو الذي أوردهم هذا المصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص775–776، تحت عنوان «دلالة الواو والتعبير بالجملة الاسمية»","url":""}]},{"id":"s42-23","number":23,"surah":42,"verses":[6,9],"references":[{"surah":42,"verses":[6,9]}],"verseLabel":"الشورى: 6، 9","question":"لماذا عاد السياق إلى إنكار اتخاذ الأولياء بقوله: ﴿أَمِ اتَّخَذُوا مِنْ دُونِهِ أَوْلِيَاءَ﴾؟","answer":"ليجدد إنكار شركهم بعد عرض دلائل الوحي والملك والقدرة؛ فكأن كل حجة سبقت تستدعي سؤالًا توبيخيًا جديدًا: كيف بقي لهم بعد ذلك ولي من دون الله؟","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص780، تحت عنوان «معنى ﴿أم﴾ ودلالتها»","url":""}]},{"id":"s42-149","number":149,"surah":42,"verses":[6,9],"references":[{"surah":42,"verses":[6,9]}],"verseLabel":"الشورى: 6، 9","question":"ماذا يفيد القصر في قوله: ﴿فَاللَّهُ هُوَ الْوَلِيُّ﴾؟","answer":"يحصر الولاية الحقيقية الكاملة في الله؛ فتعريف الطرفين وضمير الفصل يبطلان ولاية ما اتخذوه من دونه، ويثبتان أنه وحده المتولي لعباده.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص783، تحت عنوان «بلاغة أسلوب القصر، ودلالة ضمير الفصل في قوله ﴿فالله هو الولي﴾»","url":""}]},{"id":"s42-24","number":24,"surah":42,"verses":[9],"references":[{"surah":42,"verses":[9]}],"verseLabel":"الشورى: 9","question":"لماذا استُدل على ولاية الله بقوله: ﴿وَهُوَ يُحْيِي الْمَوْتَى﴾؟","answer":"لأن من يملك إعادة الخلق بعد الموت هو المستحق وحده للولاية والاعتماد؛ فأُدمج إثبات البعث في الرد على الشرك وهدم دعوى الأولياء العاجزين.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص783، تحت عنوان «بلاغة الإدماج في قوله ﴿وهو يحيي الموتى﴾»","url":""}]},{"id":"s42-25","number":25,"surah":42,"verses":[10],"references":[{"surah":42,"verses":[10]}],"verseLabel":"الشورى: 10","question":"ما سر التعبير عن مرجع الاختلاف بقوله ﴿فَحُكْمُهُ إِلَى اللَّهِ﴾ دون «فالله يحكم فيه»؟","answer":"المصدر ﴿حكمه﴾ مجرد من الزمن، فيقرر رجوع الحكم إلى الله تقريرًا ثابتًا غير مقيد بحال معينة. والتعبير الخبري يتضمن طلب الاحتكام إلى ما أنزله، فيجعل لزوم هذا الرجوع أمرًا مقررًا مؤكدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص790، تحت عنوان «دلالة التعبير بالمصدر (حكمه)»","url":""}]},{"id":"s42-26","number":26,"surah":42,"verses":[10],"references":[{"surah":42,"verses":[10]}],"verseLabel":"الشورى: 10","question":"لماذا جاء التوكل ماضيًا في ﴿تَوَكَّلْتُ﴾ والإنابة مضارعة في ﴿أُنِيبُ﴾؟","answer":"لأن التوكل أصل ثابت استقر في القلب، فجاء بالماضي، أما الإنابة فهي رجوع يتجدد بتجدد الأحوال والأعمال، فجاءت بالمضارع.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص793، تحت عنوان «دلالة التعبير بالماضي ﴿توكلت﴾، والمضارع ﴿أنيب﴾»","url":""}]},{"id":"s42-27","number":27,"surah":42,"verses":[11],"references":[{"surah":42,"verses":[11]}],"verseLabel":"الشورى: 11","question":"لماذا جُمعت أزواج الناس وأزواج الأنعام في آية واحدة؟","answer":"ليجمع الإيجاز بين استمرار نسل الإنسان وبين ما تقوم به معيشته من تناسل الأنعام ومنافعها؛ فالتزاوج نظام ممتد في العالم الحي لا نعمة منفصلة للإنسان وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص800، تحت عنوان «بلاغة واو العطف، ودورها الوظيفي في الإيجاز»","url":""}]},{"id":"s42-150","number":150,"surah":42,"verses":[11],"references":[{"surah":42,"verses":[11]}],"verseLabel":"الشورى: 11","question":"لماذا اختير فعل ﴿يَذْرَؤُكُمْ﴾ للتعبير عن التكاثر؟","answer":"لأن الذرء يدل على البث والتكثير، وجاء مضارعًا ليصور تجدد الأجيال واستمرار النماء عبر هذا النظام.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص802، تحت عنوان «بلاغة اختيار الذرء مادة وصيغة»","url":""}]},{"id":"s42-151","number":151,"surah":42,"verses":[11],"references":[{"surah":42,"verses":[11]}],"verseLabel":"الشورى: 11","question":"ماذا تضيف ﴿فِيهِ﴾ في قوله: ﴿يَذْرَؤُكُمْ فِيهِ﴾؟","answer":"تصور نظام التزاوج كأنه محيط تجري في داخله أسباب التكاثر والنماء؛ فليست الظرفية مكانًا حسيًا، بل تصويرًا لتمكن هذا النظام من حياة الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص803، تحت عنوان «بلاغة حرف الظرفية»","url":""}]},{"id":"s42-28","number":28,"surah":42,"verses":[11],"references":[{"surah":42,"verses":[11]}],"verseLabel":"الشورى: 11","question":"لماذا قيل: ﴿لَيْسَ كَمِثْلِهِ شَيْءٌ﴾ بدل «ليس مثله شيء»؟","answer":"لأن التعبير يسلك طريق الكناية الأبلغ في نفي النظير: فإذا نُفي أن يكون لمثله مثل، كان نفي المماثلة عنه سبحانه أبلغ وأرسخ، من غير أن يثبت له مثلًا أصلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص805، تحت عنوان «بلاغة الكناية في جملة ﴿ليس كمثله شيء﴾»","url":""}]},{"id":"s42-29","number":29,"surah":42,"verses":[11],"references":[{"surah":42,"verses":[11]}],"verseLabel":"الشورى: 11","question":"لماذا جمع قوله: ﴿لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ الْبَصِيرُ﴾ بين النفي والإثبات؟","answer":"ليجمع أصل التنزيه كاملًا: ينفي عن الله مماثلة المخلوقات، ويثبت له صفات الكمال على الوجه اللائق به؛ فلا يؤدي التنزيه إلى تعطيل صفاته، ولا يؤدي إثباتها إلى تشبيهه بخلقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص808، تحت عنوان «بلاغة الجمع بين جملتي النفي والإثبات»","url":""}]},{"id":"s42-30","number":30,"surah":42,"verses":[12],"references":[{"surah":42,"verses":[12]}],"verseLabel":"الشورى: 12","question":"لماذا أعقب ﴿لَهُ مَقَالِيدُ السَّمَاوَاتِ وَالْأَرْضِ﴾ بذكر بسط الرزق وتقديره؟","answer":"لأن توسيع الرزق وتضييقه أثر مشاهد من آثار امتلاك تلك الخزائن؛ فانتقل من تقرير الملك العام إلى مثال يمسه الناس في حياتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص809–810، تحت عنوان «موقع جملة بسط الرزق وتقديره»","url":""}]},{"id":"s42-152","number":152,"surah":42,"verses":[12],"references":[{"surah":42,"verses":[12]}],"verseLabel":"الشورى: 12","question":"لماذا خُتم بسط الرزق وتقديره بقوله: ﴿إِنَّهُ بِكُلِّ شَيْءٍ عَلِيمٌ﴾؟","answer":"ليبين أن التوسعة والتضييق ليسا عشوائيين، بل يجريان بعلم كامل بأحوال العباد وما يصلحهم؛ فالعلم أساس هذا التقدير الحكيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج52، ص812، تحت عنوان «علة فصل جملة ﴿إنه بكل شيء عليم﴾»","url":""}]},{"id":"s42-31","number":31,"surah":42,"verses":[13],"references":[{"surah":3,"verses":[103]},{"surah":42,"verses":[13]}],"verseLabel":"الشورى: 13؛ آل عمران: 103","question":"لماذا قُيد النهي بقوله: ﴿وَلَا تَتَفَرَّقُوا فِيهِ﴾؟","answer":"ليحدد موطن التفرق المنهي عنه: الدين الذي شرعه الله وجمع عليه رسله؛ فالمخالفة المذمومة هي تمزيق وحدته والخروج عن أصوله الجامعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص21، تحت عنوان «سر تقييد فعل ﴿تتفرقوا﴾ بقيد ﴿فيه﴾»","url":""}]},{"id":"s42-32","number":32,"surah":42,"verses":[13],"references":[{"surah":42,"verses":[13]}],"verseLabel":"الشورى: 13","question":"لماذا قيل للنبي ﷺ: ﴿وَالَّذِي أَوْحَيْنَا إِلَيْكَ﴾، وقيل في الرسل قبله: ﴿وَصَّى بِهِ﴾؟","answer":"لأن الوصية تؤكد أصل الدين الذي عُهد إلى الرسل بحفظه، أما الإيحاء إلى النبي ﷺ فينوه بتشريفه وبتفصيل الشريعة الكاملة التي أنزلت إليه، مع وحدة أصل الرسالات.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص17، تحت عنوان «بلاغة استعمال ﴿أوحينا﴾ مادة وصيغة دون (وصينا)»","url":""}]},{"id":"s42-33","number":33,"surah":42,"verses":[13],"references":[{"surah":42,"verses":[13]}],"verseLabel":"الشورى: 13","question":"لماذا خُص نوح وإبراهيم وموسى وعيسى مع النبي ﷺ بالذكر؟","answer":"لأنهم أولو العزم وأصحاب الشرائع العظيمة التي اتبعتها الأمم؛ فذكرهم يبرز أن أصل الدين الجامع ثابت في أعظم الرسالات.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص19، تحت عنوان «توجيه تخصيص هؤلاء المرسلين بالذكر»","url":""}]},{"id":"s42-34","number":34,"surah":42,"verses":[13],"references":[{"surah":42,"verses":[13]}],"verseLabel":"الشورى: 13","question":"لماذا عبّر عن العمل بالدين بقوله: ﴿أَقِيمُوا الدِّينَ﴾؟","answer":"شُبه الدين ببناء يقام مستقيمًا؛ فالإقامة ليست مجرد معرفته، بل حفظ أصوله والعمل بها وإظهاره من غير اعوجاج أو تعطيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص20، تحت عنوان «دلالة انتقاء مفردة ﴿أقيموا﴾ مادة وصيغة»","url":""}]},{"id":"s42-153","number":153,"surah":42,"verses":[13],"references":[{"surah":42,"verses":[13]}],"verseLabel":"الشورى: 13","question":"لماذا جُمع بين الأمر بـ﴿أَقِيمُوا الدِّينَ﴾ والنهي ﴿وَلَا تَتَفَرَّقُوا فِيهِ﴾؟","answer":"لأن إقامة الدين تحفظ استقامة العمل به، والنهي عن التفرق يحفظ وحدة أهله عليه؛ فاجتمع إصلاح المضمون وصيانة الجماعة من التمزق.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص21، تحت عنوان «نوع الواو في قوله ﴿ولا تتفرقوا﴾»","url":""}]},{"id":"s42-35","number":35,"surah":42,"verses":[13],"references":[{"surah":42,"verses":[13]}],"verseLabel":"الشورى: 13","question":"لماذا قيل: ﴿اللَّهُ يَجْتَبِي إِلَيْهِ﴾ ولم يكتف بقوله «يجتبي»؟","answer":"للدلالة على شرف المجتبى وقربه؛ فالاصطفاء ليس اختيارًا مجردًا، بل تقريب إلى الله وتشريف بمنزلة خاصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص25، تحت عنوان «علة ذكر ﴿إليه﴾ دون الاكتفاء بالإطلاق»","url":""}]},{"id":"s42-154","number":154,"surah":42,"verses":[13],"references":[{"surah":42,"verses":[13]}],"verseLabel":"الشورى: 13","question":"لماذا عُطفت الهداية على الاجتباء في قوله: ﴿وَيَهْدِي إِلَيْهِ مَنْ يُنِيبُ﴾؟","answer":"لبيان طريقين من فضل الله: اجتباء خاص لمن يصطفيه، وهداية يوفق إليها من يرجع إليه ويطلب الحق؛ فالهداية أوسع، والاجتباء أخص.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص26، تحت عنوان «دلالة عطف الهداية على الاجتباء»","url":""}]},{"id":"s42-36","number":36,"surah":42,"verses":[13,14],"references":[{"surah":42,"verses":[13,14]}],"verseLabel":"الشورى: 13–14","question":"لماذا جاء خبر تفرق السابقين مباشرة بعد الأمر: ﴿وَلَا تَتَفَرَّقُوا فِيهِ﴾؟","answer":"ليحذر المخاطبين من تكرار طريق من قبلهم؛ فكأن السياق يقول: الزموا الوحدة، فقد تفرق السابقون مع قيام العلم، فلا تجعلوا تاريخهم يتكرر فيكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص31، تحت عنوان «نوع الواو ودلالتها على المحذوف»","url":""}]},{"id":"s42-37","number":37,"surah":42,"verses":[14],"references":[{"surah":42,"verses":[14]}],"verseLabel":"الشورى: 14","question":"لماذا كُشف سبب التفرق بقوله: ﴿بَغْيًا﴾؟","answer":"لأن البغي يجمع الظلم والحسد وطلب الاستعلاء؛ فاختياره يكشف أن اختلافهم لم ينشأ من نقص الدليل، بل من فساد الإرادة مع معرفة الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص35، تحت عنوان «بلاغة استعمال مفردة ﴿بغيًا﴾»","url":""}]},{"id":"s42-155","number":155,"surah":42,"verses":[14],"references":[{"surah":42,"verses":[14]}],"verseLabel":"الشورى: 14","question":"ماذا يضيف قيد ﴿بَيْنَهُمْ﴾ بعد قوله: ﴿بَغْيًا﴾؟","answer":"يكشف أن البغي نشأ وتبادل داخل جماعتهم نفسها، مع أن وحدة العلم والدين كانت تقتضي الألفة؛ فزاد القيد قبح التفرق وفضح دوافعه الداخلية.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص35، تحت عنوان «دلالة تقييد البغي بشبه الجملة»","url":""}]},{"id":"s42-38","number":38,"surah":42,"verses":[14],"references":[{"surah":42,"verses":[14]}],"verseLabel":"الشورى: 14","question":"لماذا سُمّي قضاء الإمهال ﴿كَلِمَةً سَبَقَتْ مِنْ رَبِّكَ﴾؟","answer":"للدلالة على ثبات قضاء الله ونفاذه؛ فما سبق من وعده بالإمهال لا يتبدل، ولذلك تأخر الفصل إلى موعده المقدر.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص37، تحت عنوان «دلالة التعبير بالكلمة»","url":""}]},{"id":"s42-39","number":39,"surah":42,"verses":[14],"references":[{"surah":42,"verses":[14]}],"verseLabel":"الشورى: 14","question":"لماذا قيل عن المتأخرين: ﴿أُورِثُوا الْكِتَابَ﴾؟","answer":"لأن الكتاب وصل إليهم من أسلافهم ميسرًا حاضرًا كالميراث؛ فالتعبير يقوي مؤاخذتهم حين شكوا مع سهولة طريق العلم وقيام الحجة بين أيديهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص41، تحت عنوان «نكتة استعمال مفردة ﴿أورثوا﴾ مادة وصيغة»","url":""}]},{"id":"s42-40","number":40,"surah":42,"verses":[15],"references":[{"surah":42,"verses":[15]}],"verseLabel":"الشورى: 15","question":"إلى ماذا يشير اسم الإشارة في قوله: ﴿فَلِذَلِكَ فَادْعُ﴾؟","answer":"يشير إلى الدين الواحد الذي شرعه الله وأوصى به رسله، وإلى ضرورة جمع الناس عليه بعد ما وقع من التفرق والشك؛ فالدعوة رد إلى الأصل الجامع.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص47، تحت عنوان «دلالة استعمال اسم الإشارة للبعيد»","url":""}]},{"id":"s42-156","number":156,"surah":42,"verses":[15],"references":[{"surah":42,"verses":[15]}],"verseLabel":"الشورى: 15","question":"لماذا قُدم ﴿فَلِذَلِكَ﴾ على الأمر ﴿فَادْعُ﴾؟","answer":"للعناية بسبب الدعوة وإبرازه قبل التكليف؛ فالتفرق والشك يجعلان رد الناس إلى الدين الحق غاية ملحة تتقدم في الذهن على فعل الدعوة نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص47، تحت عنوان «علة تقديم شبه الجملة على متعلقها»","url":""}]},{"id":"s42-41","number":41,"surah":42,"verses":[15],"references":[{"surah":42,"verses":[15]}],"verseLabel":"الشورى: 15","question":"لماذا عُطف ﴿وَاسْتَقِمْ كَمَا أُمِرْتَ﴾ على الأمر ﴿فَادْعُ﴾؟","answer":"لأن الداعي لا يكفي أن يبلغ الناس، بل يجب أن يكون ثابتًا على ما يدعو إليه؛ فتجتمع الدعوة بالقول والقدوة بالعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص48، تحت عنوان «نكتة عطف الأمر بالاستقامة على الأمر بالدعوة»","url":""}]},{"id":"s42-157","number":157,"surah":42,"verses":[15],"references":[{"surah":42,"verses":[15]}],"verseLabel":"الشورى: 15","question":"لماذا أتبع الدعوة والاستقامة بالنهي: ﴿وَلَا تَتَّبِعْ أَهْوَاءَهُمْ﴾؟","answer":"ليحميهما من ضغط المخالفين؛ فاتباع أهوائهم يفسد صدق الدعوة ويصرف عن الاستقامة، فجاء النهي سياجًا للثبات على الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص49–50، تحت عنوان «وجه عطف النهي ﴿ولا تتبع﴾ على الأمر ﴿فادع﴾»","url":""}]},{"id":"s42-42","number":42,"surah":42,"verses":[15],"references":[{"surah":42,"verses":[15]}],"verseLabel":"الشورى: 15","question":"لماذا انتقل من الدعوة إلى وحدة الدين إلى إعلان: ﴿آمَنْتُ بِمَا أَنْزَلَ اللَّهُ مِنْ كِتَابٍ﴾؟","answer":"لأن الإيمان بجميع الوحي تطبيق عملي لوحدة الدين، ورد على من فرقوا فصدقوا بعض الكتب وكفروا ببعض؛ فجمع الإعلان ما فرقه المختلفون.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص51، تحت عنوان «دلالة عطف الأمر (قل) على السابق»","url":""}]},{"id":"s42-158","number":158,"surah":42,"verses":[15],"references":[{"surah":42,"verses":[15]}],"verseLabel":"الشورى: 15","question":"ماذا يفيد تنكير ﴿كِتَابٍ﴾ في قوله: ﴿مِنْ كِتَابٍ﴾؟","answer":"يفيد العموم: أي آمنت بكل كتاب أنزله الله من غير تفريق؛ فتنسجم العبارة مع دعوة السورة إلى وحدة أصل الرسالات.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص53، تحت عنوان «غرض تنكير ﴿كتاب﴾»","url":""}]},{"id":"s42-43","number":43,"surah":42,"verses":[15],"references":[{"surah":42,"verses":[15]}],"verseLabel":"الشورى: 15","question":"لماذا اقترن قوله: ﴿آمَنْتُ بِمَا أَنْزَلَ اللَّهُ﴾ بقوله: ﴿وَأُمِرْتُ لِأَعْدِلَ بَيْنَكُمُ﴾؟","answer":"ليجمع بين أصل الاعتقاد وأثره العملي؛ فالإيمان بالوحي يقتضي عدلًا لا يتبدل باختلاف المخاطبين، والعدل نفسه أمر من الله لا مصلحة بشرية عارضة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص53، تحت عنوان «دلالة واو العطف في قوله ﴿وأمرت﴾»","url":""}]},{"id":"s42-44","number":44,"surah":42,"verses":[15],"references":[{"surah":42,"verses":[15]}],"verseLabel":"الشورى: 15","question":"ما سر التوازي بين ﴿اللَّهُ رَبُّنَا وَرَبُّكُمْ﴾ و﴿لَنَا أَعْمَالُنَا وَلَكُمْ أَعْمَالُكُمْ﴾؟","answer":"وحدة الرب تدعو الفريقين إلى الاجتماع على الحق، ثم يقرر توزيع الأعمال أن كل فريق مسؤول عن كسبه وجزائه؛ فاجتمع مرجع واحد مع مسؤولية لا يحملها أحد عن غيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص57، تحت عنوان «فائدة العطف بين الجملتين الاسميتين»","url":""}]},{"id":"s42-45","number":45,"surah":42,"verses":[15],"references":[{"surah":42,"verses":[15]}],"verseLabel":"الشورى: 15","question":"لماذا قيل: ﴿لَا حُجَّةَ بَيْنَنَا وَبَيْنَكُمُ﴾ مع أن المؤمنين يملكون الحجة؟","answer":"الحجة هنا المحاجة والخصومة، لا البرهان؛ فالمعنى أن الحق قد بُين ولم تبق فائدة في استمرار الجدل، لا أن أدلة الإيمان غائبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص57، تحت عنوان «بلاغة استعمال مفردة ﴿حجة﴾»","url":""}]},{"id":"s42-159","number":159,"surah":42,"verses":[15],"references":[{"surah":42,"verses":[15]}],"verseLabel":"الشورى: 15","question":"ما الكناية في قوله بعد انتهاء المحاجة: ﴿اللَّهُ يَجْمَعُ بَيْنَنَا﴾؟","answer":"الجمع كناية عن جمع الفريقين يوم القيامة للحكم والفصل واستيفاء الحقوق؛ فانتقل من جدل الدنيا الذي لا ينتهي إلى القضاء الذي يظهر فيه الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص59، تحت عنوان «بلاغة الكناية في لفظ ﴿يجمع﴾»","url":""}]},{"id":"s42-46","number":46,"surah":42,"verses":[16],"references":[{"surah":42,"verses":[16]}],"verseLabel":"الشورى: 16","question":"ما الصورة في وصف حجة المحاجين بأنها ﴿دَاحِضَةٌ﴾؟","answer":"استعير الدحض، وهو الزلق عن موضع الثبات، لبطلان حجتهم؛ فكأنها تحاول الوقوف فلا تجد أرضًا تستقر عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص69، تحت عنوان «بلاغة الاستعارة في قوله ﴿داحضة﴾»","url":""}]},{"id":"s42-160","number":160,"surah":42,"verses":[16],"references":[{"surah":42,"verses":[16]}],"verseLabel":"الشورى: 16","question":"لماذا قيل: ﴿حُجَّتُهُمْ دَاحِضَةٌ عِنْدَ رَبِّهِمْ﴾ بوصف الربوبية؟","answer":"لزيادة توبيخهم؛ فحجتهم باطلة عند من خلقهم ورباهم وتولى أمرهم، ومع ذلك يحاجون في دينه ويعرضون عن هديه.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص70، تحت عنوان «دلالة التعبير بوصف الربوبية في ﴿ربهم﴾»","url":""}]},{"id":"s42-47","number":47,"surah":42,"verses":[16],"references":[{"surah":42,"verses":[16]}],"verseLabel":"الشورى: 16","question":"لماذا انتقل جزاء المحاجِّين من دحض حجتهم إلى غضب الله عليهم؟","answer":"لأن سقوط حجتهم فضيحة لهم في الدنيا، ثم يعقبه غضب الله جزاءً أخرويًا؛ فالعطف يجمع خسارتهم في موطن البرهان وخسارتهم عند الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص71، تحت عنوان «دلالة التعبير بالواو في ﴿وعليهم﴾»","url":""}]},{"id":"s42-161","number":161,"surah":42,"verses":[16],"references":[{"surah":42,"verses":[16]}],"verseLabel":"الشورى: 16","question":"ماذا يضيف قوله: ﴿وَلَهُمْ عَذَابٌ شَدِيدٌ﴾ بعد ذكر الغضب؟","answer":"يجعل العذاب نتيجة ثابتة مستقلة للغضب، لا حالة عابرة؛ فالجملة الاسمية مع العطف ترسّخ دوام الجزاء وشدته.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص72، تحت عنوان «دلالة الواو في ﴿ولهم عذاب﴾»","url":""}]},{"id":"s42-48","number":48,"surah":42,"verses":[17],"references":[{"surah":42,"verses":[17]}],"verseLabel":"الشورى: 17","question":"لماذا جُمع بين إنزال الكتاب وإنزال الميزان؟","answer":"لأن الكتاب يقرر منهج الحق، والميزان يترجم ذلك المنهج إلى عدل يضبط الحكم والمعاملة؛ فاجتماعهما يربط الوحي بإقامة القسط في واقع الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص82، تحت عنوان «دلالة العطف في قوله: ﴿والميزان﴾»","url":""}]},{"id":"s42-162","number":162,"surah":42,"verses":[17],"references":[{"surah":42,"verses":[17]}],"verseLabel":"الشورى: 17","question":"لماذا سُمِّي العدل ﴿الْمِيزَانَ﴾؟","answer":"لأن الميزان الحسي يميّز المقادير ويمنع الجور، فاستعير للعدل والشريعة اللذين تُوزن بهما الحقوق والأعمال وتستقيم بهما حياة الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص82، تحت عنوان «بلاغة المجاز في التعبير بلفظ ﴿الميزان﴾»","url":""}]},{"id":"s42-49","number":49,"surah":42,"verses":[17],"references":[{"surah":42,"verses":[17]}],"verseLabel":"الشورى: 17","question":"لماذا جاء التنبيه على قرب الساعة بعد إنزال الكتاب والميزان؟","answer":"لأن الحساب هو الموطن الذي تظهر فيه ثمرة الالتزام بالكتاب والعدل، وفيه يوفّى كل إنسان ما قدّم؛ فجاء ذكر الساعة ليصل المنهج بعاقبته.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص83، تحت عنوان «دور التعبير بالاستئناف»","url":""}]},{"id":"s42-163","number":163,"surah":42,"verses":[17],"references":[{"surah":42,"verses":[17]}],"verseLabel":"الشورى: 17","question":"ماذا يضيف قوله: ﴿وَمَا يُدْرِيكَ لَعَلَّ السَّاعَةَ قَرِيبٌ﴾ بعد ذكر الكتاب والميزان؟","answer":"يذيّل السياق بإنذار يوقظ من الغفلة: فالميزان الذي أُنزل لإقامة العدل سيعقبه ميزان الجزاء، ووقت الساعة مجهول قد يكون قريبًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص86، تحت عنوان «بلاغة التذييل بقوله: ﴿وما يدريك لعل الساعة قريب﴾»","url":""}]},{"id":"s42-50","number":50,"surah":42,"verses":[17],"references":[{"surah":42,"verses":[17]}],"verseLabel":"الشورى: 17","question":"ما سر وصف الساعة المؤنثة بقوله ﴿قَرِيبٌ﴾؟","answer":"تذكر الموسوعة أن الساعة غير حقيقية التأنيث، فيجوز تذكير خبرها وتأنيثه، وأن المعنى يمكن أن يحمل على قرب وقتها أو مجيئها. وتذكر أيضًا استعمال العرب «قريب» استعمال الظرف الذي لا تلزمه علامة التأنيث.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص85–86، تحت عنوان «سر التعبير بقوله ﴿قريب﴾ دون (قريبة)»","url":""}]},{"id":"s42-51","number":51,"surah":42,"verses":[18],"references":[{"surah":42,"verses":[18]}],"verseLabel":"الشورى: 18","question":"لماذا يستعجل غير المؤمنين بالساعة؟","answer":"لا يستعجلونها طلبًا لوقوعها، بل سخريةً وإنكارًا؛ إذ يتخذون تأخرها ذريعة للتكذيب ويطلبونها طلب المستهزئ الذي لا يوقن بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص92، تحت عنوان «سر استعجال ﴿الذين لا يؤمنون﴾ وقوع الساعة»","url":""}]},{"id":"s42-164","number":164,"surah":42,"verses":[18],"references":[{"surah":42,"verses":[18]}],"verseLabel":"الشورى: 18","question":"كيف قابلت الآية بين مستعجلي الساعة والمشفقين منها بهذا الإيجاز؟","answer":"ذكرت من الكافرين استعجالهم الدال على إنكارهم، ومن المؤمنين إشفاقهم الدال على تصديقهم، فدل كل مذكور على المقابل المحذوف في الطرف الآخر؛ وهذا هو الاحتباك.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص94، تحت عنوان «بلاغة الاحتباك في الآية»","url":""}]},{"id":"s42-165","number":165,"surah":42,"verses":[18],"references":[{"surah":42,"verses":[18]}],"verseLabel":"الشورى: 18","question":"لماذا وُصف خوف المؤمنين من الساعة بالإشفاق؟","answer":"لأن الإشفاق خوفٌ ممزوج بعناية واستعداد، لا فزع مجرد؛ فهم يوقنون بالساعة فيحذرون حسابها ويعملون لما ينجيهم منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص95، تحت عنوان «سر التعبير بالإشفاق دون الخوف»","url":""}]},{"id":"s42-166","number":166,"surah":42,"verses":[18],"references":[{"surah":42,"verses":[18]}],"verseLabel":"الشورى: 18","question":"لماذا قيل عن المؤمنين: ﴿وَيَعْلَمُونَ أَنَّهَا الْحَقُّ﴾ بعد وصف إشفاقهم؟","answer":"ليبيّن أن خوفهم ثمرة يقين راسخ لا وهم عابر؛ فهم يستعدون للساعة لأنهم يعلمون حتم وقوعها وحقيقة ما فيها من حساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص96، تحت عنوان «دلالة العطف في قوله: ﴿ويعلمون﴾»","url":""}]},{"id":"s42-52","number":52,"surah":42,"verses":[17,18],"references":[{"surah":42,"verses":[17,18]}],"verseLabel":"الشورى: 17–18","question":"لماذا قوبل قرب الساعة بوصف ضلال الممارين فيها بأنه بعيد؟","answer":"لأن الساعة قريبة الوقوع، لكن إنكارهم لها أبعدهم عن دلائل الحق؛ فبرزت المفارقة بين قرب الحقيقة وشدة بُعدهم عنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص101، تحت عنوان «سر وصف الضلال بالبعيد»","url":""}]},{"id":"s42-53","number":53,"surah":42,"verses":[19],"references":[{"surah":42,"verses":[19]}],"verseLabel":"الشورى: 19","question":"ما دلالة الجمع بين اسمي الله ﴿الْقَوِيُّ الْعَزِيزُ﴾ بعد ذكر الرزق؟","answer":"يدل اقترانهما على أن عطاء الله صادر عن قدرة لا يعجزها شيء، وعن عزة لا يمانعها أحد؛ فلا يستطيع مخلوق منع رزقه أو نقض تدبيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص110، تحت عنوان «دلالة الجمع بين وصفي القوة والعزة»","url":""}]},{"id":"s42-54","number":54,"surah":42,"verses":[19],"references":[{"surah":42,"verses":[19]}],"verseLabel":"الشورى: 19","question":"ما مناسبة وصف الله باللطف في سياق الرزق؟","answer":"لأن رزقه يصل إلى عباده بطرق دقيقة قد تخفى عليهم، ويهيئ لهم أسباب المعاش من حيث لا يشعرون؛ فالرزق مظهر ظاهر للطفه الخفي.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص108، تحت عنوان «سر لطف لفظة ﴿يرزق من يشاء﴾ عما قبلها»","url":""}]},{"id":"s42-55","number":55,"surah":42,"verses":[20],"references":[{"surah":42,"verses":[20]}],"verseLabel":"الشورى: 20","question":"لماذا سُمِّي العمل للآخرة ﴿حَرْثَ الْآخِرَةِ﴾؟","answer":"لأن العامل يزرع في الدنيا بطاعته ما يحصد ثمرته في الآخرة، كما يبذر الزارع البذر منتظرًا نماءه؛ فالتعبير يجسّد الصلة بين السعي والجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص116، تحت عنوان «بلاغة المجاز في قوله: ﴿حرث الآخرة﴾»","url":""}]},{"id":"s42-167","number":167,"surah":42,"verses":[20],"references":[{"surah":42,"verses":[20]}],"verseLabel":"الشورى: 20","question":"لماذا عُبِّر عن السعي للدنيا بالحرث؟","answer":"لأن طالب الدنيا يبذل ويكدح ليحصل ثمرتها كما يحرث الزارع أرضه، غير أن حصاده محدود بحدود الدنيا وزوالها.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص120، تحت عنوان «سر التعبير عن السعي للدنيا بالحرث»","url":""}]},{"id":"s42-56","number":56,"surah":42,"verses":[20],"references":[{"surah":42,"verses":[20]}],"verseLabel":"الشورى: 20","question":"لماذا وُعد مريد الآخرة بالزيادة في حرثه؟","answer":"لأن عمل الآخرة لا يرد إلى صاحبه بمقداره فقط، بل ينمّيه الله ويضاعف ثوابه؛ فجاء لفظ الزيادة ليفتح معنى الفضل المتجدد فوق أصل الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص116–117، تحت عنوان «سر التعبير بلفظ الزيادة من حيث المادة والصيغة»","url":""}]},{"id":"s42-168","number":168,"surah":42,"verses":[20],"references":[{"surah":42,"verses":[20]}],"verseLabel":"الشورى: 20","question":"لماذا قيل لمريد الآخرة: ﴿نَزِدْ لَهُ فِي حَرْثِهِ﴾، ولمريد الدنيا: ﴿نُؤْتِهِ مِنْهَا﴾؟","answer":"لأن ﴿في﴾ توحي بنماء حرث الآخرة في داخله وتضاعفه، أما ﴿من﴾ فتفيد أن طالب الدنيا لا ينال إلا بعضًا منها؛ فالأول فضل متزايد والثاني نصيب محدود.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص121، تحت عنوان «سر التعبير بـ(من) مع الدنيا و(في) مع الآخرة»","url":""}]},{"id":"s42-57","number":57,"surah":42,"verses":[21],"references":[{"surah":42,"verses":[21]}],"verseLabel":"الشورى: 21","question":"لماذا سُمِّي مشرِّعو الدين الباطل ﴿شُرَكَاءَ﴾؟","answer":"لأن طاعتهم في التشريع من دون الله جعلتهم بمنزلة من نازع الله حقه الخالص في التحليل والتحريم، وفي اللفظ تهكم يكشف بطلان هذه الشراكة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص130، تحت عنوان «سر التعبير بلفظ ﴿شركاء﴾»","url":""}]},{"id":"s42-169","number":169,"surah":42,"verses":[21],"references":[{"surah":42,"verses":[21]}],"verseLabel":"الشورى: 21","question":"لماذا قيل عن أهل الدين الباطل: ﴿شَرَعُوا لَهُمْ﴾؟","answer":"لأنهم صاغوا أهواءهم في صورة أحكام تُتبع، فكأنهم حاكوا فعل الشارع الحق؛ وفي اختيار اللفظ تشنيع على جرأتهم في إضفاء صفة الدين على الباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص131، تحت عنوان «سر التعبير بلفظ ﴿شرعوا﴾»","url":""}]},{"id":"s42-58","number":58,"surah":42,"verses":[21],"references":[{"surah":42,"verses":[21]}],"verseLabel":"الشورى: 21","question":"لماذا عُبِّر عن بطلان تشريع الشركاء بأنه مما ﴿لَمْ يَأْذَنْ بِهِ اللَّهُ﴾؟","answer":"لأن الإذن هو علامة المشروعية والسلطان، فإذا انتفى إذن الله سقط عن ذلك التشريع كل سند ديني، وبان أنه افتراء لا حق لأحد في إلزام الناس به.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص133، تحت عنوان «سر التعبير بالإذن»","url":""}]},{"id":"s42-59","number":59,"surah":42,"verses":[14,21],"references":[{"surah":42,"verses":[14,21]}],"verseLabel":"الشورى: 14، 21","question":"لماذا نُكِّرت ﴿كَلِمَةٌ﴾ في قوله: ﴿وَلَوْلَا كَلِمَةٌ سَبَقَتْ مِنْ رَبِّكَ﴾؟","answer":"للتعظيم والتهويل؛ فهي كلمة قاطعة نافذة اقتضت إمهالهم إلى الأجل، وعِظم أثرها يغني عن تعيين ألفاظها.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص37، تحت عنوان «غرض تنكير ﴿كلمة﴾»","url":""}]},{"id":"s42-170","number":170,"surah":42,"verses":[14,21],"references":[{"surah":42,"verses":[14,21]}],"verseLabel":"الشورى: 14، 21","question":"ماذا تفيد إضافة ﴿كَلِمَةُ﴾ إلى ﴿الْفَصْلِ﴾؟","answer":"تفيد أنها الكلمة المعيّنة الحاسمة التي ينتهي بها النزاع ويتميز بها المحق من المبطل عند القضاء النهائي.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص135، تحت عنوان «دلالة إضافة ﴿كلمة﴾ إلى ﴿الفصل﴾»","url":""}]},{"id":"s42-171","number":171,"surah":42,"verses":[14,21],"references":[{"surah":42,"verses":[14,21]}],"verseLabel":"الشورى: 14، 21","question":"لماذا قيل: ﴿كَلِمَةُ الْفَصْلِ﴾ دون كلمة القضاء أو الحكم؟","answer":"لأن الفصل لا يكتفي بإصدار الحكم، بل يقطع الخصومة ويفرّق بين الحق والباطل بحيث لا يبقى بعده نزاع ولا التباس.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص135، تحت عنوان «سر التعبير بالفصل دون القضاء أو الحكم»","url":""}]},{"id":"s42-60","number":60,"surah":42,"verses":[16,21],"references":[{"surah":42,"verses":[16,21]}],"verseLabel":"الشورى: 16، 21","question":"لماذا وُصف عذاب المحاجِّين في الله بأنه ﴿شَدِيدٌ﴾؟","answer":"لأن محاجتهم جاءت بعد الاستجابة للحق وقيام الحجة، فناسب عنادهم القوي وصف العذاب بالشدة التي تشمل قوة الإيلام وتنوعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص73–74، تحت عنوان «سر وصف العذاب بالشديد دون المهين والأليم والعظيم»","url":""}]},{"id":"s42-172","number":172,"surah":42,"verses":[16,21],"references":[{"surah":42,"verses":[16,21]}],"verseLabel":"الشورى: 16، 21","question":"لماذا وُصف عذاب أصحاب التشريع الباطل بأنه ﴿أَلِيمٌ﴾؟","answer":"لأنهم انحرفوا عن شرع الله وأضلوا غيرهم، فناسب جريمتهم إبراز ما يباشرونه من ألم العذاب وحسرتهم الدائمة عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص138، تحت عنوان «سر وصف العذاب بالأليم دون العظيم»","url":""}]},{"id":"s42-61","number":61,"surah":42,"verses":[22],"references":[{"surah":42,"verses":[22]}],"verseLabel":"الشورى: 22","question":"لماذا عُطف ﴿وَهُوَ وَاقِعٌ بِهِمْ﴾ على إشفاق الظالمين من العذاب؟","answer":"ليبيّن أن خوفهم لا يغيّر المصير، بل إن العذاب الذي يشفقون منه نازل بهم حتمًا؛ فيجتمع في المشهد توقعهم المرعب وتحقق الوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص146، تحت عنوان «دلالة الواو في قوله ﴿وهو واقع﴾»","url":""}]},{"id":"s42-62","number":62,"surah":42,"verses":[22],"references":[{"surah":42,"verses":[22]}],"verseLabel":"الشورى: 22","question":"ما دلالة المقابلة بين وقوع العذاب بالظالمين ونعيم المؤمنين؟","answer":"تُظهر الفرق التام بين المصيرين: عذاب محتوم يهبط بالظالمين، وأمن واسع ينال فيه المؤمنون ما يشاؤون عند ربهم؛ فيزداد الوعد والوعيد وضوحًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص148، تحت عنوان «بلاغة المقابلة بين حال الظالمين وحال المؤمنين»","url":""}]},{"id":"s42-173","number":173,"surah":42,"verses":[22],"references":[{"surah":42,"verses":[22]}],"verseLabel":"الشورى: 22","question":"لماذا قيل للمؤمنين: ﴿لَهُمْ مَا يَشَاءُونَ﴾ دون «ما يطلبون»؟","answer":"للدلالة على أن نعيمهم يوافق رغباتهم من غير عناء طلب ولا انتظار؛ فما تقع عليه مشيئتهم مهيأ لهم عند ربهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص152–153، تحت عنوان «دلالة التعبير بالمشيئة دون الطلب»","url":""}]},{"id":"s42-63","number":63,"surah":42,"verses":[22],"references":[{"surah":42,"verses":[22]}],"verseLabel":"الشورى: 22","question":"لماذا عُبِّر عن نعيم المؤمنين بلفظ ﴿رَوْضَاتٍ﴾؟","answer":"لأن الروضة توحي بالخضرة والجمال وطيب المقام، وجمعها يدل على تنوع مشاهد النعيم واتساعها وتجدد بهجتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص151، تحت عنوان «دلالة التعبير بـ﴿روضات﴾ مادة وصيغة»","url":""}]},{"id":"s42-174","number":174,"surah":42,"verses":[22],"references":[{"surah":42,"verses":[22]}],"verseLabel":"الشورى: 22","question":"ماذا تضيف إضافة الروضات إلى الجنات في ﴿رَوْضَاتِ الْجَنَّاتِ﴾؟","answer":"تجعل تلك الروضات مختارة من أعظم الجنات وأحسنها، فتضاعف صورة السعة والبهجة بدل أن يكون الحديث عن روضة واحدة محدودة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص151–152، تحت عنوان «دلالة إضافة الروضات إلى الجنات»","url":""}]},{"id":"s42-64","number":64,"surah":42,"verses":[22,23],"references":[{"surah":42,"verses":[22,23]}],"verseLabel":"الشورى: 22–23","question":"لماذا تكرر اسم الإشارة في ﴿ذَلِكَ هُوَ الْفَضْلُ الْكَبِيرُ * ذَلِكَ الَّذِي يُبَشِّرُ اللَّهُ عِبَادَهُ﴾؟","answer":"ليعيد استحضار الفضل العظيم نفسه ويؤكده، ثم ينقله من وصف مجمل إلى بشارة مخصوصة لعباد الله المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص162، تحت عنوان «موقع جملة ﴿ذلك الذي ...﴾ مما قبلها ودلالته»","url":""}]},{"id":"s42-175","number":175,"surah":42,"verses":[22,23],"references":[{"surah":42,"verses":[22,23]}],"verseLabel":"الشورى: 22–23","question":"لماذا جاء تبشير الله عباده بالمضارع في ﴿يُبَشِّرُ﴾؟","answer":"ليصور البشارة متجددة متكررة، يقرؤها المؤمنون ويسمعونها جيلاً بعد جيل، فيظل أثر الرجاء حاضرًا في نفوسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص163، تحت عنوان «دلالة التعبير بالمضارع ﴿يبشر﴾»","url":""}]},{"id":"s42-65","number":65,"surah":42,"verses":[23],"references":[{"surah":42,"verses":[23]}],"verseLabel":"الشورى: 23","question":"لماذا استُعمل ﴿يَقْتَرِفْ﴾ مع الحسنة؟","answer":"لأن الاقتراف يدل على الاكتساب المتعمد، فيبرز أن الحسنة ثمرة قصد وسعي، وأن ما يحصله العبد منها يُثبت له ولو كان قليلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص174–175، تحت عنوان «دلالة التعبير بمادة الاقتراف في ﴿يقترف﴾»","url":""}]},{"id":"s42-176","number":176,"surah":42,"verses":[23],"references":[{"surah":42,"verses":[23]}],"verseLabel":"الشورى: 23","question":"ماذا يفيد الوعد: ﴿نَزِدْ لَهُ فِيهَا حُسْنًا﴾؟","answer":"يفيد أن جزاء الحسنة لا يقف عند مثلها، بل ينمّيه الله ويضاعف جمال أثرها وثوابها فضلًا منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص176، تحت عنوان «دلالة التعبير بمادة الزيادة في ﴿نزد﴾»","url":""}]},{"id":"s42-66","number":66,"surah":42,"verses":[23],"references":[{"surah":42,"verses":[23]}],"verseLabel":"الشورى: 23","question":"لماذا ذُيّل الوعد بزيادة الحسنة بقوله: ﴿إِنَّ اللَّهَ غَفُورٌ شَكُورٌ﴾؟","answer":"لأن الزيادة ثمرة شكره للطاعة، والمغفرة تجبر ما يعتري العامل من تقصير؛ فالتذييل يبيّن منشأ الفضل الذي وعدت به الآية.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص177، تحت عنوان «الغرض من الختم بجملة التذييل ﴿إن الله غفور شكور﴾»","url":""}]},{"id":"s42-177","number":177,"surah":42,"verses":[23],"references":[{"surah":42,"verses":[23]}],"verseLabel":"الشورى: 23","question":"ما سر الجمع بين اسمي الله ﴿غَفُورٌ شَكُورٌ﴾؟","answer":"ليجمع للعبد زوال الشر وحصول الخير: يغفر الله الزلل، ويشكر العمل القليل فيثيب عليه كثيرًا؛ فلا يبقى التقصير حاجبًا ولا الطاعة بلا مضاعفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص178، تحت عنوان «سر اصطفاء الاسمين الجليلين ﴿غفور شكور﴾»","url":""}]},{"id":"s42-67","number":67,"surah":42,"verses":[24],"references":[{"surah":42,"verses":[24]}],"verseLabel":"الشورى: 24","question":"ما الدلالة البلاغية لحذف الواو رسمًا من ﴿وَيَمْحُ اللَّهُ الْبَاطِلَ﴾؟","answer":"يشير الحذف الخطي إلى سهولة محو الباطل وسرعة زواله أمام القدرة الإلهية، ويؤكد أن إبطاله أمر نافذ لا يعجز الله؛ أما في النطق فالفعل مرفوع والواو ثابتة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص190، تحت عنوان «دلالة حذف الواو في ﴿ويمح﴾ في الوصل والوقف»","url":""}]},{"id":"s42-68","number":68,"surah":42,"verses":[24],"references":[{"surah":42,"verses":[24]}],"verseLabel":"الشورى: 24","question":"ماذا يضيف لفظ ﴿يَمْحُ﴾ إلى الوعد بزوال الباطل؟","answer":"لا يدل على مجرد إيقاف الباطل، بل على إزالته وإذهاب أثره؛ وجاء بالمضارع ليصور هذا سنة متجددة من سنن الله، يحفظ بها دينه ويزيل ما يفتريه المبطلون.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص189–190، تحت عنوان «دلالة التعبير بـ(يمح) مادة وصيغة»","url":""}]},{"id":"s42-69","number":69,"surah":42,"verses":[24,25],"references":[{"surah":42,"verses":[24,25]}],"verseLabel":"الشورى: 24–25","question":"لماذا عُقِّب قبول التوبة والعفو بقوله ﴿وَيَعْلَمُ مَا تَفْعَلُونَ﴾؟","answer":"ليؤكد أن القبول والعفو صادران عن علم تام لا عن خفاءٍ بالفعل؛ فهو يعلم صدق التائب وإخلاصه كما يعلم إصرار المسيء، فيجمع الختام بين فتح باب الرجاء والحث على مراقبة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص205، تحت عنوان «دلالة العطف في ﴿ويعلم﴾»","url":""}]},{"id":"s42-70","number":70,"surah":42,"verses":[25],"references":[{"surah":42,"verses":[25]}],"verseLabel":"الشورى: 25","question":"ماذا يوحي وصف الله بأنه ﴿يَقْبَلُ التَّوْبَةَ﴾؟","answer":"يوحي بأن رجوع العبد إلى ربه لا يضيع، بل يعتد الله به ويتلقاه بالرضا والقبول؛ وفي ذلك فتح لباب الأمل وحث على المبادرة بالتوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص200–201، تحت عنوان «دلالة التعبير بمادة القبول»","url":""}]},{"id":"s42-200","number":200,"surah":42,"verses":[25],"references":[{"surah":42,"verses":[25]}],"verseLabel":"الشورى: 25","question":"ماذا يضيف قوله ﴿وَيَعْفُو عَنِ السَّيِّئَاتِ﴾ بعد قبول التوبة؟","answer":"يبين أن فضل الله لا يقف عند قبول الرجوع، بل يتجاوز السيئات ويمحو تبعتها ولا يؤاخذ بها؛ فتجتمع للتائب نعمة القبول ونعمة إسقاط العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص204، تحت عنوان «دلالة التعبير بمادة العفو»","url":""}]},{"id":"s42-71","number":71,"surah":42,"verses":[26],"references":[{"surah":42,"verses":[26]}],"verseLabel":"الشورى: 26","question":"من المستجيب في قوله ﴿وَيَسْتَجِيبُ الَّذِينَ آمَنُوا﴾: المؤمنون أم ربهم؟","answer":"يحتمل التعبير وجهين صحيحين: أن يجيب الله دعاء المؤمنين ويثيبهم على طاعتهم، أو أن يستجيب المؤمنون لربهم بالطاعة والانقياد. ويسمح اللفظ بالجمع بين المعنيين: استجابتهم له يعقبها قبوله وثوابه لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص212، تحت عنوان «دلالة التعبير بمادة الاستجابة»","url":""}]},{"id":"s42-178","number":178,"surah":42,"verses":[26],"references":[{"surah":42,"verses":[26]}],"verseLabel":"الشورى: 26","question":"ماذا تضيف جملة ﴿وَيَزِيدُهُمْ مِنْ فَضْلِهِ﴾ بعد استجابة المؤمنين؟","answer":"تنقل الجزاء من مجرد الإجابة والثواب المستحق إلى عطاء زائد لا تحده أعمالهم؛ فالله يمنحهم فوق ما سألوا وفوق ما تقابله طاعتهم، وتتجدد هذه الزيادة من واسع فضله.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص215، تحت عنوان «دلالة العطف بالواو في ﴿ويزيدهم﴾»","url":""}]},{"id":"s42-179","number":179,"surah":42,"verses":[26],"references":[{"surah":42,"verses":[26]}],"verseLabel":"الشورى: 26","question":"كيف جمعت الآية بين ترغيب المؤمنين وترهيب الكافرين بألفاظ قليلة؟","answer":"ذكرت استجابة المؤمنين وزيادتهم من الفضل، فدل ذلك على نجاتهم من العذاب؛ وذكرت عذاب الكافرين، فدل على حرمانهم من الإجابة والفضل. فحذف من كل جانب ما دل عليه مقابله، واكتمل الوعد والوعيد بإيجاز.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص219، تحت عنوان «بلاغة الاحتباك في الآية»","url":""}]},{"id":"s42-72","number":72,"surah":42,"verses":[27],"references":[{"surah":42,"verses":[27]}],"verseLabel":"الشورى: 27","question":"لماذا كان بسط الرزق لجميع الناس مظنةً للبغي في الأرض؟","answer":"لأن السعة العامة تفتح باب التنافس والاستعلاء، وقد تدفع النفوس إلى تجاوز الحدود طلبًا للمزيد؛ فتقدير الأرزاق يحفظ توازن الحياة ولا يعني أن كل غني يبغي أو أن الفقر يمنع البغي، وإنما يبين ما يغلب عند البسط الشامل.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص223–224، تحت عنوان «الغرض من التعبير بأسلوب الشرط بالأداة (لو)»","url":""}]},{"id":"s42-180","number":180,"surah":42,"verses":[27],"references":[{"surah":42,"verses":[27]}],"verseLabel":"الشورى: 27","question":"لماذا اختير لفظ ﴿لَبَغَوْا﴾ لوصف ما يفعله الناس عند بسط الرزق؟","answer":"لأن البغي يجمع تجاوز الحد والعدوان والظلم مع شدة الطلب والرغبة في الازدياد؛ فيصور كيف قد يحول التوسع في المال الشهوة إلى استعلاء وفساد يتعدى صاحبه إلى الأرض والمجتمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص227، تحت عنوان «دلالة التعبير بمادة البغي في ﴿لبغوا﴾»","url":""}]},{"id":"s42-73","number":73,"surah":42,"verses":[27],"references":[{"surah":42,"verses":[27]}],"verseLabel":"الشورى: 27","question":"لماذا عُبّر عن الرزق بقوله ﴿يُنَزِّلُ﴾؟","answer":"ليصوَّر الرزق عطاءً يأتي من عند الله إلى عباده، كما ينزل الغيث، فيستحضر مصدر النعمة وافتقار الخلق إلى تدبير المنعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص228، تحت عنوان «دلالة التعبير بمادة التنزيل في ﴿ينزل﴾»","url":""}]},{"id":"s42-201","number":201,"surah":42,"verses":[27],"references":[{"surah":42,"verses":[27]}],"verseLabel":"الشورى: 27","question":"ما الذي يضيفه المضارع ﴿يُنَزِّلُ﴾ إلى معنى الرزق؟","answer":"يصور إنزال الرزق فعلًا متجددًا مستمرًا، يتكرر على وفق أحوال العباد وحاجاتهم، لا عطاءً وقع مرة وانقطع.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص229، تحت عنوان «دلالة التعبير بالمضارع ﴿ينزل﴾»","url":""}]},{"id":"s42-202","number":202,"surah":42,"verses":[27],"references":[{"surah":42,"verses":[27]}],"verseLabel":"الشورى: 27","question":"لماذا ينزل الله الرزق ﴿بِقَدَرٍ﴾؟","answer":"لأن العطاء مضبوط بعلمه وحكمته؛ فيبلغ كل عبد المقدار الذي يصلحه، فلا يكون البسط والمنع عشوائيين ولا خارجين عن التدبير.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص229، تحت عنوان «سر تقييد الفعل ﴿بقدر﴾»","url":""}]},{"id":"s42-74","number":74,"surah":42,"verses":[27],"references":[{"surah":42,"verses":[27]}],"verseLabel":"الشورى: 27","question":"لماذا جمع بين ﴿خَبِيرٌ﴾ و﴿بَصِيرٌ﴾ في تقدير أرزاق العباد؟","answer":"ليدل على شمول العلم الذي يقوم عليه التدبير: فالخبير محيط بالبواطن والحقائق وما تخفيه النفوس، والبصير محيط بالذوات والمشاهدات والظواهر؛ فلا يخفى عليه من حال عباده ما يصلح معه البسط أو التضييق.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص232، تحت عنوان «سر اقتران ﴿بصير﴾ بـ﴿خبير﴾»","url":""}]},{"id":"s42-75","number":75,"surah":42,"verses":[27,28],"references":[{"surah":42,"verses":[27,28]}],"verseLabel":"الشورى: 27–28","question":"لماذا انتقل الحديث من تقدير الأرزاق إلى إنزال الغيث بعد القنوط؟","answer":"لأن الغيث مثال مشاهد على حكمة البسط والقبض: قد يؤخره الله حتى تظهر الحاجة ويزول الاتكال على العادة، ثم ينزله في وقته فتجتمع النعمة والدلالة على القدرة؛ فيرى الناس أثر التدبير الذي قررته الآية السابقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص234، تحت عنوان «مناسبة الآيتين لما قبلهما»","url":""}]},{"id":"s42-76","number":76,"surah":42,"verses":[28],"references":[{"surah":42,"verses":[28]}],"verseLabel":"الشورى: 28","question":"لماذا وصفهم القرآن بأنهم ﴿قَنَطُوا﴾ ولم يكتف بوصف اليأس؟","answer":"لأن القنوط يصف يأسًا اشتد حتى انقطع معه الأمل وظهرت آثاره على ملامح الإنسان وتصرفاته؛ أما اليأس فأصله شعور في القلب والعقل. فالتعبير يرسم شدة الكرب التي جاء الغيث بعدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص242، تحت عنوان «دلالة التعبير بـ﴿قنطوا﴾ مادة وصيغة»","url":""}]},{"id":"s42-77","number":77,"surah":42,"verses":[28],"references":[{"surah":42,"verses":[28]}],"verseLabel":"الشورى: 28","question":"ما الصورة التي يرسمها قوله بعد الغيث ﴿وَيَنْشُرُ رَحْمَتَهُ﴾؟","answer":"يصور الرحمة شيئًا يمتد وينبسط في أرجاء الحياة؛ فتتوزع آثار الغيث في النبات والحيوان والإنسان، وينقلب ضيق القنوط إلى رجاء وفرح ظاهرين، كأن الرحمة قد نُشرت أمام العيون.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص243، تحت عنوان «بلاغة الاستعارة في ﴿ينشر﴾»","url":""}]},{"id":"s42-78","number":78,"surah":42,"verses":[28],"references":[{"surah":42,"verses":[28]}],"verseLabel":"الشورى: 28","question":"ما مناسبة ختم آية الغيث والرحمة بقوله ﴿وَهُوَ الْوَلِيُّ الْحَمِيدُ﴾؟","answer":"الولي يتولى مصالح عباده ويسوق إليهم ما يصلحهم من الغيث وغيره، والحميد هو المستحق للحمد على هذا التدبير والإنعام. فاقتران الاسمين يربط نعمة الغيث بولاية الله التي تستوجب حمده.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص245، تحت عنوان «سر الاقتران في ﴿الولي الحميد﴾»","url":""}]},{"id":"s42-79","number":79,"surah":42,"verses":[29],"references":[{"surah":42,"verses":[29]}],"verseLabel":"الشورى: 29","question":"ماذا تصوّر كلمة ﴿بَثَّ﴾ في خلق الدواب؟","answer":"تصور نشر المخلوقات وتفريقها في مواطن متباينة مع كثرتها وتنوعها، فكأن الحياة قد انتشرت في أرجاء السماوات والأرض بعد خلقهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص254، تحت عنوان «البث والنشر»","url":""}]},{"id":"s42-80","number":80,"surah":42,"verses":[29],"references":[{"surah":42,"verses":[29]}],"verseLabel":"الشورى: 29","question":"هل يدل قوله ﴿وَمَا بَثَّ فِيهِمَا مِنْ دَابَّةٍ﴾ على وجود مخلوقات في السماوات؟","answer":"الضمير يشمل السماوات والأرض، لكن دلالته لا تُحصر في صورة واحدة: قيل إن ذكرهما معًا من التغليب والدواب في الأرض، وقيل يشمل الطير أو أجناسًا من المخلوقات السماوية لا نعرفها. فالآية تثبت سعة القدرة ولا تعيّن لنا طبيعة تلك المخلوقات.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص248–249، تحت عنوان «معنى (في) ودلالتها في ﴿فيهما﴾»","url":""}]},{"id":"s42-81","number":81,"surah":42,"verses":[29],"references":[{"surah":42,"verses":[29]}],"verseLabel":"الشورى: 29","question":"لماذا قيل ﴿إذا يشاء﴾ لا «إن يشأ» عند الحديث عن جمع الخلق؟","answer":"لأن ﴿إذا﴾ تستحضر الجمع أمرًا متحقق الوقوع في الوقت الذي تعلقت به مشيئة الله، لا احتمالًا مشكوكًا فيه. فالاعتراض يرد البعث إلى توقيته الإلهي مع تأكيد أن القدرة عليه تامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص252–253، تحت عنوان «بلاغة الاعتراض في ﴿إذا يشاء﴾»","url":""}]},{"id":"s42-82","number":82,"surah":42,"verses":[30],"references":[{"surah":42,"verses":[30]}],"verseLabel":"الشورى: 30","question":"ما سر إسناد كسب السيئات إلى الأيدي في ﴿فَبِمَا كَسَبَتْ أَيْدِيكُمْ﴾؟","answer":"نسب الكسب إلى الأيدي لأنها أبرز آلات مباشرة العمل، وأطلق الجزء وأريد به الإنسان وعمله. وفي هذا التصوير إشعار بأن ما يؤاخذون به من فعلهم هم، فيدعو إلى محاسبة النفس بدل الغفلة عن أسباب المؤاخذة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص263، تحت عنوان «بلاغة التعبير بالمجاز المرسل ﴿أيديكم﴾»","url":""}]},{"id":"s42-83","number":83,"surah":42,"verses":[30],"references":[{"surah":42,"verses":[30]}],"verseLabel":"الشورى: 30","question":"هل يعني قوله ﴿وما أصابكم من مصيبة فبما كسبت أيديكم﴾ أن كل ابتلاء عقوبة؟","answer":"الخطاب عام فيمن تقع عليهم المؤاخذة بذنوبهم، لكنه لا يجعل كل ما ينزل بكل إنسان عقوبة؛ فالأنبياء ومن لا ذنب له قد يبتلون لرفع الدرجات وزيادة الأجر. فالآية تقرر أثر الكسب من غير أن تلغي حكم الابتلاء الأخرى.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص262، تحت عنوان «دلالة التعبير بـ﴿مصيبة﴾ نكرة»","url":""}]},{"id":"s42-181","number":181,"surah":42,"verses":[30],"references":[{"surah":42,"verses":[30]}],"verseLabel":"الشورى: 30","question":"ماذا يفيد اختيار لفظ ﴿يعفو﴾ بعد ذكر ما تكسبه الأيدي؟","answer":"يفيد ترك المؤاخذة والتجاوز عن الذنب مع ما في أصل العفو من الستر والمحو؛ فالله لا يعاقب عباده على كل ما كسبوا، بل يتجاوز عن كثير تفضلًا ورحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص264، تحت عنوان «دلالة التعبير بمادة العفو»","url":""}]},{"id":"s42-182","number":182,"surah":42,"verses":[30],"references":[{"surah":42,"verses":[30]}],"verseLabel":"الشورى: 30","question":"ماذا يفيد تنكير ﴿كثير﴾ في قوله ﴿ويعفو عن كثير﴾؟","answer":"يفخّم مقدار ما يتجاوز الله عنه، فيشمل ذنوبًا كثيرة أو خلقًا كثيرين لا يؤاخذهم بكل ما استحقوه. وفي إبقاء الكثير غير محصور إشعار بسعة الرحمة وعجز الإنسان عن إحصاء وجوه العفو.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص265، تحت عنوان «الغرض من التنكير في ﴿كثير﴾»","url":""}]},{"id":"s42-84","number":84,"surah":42,"verses":[31],"references":[{"surah":42,"verses":[31]}],"verseLabel":"الشورى: 31","question":"ما سر الجمع بين نفي الإعجاز في الأرض ونفي الولي والنصير من دون الله؟","answer":"ينفي أولًا قدرتهم على الإفلات من سلطان الله، ثم ينفي أن يجدوا من دونه وليًا يتولى خلاصهم أو نصيرًا يدفع عنهم. فتسد الجملتان طريق الاعتماد على النفس وطريق الاستعانة بغيره في دفع ما أراده.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص269، تحت عنوان «نكتة الواو ودلالتها في ﴿وما لكم﴾»","url":""}]},{"id":"s42-85","number":85,"surah":42,"verses":[31],"references":[{"surah":42,"verses":[31]}],"verseLabel":"الشورى: 31","question":"ما الذي يضيفه تنكير ﴿وَلِيٍّ﴾ و﴿نَصِيرٍ﴾؟","answer":"يعمم النفي حتى لا يبقى لهم أي ولي أو نصير، مهما صغر شأنه أو عظم؛ فلا حماية ولا معونة من أي جهة دون الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص272، تحت عنوان «نكتة تنكير ﴿ولي﴾ و﴿نصير﴾»","url":""}]},{"id":"s42-86","number":86,"surah":42,"verses":[29,32],"references":[{"surah":42,"verses":[29,32]}],"verseLabel":"الشورى: 29، 32","question":"لماذا جاءت السفن آيةً جديدة بعد ذكر خلق السماوات والأرض؟","answer":"لأن جريان السفن مثال محسوس قريب يضاف إلى الدليل الكلي في خلق السماوات والأرض؛ فتتجدد دعوة النظر في قدرة الله، وينتقل التأمل من إحاطة الخلق كله إلى نعمة يباشرها الناس في البحر.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص275، تحت عنوان «معنى الواو ودلالتها في قوله ﴿ومن آياته﴾»","url":""}]},{"id":"s42-87","number":87,"surah":42,"verses":[32],"references":[{"surah":42,"verses":[32]}],"verseLabel":"الشورى: 32","question":"لماذا عُبّر عن السفن في البحر بـ﴿الجوار﴾؟","answer":"لإبراز حال جريانها، فهو موضع النعمة والعبرة في تسخير البحر. وإطلاق الجريان عليها يوجه النظر إلى حركتها الظاهرة كأنها هي الجريان نفسه، فيقوى مشهد القدرة التي تحملها وتسيرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص276–277، تحت عنوان «بلاغة التعبير المجازي في إطلاق الجريان على السفن»","url":""}]},{"id":"s42-183","number":183,"surah":42,"verses":[32],"references":[{"surah":42,"verses":[32]}],"verseLabel":"الشورى: 32","question":"لماذا شُبّهت السفن الجارية في البحر بالأعلام؟","answer":"لأن الأعلام هي الجبال البارزة العالية؛ فالتشبيه يستحضر ضخامة السفن وظهورها من بعيد، ومع ذلك تجري فوق الماء ولا تغرق. فتتحول عظمتها وحركتها إلى آية ظاهرة على قدرة الله وتسخيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص277–278، تحت عنوان «الغرض من التعبير بالتشبيه في قوله ﴿الجوار في البحر كالأعلام﴾»","url":""}]},{"id":"s42-88","number":88,"surah":42,"verses":[32,33],"references":[{"surah":42,"verses":[32,33]}],"verseLabel":"الشورى: 32–33","question":"لماذا فُصل قوله ﴿إن يشأ يسكن الريح﴾ عما قبله من وصف السفن؟","answer":"لأنه استئناف يجيب عما يثيره مشهد السفن العظيمة من سؤال عن سر حركتها؛ فالله الذي أجراها قادر على إسكان الريح التي تحملها، وعندئذ تبقى ثابتة لا يحميها عظمها من العجز عن السير.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص284–285، تحت عنوان «سر فصل الآية عما قبلها»","url":""}]},{"id":"s42-89","number":89,"surah":42,"verses":[33],"references":[{"surah":42,"verses":[33]}],"verseLabel":"الشورى: 33","question":"لماذا قيل إن السفن تبقى ﴿على ظهره﴾ لا على سطح البحر؟","answer":"صوّر البحر ككائن له ظهر بارز تحمل عليه السفن، فبرز استقرارها وعلوها وظهورها للناظر. وهذه الاستعارة أقوى من لفظ السطح في تجسيد ثبات الأجسام الثقيلة فوق الماء.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص288–289، تحت عنوان «سر التعبير بلفظ ﴿ظهره﴾ دون (سطحه)»","url":""}]},{"id":"s42-90","number":90,"surah":42,"verses":[33],"references":[{"surah":42,"verses":[33]}],"verseLabel":"الشورى: 33","question":"لماذا وصفت الآية المنتفع بآيات البحر بأنه ﴿صبار شكور﴾؟","answer":"لأن البحر يجمع أحوالًا تتكرر فيها الشدائد والنعم؛ فشدته تحتاج إلى صبر كثير، وتسخيره والنجاة فيه يحتاجان إلى شكر كثير. وصيغتا المبالغة تدلان على رسوخ الصفتين وتجددهما في صاحب العبرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص291، تحت عنوان «سر اختيار ﴿صبار شكور﴾ مادة وصيغة وتنكيرًا»","url":""}]},{"id":"s42-184","number":184,"surah":42,"verses":[33],"references":[{"surah":42,"verses":[33]}],"verseLabel":"الشورى: 33","question":"لماذا قُدّم ﴿صبار﴾ على ﴿شكور﴾؟","answer":"لأن الصبر يسبق الشكر عند الشدة ويمهد له؛ فالإنسان يصبر على الخطر أولًا ثم يشكر نعمة التيسير والنجاة. كما أن الثبات على الشكر نفسه يحتاج إلى صبر، فكان تقديم الصبر أنسب.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص291، تحت عنوان «سر تقديم ﴿صبار﴾ على ﴿شكور﴾»","url":""}]},{"id":"s42-91","number":91,"surah":42,"verses":[33,34],"references":[{"surah":42,"verses":[33,34]}],"verseLabel":"الشورى: 33–34","question":"ماذا يضيف قوله ﴿أو يوبقهن﴾ بعد إمكان إسكان الريح؟","answer":"يضيف وجهًا آخر من القدرة والتهديد: فالله قد يسكن الريح فتركد السفن، وقد يرسلها عاصفة فتغرق. وبذلك تظهر أحوال السير والتوقف والهلاك جميعًا خاضعة لمشيئته.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص292، تحت عنوان «دلالة عطف قوله ﴿أو يوبقهن﴾ على جزاء الشرط»","url":""}]},{"id":"s42-185","number":185,"surah":42,"verses":[33,34],"references":[{"surah":42,"verses":[33,34]}],"verseLabel":"الشورى: 33–34","question":"لماذا أُسند الإهلاك إلى السفن في قوله ﴿يوبقهن﴾ مع أن الهلاك يقع على ركابها؟","answer":"لأن السفن أقيمت مقام أهلها بالمجاز، فكأنها كائنات حية يصيبها الهلاك بسبب أفعال راكبيها. وهذا التجسيد يشدد صورة الخطر ويجعل مصير السفينة وركابها مشهدًا واحدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص293، تحت عنوان «بلاغة التعبير بالمجاز العقلي في ﴿يوبقهن﴾»","url":""}]},{"id":"s42-92","number":92,"surah":42,"verses":[30,34],"references":[{"surah":42,"verses":[30,34]}],"verseLabel":"الشورى: 30، 34","question":"ماذا يكشف قوله ﴿وَيَعْفُ عَنْ كَثِيرٍ﴾ بعد تهديد السفن بالإهلاك؟","answer":"يكشف أن القدرة التي تملك إغراق السفن تقترن بالعفو؛ فقد يهلك الله قومًا، وقد ينجي كثيرًا ممن استحقوا الهلاك، فتكون نجاتهم تجاوزًا ورحمة لا عجزًا عن مؤاخذتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص295، تحت عنوان «دلالة العطف في قوله ﴿ويعف﴾»","url":""}]},{"id":"s42-93","number":93,"surah":42,"verses":[35],"references":[{"surah":42,"verses":[35]}],"verseLabel":"الشورى: 35","question":"لماذا انتقل السياق من آيات البحر إلى الحديث عن المجادلين في آيات الله؟","answer":"لأن تسخير البحر وجريان السفن وركودها أو غرقها دلائل مشاهدة على القدرة؛ فمن يجادل بعد هذا البيان لا يطلب الحجة بل ينازع في آيات ظاهرة. فجاء الانتقال ليكشف عناده ويهدده بعاقبة المكابرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص300، تحت عنوان «مناسبة الآية لما قبلها»","url":""}]},{"id":"s42-186","number":186,"surah":42,"verses":[35],"references":[{"surah":42,"verses":[35]}],"verseLabel":"الشورى: 35","question":"ماذا يضيف ختام الآية بقوله ﴿ما لهم من محيص﴾؟","answer":"يذيّل تهديد المجادلين بنفي أي موضع يهربون إليه من لقاء الله وعذابه. فكما لا يملك ركاب السفن الخروج من سلطان البحر حين يحيط بهم الخطر، لا يملك المعاندون الإفلات من قدرة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص305، تحت عنوان «بلاغة التذييل بقوله ﴿ما لهم من محيص﴾»","url":""}]},{"id":"s42-94","number":94,"surah":42,"verses":[36],"references":[{"surah":42,"verses":[36]}],"verseLabel":"الشورى: 36","question":"ما دلالة وصف ما أوتيه الناس بأنه ﴿متاع الحياة الدنيا﴾؟","answer":"المتاع ما ينتفع به زمنًا ثم ينقضي، وإضافته إلى الحياة الدنيا تؤكد فناءه وقلة بقائه. فالتعبير يضع العطايا الدنيوية في قدرها، ويهيئ للموازنة بينها وبين الخير الباقي عند الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص310–311، تحت عنوان «سر التعبير بالمتاع، والغرض من إضافته للدنيا في ﴿فمتاع الحياة الدنيا﴾»","url":""}]},{"id":"s42-95","number":95,"surah":42,"verses":[36],"references":[{"surah":42,"verses":[36]}],"verseLabel":"الشورى: 36","question":"ما دلالة الجمع بين ﴿خير﴾ و﴿أبقى﴾ في وصف ما عند الله؟","answer":"الخير يقرر تفوق ما عند الله في نفعه وجودته، والأبقى يقرر دوامه وعدم انقطاعه. فجمع الوصفان كمال النعمة وبقاءها، في مقابل متاع الدنيا الذي يشوبه النقص ويعتريه الزوال.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص313، تحت عنوان «دلالة التعبير بـ(أفعل) التفضيل في ﴿خير وأبقى﴾»","url":""}]},{"id":"s42-96","number":96,"surah":42,"verses":[36],"references":[{"surah":42,"verses":[36]}],"verseLabel":"الشورى: 36","question":"لماذا خُص ما عند الله بالذين آمنوا؟","answer":"لأن التعبير بالموصول يجعل الإيمان صفةً كاشفة عن سبب استحقاق الوعد؛ فما عند الله خير دائم لمن صدق به وعمل بمقتضى إيمانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص314، تحت عنوان «الغرض من التعبير باسم الموصول وصلته ﴿للذين آمنوا﴾»","url":""}]},{"id":"s42-203","number":203,"surah":42,"verses":[36],"references":[{"surah":42,"verses":[36]}],"verseLabel":"الشورى: 36","question":"ماذا يفيد تقديم ﴿عَلَى رَبِّهِمْ﴾ في وصف المتوكلين؟","answer":"يفيد اختصاص اعتمادهم بربهم؛ فهم لا يجعلون اتكال القلب على الأسباب أو الخلق، بل يرجعون في شؤونهم إليه وحده مع فعل ما يستطيعون.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص316، تحت عنوان «الغرض من تقديم ﴿على ربهم﴾ على الفعل ﴿يتوكلون﴾»","url":""}]},{"id":"s42-97","number":97,"surah":42,"verses":[37],"references":[{"surah":42,"verses":[37]}],"verseLabel":"الشورى: 37","question":"ما سر اختيار الاجتناب دون الترك في قوله ﴿يَجْتَنِبُونَ كَبَائِرَ الْإِثْمِ وَالْفَوَاحِشَ﴾؟","answer":"الاجتناب جعل الشيء في جانب بعيد، فهو يصور شدة المباعدة عن الإثم، لا مجرد تركه مع البقاء قريبًا من دواعيه. وصيغة الفعل تدل على مجاهدة المؤمنين أنفسهم ليستمروا على هذه المباعدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص323، تحت عنوان «دلالة التعبير بالفعل ﴿يجتنبون﴾ مادة وصيغة»","url":""}]},{"id":"s42-98","number":98,"surah":42,"verses":[37],"references":[{"surah":42,"verses":[37]}],"verseLabel":"الشورى: 37","question":"هل تدل عبارة ﴿كَبَائِرَ الْإِثْمِ﴾ على أن الذنوب درجة واحدة؟","answer":"لا؛ فالإثم اسم عام يدخل فيه الصغير والكبير، وإضافة ﴿كَبَائِرَ﴾ إليه تكشف أن الذنوب متفاوتة الدرجات. لذلك تركز صفة المدح هنا على اجتناب العظائم، وفي هذا التفريق أثر من رحمة الله بعباده من غير أن يكون ترخيصًا في الصغائر.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص324، تحت عنوان «الغرض من إضافة ﴿كبائر﴾ إلى ﴿الإثم﴾»","url":""}]},{"id":"s42-187","number":187,"surah":42,"verses":[37],"references":[{"surah":42,"verses":[37]}],"verseLabel":"الشورى: 37","question":"لماذا خُصَّت ﴿الْفَوَاحِشَ﴾ بالذكر بعد ﴿كَبَائِرَ الْإِثْمِ﴾ مع أنها منها؟","answer":"عطف الفواحش من تخصيص الخاص بعد العام؛ فهي داخلة في كبائر الإثم، لكن إفرادها بالذكر ينبه إلى بلوغها الغاية في القبح والخطر، ويؤكد شدة العناية باجتنابها كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص324–325، تحت عنوان «دلالة العطف في ﴿والفواحش﴾»","url":""}]},{"id":"s42-99","number":99,"surah":42,"verses":[37],"references":[{"surah":42,"verses":[37]}],"verseLabel":"الشورى: 37","question":"كيف يصوّر المضارع ﴿يَغْفِرُونَ﴾ تعامل المؤمنين مع الغضب؟","answer":"يصوّر المغفرة سجيّة تتجدد منهم كلما تجدد الغضب؛ فلا يكون الصفح موقفًا عابرًا وقع مرة، بل خلقًا مستمرًا مع القدرة على الرد. ويقابل ذلك مجيء الغضب بالماضي، كأنه عارض سريع الزوال بينما يبقى العفو هو الأصل.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص327–328، تحت عنوان «دلالة التعبير بالمضارع ﴿يغفرون﴾»","url":""}]},{"id":"s42-100","number":100,"surah":42,"verses":[38],"references":[{"surah":42,"verses":[38]}],"verseLabel":"الشورى: 38","question":"لماذا جاء الإنفاق بعد الاستجابة والصلاة والشورى في صفات المؤمنين؟","answer":"لأن الإنفاق صورة عملية من الاستجابة لله، وفي مجيئه بعد الشورى اكتمال لتعاون الجماعة: يبذلون خبرة عقولهم بالمشاورة، ويبذلون فضل أموالهم بالمواساة. وهكذا تجتمع العبادة والرأي والمال في بناء جماعة متآلفة كالجسد الواحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص339–340، تحت عنوان «بلاغة عطف قوله ﴿ومما رزقناهم ينفقون﴾ على ما سبق»","url":""}]},{"id":"s42-101","number":101,"surah":42,"verses":[38],"references":[{"surah":42,"verses":[38]}],"verseLabel":"الشورى: 38","question":"لماذا قيل ﴿وَأَمْرُهُمْ شُورَى﴾ ولم يقل: «يتشاورون»؟","answer":"الإخبار بالمصدر مبالغة في تمكن هذا الخلق منهم؛ فكأن أمرهم المشترك هو الشورى نفسها، لا مجرد فعل يقع أحيانًا. وفيه إشعار بأن تشاورهم عظيم صادق، تحمله النصيحة وصفاء القصد.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص337، تحت عنوان «دلالة التعبير بالمصدر ﴿شورى﴾ دون غيره»","url":""}]},{"id":"s42-188","number":188,"surah":42,"verses":[38],"references":[{"surah":42,"verses":[38]}],"verseLabel":"الشورى: 38","question":"ماذا تضيف الجملة الاسمية ﴿وَأَمْرُهُمْ شُورَى بَيْنَهُمْ﴾ إلى وصف المؤمنين؟","answer":"تجعل الشورى شأنًا ثابتًا مستقرًا في جماعتهم، لا تصرفًا عارضًا ينفك عنهم عند تغير الظروف. ولذلك عدل السياق إليها بين جمل فعلية ليلفت إلى رسوخ هذا الخلق وعظيم العناية به.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص338، تحت عنوان «دلالة التعبير بالجملة الاسمية ﴿وأمرهم شورى بينهم﴾»","url":""}]},{"id":"s42-102","number":102,"surah":42,"verses":[38],"references":[{"surah":42,"verses":[38]}],"verseLabel":"الشورى: 38","question":"ما سر توسط الشورى بين الصلاة والإنفاق؟","answer":"توسط الشورى يبرز أثرها في انتظام أمر الجماعة واجتماعها على ما يحقق الخير. فهي مع الصلاة والإنفاق من الخصال التي تقيم المجتمع على طاعة الله والتعاون، وتشير إلى العناية بالشأن المشترك.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص336، تحت عنوان «دلالة توسط أمر الشورى بين إقامة الصلاة والإنفاق»","url":""}]},{"id":"s42-103","number":103,"surah":42,"verses":[38],"references":[{"surah":42,"verses":[38]}],"verseLabel":"الشورى: 38","question":"لماذا لم يُذكر في ماذا ينفق المؤمنون؟","answer":"ليعم الإنفاق كل وجه مشروع نافع، من سد حاجة الفقير إلى مصالح الجماعة وسائر أبواب البر، فلا يحصره اللفظ في مصرف واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص342، تحت عنوان «الغرض من حذف متعلق الإنفاق»","url":""}]},{"id":"s42-104","number":104,"surah":42,"verses":[37,39],"references":[{"surah":42,"verses":[37,39]}],"verseLabel":"الشورى: 37، 39","question":"لماذا خُصَّ الغضب بالذكر عند مدح المؤمنين بالمغفرة؟","answer":"لأن الغضب من أشد دوافع الثأر والانتقام، والسيطرة عليه صعبة؛ فإذا عفا المؤمن في تلك اللحظة ظهر كمال إيمانه وقوة إرادته وابتعاده عن أخلاق الجاهلية. ففضل المغفرة يتجلى أوضح ما يكون حين يشتد باعث الرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص328، تحت عنوان «سر تخصيص الغضب بالغفران»","url":""}]},{"id":"s42-189","number":189,"surah":42,"verses":[37,39],"references":[{"surah":42,"verses":[37,39]}],"verseLabel":"الشورى: 37، 39","question":"كيف يجتمع مدح المؤمنين بالعفو عند الغضب ومدحهم بالانتصار عند البغي؟","answer":"يختلف الحكم باختلاف أثر الموقف: يُمدح العفو حين يسكن الفتنة ويرد الجاني عن جنايته، ويُمدح الانتصار المنضبط حين يشجّع العفو الظالم على مزيد من البغي. فالقرآن يجمع بين تهذيب النفس وحماية الحقوق، ولا يجعل الصفح ذلًا ولا الانتصار تشفيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص347–348، تحت عنوان «دفع توهم معارضة هذه الآية لقوله ﴿وإذا ما غضبوا هم يغفرون﴾»","url":""}]},{"id":"s42-105","number":105,"surah":42,"verses":[40],"references":[{"surah":42,"verses":[40]}],"verseLabel":"الشورى: 40","question":"ما سر تسمية عقوبة السيئة ﴿سَيِّئَةٌ﴾ في قوله ﴿جَزَاءُ سَيِّئَةٍ سَيِّئَةٌ مِثْلُهَا﴾؟","answer":"سميت العقوبة سيئة لمشاكلتها الإساءة الأولى في اللفظ والصورة، ولأنها تسوء من تقع عليه، مع أن الجزاء العادل غير مذموم. فالتسمية لا تسوي الحكم الأخلاقي بين العدوان وعقوبته المشروعة، بل تراعي المناسبة بين الفعل وجزائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص353–354، تحت عنوان «بلاغة التعبير بالمشاكلة في ﴿وجزاء سيئة سيئة مثلها﴾»","url":""}]},{"id":"s42-106","number":106,"surah":42,"verses":[40],"references":[{"surah":42,"verses":[40]}],"verseLabel":"الشورى: 40","question":"ما دلالة تقييد جزاء السيئة بالمماثلة قبل فتح باب العفو والإصلاح؟","answer":"المماثلة تمنع أن يتحول استيفاء الحق إلى عدوان زائد، فتضبط الانتصار بالعدل. ثم ينتقل النظم إلى العفو والإصلاح ترغيبًا في مرتبة الإحسان إذا تحققت بها المصلحة، مع بقاء حق الجزاء في حدوده.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص354، تحت عنوان «بلاغة التقييد في قوله ﴿وجزاء سيئة سيئة مثلها﴾»","url":""}]},{"id":"s42-107","number":107,"surah":42,"verses":[40],"references":[{"surah":42,"verses":[40]}],"verseLabel":"الشورى: 40","question":"لماذا لم يبيّن القرآن مقدار أجر من عفا وأصلح؟","answer":"إبهام الأجر يعظمه؛ فهو وعد من الله الكريم بأجر يخرج عن المقادير المألوفة ولا يحيط بكنهه أحد. لذلك كان تركه بلا رقم أبلغ في الرجاء والترغيب في العفو الذي يحقق الإصلاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص359، تحت عنوان «دلالة الإبهام في عدم تعيين الأجر في قوله ﴿فأجره على الله﴾»","url":""}]},{"id":"s42-108","number":108,"surah":42,"verses":[40],"references":[{"surah":42,"verses":[40]}],"verseLabel":"الشورى: 40","question":"لماذا خُتمت أحكام الانتصار والعفو بقوله ﴿إِنَّهُ لَا يُحِبُّ الظَّالِمِينَ﴾؟","answer":"ليظل حق الانتصار منضبطًا بالعدل؛ فالمعتدى عليه لا يملك أن يزيد على حقه فيتحول هو إلى ظالم. والختام قاعدة عامة تذم الباغي، وتحذر المنتصر من تجاوز المماثلة، وتؤكد في الوقت نفسه فضل العفو والإصلاح حين يكونان في موضعهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص362، تحت عنوان «بلاغة التذييل بجملة ﴿إنه لا يحب الظالمين﴾»","url":""}]},{"id":"s42-109","number":109,"surah":42,"verses":[40,41],"references":[{"surah":42,"verses":[40,41]}],"verseLabel":"الشورى: 40–41","question":"لماذا سُمِّيت معاقبة الظالم انتصارًا للمظلوم؟","answer":"لأن ردع الظالم المفسد عن التمادي في عدوانه نصر للمظلوم وللمجتمع، ولأن المظلوم يتحرى باستيفاء حقه الجزاء العادل؛ فاللفظ يصوّر طلب الحق لا التشفي المفتوح.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص368، تحت عنوان «دلالة التعبير بـ﴿انتصر﴾ مادة وصيغة»","url":""}]},{"id":"s42-190","number":190,"surah":42,"verses":[40,41],"references":[{"surah":42,"verses":[40,41]}],"verseLabel":"الشورى: 40–41","question":"لماذا قُيِّد انتصار المظلوم بأنه يكون ﴿بَعْدَ ظُلْمِهِ﴾؟","answer":"لأن استيفاء الحق لا يبدأ إلا بعد وقوع ظلم محقق؛ أما مجرد نية الاعتداء قبل أن يصدر من صاحبها قول أو فعل فلا تُقابل بعدوان مماثل، وإنما يُردع صاحبها بالوسيلة المشروعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص368، تحت عنوان «سر التقييد بالظرفية ﴿بعد﴾»","url":""}]},{"id":"s42-110","number":110,"surah":42,"verses":[41,42],"references":[{"surah":42,"verses":[41,42]}],"verseLabel":"الشورى: 41–42","question":"لماذا عُبّر عن المؤاخذة بلفظ ﴿السَّبِيلُ﴾؟","answer":"صُورت المؤاخذة طريقًا واضحًا تسلكه الحجة إلى مستحقها؛ فلا طريق للوم المظلوم المنتصر في حد حقه، وإنما يقوم الطريق على المعتدي.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص370، تحت عنوان «سر التعبير بلفظ ﴿سبيل﴾ وبلاغة المجاز فيه»","url":""}]},{"id":"s42-204","number":204,"surah":42,"verses":[41,42],"references":[{"surah":42,"verses":[41,42]}],"verseLabel":"الشورى: 41–42","question":"ماذا يفيد قصر السبيل على الذين يظلمون الناس؟","answer":"يحصر اللوم والعقوبة في المعتدين الذين يبغون بغير حق، فيبرئ المظلوم الذي استوفى حقه من المؤاخذة ويحدد موضع الإدانة بدقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص371، تحت عنوان «الغرض من التعبير بأسلوب القصر بـ﴿إنما﴾»","url":""}]},{"id":"s42-111","number":111,"surah":42,"verses":[42],"references":[{"surah":42,"verses":[42]}],"verseLabel":"الشورى: 42","question":"لماذا قيل إنهم ﴿يَبْغُونَ فِي الْأَرْضِ﴾ ولم يقل: في الدنيا؟","answer":"لأن لفظ الأرض يستحضر الموطن الذي استخلف الله الناس لإعماره وإصلاحه، فيبدو بغيهم نقضًا للأمانة وإفسادًا للمكان المشترك بعد إصلاحه؛ كما يعمم الذم كل بغي يقع في أي جزء منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص374، تحت عنوان «سر تقييد البغي بلفظ ﴿في الأرض﴾ دون الدنيا»","url":""}]},{"id":"s42-112","number":112,"surah":42,"verses":[41,42,43],"references":[{"surah":42,"verses":[41,42,43]}],"verseLabel":"الشورى: 41–43","question":"ما سر العودة إلى مدح الصبر والمغفرة بعد تقرير جواز الانتصار؟","answer":"بعد تقرير حق الانتصار يرجع السياق إلى الترغيب في الصبر والعفو، حتى يجتمع حفظ الحق مع تهذيب النفس. فليس المقصود إبطال الانتصار المشروع، بل بيان فضل المسامحة في الموضع الذي يصلح له العفو.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص377، تحت عنوان «مناسبة الآية لما قبلها»","url":""}]},{"id":"s42-113","number":113,"surah":42,"verses":[43],"references":[{"surah":42,"verses":[43]}],"verseLabel":"الشورى: 43","question":"هل يكفي أن يصبر المظلوم عن الرد من غير أن يغفر؟","answer":"قد يصبر الإنسان على الإساءة ويؤخر الانتصار لنفسه، لكن يبقى أثرها في قلبه؛ لذلك عُطفت المغفرة على الصبر لتجمع الآية بين احتمال الأذى وصفح النفس عن المسيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص380، تحت عنوان «دلالة عطف المغفرة على الصبر في ﴿صبر وغفر﴾»","url":""}]},{"id":"s42-191","number":191,"surah":42,"verses":[43],"references":[{"surah":42,"verses":[43]}],"verseLabel":"الشورى: 43","question":"لماذا قُدِّم الصبر على المغفرة في قوله ﴿صَبَرَ وَغَفَرَ﴾؟","answer":"لأن الصبر هو الأساس الذي يحمل صاحبه على كف الانتقام، ولأن العفو المحمود ما صدر عن قدرة واحتمال لا عن عجز؛ فالتقديم يميز الصفح الأخلاقي من مجرد عدم القدرة على الرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص380، تحت عنوان «غرض تقديم الصبر على المغفرة»","url":""}]},{"id":"s42-114","number":114,"surah":42,"verses":[43],"references":[{"surah":42,"verses":[43]}],"verseLabel":"الشورى: 43","question":"ما سر التعبير عن الصبر والمغفرة بأنهما ﴿لَمِنْ عَزْمِ الْأُمُورِ﴾؟","answer":"اختير العزم لما يدل عليه من قوة وثبات ونفاذ؛ لأن الصبر على المكروه والعفو عمن أساء مع القدرة على الرد يحتاجان إلى قوة إرادة وثبات يصدران عن روية وإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص382، تحت عنوان «سر اختيار التعبير بلفظ ﴿عزم﴾»","url":""}]},{"id":"s42-115","number":115,"surah":42,"verses":[44],"references":[{"surah":42,"verses":[44]}],"verseLabel":"الشورى: 44","question":"كيف يحوّل المضارع في ﴿وَتَرَى الظَّالِمِينَ﴾ مصيرهم إلى مشهد حاضر؟","answer":"يستحضر رؤيتهم يوم القيامة كأنها تقع أمام المخاطب الآن، فيشاهد ذلهم وندامتهم بدل أن يسمع خبرًا بعيدًا؛ فتشتد العبرة والتحذير من الطريق الذي أوصلهم إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص390، تحت عنوان «دلالة التعبير بالمضارع ﴿وترى﴾»","url":""}]},{"id":"s42-116","number":116,"surah":42,"verses":[44],"references":[{"surah":42,"verses":[44]}],"verseLabel":"الشورى: 44","question":"ماذا يكشف سؤال الظالمين ﴿هَلْ إِلَى مَرَدٍّ مِنْ سَبِيلٍ﴾ عند رؤية العذاب؟","answer":"يكشف لهفتهم على فرصة فاتت؛ فالاستفهام تمنٍّ للرجوع إلى زمن العمل واستغاثة لطلب أي خلاص بعد معاينة العذاب، لا سؤال من يملك طريقًا حقيقيًا للنجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص393، تحت عنوان «الغرض من التعبير بالاستفهام في ﴿هل إلى مرد﴾»","url":""}]},{"id":"s42-192","number":192,"surah":42,"verses":[44],"references":[{"surah":42,"verses":[44]}],"verseLabel":"الشورى: 44","question":"لماذا لم يُذكر إلى أين يريد الظالمون الرجوع في ﴿هَلْ إِلَى مَرَدٍّ مِنْ سَبِيلٍ﴾؟","answer":"لأن المقام يكشف مرادهم: الرجوع إلى الدنيا قبل فوات العمل، أو الخروج من العذاب؛ وحذف الجهة يوسّع الحسرة، فكأنهم يطلبون أي مردّ وأي منفذ مهما كان.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص393، تحت عنوان «دلالة عدم ذكر محل المرد في الآية»","url":""}]},{"id":"s42-117","number":117,"surah":42,"verses":[45],"references":[{"surah":42,"verses":[45]}],"verseLabel":"الشورى: 45","question":"لماذا وُصف الظالمون بالخشوع عند عرضهم على النار؟","answer":"لأن الخشوع يُظهر على الجوارح أثر الانكسار والمهانة؛ فتبدو أجسامهم خاضعة ذليلة بعد استكبارهم في الدنيا، ويصير الجزاء صورة مقابلة لما كانوا عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص402، تحت عنوان «سر التعبير بالخشوع»","url":""}]},{"id":"s42-193","number":193,"surah":42,"verses":[45],"references":[{"surah":42,"verses":[45]}],"verseLabel":"الشورى: 45","question":"ما الذي تصوّره نظراتهم ﴿مِنْ طَرْفٍ خَفِيٍّ﴾؟","answer":"تصوّر نظرات ضعيفة مسروقة؛ يريدون رؤية ما يخافونه ولا يطيقون التحديق فيه، فينظرون من جانب وعلى استحياء وخوف، فتجتمع في حركتهم المهانة والرعب وانكسار النفوس.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص406، تحت عنوان «بلاغة التعبير بجملة ﴿ينظرون من طرف خفي﴾»","url":""}]},{"id":"s42-118","number":118,"surah":42,"verses":[45],"references":[{"surah":42,"verses":[45]}],"verseLabel":"الشورى: 45","question":"كيف يخسر الإنسان يوم القيامة نفسه وأهله معًا؟","answer":"يخسر نفسه باستحقاق العذاب، ويفقد الانتفاع بأهله: فإن كانوا معه في النار لم يغنوا عنه، وإن كانوا من أهل الجنة حيل بينه وبينهم؛ وقد تمتد الخسارة إلى أنه أورث أهله الضلال فصار سبب شقائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص411، تحت عنوان «سر التعبير بخسران الأنفس والأهل»","url":""}]},{"id":"s42-120","number":120,"surah":42,"verses":[44,46],"references":[{"surah":42,"verses":[44,46]}],"verseLabel":"الشورى: 44، 46","question":"ما سر تكرار ﴿وَمَنْ يُضْلِلِ اللَّهُ﴾ ثم اختلاف الجواب بين ﴿فَمَا لَهُ مِنْ وَلِيٍّ مِنْ بَعْدِهِ﴾ و﴿فَمَا لَهُ مِنْ سَبِيلٍ﴾؟","answer":"ينفي الموضع الأول الولي الذي يتولى من ضل، ثم يصور حاله عند العذاب. ويأتي الموضع الثاني بعد تمام المشهد لينفي سبيل الخلاص نفسه. فاختلاف الجواب يوافق موقع كل جملة: أولاهما تفتتح بيان الخذلان، والأخرى تغلق طرق النجاة بعد عرض عاقبته.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص423–424، تحت عنوان «توجيه المتشابه اللفظي»","url":""}]},{"id":"s42-121","number":121,"surah":42,"verses":[46],"references":[{"surah":42,"verses":[46]}],"verseLabel":"الشورى: 46","question":"كيف يجمع ختام الآية بين فقد الناصر وانسداد كل طريق للخلاص؟","answer":"نفت الآية أولًا أن يكون لهم أولياء ينصرونهم، ثم عممت بنفي أي سبيل؛ فالولي واحد من سبل الخلاص، ونفي السبيل يضم إليه كل طريق آخر يمكن أن يتوهموه للنجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص423، تحت عنوان «بلاغة التذييل في جملة الفاصلة»","url":""}]},{"id":"s42-122","number":122,"surah":42,"verses":[47],"references":[{"surah":42,"verses":[47]}],"verseLabel":"الشورى: 47","question":"لماذا قيل ﴿اسْتَجِيبُوا لِرَبِّكُمْ﴾ باسم الربوبية؟","answer":"ليذكّرهم بأن الداعي هو الذي رباهم ورعاهم وأنعم عليهم، فتجتمع رهبة الأمر مع باعث المحبة والشكر والرجوع إلى المحسن.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص429–430، تحت عنوان «سر إيثار لفظ الربوبية ﴿ربكم﴾ دون لفظ الجلالة»","url":""}]},{"id":"s42-123","number":123,"surah":42,"verses":[47],"references":[{"surah":42,"verses":[47]}],"verseLabel":"الشورى: 47","question":"كيف يجعل المضارع في ﴿أَنْ يَأْتِيَ يَوْمٌ﴾ القيامةَ حاضرةً في النفس قبل وقوعها؟","answer":"يدل المضارع على أن إتيان اليوم مستقبل، لكنه يدعو السامع في الوقت نفسه إلى استحضار مشاهده كأنها ماثلة أمامه؛ فيتحول الخبر عن الغيب إلى واعظ حي يحث على الاستجابة قبل فوات الأوان.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص431، تحت عنوان «نكتة صيغة المضارع في ﴿يأتي﴾»","url":""}]},{"id":"s42-194","number":194,"surah":42,"verses":[47],"references":[{"surah":42,"verses":[47]}],"verseLabel":"الشورى: 47","question":"لماذا جُعل يوم القيامة نفسه ﴿لَا مَرَدَّ لَهُ﴾ مع أن الناس هم العاجزون عن رده؟","answer":"أُسند عدم الرد إلى اليوم مبالغةً في تهويله؛ فكأن حتميته صفة قائمة به لا يستطيع أحد تغييرها. وتزيد هذه الصورة ضغط الإنذار على الظالمين ليرجعوا إلى الإيمان قبل مجيئه.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص432، تحت عنوان «سر نسبة الرد إلى اليوم»","url":""}]},{"id":"s42-124","number":124,"surah":42,"verses":[47],"references":[{"surah":42,"verses":[47]}],"verseLabel":"الشورى: 47","question":"ماذا أضاف قوله ﴿وَمَا لَكُمْ مِنْ نَكِيرٍ﴾ بعد نفي كل ملجأ يوم القيامة؟","answer":"أضاف أنهم لا يملكون إنكار العذاب ولا حجة تدفعه، كما لا يملكون مكانًا أو عاصمًا يهربون إليه؛ فاجتمع انتفاء العاصم وانتفاء الحجة، وبلغ إفلاسهم غايته، ليبقى طريق النجاة قبل ذلك اليوم هو الاستجابة لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص435، تحت عنوان «بلاغة عطف ﴿وما لكم من نكير﴾»","url":""}]},{"id":"s42-125","number":125,"surah":42,"verses":[48],"references":[{"surah":42,"verses":[48]}],"verseLabel":"الشورى: 48","question":"ما سر مقابلة نفي كون الرسول ﷺ حفيظًا على المعرضين بقصر مهمته على البلاغ؟","answer":"الحفظ المنفي يتناول مراقبة أعمالهم وإحصاءها وإجبارهم على الإيمان، وهي أمور لا تقتضيها وظيفة البلاغ. والقصر يقرر أن عليه إيصال الرسالة؛ أما حسابهم وتوفيقهم فإلى الله، وفي ذلك تسلية له عن إعراضهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص444–445، تحت عنوان «بلاغة القصر بالنفي والاستثناء»","url":""}]},{"id":"s42-126","number":126,"surah":42,"verses":[48],"references":[{"surah":42,"verses":[48]}],"verseLabel":"الشورى: 48","question":"لماذا وصف تعلق الإنسان بالنعمة بـ﴿فَرِحَ بِهَا﴾ ولم يقل: بطر بها؟","answer":"لأن الفرح أعم من البطر: قد يكون محمودًا أو مذمومًا، وهو يكشف أصل تعلق النفس بالنعم؛ أما البطر فهو إساءة استعمال النعمة ولا يكون إلا مذمومًا. وفي السياق تجاوز الفرح حد السرور إلى التعلق المتجبر، فظهر الذم من المقام لا من أصل اللفظ وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص451، تحت عنوان «نكتة التعبير بالفرح دون البطر»","url":""}]},{"id":"s42-127","number":127,"surah":42,"verses":[48],"references":[{"surah":42,"verses":[48]}],"verseLabel":"الشورى: 48","question":"لماذا أُعيد اسم ﴿الْإِنْسَانَ﴾ ظاهرًا في قوله ﴿فَإِنَّ الْإِنْسَانَ كَفُورٌ﴾؟","answer":"لتسجيل كفران النعمة على جنس الإنسان حين تستحكم فيه هذه الطبيعة، والتنبيه إلى أن الفرح بالنعمة ثم نسيان المنعم خلق بشري متكرر، لا حادثة عارضة لفرد واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص457–458، تحت عنوان «سر إظهار لفظ الإنسان»","url":""}]},{"id":"s42-128","number":128,"surah":42,"verses":[48],"references":[{"surah":42,"verses":[48]}],"verseLabel":"الشورى: 48","question":"لماذا وُصف الإنسان بالكفران عند إصابته بسيئة سببها عمله؟","answer":"لأن ما يصيبه قليل من كثير مما كسب، ولم يؤاخذه الله بكل ما قدمت يداه؛ فكان حقه أن يرى العفو الواسع فيشكر، لكنه يستعظم البلاء وينسى سببه وما بقي له من النعم، فيظهر كفرانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص456، تحت عنوان «سر ذكر هذه الفاصلة مع إصابة السيئة»","url":""}]},{"id":"s42-195","number":195,"surah":42,"verses":[48],"references":[{"surah":42,"verses":[48]}],"verseLabel":"الشورى: 48","question":"كيف كشفت الآية ما حُذف من حال الإنسان في النعمة والشدة؟","answer":"ذكرت فرحه عند الرحمة، فدل مقابله على حزنٍ محذوف عند السيئة؛ وذكرت كفرانه عند السيئة، فدل مقابله على شكرٍ غائب عند الرحمة. بهذا الاحتباك حذرت من بطر الرخاء وجزع الشدة معًا، وأبرزت ما ينبغي ألا يقع من الإنسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص458، تحت عنوان «بلاغة الاحتباك في الآية»","url":""}]},{"id":"s42-129","number":129,"surah":42,"verses":[49],"references":[{"surah":42,"verses":[49]}],"verseLabel":"الشورى: 49","question":"لماذا انتقل السياق من تقلب الإنسان بين الفرح والكفران إلى قوله ﴿لِلَّهِ مُلْكُ السَّمَاوَاتِ وَالْأَرْضِ﴾؟","answer":"لأن تقلب الإنسان يثير سؤالًا عن سر اختلاف أحواله، فجاء الجواب بأن الله وحده مالك الكون والمتصرف في الخلق والأحوال. ثم عُرض تنوع الذرية مثالًا محسوسًا لمشيئته: يهب هذا، ويجمع ذاك، ويمنع آخر بحكمة وقدرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص460–461، تحت عنوان «علة فصل ﴿لله ملك السماوات والأرض﴾»","url":""}]},{"id":"s42-130","number":130,"surah":42,"verses":[49],"references":[{"surah":42,"verses":[49]}],"verseLabel":"الشورى: 49","question":"لماذا كررت الآية ﴿يَهَبُ﴾ و﴿لِمَنْ يَشَاءُ﴾ مع الإناث والذكور بدل أن تجمعهما في عبارة واحدة؟","answer":"ليفرد كل هبة بالعناية ويؤكد استقلالها بمشيئة الله، فلا يُجعل أحد الصنفين تابعًا للآخر. وفي التكرار تقرير أن الإناث والذكور عطيتان متساويتان في أصل الهبة، تستحق كل منهما الشكر ولا يليق الانتقاص من شأن الإناث.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص467، تحت عنوان «بلاغة تكرار الهبة والمشيئة»","url":""}]},{"id":"s42-131","number":131,"surah":42,"verses":[49],"references":[{"surah":42,"verses":[49]}],"verseLabel":"الشورى: 49","question":"ما سر تقديم هبة الإناث على هبة الذكور؟","answer":"تذكر الموسوعة أن تقديم الإناث يلائم بيان أن الهبة بمشيئة الله، لا وفق ما يتخير الناس لأنفسهم؛ فقد كانوا يفضلون الذكور. وتذكر فيه أيضًا جبر خواطر من تلحقهم الوحشة بسبب كراهة الجاهلية للإناث، فقدم ذكرهن في مقام العطية والرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص466–467، تحت عنوان «سر تقديم (الإناث) على ﴿الذكور﴾»","url":""}]},{"id":"s42-132","number":132,"surah":42,"verses":[49],"references":[{"surah":42,"verses":[49]}],"verseLabel":"الشورى: 49","question":"ما دلالة تنكير ﴿إِنَاثًا﴾ وتعريف ﴿الذُّكُورَ﴾؟","answer":"الأصل في اسمي الجنس هنا التنكير، فبقيت ﴿إناثًا﴾ عليه. أما تعريف الذكور فوجهته الموسوعة بالعهد إلى الجنس المعروف في رغبتهم؛ أي الذكور الذين يتطلعون إليهم. وفي جمعهما تحت الهبة بيان أن كليهما عطية من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص466، تحت عنوان «سر تنكير (الإناث) وتعريف ﴿الذكور﴾»","url":""}]},{"id":"s42-133","number":133,"surah":42,"verses":[49,50],"references":[{"surah":42,"verses":[49,50]}],"verseLabel":"الشورى: 49–50","question":"لماذا قُدِّم الذكران على الإناث حين جمعهما في قوله ﴿ذُكْرَانًا وَإِنَاثًا﴾؟","answer":"لأن سبب تقديم الإناث في الهبة المنفردة—مخالفة اختيار الجاهلية وجبر خاطر من يكرههن—لم يعد قائمًا عند جمع الصنفين معًا. فعاد الترتيب هنا إلى ما يوافق مواضع خلق الزوجين في القرآن، مع بقاء الصنفين كليهما داخل العطية الإلهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص469، تحت عنوان «سر تقديم الذكران على الإناث»","url":""}]},{"id":"s42-134","number":134,"surah":42,"verses":[50],"references":[{"surah":42,"verses":[50]}],"verseLabel":"الشورى: 50","question":"لماذا قيل فيمن رُزق بنين وبنات ﴿يُزَوِّجُهُمْ﴾ بدل أن يقال: يهبهم؟","answer":"لأن التزويج هنا هو قرن أحد الصنفين بالآخر؛ فكل شيئين اقترن أحدهما بصاحبه زوجان. لذلك ناسب حال من جُمعت له هبة البنين والبنات، بعد أن استُعملت الهبة لكل صنف حين ذُكر منفردًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص468، تحت عنوان «نكتة التعبير بالتزويج دون الهبة»","url":""}]},{"id":"s42-196","number":196,"surah":42,"verses":[50],"references":[{"surah":42,"verses":[50]}],"verseLabel":"الشورى: 50","question":"ما الرحمة التي يفتحها قوله ﴿وَيَجْعَلُ مَنْ يَشَاءُ عَقِيمًا﴾ بدل «ويخلق عقيمًا»؟","answer":"يفرق الجعل بين أصل خلق الإنسان وبين الحالة التي يُصيَّر إليها؛ فقد يكون العقم طورًا أو وصفًا يتغير، لا حقيقة ملازمة منذ الخلق. كما يوجه اللفظ إلى حكمة الله في هذه الحال، فلا تُفهم على أنها عقوبة، وفي ذلك تطييب لخاطر من ابتلي بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص470–471، تحت عنوان «سر التعبير بالجعل دون الخلق مادة وصيغة»","url":""}]},{"id":"s42-197","number":197,"surah":42,"verses":[50],"references":[{"surah":42,"verses":[50]}],"verseLabel":"الشورى: 50","question":"كيف استوعبت الآيتان جميع أحوال الناس في الذرية؟","answer":"جاء التقسيم حاصرًا لا يترك صورة: إناث وحدهن، أو ذكور وحدهم، أو الصنفان معًا، أو عدم الولد. فجمع العطاء والمنع في أربعة أقسام تكشف شمول المشيئة الإلهية لكل أحوال الإنجاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص473، تحت عنوان «بلاغة التقسيم في الآيتين»","url":""}]},{"id":"s42-135","number":135,"surah":42,"verses":[50],"references":[{"surah":42,"verses":[50]}],"verseLabel":"الشورى: 50","question":"لماذا خُتم تقسيم أحوال الذرية بقوله ﴿إِنَّهُ عَلِيمٌ قَدِيرٌ﴾؟","answer":"لأن اختلاف العطاء والمنع لا يقع عبثًا، بل يصدر عن علم بمن تصلح له كل حال وقدرة على إنفاذها؛ فيدعو الموهوب إلى الشكر، ويعين المحروم على الرضا بحكم العليم القدير.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص474، تحت عنوان «وجه إيثار صفتي العلم والقدرة»","url":""}]},{"id":"s42-198","number":198,"surah":42,"verses":[50],"references":[{"surah":42,"verses":[50]}],"verseLabel":"الشورى: 50","question":"لماذا قُدِّم ﴿عَلِيمٌ﴾ على ﴿قَدِيرٌ﴾ بعد ذكر هبة الأولاد والعقم؟","answer":"لأن العلم أساس التصرف المحكم؛ فالله يعلم من يستحق كل صورة من العطاء والمنع، ثم تنفذ قدرته ما اقتضاه ذلك العلم. فجاء ترتيب الاسمين موافقًا لترتيب المعنى.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص474، تحت عنوان «غرض تقديم العليم على القدير»","url":""}]},{"id":"s42-136","number":136,"surah":42,"verses":[51],"references":[{"surah":42,"verses":[51]}],"verseLabel":"الشورى: 51","question":"ما دلالة تنكير ﴿بشر﴾ في قوله ﴿وما كان لبشر أن يكلمه الله﴾؟","answer":"جاء ﴿بشر﴾ نكرة في سياق النفي ليعم الحكم جنس البشر؛ فلا يختص بيان كيفية التكليم بفرد دون آخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص478، تحت عنوان «دلالة تنكير ﴿لبشر﴾»","url":""}]},{"id":"s42-137","number":137,"surah":42,"verses":[51],"references":[{"surah":42,"verses":[51]}],"verseLabel":"الشورى: 51","question":"كيف يقع تكليم الله للبشر في الصور الثلاث التي ذكرتها الآية؟","answer":"إما أن يلقي الله المعنى في القلب يقظة أو منامًا، وإما أن يُسمع كلامه من وراء حجاب دون رؤية المتكلم كما وقع لموسى، وإما أن يرسل ملكًا يبلغ ما شاء. فالمراد واحد، وتختلف وسيلة وصوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص477، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s42-138","number":138,"surah":42,"verses":[51],"references":[{"surah":42,"verses":[51]}],"verseLabel":"الشورى: 51","question":"لماذا سمّت الآية صور تكليم الله للبشر كلَّها ﴿وَحْيًا﴾؟","answer":"لأن الوحي لفظ جامع لكل تكليم من الله للإنسان، أيًّا كان طريقه، ولأنه يدل أصلًا على إلقاء العلم في خفاء؛ فجمع اللفظ شمول صور التكليم مع إبراز الصفة المشتركة بينها.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص479–480، تحت عنوان «بلاغة التعبير بالوحي»","url":""}]},{"id":"s42-139","number":139,"surah":42,"verses":[51],"references":[{"surah":42,"verses":[51]}],"verseLabel":"الشورى: 51","question":"لماذا خُتم بيان طرق الوحي بوصف الله بأنه ﴿عَلِيٌّ حَكِيمٌ﴾؟","answer":"لأن علوه ينزهه عن أن يكون تكليمه كتكليم البشر، وحكمته تقتضي أن يختار لكل رسول صورة الوحي التي تلائم حاله وطاقته؛ فاجتمع التنزيه مع حسن التدبير.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص485، تحت عنوان «وجه إيثار صفتي العلو والحكمة»","url":""}]},{"id":"s42-199","number":199,"surah":42,"verses":[51],"references":[{"surah":42,"verses":[51]}],"verseLabel":"الشورى: 51","question":"لماذا قُدِّم وصف الله بـ﴿عَلِيٌّ﴾ على ﴿حَكِيمٌ﴾ في ختام آية الوحي؟","answer":"لأن علو الله يهيئ نفوس البشر لتلقي خطابه، ثم تختار حكمته من صور التكليم ما يبلغ مراده على الوجه الأتم الأكمل؛ فجاء ترتيب الاسمين موافقًا لهذا المعنى.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص486، تحت عنوان «سر تقديم العلي على الحكيم»","url":""}]},{"id":"s42-140","number":140,"surah":42,"verses":[51,52],"references":[{"surah":42,"verses":[51,52]}],"verseLabel":"الشورى: 51–52","question":"إلى ماذا تشير ﴿كَذَلِكَ﴾ في قوله ﴿وَكَذَلِكَ أَوْحَيْنَا إِلَيْكَ﴾؟","answer":"تشير إلى صور التكليم المذكورة قبلها، أي أن ما أوحي إلى النبي ﷺ وقع بطريق من تلك الطرق، ولا سيما بواسطة الرسول الملكي؛ فتصل الإشارة الحكم بمثاله الحاضر.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص492، تحت عنوان «مرجع الإشارة في ﴿وكذلك﴾ ولطيفة إيثار التعبير بها»","url":""}]},{"id":"s42-141","number":141,"surah":42,"verses":[52],"references":[{"surah":42,"verses":[52]}],"verseLabel":"الشورى: 52","question":"لماذا وصف الله القرآن بأنه ﴿رُوحًا﴾؟","answer":"لأنه يحيي القلوب بالإيمان والعلم كما تحيا الأجساد بالروح، وينقل النفوس من موت الجهل والضلال إلى حياة الهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص494–495، تحت عنوان «حكمة التعبير بلفظ ﴿روحًا﴾»","url":""}]},{"id":"s42-142","number":142,"surah":42,"verses":[52],"references":[{"surah":42,"verses":[52]}],"verseLabel":"الشورى: 52","question":"لماذا عُقِّب تشبيه الوحي بالنور بقوله ﴿نَهْدِي بِهِ﴾؟","answer":"لأن الهداية هي وجه الشبه المقصود ومهمة الوحي الأولى: فكما يكشف النور الطريق المحسوس، يكشف الوحي طريق الحق ويأخذ من شاء الله به إلى السلامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص505، تحت عنوان «حكمة التعبير بمفردة الهداية في ﴿نهدي﴾»","url":""}]},{"id":"s42-143","number":143,"surah":42,"verses":[52],"references":[{"surah":1,"verses":[6]},{"surah":42,"verses":[52]}],"verseLabel":"الشورى: 52؛ الفاتحة: 6","question":"كيف تبقى هداية الرسول ﷺ ممتدة بعد وفاته؟","answer":"تبقى بما بلغه من القرآن والسنة؛ فجاء ﴿لَتَهْدِي﴾ مصورًا دوام مهمته في الدعوة إلى الله وتجدد ثمارها، إذ يحمل الوحي وهديه دعوته إلى الناس بعد وفاته.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص512، تحت عنوان «فائدة المضارعة في الفعل ﴿لتهدي﴾»","url":""}]},{"id":"s42-144","number":144,"surah":42,"verses":[52,53],"references":[{"surah":42,"verses":[52,53]}],"verseLabel":"الشورى: 52–53","question":"لماذا جاء ﴿صِرَاطِ اللَّهِ﴾ بعد قوله ﴿صِرَاطٍ مُسْتَقِيمٍ﴾؟","answer":"ليبين أن الطريق الذي يهدي إليه الرسول ليس طريقًا من عنده، بل هو طريق الله. وإضافته إلى الله تزكي دعوة الرسول وتعظم شأن هذا الصراط المستقيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص515، تحت عنوان «فائدة موقع ﴿صراط الله﴾»","url":""}]},{"id":"s42-145","number":145,"surah":42,"verses":[53],"references":[{"surah":42,"verses":[53]}],"verseLabel":"الشورى: 53","question":"لماذا كان قوله ﴿أَلَا إِلَى اللَّهِ تَصِيرُ الْأُمُورُ﴾ حسن ختام لسورة الشورى؟","answer":"لأن نهاية التلاوة توافق نهاية الأحداث كلها إلى الله؛ وفيها وعد لمن آمن بالوحي وسلك صراطه، ووعيد لمن عانده. فاختتمت السورة بالمصير الذي تنتهي عنده حججها ووعدها ووعيدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص520–521، تحت عنوان «بلاغة التذييل بجملة ﴿ألا إلى الله تصير الأمور﴾»","url":""}]},{"id":"s43-1","number":1,"surah":43,"verses":[1],"references":[{"surah":43,"verses":[1]}],"verseLabel":"عنوان السورة","question":"ما مناسبة تسمية السورة بـ«الزخرف»، مع أن اللفظ لم يرد فيها إلا مرة واحدة؟","answer":"ورد اسم الزخرف في سياق بيان متاع الدنيا، وهو رمز الزينة المادية التي افتتن بها المكذبون. وتسميتها به تلائم نقد هذه الموازين الزائلة، وتوجيه النظر إلى هداية القرآن وحكمته بدل الاغترار بالزخرف.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص525–526، تحت عنوان «اسم السورة، ومناسبة تسميتها»","url":""}]},{"id":"s43-2","number":2,"surah":43,"verses":[1],"references":[{"surah":43,"verses":[1]}],"verseLabel":"مقدمة السورة","question":"ما الخيط الذي يجمع جدل سورة الزخرف وقصصها؟","answer":"يجمعها صراع الوحي مع القيم المادية الموروثة: فقد خاصم المشركون الحق بترفهم وتقليد آبائهم، وردت السورة ميزانهم إلى الإيمان والوحي، ثم عرضت مصائر نماذج سابقة تؤكد هذا الصراع.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص526، تحت عنوان «المحور العام للسورة»","url":""}]},{"id":"s43-3","number":3,"surah":43,"verses":[1],"references":[{"surah":43,"verses":[1]}],"verseLabel":"مقدمة السورة","question":"ما المفارقة العقدية التي تكشفها سورة الزخرف في مجادلة المشركين؟","answer":"تكشف السورة تناقضهم بين الاعتراف بأن الله خالقهم وخالق الموجودات، وبين اتخاذ شركاء عاجزين معه ونسبة البنات إليه. فيكون إقرارهم بالخلق حجة على بطلان شركهم وافترائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص527–528، تحت عنوان «موضوعات السورة وخصائصها»","url":""}]},{"id":"s43-4","number":4,"surah":43,"verses":[1],"references":[{"surah":43,"verses":[1]}],"verseLabel":"مقدمة السورة","question":"لماذا جمعت سورة الزخرف بين قصص إبراهيم وموسى وعيسى عليهم السلام؟","answer":"جمعتها لتبطل أصول الانحراف التي واجهتها: تقليد الآباء في قصة إبراهيم، والاغترار بالملك في قصة موسى، والغلو في عيسى؛ فتتساند القصص في تقرير التوحيد وتصحيح ميزان الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص527–528، تحت عنوان «موضوعات السورة ومحاورها»","url":""}]},{"id":"s43-5","number":5,"surah":43,"verses":[1,2],"references":[{"surah":43,"verses":[1,2]}],"verseLabel":"الزخرف: 1–2","question":"ما دلالة القسم بـ﴿الكتاب المبين﴾ في افتتاح سورة الزخرف؟","answer":"القسم تنويه بعظمة القرآن ووضوحه، وقد اتحد المقسم به والمقسم عليه؛ فكأنه بلغ من شرفه أن يشهد لنفسه. ثم يبين أنه قرآن عربي ليعقله المخاطبون.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص533–534، تحت عنوان «بلاغة التناسب في القسم»","url":""}]},{"id":"s43-6","number":6,"surah":43,"verses":[2],"references":[{"surah":43,"verses":[2]}],"verseLabel":"الزخرف: 2","question":"ما سر وصف القرآن بـ﴿الْكِتَابِ الْمُبِينِ﴾ في سورة تعرض شبه المشركين وجدالهم؟","answer":"المبين يوضح الهدى من الضلال والحلال من الحرام، ويكشف ما يحتاج إليه الناس. وفي وصفه بذلك تعريض بالمعاندين من أهل اللسان؛ فهم يدركون وضوح بيانه ومع ذلك يعرضون عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص534–535، تحت عنوان «نكتة وصف الكتاب بـ﴿المبين﴾»","url":""}]},{"id":"s43-7","number":7,"surah":43,"verses":[2,3],"references":[{"surah":43,"verses":[2,3]}],"verseLabel":"الزخرف: 2–3","question":"ما دلالة الانتقال من ﴿الْكِتَابِ﴾ إلى ﴿قُرْآنًا عَرَبِيًّا﴾، واختيار ﴿جَعَلْنَاهُ﴾ بدل «أنزلناه»؟","answer":"وصفه بالكتاب يبرز ثبوته وبقاء هدايته، والتعبير بجعله قرآنًا عربيًا يعتني بخصوصية بيانه العربي المقصودة للفهم. وإيثار الجعل على الإنزال أو التسمية ينبه إلى أن هذه الخصوصية مرادة، لا مجرد وصف عارض.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص537، تحت عنوان «سر إيثار التعبير بالجعل في ﴿جعلناه قرآنًا﴾»","url":""}]},{"id":"s43-8","number":8,"surah":43,"verses":[3],"references":[{"surah":43,"verses":[3]}],"verseLabel":"الزخرف: 3","question":"ما المسؤولية التي يحملها قوله: ﴿لَعَلَّكُمْ تَعْقِلُونَ﴾ للمخاطبين؟","answer":"يحملهم مسؤولية إعمال عقولهم في القرآن بعد أن جاء بلسانهم واضحًا؛ فبيانه لا يغني عن تدبرهم، ومن أعرض عنه عطّل النعمة التي تتيح له إدراك الحق والانتفاع به.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص539–540، تحت عنوان «نكتة الصياغة في ﴿تعقلون﴾»","url":""}]},{"id":"s43-9","number":9,"surah":43,"verses":[3,4],"references":[{"surah":43,"verses":[3,4]}],"verseLabel":"الزخرف: 3–4","question":"لماذا قُيّد القرآن بأنه ﴿فِي أُمِّ الْكِتَابِ لَدَيْنَا﴾؟","answer":"ليثبت أن هذا القرآن ثابت في أصله المحفوظ عند الله، جامع لحقائق الكتب؛ فيسقط زعم المشركين أنه مختلق، ويظهر كمال تقديره وحفظه وشرف منزلته.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص542، تحت عنوان «نكتة التقييد بـ﴿في أم الكتاب لدينا﴾»","url":""}]},{"id":"s43-164","number":164,"surah":43,"verses":[3,4],"references":[{"surah":43,"verses":[3,4]}],"verseLabel":"الزخرف: 3–4","question":"ما سر الجمع بين وصفي القرآن ﴿لَعَلِيٌّ حَكِيمٌ﴾؟","answer":"يجمع الوصفان كمالين متلازمين: فهو بالغ العلو في قدره، بالغ الحكمة في بيانه؛ فلا يكون علوه غموضًا يمنع الانتفاع به، ولا حكمته منزلة بلا رفعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص545–546، تحت عنوان «لطيفة الجمع بين ﴿لعلي﴾، و﴿حكيم﴾»","url":""}]},{"id":"s43-10","number":10,"surah":43,"verses":[4],"references":[{"surah":43,"verses":[4]}],"verseLabel":"الزخرف: 4","question":"لماذا عُبّر عن اللوح المحفوظ بـ﴿أُمِّ الْكِتَابِ﴾؟","answer":"لأن الأم أصل ما يتفرع عنها؛ فالتعبير يصور اللوح المحفوظ أصلًا جامعًا للكتب، ويكني عن ثبوت القرآن فيه وسمو مصدره وحفظه.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص543–544، تحت عنوان «بلاغة الاستعارة، وما وراءها من كناية في ﴿أم الكتاب﴾»","url":""}]},{"id":"s43-165","number":165,"surah":43,"verses":[4],"references":[{"surah":43,"verses":[4]}],"verseLabel":"الزخرف: 4","question":"لماذا قُدّم ﴿فِي أُمِّ الْكِتَابِ لَدَيْنَا﴾ على وصف القرآن بالعلو والحكمة؟","answer":"لأن المقام يعتني أولًا بإثبات مصدر القرآن عند الله ونفي الشك فيه؛ فإذا تقرر أصله المحفوظ جاء وصفه بالعلو والحكمة نتيجة تليق بذلك المصدر.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص542–543، تحت عنوان «حكمة تقديم ﴿في أم الكتاب لدينا﴾ على الخبر»","url":""}]},{"id":"s43-11","number":11,"surah":43,"verses":[1,2,3,4],"references":[{"surah":43,"verses":[1,2,3,4]}],"verseLabel":"الزخرف: 1–4","question":"لماذا أقسم الله في مطلع السورة بـ﴿الْكِتَابِ الْمُبِينِ﴾؟","answer":"لأن القرآن نفسه آية التحدي وموضع إنكار المكذبين؛ فجاء القسم به تنويهًا بعظمته ووضوح دلالته، وتناسب المقسم به مع القضية التي يثبتها القسم.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص533–534، تحت عنوان «بلاغة التناسب في القسم»","url":""}]},{"id":"s43-12","number":12,"surah":43,"verses":[5],"references":[{"surah":43,"verses":[5]}],"verseLabel":"الزخرف: 5","question":"ما الصورة التي يرسمها قوله: ﴿أَفَنَضْرِبُ عَنْكُمُ الذِّكْرَ﴾؟","answer":"يصور إبعاد الذكر عنهم بصورة طرد الإبل الغريبة عن الحوض ومنعها منه؛ فتجعل الصورة حرمانهم من الوحي عقوبة مهولة بعد أن كان باب الهداية مفتوحًا لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص551، تحت عنوان «جمال الاستعارة التمثيلية في ﴿أفنضرب عنكم الذكر﴾»","url":""}]},{"id":"s43-166","number":166,"surah":43,"verses":[5],"references":[{"surah":43,"verses":[5]}],"verseLabel":"الزخرف: 5","question":"لماذا قيل: ﴿أَفَنَضْرِبُ عَنْكُمُ الذِّكْرَ صَفْحًا﴾؟","answer":"لأن الصفح مأخوذ من صفحة الوجه، فيصور الإعراض عنهم بترك الالتفات إليهم؛ وهو أشد من مجرد ترك الكلام، إذ يجمع الإهمال والحرمان من التذكير.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص552–553، تحت عنوان «دلالة التعبير بالصفح في ﴿أفنضرب عنكم الذكر صفحًا﴾»","url":""}]},{"id":"s43-13","number":13,"surah":43,"verses":[5],"references":[{"surah":43,"verses":[5]}],"verseLabel":"الزخرف: 5","question":"كيف يكشف قوله: ﴿إِنْ كُنْتُمْ قَوْمًا مُسْرِفِينَ﴾ أن إسرافهم لم يكن عذرًا لترك تذكيرهم؟","answer":"جاء إسرافهم في صورة الشرط مع أنه واقع؛ ليوبخهم على حال كان ينبغي ألا تقع، وينكر أن يصبح تماديهم في الباطل سببًا لقطع الوحي عنهم قبل إقامة الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص554–555، تحت عنوان «نكتة التقييد بـ (إن) على قراءة كسر همزتها»","url":""}]},{"id":"s43-14","number":14,"surah":43,"verses":[5],"references":[{"surah":43,"verses":[5]}],"verseLabel":"الزخرف: 5","question":"لماذا لم يمنع إسراف المخاطبين استمرار تذكيرهم بالقرآن؟","answer":"لأن الله أنزل الكتاب رحمةً ونصحًا ليبين لهم طريق الحق؛ فلا يقطع عنهم التذكير بسبب عنادهم، بل يمهلهم للرجوع ويقيم عليهم الحجة إن أصروا.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص548–549، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s43-15","number":15,"surah":43,"verses":[6,7,8],"references":[{"surah":43,"verses":[6,7,8]}],"verseLabel":"الزخرف: 6–8","question":"ما دلالة تدرج سنة المكذبين من كثرة إرسال الأنبياء إلى الاستهزاء بهم ثم إهلاك أمم أشد بطشًا؟","answer":"تقرر الآيات تكرر إرسال الرسل واستهزاء المكذبين بهم، ثم تذكر هلاك أمم كانت أشد قوة من المخاطبين. ففيها تسلية للنبي ﷺ وتحذير لقومه؛ إذ لا تمنع القوة عقوبة التكذيب، وإهلاك الأقوى ينذر الأضعف.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص558–559، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s43-16","number":16,"surah":43,"verses":[6,7,8],"references":[{"surah":43,"verses":[6,7,8]}],"verseLabel":"الزخرف: 6–8","question":"لماذا وُصفت الأمم السابقة بـ﴿الْأَوَّلِينَ﴾؟","answer":"ليستحضر اللفظ رسل الله وأممهم السابقين بوصفهم أصولًا في التاريخ البشري، ويقرر أن اعتراض المكذبين الحاليين امتداد لطريق قديم انتهى بأهله إلى الهلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص562، تحت عنوان «معنى (الـ) في ﴿الأولين﴾، ودلالة التعبير به»","url":""}]},{"id":"s43-167","number":167,"surah":43,"verses":[6,7,8],"references":[{"surah":43,"verses":[6,7,8]}],"verseLabel":"الزخرف: 6–8","question":"لماذا أُعيد لفظ ﴿الْأَوَّلِينَ﴾ ظاهرًا في قوله: ﴿وَمَضَى مَثَلُ الْأَوَّلِينَ﴾؟","answer":"لزيادة التقرير وربط مصير المكذبين مباشرة بمن سبقهم؛ فالإظهار يزيل احتمال عود الضمير إلى غيرهم، ويجعل سنتهم الماضية حاضرة في السمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص571، تحت عنوان «دلالة الإظهار في جملة ﴿ومضى مثل الأولين﴾»","url":""}]},{"id":"s43-17","number":17,"surah":43,"verses":[9],"references":[{"surah":43,"verses":[9]}],"verseLabel":"الزخرف: 9","question":"ما مناسبة وصف خالق السماوات والأرض بـ﴿العزيز العليم﴾؟","answer":"خلق السماوات والأرض بهذا الإحكام يدل على عزة لا تعجزها المخلوقات، وعلم محيط بتفاصيلها. وهذه صفات لا تتصف بها الأصنام، فذكرها يحتج على بطلان إشراك العاجز بمن خلق وأحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص578–579، تحت عنوان «دلالة تخصيص صفتي ﴿العزيز العليم﴾»","url":""}]},{"id":"s43-18","number":18,"surah":43,"verses":[9],"references":[{"surah":43,"verses":[9]}],"verseLabel":"الزخرف: 9","question":"هل نطق المشركون فعلًا بقولهم: ﴿خَلَقَهُنَّ الْعَزِيزُ الْعَلِيمُ﴾؟","answer":"جمهور المفسرين على أن أصل جوابهم كان: خلقهن الله، ثم حكى القرآن لازم اعترافهم ووصف الخالق بما يليق به؛ فحُذف قولهم المقدر وأقيم البيان الإلهي مقامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص579–580، تحت عنوان «دلالة الحذف في ﴿خلقهن العزيز العليم﴾»","url":""}]},{"id":"s43-19","number":19,"surah":43,"verses":[10],"references":[{"surah":43,"verses":[10]}],"verseLabel":"الزخرف: 10","question":"ما سر تشبيه الأرض بالمهد في قوله ﴿جَعَلَ لَكُمُ الْأَرْضَ مَهْدًا﴾؟","answer":"تشبيه الأرض بالمهد يستحضر ما يهيأ للوليد من راحة واستقرار. فكما هيئ المهد للطفل، هيأ الله الأرض لمعيشة الناس بما فيها من أسباب الانتفاع، وفي الصورة تذكير بعنايته وحث على شكره.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص582–583، تحت عنوان «بلاغة التشبيه في ﴿جعل لكم الأرض مهدًا﴾»","url":""}]},{"id":"s43-20","number":20,"surah":43,"verses":[10],"references":[{"surah":43,"verses":[10]}],"verseLabel":"الزخرف: 10","question":"لماذا قيل: ﴿وَجَعَلَ لَكُمْ فِيهَا سُبُلًا﴾ بالجمع؟","answer":"لأن تعدد السبل يبرز كثرة الطرق الممتدة في الأرض وتنوع المقاصد التي تبلغها؛ وهي نعمة تيسر التنقل والتعارف وجلب المنافع ودفع الأضرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص584–585، تحت عنوان «دلالة التعبير بـ﴿سبلًا﴾»","url":""}]},{"id":"s43-21","number":21,"surah":43,"verses":[9,10],"references":[{"surah":43,"verses":[9,10]}],"verseLabel":"الزخرف: 9–10","question":"لماذا عُرّف الخالق بقوله: ﴿الَّذِي جَعَلَ لَكُمُ الْأَرْضَ مَهْدًا﴾؟","answer":"لأن الموصول يستدعي أفعالًا يعرفها المخاطبون ويلفتهم إلى آثار عزة الله وعلمه في حياتهم؛ فمن مهّد لهم الأرض وشق فيها السبل هو المستحق وحده للشكر والطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص580–581، تحت عنوان «وجه التعبير بالموصول ﴿الذي﴾»","url":""}]},{"id":"s43-22","number":22,"surah":43,"verses":[11],"references":[{"surah":43,"verses":[11]}],"verseLabel":"الزخرف: 11","question":"لماذا قال عن المطر: ﴿وَالَّذِي نَزَّلَ مِنَ السَّمَاءِ مَاءً بِقَدَرٍ﴾؟","answer":"ليدل على أن نزوله مضبوط بمقدار تقتضيه الحكمة وتصلح به معايش الناس، لا فعلًا عشوائيًا؛ ولا يمنع ذلك أن يأتي الماء أحيانًا ابتلاءً أو تخويفًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص592، تحت عنوان «دلالة لفظ قدر»","url":""}]},{"id":"s43-23","number":23,"surah":43,"verses":[11],"references":[{"surah":43,"verses":[11]}],"verseLabel":"الزخرف: 11","question":"ما سر تذكير وصف البلدة في قوله ﴿بَلْدَةً مَيْتًا﴾؟","answer":"تذكر الموسوعة أن البلدة هنا بمعنى البلد أو المكان، فجاء الوصف مراعيًا هذا المعنى. وتذكر وجهًا آخر: أن «ميت» على أصل المصدر، والمصدر يوصف به المذكر والمؤنث؛ فلا يلزم من تذكيره اختلاف حقيقة الموصوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص595، تحت عنوان «نكتة العدول عن التأنيث في النعت»","url":""}]},{"id":"s43-24","number":24,"surah":43,"verses":[11],"references":[{"surah":43,"verses":[11]}],"verseLabel":"الزخرف: 11","question":"ما دلالة الاستدلال بإنشار البلدة الميتة على بعث الناس في قوله ﴿كَذَلِكَ تُخْرَجُونَ﴾؟","answer":"يشبه إخراج الأموات من قبورهم بإخراج النبات من البلدة الميتة. فالمشهد الحاضر يقرب إمكان البعث وينبه إلى قدرة من أحيا الأرض على إحياء الأجساد، ويصور المستقبل الموعود بصورة المحسوس المتحقق.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص598، تحت عنوان «بلاغة التشبيه في ﴿كذلك تخرجون﴾»","url":""}]},{"id":"s43-25","number":25,"surah":43,"verses":[10,11,12],"references":[{"surah":43,"verses":[10,11,12]}],"verseLabel":"الزخرف: 10–12","question":"لماذا لم يُكرر ﴿الَّذِي﴾ بين تمهيد الأرض وجعل السبل، بينما تكرر ﴿جَعَلَ لَكُمْ﴾؟","answer":"لأن الموصول الواحد يجمع النعمتين في تعريف المنعم، بينما يجدد تكرار الصلة العناية بكل نعمة على حدة: تمهيد الأرض، ثم فتح السبل فيها؛ فيتضاعف باعث الشكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص581–582، تحت عنوان «نكتة الاكتفاء بموصول واحد، وتكرار الصلتين»","url":""}]},{"id":"s43-26","number":26,"surah":43,"verses":[12,13,14],"references":[{"surah":43,"verses":[12,13,14]}],"verseLabel":"الزخرف: 12–14","question":"ما سر ذكر ركوب الفلك والأنعام دون الأكل من الأنعام؟","answer":"خص الركوب لأنه غرض مهم في معاشهم: يحملون أنفسهم وأمتعتهم في أسفارهم وتجاوز البلاد البعيدة. والاقتصار على المنفعة المقصودة يلائم ما بعدها من الاستواء وشكر التسخير، مع أن للأنعام منافع أخرى.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص613–614، تحت عنوان «نكتة الاقتصار على الركوب»","url":""}]},{"id":"s43-27","number":27,"surah":43,"verses":[12],"references":[{"surah":43,"verses":[12]}],"verseLabel":"الزخرف: 12","question":"لماذا اقتصر في وسائل الركوب على ﴿الْفُلْكِ وَالْأَنْعَامِ﴾؟","answer":"لأنهما أصلا المركوبات التي تحمل الإنسان في الماء والبر، ويدخل في تذكيرهما الامتنان بأجناس وسائل النقل وما يتصل بها من منافع.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص613، تحت عنوان «سر الاقتصار على ﴿الفلك والأنعام﴾»","url":""}]},{"id":"s43-168","number":168,"surah":43,"verses":[12],"references":[{"surah":43,"verses":[12]}],"verseLabel":"الزخرف: 12","question":"لماذا باشر فعل الجعل ﴿الْفُلْكَ﴾ ثم عطف عليها ﴿الْأَنْعَامَ﴾؟","answer":"للتنبيه إلى فرق دقيق: الفلك يصنعها الإنسان بما أودعه الله فيه من علم، أما الأنعام فيخلقها الله ويسخرها مباشرة؛ فجمعهما الامتنان وميز بين طريق إيجادهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص610–611، تحت عنوان «سر مباشرة الجعل للفلك دون الأنعام»","url":""}]},{"id":"s43-28","number":28,"surah":43,"verses":[13],"references":[{"surah":43,"verses":[13]}],"verseLabel":"الزخرف: 13","question":"لماذا رُبط تذكر نعمة الله بوقت الاستواء على وسيلة الركوب؟","answer":"لأن المنفعة تتحقق ويظهر أثر التسخير عند الاستواء؛ فيكون القلب أحضر لشكر المنعم، وينتقل من مجرد استعمال المركوب إلى الاعتراف بأن الله هو الذي ذلله له.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص620، تحت عنوان «نكتة التقييد بـ(إذا)»","url":""}]},{"id":"s43-29","number":29,"surah":43,"verses":[13],"references":[{"surah":43,"verses":[13]}],"verseLabel":"الزخرف: 13","question":"ما الذي يضيفه قوله في دعاء الركوب: ﴿وَمَا كُنَّا لَهُ مُقْرِنِينَ﴾؟","answer":"يقرر أن الإنسان لم يكن قادرًا بقوته الذاتية على إخضاع المركوب ومماثلته قوةً؛ فالانتفاع به ثمرة تسخير الله، والاعتراف بالعجز يحرس الشكر من الغرور.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص625–626، تحت عنوان «دلالة لفظ ﴿مقرنين﴾ في السياق»","url":""}]},{"id":"s43-30","number":30,"surah":43,"verses":[13,14],"references":[{"surah":43,"verses":[13,14]}],"verseLabel":"الزخرف: 13–14","question":"لماذا ينتقل دعاء الركوب من نعمة التسخير إلى قوله: ﴿وَإِنَّا إِلَى رَبِّنَا لَمُنْقَلِبُونَ﴾؟","answer":"لأن السفر بالمركوب يذكّر بالسفر الأخير إلى الله؛ فيكتمل الشكر بتذكر المسؤولية والمصير، ويصبح الانتقال الدنيوي باعثًا على الاستعداد للرجوع إلى المنعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص626–627، تحت عنوان «دلالة العطف بالواو في ﴿وإنا﴾»","url":""}]},{"id":"s43-31","number":31,"surah":43,"verses":[15],"references":[{"surah":43,"verses":[15]}],"verseLabel":"الزخرف: 15","question":"لماذا عبّر القرآن عن نسبتهم الولد إلى الله بقولهم: ﴿جُزْءًا﴾؟","answer":"لأن الولد يُتوهم جزءًا من والده؛ فاختيار اللفظ يكشف تناقضهم إذ جعلوا بعض عباد الله جزءًا منه، مع أن الخالق منزه عن التجزؤ والاحتياج.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص637، تحت عنوان «دلالة لفظ ﴿جزءًا﴾»","url":""}]},{"id":"s43-32","number":32,"surah":43,"verses":[15],"references":[{"surah":43,"verses":[15]}],"verseLabel":"الزخرف: 15","question":"هل يراد بـ﴿الْإِنْسَانَ﴾ هنا كل إنسان؟","answer":"يجوز أن يكون التعريف للعهد، فيراد الإنسان الكافر المذكور حاله، ويجوز أن يكون للجنس بالنظر إلى غلبة كفران النعمة في البشر؛ فلا يلزم من اللفظ أن كل فرد موصوف بالكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص638–639، تحت عنوان «دلالة التعريف في لفظ ﴿الإنسان﴾»","url":""}]},{"id":"s43-169","number":169,"surah":43,"verses":[15],"references":[{"surah":43,"verses":[15]}],"verseLabel":"الزخرف: 15","question":"لماذا وُصف الإنسان بـ﴿لَكَفُورٌ﴾ بصيغة المبالغة؟","answer":"صيغة المبالغة تصور شدة كفران الإنسان للنعمة وتكرره، مع معرفته بمنعمِه، فتبرز خطورة انقلاب الفطرة عن مقتضى الشكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص639، تحت عنوان «دلالة استعمال صيغة ﴿لكفور﴾»","url":""}]},{"id":"s43-170","number":170,"surah":43,"verses":[15],"references":[{"surah":43,"verses":[15]}],"verseLabel":"الزخرف: 15","question":"ماذا يضيف وصف كفر الإنسان بأنه ﴿مُبِينٌ﴾؟","answer":"يفيد أن كفرانه ظاهر بيّن أو مُظهر لنفسه بآثاره؛ إذ يجحد الدلائل الواضحة ويجاهر بنسبة الولد إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص640، تحت عنوان «دلالة الإبانة في ﴿مبين﴾»","url":""}]},{"id":"s43-33","number":33,"surah":43,"verses":[2,15,18],"references":[{"surah":43,"verses":[2,15,18]}],"verseLabel":"الزخرف: 2، 15، 18","question":"ما الذي يصوّره قوله عن المنشَّأة في الحلية: ﴿وَهُوَ فِي الْخِصَامِ غَيْرُ مُبِينٍ﴾؟","answer":"يصوّر حالها حين يشتد الجدال والانفعال، فلا تُظهر حجتها على وجه واضح ولا تفصل بين أجزاء كلامها، وإن كان البيان موجودًا لديها في غير حال الخصام؛ فالنفي متعلق بحال المنازعة لا بجميع الأحوال.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص664–665، تحت عنوان «دلالة اسم الفاعل ﴿مبين﴾»","url":""}]},{"id":"s43-34","number":34,"surah":43,"verses":[16],"references":[{"surah":43,"verses":[16]}],"verseLabel":"الزخرف: 16","question":"ماذا يكشف لفظ ﴿أَصْفَاكُمْ﴾ في دعوى المشركين أن لله البنات ولهم البنون؟","answer":"يكشف أن دعواهم تجعلهم مختصين بما يعدّونه الأفضل، أي البنين، ثم ينسبون إلى الله ما يكرهونه لأنفسهم؛ فتظهر مجاوزتهم في القسمة والتناقض.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص644، تحت عنوان «دلالة الفعل (أصفاكم) مادة وصيغة»","url":""}]},{"id":"s43-35","number":35,"surah":43,"verses":[16],"references":[{"surah":43,"verses":[16]}],"verseLabel":"الزخرف: 16","question":"لماذا نُكّرت ﴿بَنَاتٍ﴾ في حكاية دعوى المشركين؟","answer":"جاء التنكير على وفق نظرتهم التي تنتقص البنات، ليكشف قبح جرأتهم حين ينسبون إلى الله ما يكرهونه لأنفسهم، لا لأن القرآن يقرر انتقاص البنات.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص646، تحت عنوان «دلالة تنكير ﴿بنات﴾ في السياق المحكم»","url":""}]},{"id":"s43-171","number":171,"surah":43,"verses":[16],"references":[{"surah":43,"verses":[16]}],"verseLabel":"الزخرف: 16","question":"لماذا عُرّف ﴿الْبَنِينَ﴾ في حكاية دعوى المشركين؟","answer":"التعريف يصور البنين عندهم جنسًا معروفًا مستكملًا لصفات التفضيل، فيفضح أنهم اختاروا لأنفسهم القسم الذي يعظمونه ونسبوا إلى الله ما يحتقرونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص646، تحت عنوان «دلالة تعريف (البنين) في السياق المحكم»","url":""}]},{"id":"s43-36","number":36,"surah":43,"verses":[17],"references":[{"surah":43,"verses":[17]}],"verseLabel":"الزخرف: 17","question":"ما دلالة استعمال البشارة تهكمًا في ﴿وَإِذَا بُشِّرَ أَحَدُهُمْ بِمَا ضَرَبَ لِلرَّحْمَنِ مَثَلًا﴾؟","answer":"إطلاق التبشير على الخبر الذي يسوء أحدهم يصور تناقضه على وجه التهكم والتوبيخ: ينسب إلى الله ما يضيق هو به. وتذكر الموسوعة أيضًا أن العبارة تشعر بأن ولادة الأنثى في حقيقتها بشارة ونعمة، وإنما جاءت الإساءة من موقف الجاهلي منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص654، تحت عنوان «دلالة فعل (التبشير)»","url":""}]},{"id":"s43-37","number":37,"surah":43,"verses":[17],"references":[{"surah":43,"verses":[17]}],"verseLabel":"الزخرف: 17","question":"ما سر الجمع بين اسوداد الوجه والكظم في تصوير حال من بُشّر بالأنثى؟","answer":"اسوداد الوجه يكشف أثر الحزن والخجل في الظاهر، والكظم يكشف الغيظ والحزن المحبوسين في الداخل. فاجتماعهما يصور حالته من خارجها وداخلها، ويفضح تناقض من ينسب إلى الله ما يشتد حزنه إذا نُسب إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص658–659، تحت عنوان «دلالة الجملة الاسمية: ﴿وهو كظيم﴾»","url":""}]},{"id":"s43-38","number":38,"surah":43,"verses":[19],"references":[{"surah":43,"verses":[19]}],"verseLabel":"الزخرف: 19","question":"ماذا يهدم وصف الملائكة بأنهم ﴿عِبَادُ الرَّحْمَنِ﴾ من دعوى المشركين؟","answer":"يثبت أنهم مخلوقون عابدون خاضعون لله، والعبودية تناقض البنوة التي زعمها المشركون، مع ما في إضافتهم إلى الرحمن من تشريف لهم بالطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص670، تحت عنوان «دلالة الإضافة في ﴿عباد الرحمن﴾»","url":""}]},{"id":"s43-39","number":39,"surah":43,"verses":[19],"references":[{"surah":43,"verses":[19]}],"verseLabel":"الزخرف: 19","question":"كيف يبطل سؤال ﴿أَشَهِدُوا خَلْقَهُمْ﴾ دعواهم أن الملائكة إناث؟","answer":"يوبخهم لأنهم لم يحضروا خلق الملائكة ولم يشاهدوه، فدعواهم بلا علم ولا شاهد، وبذلك يسقط أصل قولهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص672، تحت عنوان «دلالة الاستفهام في ﴿أشهدوا﴾»","url":""}]},{"id":"s43-172","number":172,"surah":43,"verses":[19],"references":[{"surah":43,"verses":[19]}],"verseLabel":"الزخرف: 19","question":"ما الصورة التي يرسمها قوله عن دعواهم ﴿سَتُكْتَبُ شَهَادَتُهُمْ﴾؟","answer":"يصور قولهم شهادة مثبتة محفوظة تتحول إلى حجة عليهم، فلا تضيع جرأتهم بل تُسجل ويُسألون عنها يوم الحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص674–675، تحت عنوان «دلالة الكناية في ﴿ستكتب شهادتهم﴾»","url":""}]},{"id":"s43-40","number":40,"surah":43,"verses":[20],"references":[{"surah":43,"verses":[20]}],"verseLabel":"الزخرف: 20","question":"ما سر احتجاجهم بالمشيئة في ﴿لَوْ شَاءَ الرَّحْمَنُ مَا عَبَدْنَاهُمْ﴾، ووصف قولهم بعد ذلك بالخرص؟","answer":"استدلوا بوقوع العبادة على أنها مرضية لله، فخلطوا وقوع الفعل بمشيئته مع رضاه عنه. وتبين الموسوعة أن المشيئة لا تستلزم الرضا؛ ووصفهم بالخرص لأن دعواهم قائمة على التخمين ونسبة حكم إلى الله بلا دليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص677، تحت عنوان «دلالة فعل المشيئة»","url":""}]},{"id":"s43-41","number":41,"surah":43,"verses":[20],"references":[{"surah":43,"verses":[20]}],"verseLabel":"الزخرف: 20","question":"ما دلالة مقابلة ﴿مَا لَهُمْ بِذَلِكَ مِنْ عِلْمٍ﴾ بقوله ﴿إِنْ هُمْ إِلَّا يَخْرُصُونَ﴾؟","answer":"يحصرهم القصر في الخرص والتخمين، فيكشف أن ما عرضوه حجة لا يستند إلى علم أو دليل؛ فالجملة الثانية تبين حقيقة الجهل المنفي في الأولى.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص680، تحت عنوان «دلالة القصر في ﴿إن هم إلا﴾»","url":""}]},{"id":"s43-42","number":42,"surah":43,"verses":[21,22],"references":[{"surah":43,"verses":[21,22]}],"verseLabel":"الزخرف: 21–22","question":"ما الفرق بين التمسك بكتاب منزل والتمسك بآثار الآباء؟","answer":"الكتاب المنزل حجة موصلة إلى العلم يمكن أن تقوم عليها العقيدة، أما مجرد اتباع آثار الآباء بلا عقل ولا وحي فليس دليلًا، ولو سُمّي تمسكًا أو اهتداء.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص683، تحت عنوان «مناسبة الآيتين لما قبلهما»","url":""}]},{"id":"s43-43","number":43,"surah":43,"verses":[21],"references":[{"surah":43,"verses":[21]}],"verseLabel":"الزخرف: 21","question":"ما الصورة التي يرسمها التعبير بـ﴿فَهُمْ بِهِ مُسْتَمْسِكُونَ﴾ للحجة الصحيحة؟","answer":"الاستمساك مبالغة في التمسك، يصور شدة التعلق بما يعتمد عليه وعدم إفلاته. وقد استعمل مجازًا في التزام ما جاء في الكتاب، مع دلالة الصيغة على الدوام؛ والآية تنكر أن يكون لهم كتاب يعتصمون به في دعواهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص688، تحت عنوان «دلالة استعمال ﴿مستمسكون﴾ مادة وصيغة»","url":""}]},{"id":"s43-44","number":44,"surah":43,"verses":[22],"references":[{"surah":43,"verses":[22]}],"verseLabel":"الزخرف: 22","question":"ما الصورة في قولهم ﴿إِنَّا عَلَى آثَارِهِمْ مُهْتَدُونَ﴾؟","answer":"يصور تقليد الآباء كأن السابقين تركوا آثار أقدام في طريق، واللاحقون يمشون خلفها؛ فهي كناية تكشف أن ما يسمونه هداية ليس إلا اتباعًا موروثًا بلا برهان.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص693–694، تحت عنوان «بلاغة الكناية في: ﴿على آثارهم مهتدون﴾»","url":""}]},{"id":"s43-45","number":45,"surah":43,"verses":[22,23],"references":[{"surah":43,"verses":[22,23]}],"verseLabel":"الزخرف: 22–23","question":"لماذا أُعيدت حجة ﴿وَجَدْنَا آبَاءَنَا عَلَى أُمَّةٍ﴾ بعد الآية السابقة؟","answer":"الأولى تحكي قول مشركي مكة، ثم تعمم الثانية أن هذا العذر نفسه عادة قديمة عند المترفين في الأمم؛ فيتضح أن الاعتراض تقليد متكرر لا حجة، وفيه تسلية للنبي.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص695، تحت عنوان «مناسبة الآية لما قبلها»","url":""}]},{"id":"s43-46","number":46,"surah":43,"verses":[22,23],"references":[{"surah":43,"verses":[22,23]}],"verseLabel":"الزخرف: 22–23","question":"لماذا قيل عن السابقين ﴿مُقْتَدُونَ﴾ بعد قول المخاطبين ﴿مُهْتَدُونَ﴾؟","answer":"﴿مهتدون﴾ تنقل دعوى المتأخرين أنهم على هدى، أما ﴿مقتدون﴾ فتصف حقيقة صنيع السابقين: اتباع الآباء والنسج على طريقتهم، من غير إقرار بأن ذلك هداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص707، تحت عنوان «دلالة التعبير بالاقتداء مادة وصيغة»","url":""}]},{"id":"s43-47","number":47,"surah":43,"verses":[23],"references":[{"surah":43,"verses":[23]}],"verseLabel":"الزخرف: 23","question":"ما سر إسناد حجة تقليد الآباء إلى ﴿مُتْرَفُوهَا﴾ خاصة؟","answer":"خص المترفين لأن الاستغراق في النعمة والشهوات يصرفهم عن النظر والتفكر، فيستروحون إلى التقليد الذي ألفوه. وتعرض الموسوعة ذلك تحذيرًا من الإخلاد إلى التنعم الذي يضعف الاستدلال ومواجهة الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص702–703، تحت عنوان «علة التعبير بالترف مادة وصيغة»","url":""}]},{"id":"s43-48","number":48,"surah":43,"verses":[24],"references":[{"surah":43,"verses":[24]}],"verseLabel":"الزخرف: 24","question":"ماذا يفضح سؤال ﴿أَوَلَوْ جِئْتُكُمْ﴾ في تمسكهم بآبائهم؟","answer":"يوبخهم: أيستمرون في التقليد حتى لو جاءهم رسول بما هو أوضح هداية؟ وبذلك يكشف أن موقفهم عناد سابق على النظر في الدليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص712، تحت عنوان «بلاغة التعبير بالاستفهام في ﴿أولو﴾»","url":""}]},{"id":"s43-173","number":173,"surah":43,"verses":[24],"references":[{"surah":43,"verses":[24]}],"verseLabel":"الزخرف: 24","question":"لماذا قال الرسول ﴿بِأَهْدَى﴾ مع أن دين آبائهم ليس هدى؟","answer":"هذا تنزل حجاجي مع الخصم لا إقرار بأن دين الآباء هدى؛ فحتى على فرض مقايستهم لا يجوز رد ما هو أهدى وأقوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص714، تحت عنوان «دلالة صيغة التفضيل (أهدى)»","url":""}]},{"id":"s43-49","number":49,"surah":43,"verses":[24],"references":[{"surah":43,"verses":[24]}],"verseLabel":"الزخرف: 24","question":"ماذا يكشف توكيد قولهم ﴿إِنَّا بِمَا أُرْسِلْتُمْ بِهِ كَافِرُونَ﴾؟","answer":"يكشف أن رفضهم موقف مقصود راسخ بعد قيام التحدي والحجة، لا تردد عابر ولا جهل ينتظر البيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص715، تحت عنوان «سر التوكيد في جملة مقول القول»","url":""}]},{"id":"s43-174","number":174,"surah":43,"verses":[24],"references":[{"surah":43,"verses":[24]}],"verseLabel":"الزخرف: 24","question":"لماذا قالوا ﴿بِمَا أُرْسِلْتُمْ بِهِ﴾ بدل تسمية الرسالة؟","answer":"الموصول يعمم رفضهم لكل ما جاء به الرسل، وفي عبارتهم إعراض متكبر عن مضمون الرسالة حتى لا يسموه ولا يناقشوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص716، تحت عنوان «دلالة التعبير بالموصول (ما)»","url":""}]},{"id":"s43-50","number":50,"surah":43,"verses":[24,25],"references":[{"surah":43,"verses":[24,25]}],"verseLabel":"الزخرف: 24–25","question":"لماذا عُطف الانتقام بالفاء على إعلانهم الكفر؟","answer":"لتصوير الانتقام نتيجةً مترتبة على إعلانهم الكفر وإصرارهم عليه؛ فالعقوبة لم تقع اعتباطًا، بل جاءت بعد أن واجهوا الهدى بالرفض الصريح، وفي ذلك تحذير من أن التمادي في التكذيب يقود إلى عاقبته.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص717، تحت عنوان «معنى الفاء في صدر الجملة، ودلالة التعبير بها»","url":""}]},{"id":"s43-51","number":51,"surah":43,"verses":[25],"references":[{"surah":43,"verses":[25]}],"verseLabel":"الزخرف: 25","question":"لماذا عُبّر عن مصير المكذبين بلفظ ﴿العاقبة﴾؟","answer":"لأن «العاقبة» تبرز نهاية أمرهم وما ترتب على إصرارهم على الكفر؛ فهي لا تذكر وقوع الهلاك وحده، بل تعرضه خاتمةً لطريق اختاروه، فيشتد التهديد ويصبح مصيرهم عبرةً لمن بعدهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص720، تحت عنوان «دلالة التعبير بلفظ (العاقبة)»","url":""}]},{"id":"s43-52","number":52,"surah":43,"verses":[22,26],"references":[{"surah":43,"verses":[22,26]}],"verseLabel":"الزخرف: 22، 26","question":"لماذا احتج السياق على مقلدي الآباء بموقف إبراهيم من أبيه وقومه؟","answer":"لأنهم يعظمون إبراهيم وينتسبون إليه، وقد خالف أباه وقومه حين بان بطلان عبادتهم واتبع الدليل؛ فمثال الجد الذي يجلونه نفسه ينقض اتخاذ الآباء حجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص725، تحت عنوان «سر ذكر إبراهيم عليه السلام»","url":""}]},{"id":"s43-53","number":53,"surah":43,"verses":[26],"references":[{"surah":43,"verses":[26]}],"verseLabel":"الزخرف: 26","question":"ما سر اختيار المصدر ﴿بَرَاءٌ﴾ بدل «بريء» في إعلان إبراهيم البراءة مما يعبد قومه؟","answer":"المصدر ﴿براء﴾ أبلغ في إعلان التبرؤ من الوصف بالمشتق؛ فكأنه محض البراءة من عبادة ما يعبدونه. وفيه تقوية للموقف وإظهار لشدة انفصاله عن باطلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص726–727، تحت عنوان «دلالة التعبير بالبراء مادة وصيغة»","url":""}]},{"id":"s43-54","number":54,"surah":43,"verses":[26,27],"references":[{"surah":43,"verses":[26,27]}],"verseLabel":"الزخرف: 26–27","question":"ما دلالة الاستثناء ﴿إِلَّا الَّذِي فَطَرَنِي﴾ بعد البراءة العامة؟","answer":"الاستثناء يخرج الفاطر من المعبودات التي تبرأ منها، فيجمع نفي عبادة الباطل وإثبات العبادة للخالق. وتذكر الموسوعة أن الاستثناء يحتمل الاتصال إن كانوا يعبدون الله مع غيره، والانقطاع إن لم يكن داخلًا في معبوداتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص728، تحت عنوان «نوع الاستثناء ودلالته»","url":""}]},{"id":"s43-55","number":55,"surah":43,"verses":[27],"references":[{"surah":43,"verses":[27]}],"verseLabel":"الزخرف: 27","question":"لماذا عبّر إبراهيم عن خلقه بقوله ﴿الَّذِي فَطَرَنِي﴾؟","answer":"الفطر هو الإنشاء والابتداء على غير مثال سابق، فاختيار اللفظ يوجه إلى أن من أوجد الإنسان ابتداء هو وحده المستحق للعبادة والهادي له.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص729، تحت عنوان «دلالة التعبير بالفطر مادة وصيغة»","url":""}]},{"id":"s43-56","number":56,"surah":43,"verses":[28],"references":[{"surah":43,"verses":[28]}],"verseLabel":"الزخرف: 28","question":"إلى ماذا يعود ضمير المفعول في ﴿وجعلها كلمة باقية في عقبه﴾، وما وجها تعيين فاعل الجعل؟","answer":"ضمير المفعول يعود إلى الكلمة التي تضمنها إعلان البراءة من الشرك واستثناء الفاطر، أي كلمة التوحيد. أما فاعل ﴿جعلها﴾ فيحتمل إبراهيم الذي أوصى بها ذريته، ويحتمل الله الذي أبقاها في عقبه؛ وكلا الوجهين يقرر استمرار دعوة التوحيد فيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص731–732، تحت عنوان «بيان مرجع الضمائر في ﴿وجعلها﴾»","url":""}]},{"id":"s43-57","number":57,"surah":43,"verses":[28],"references":[{"surah":43,"verses":[28]}],"verseLabel":"الزخرف: 28","question":"لماذا قيل ﴿فِي عَقِبِهِ﴾ بدل «في ولده»؟","answer":"العقب يشمل الذرية المتتابعة جيلًا بعد جيل، فهو أنسب ببقاء كلمة التوحيد في السلسلة الممتدة، من غير أن يلزم إيمان كل فرد من ذريته.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص734–735، تحت عنوان «العقب والولد»","url":""}]},{"id":"s43-58","number":58,"surah":43,"verses":[26,27,28],"references":[{"surah":43,"verses":[26,27,28]}],"verseLabel":"الزخرف: 26–28","question":"كيف يتدرج موقف إبراهيم من البراءة من المعبودات إلى إبقاء التوحيد في ذريته؟","answer":"يبدأ بقطع الصلة بما يعبد قومه، ثم يستثني فاطره الذي يهديه، ثم يجعل كلمة التوحيد باقية في عقبه. وهكذا ينتقل الموقف من براءة شخصية إلى عهد ممتد يدعو ذريته إلى الرجوع للحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص724، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s43-59","number":59,"surah":43,"verses":[28,29],"references":[{"surah":43,"verses":[28,29]}],"verseLabel":"الزخرف: 28–29","question":"لماذا انتقل السياق من بقاء كلمة التوحيد في عقب إبراهيم إلى تمتيع المشركين وآبائهم؟","answer":"لأن رجوع الذرية إلى التوحيد كان هو المأمول، لكن فريقًا منهم اتبع الآباء واغتر بالإمهال والنعم. فجاء الانتقال ليكشف كيف قابلوا العهد القديم بالتقليد والغفلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص736، تحت عنوان «مناسبة الآيتين لما قبلهما»","url":""}]},{"id":"s43-175","number":175,"surah":43,"verses":[28,29],"references":[{"surah":43,"verses":[28,29]}],"verseLabel":"الزخرف: 28–29","question":"ما دلالة جعل مجيء الحق والرسول غاية للتمتيع في قوله ﴿حتى جاءهم الحق﴾؟","answer":"يدل على أن الإمهال استمر إلى أن جاءت الحجة القاطعة بالقرآن والرسول المبين؛ فعندها انتهى عذرهم وصار ردهم للحق عنادًا بعد تمام البيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص739–740، تحت عنوان «معنى ﴿حتى﴾، ودلالة التعبير بها»","url":""}]},{"id":"s43-60","number":60,"surah":43,"verses":[29,30],"references":[{"surah":43,"verses":[29,30]}],"verseLabel":"الزخرف: 29–30","question":"لماذا أعيد لفظ ﴿الحق﴾ ظاهرًا في قوله ﴿ولما جاءهم الحق﴾ بدل الإضمار؟","answer":"ليُستحضر أن الشيء الذي أنكروه وسموه سحرًا هو الحق نفسه، فيشتد التعجيب من حكمهم ويتأكد أنهم ردوه بعد ظهوره لا بسبب خفائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص743، تحت عنوان «دلالة إظهار ﴿الحق﴾ في محل الإضمار»","url":""}]},{"id":"s43-176","number":176,"surah":43,"verses":[29,30],"references":[{"surah":43,"verses":[29,30]}],"verseLabel":"الزخرف: 29–30","question":"لماذا وصف المكذبون القرآن بأنه ﴿سحر﴾؟","answer":"ليصرفوا الناس عن تصديقه ويصوروا أثر بيانه وإعجازه تخييلًا لا حقيقة. فوصفهم لا يطابق الواقع، لكنه يكشف عجزهم عن مواجهة الحق إلا بالتهمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص744، تحت عنوان «علة وصفهم القرآن بلفظ (السحر)»","url":""}]},{"id":"s43-61","number":61,"surah":43,"verses":[29],"references":[{"surah":43,"verses":[29]}],"verseLabel":"الزخرف: 29","question":"ماذا يفيد وصف القرآن الذي جاءهم بأنه ﴿الحق﴾؟","answer":"يفيد ظهوره وثبوته ومطابقته للواقع، فلا يعتريه شك ولا يقبل أن يوصف بالسحر. وفي تسميته حقًا تعظيم له وإدانة لمن قابله بالكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص740، تحت عنوان «دلالة التعبير بـ﴿الحق﴾»","url":""}]},{"id":"s43-177","number":177,"surah":43,"verses":[29],"references":[{"surah":43,"verses":[29]}],"verseLabel":"الزخرف: 29","question":"لماذا وُصف الرسول بأنه ﴿مبين﴾؟","answer":"لظهور رسالته ووضوح حجته، ولأنه يبين للناس ما جاء به من الحق. فالوصف يجمع وضوح حال المبلِّغ ووضوح البيان الذي يحمله.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص742، تحت عنوان «سر وصف الرسول بأنه ﴿مبين﴾»","url":""}]},{"id":"s43-62","number":62,"surah":43,"verses":[31],"references":[{"surah":43,"verses":[31]}],"verseLabel":"الزخرف: 31","question":"ماذا يكشف وصفهم الرجل المستحق للرسالة بأنه ﴿عظيم﴾؟","answer":"يكشف أنهم جعلوا المال والجاه والرئاسة معيار العظمة وأهلية الرسالة، فاقترحوا رجلًا من سادة مكة أو الطائف. وبذلك فضح قولهم ميزانًا دنيويًا لا يدرك أن النبوة اصطفاء إلهي لا ثمرة للثراء.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص752–753، تحت عنوان «دلالة وصف الرجل بصفة العظمة»","url":""}]},{"id":"s43-63","number":63,"surah":43,"verses":[31,32],"references":[{"surah":43,"verses":[31,32]}],"verseLabel":"الزخرف: 31–32","question":"ما غرض الاستفهام في قوله ﴿أهم يقسمون رحمت ربك﴾؟","answer":"هو إنكار وتعجيب من تدخلهم في اختيار الرسول؛ فهم لا يملكون توزيع النبوة ولا تعيين من يستحقها، كما لا يملكون تدبير أرزاقهم على الحقيقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص753، تحت عنوان «بلاغة الاستفهام»","url":""}]},{"id":"s43-178","number":178,"surah":43,"verses":[31,32],"references":[{"surah":43,"verses":[31,32]}],"verseLabel":"الزخرف: 31–32","question":"لماذا سُمّيت النبوة ﴿رحمة ربك﴾؟","answer":"لأن إرسال الرسول إحسان وهداية من الله لعباده، واصطفاء من يحملها مظهر من رحمته وتدبيره. وإضافتها إلى الرب تذكر بأن اختيار الرسول حق للرب المربي لا للناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص754–755، تحت عنوان «دلالة التعبير بالرحمة وإضافتها إلى الرب»","url":""}]},{"id":"s43-64","number":64,"surah":43,"verses":[32],"references":[{"surah":43,"verses":[32]}],"verseLabel":"الزخرف: 32","question":"ماذا يقرر قوله ﴿ورحمت ربك خير مما يجمعون﴾؟","answer":"يقرر أن النبوة والهداية خير من الأموال والزخارف التي يجمعونها؛ فميزان الفضل ليس كثرة المتاع، بل الرحمة التي تقود إلى سعادة الدنيا والآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص764، تحت عنوان «دلالة التعبير باسم التفضيل»","url":""}]},{"id":"s43-65","number":65,"surah":43,"verses":[32,33],"references":[{"surah":43,"verses":[32,33]}],"verseLabel":"الزخرف: 32–33","question":"لماذا فُصّل هوان زخرف الدنيا بعد قوله ﴿ورحمت ربك خير مما يجمعون﴾؟","answer":"ليقام الدليل على أن المال ليس ميزان كرامة؛ فلولا خشية افتتان الناس لأفيض الزخرف على الكافرين. فكون الدنيا تُعطى لمن يكفر يبين أنها أدنى من أن تدل وحدها على الفضل.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص766، تحت عنوان «مناسبة الآية لما قبلها»","url":""}]},{"id":"s43-66","number":66,"surah":43,"verses":[33],"references":[{"surah":43,"verses":[33]}],"verseLabel":"الزخرف: 33","question":"ماذا تكشف ﴿لولا﴾ في قوله ﴿ولولا أن يكون الناس أمة واحدة﴾ عن منع تعميم الزخرف؟","answer":"تكشف أن المانع ليس عجزًا عن إغناء الكافرين، بل رحمة بالناس حتى لا يجتمعوا على الكفر افتتانًا بالزينة. فالله قادر على الإغداق، لكنه يمنع ما يفتح باب الضلال العام.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص769، تحت عنوان «دلالة التعبير بـ(لولا)»","url":""}]},{"id":"s43-67","number":67,"surah":43,"verses":[33],"references":[{"surah":43,"verses":[33]}],"verseLabel":"الزخرف: 33","question":"لماذا قيل ﴿لمن يكفر بالرحمن﴾ في مقام متاع الدنيا؟","answer":"ليُذكّر بأن الرزق والتنعيم من آثار رحمة الله، فلا يكون حظ الكافر من الدنيا دليل رضاه عنه. وفي مقابلة الكفر باسم الرحمن توبيخ لمن يجحد المنعم الذي وسعت رحمته الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص773، تحت عنوان «علة التعبير باسم الرحمن دون سواه»","url":""}]},{"id":"s43-68","number":68,"surah":43,"verses":[33,34,35],"references":[{"surah":43,"verses":[33,34,35]}],"verseLabel":"الزخرف: 33–35","question":"ماذا يجمع لفظ ﴿زخرفًا﴾ بعد تعداد السقف والمعارج والأبواب والسرر؟","answer":"يجمع معنى الزينة وكمال الترف، ويحتمل الذهب الذي يكسو تلك المظاهر. فجاء لفظ واحد يلخص بريق المتاع كله ويبين أنه، مهما عظم، من عرض الدنيا الزائل.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص784–785، تحت عنوان «علة التعبير بالزخرف مادة وصيغة»","url":""}]},{"id":"s43-179","number":179,"surah":43,"verses":[33,34,35],"references":[{"surah":43,"verses":[33,34,35]}],"verseLabel":"الزخرف: 33–35","question":"لماذا أُخر ذكر ﴿الزخرف﴾ بعد السقف والمعارج والأبواب والسرر؟","answer":"لأنه كمال للنعيم يأتي بعد أصوله؛ فذُكرت المرافق أولًا ثم الزينة التي تتمم صورتها. وبذلك يبلغ المشهد غاية البريق قبل الحكم عليه بأنه متاع زائل.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص785، تحت عنوان «سر تأخير ذكر الزخرف»","url":""}]},{"id":"s43-69","number":69,"surah":43,"verses":[35],"references":[{"surah":43,"verses":[35]}],"verseLabel":"الزخرف: 35","question":"ما دلالة ورود لفظ ﴿زُخْرُفًا﴾ الذي سميت به السورة في هذا الموضع وحده؟","answer":"جاء الزخرف عند استيفاء صورة التنعيم الدنيوي، ثم بُيّن أن ذلك كله متاع الحياة الدنيا. وتسميتها به تلائم نقد الافتتان بالمظاهر المادية وتضع الزينة في حدود المتاع الزائل.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص525–526، تحت عنوان «اسم السورة، ومناسبة تسميتها»","url":""}]},{"id":"s43-70","number":70,"surah":43,"verses":[33,34,35],"references":[{"surah":43,"verses":[33,34,35]}],"verseLabel":"الزخرف: 33–35","question":"لماذا جُمعت مظاهر الزخرف السابقة في قوله ﴿كل ذلك﴾؟","answer":"لاستحضار السقف والمعارج والأبواب والسرر والزينة جميعًا ثم إصدار حكم واحد عليها. فمهما تعددت صورها لا تخرج عن كونها أجزاء من نعيم دنيوي محدود.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص787، تحت عنوان «علة التعبير بـ﴿كل﴾»","url":""}]},{"id":"s43-180","number":180,"surah":43,"verses":[33,34,35],"references":[{"surah":43,"verses":[33,34,35]}],"verseLabel":"الزخرف: 33–35","question":"لماذا وُصف زخرف الدنيا بأنه ﴿متاع﴾؟","answer":"لأن المتاع منفعة مؤقتة ينتفع بها صاحبها ثم تزول، فهو لا يساوي النعيم الباقي. واللفظ يضع بريق الدنيا في حجمه الحقيقي ويمنع اتخاذه معيارًا للسعادة الدائمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص787–788، تحت عنوان «علة التعبير بالمتاع»","url":""}]},{"id":"s43-71","number":71,"surah":43,"verses":[35],"references":[{"surah":43,"verses":[35]}],"verseLabel":"الزخرف: 35","question":"ماذا تضيف عبارة ﴿عند ربك﴾ إلى نعيم الآخرة؟","answer":"تشرف هذا النعيم بنسبته إلى عطاء الله المدخر عنده، وتوحي بقرب المتقين من إحسانه ورعايته. فهو جزاء باق مضمون لا متاع عابر يملكه الناس ثم يفقدونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص790–791، تحت عنوان «فائدة: ﴿عند ربك﴾»","url":""}]},{"id":"s43-181","number":181,"surah":43,"verses":[35],"references":[{"surah":43,"verses":[35]}],"verseLabel":"الزخرف: 35","question":"لماذا خُصت الآخرة في قوله ﴿للـمتقين﴾؟","answer":"لأن نعيمها الكامل معد لمن آمن واتقى، بخلاف متاع الدنيا الذي قد يناله المؤمن والكافر. فالاختصاص يصحح معيار الفضل ويجعله التقوى لا مقدار المال.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص792، تحت عنوان «دلالة اللام في ﴿للمتقين﴾»","url":""}]},{"id":"s43-72","number":72,"surah":43,"verses":[35,36],"references":[{"surah":43,"verses":[35,36]}],"verseLabel":"الزخرف: 35–36","question":"لماذا انتقل السياق من فتنة الزخرف إلى عاقبة العشو عن ذكر الرحمن؟","answer":"ليبين أن الاغترار بالدنيا قد يضعف البصيرة عن القرآن، فإذا أعرض الإنسان عن الذكر سُلّط عليه قرين يزيده ضلالًا. فالانتقال يكشف العاقبة الباطنة للانشغال بالبريق الزائل.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص794، تحت عنوان «مناسبة الآية لما قبلها»","url":""}]},{"id":"s43-73","number":73,"surah":43,"verses":[36],"references":[{"surah":43,"verses":[36]}],"verseLabel":"الزخرف: 36","question":"ما الصورة التي يرسمها فعل ﴿يعش﴾ في الإعراض عن ذكر الرحمن؟","answer":"العشا ضعف في البصر استُعير لضعف البصيرة عن القرآن؛ فكأن المعرض يرى الحق رؤية باهتة ثم ينصرف عنه. والصورة تجعل الغفلة مرضًا في النظر القلبي لا مجرد ترك عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص797، تحت عنوان «علة التعبير بالعشا»","url":""}]},{"id":"s43-74","number":74,"surah":43,"verses":[36],"references":[{"surah":43,"verses":[36]}],"verseLabel":"الزخرف: 36","question":"ماذا يصور فعل ﴿نقيض له شيطانًا﴾؟","answer":"يصور تهيئة الشيطان وتسليطه ملازمًا لمن أعرض عن الذكر، حتى يحيط به ويزين له الشر. فالتقييض نتيجة تناسب اختياره للغفلة، لا صحبة عارضة بلا سبب.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص799–800، تحت عنوان «علة التعبير بالتقييض»","url":""}]},{"id":"s43-75","number":75,"surah":43,"verses":[36,37],"references":[{"surah":43,"verses":[36,37]}],"verseLabel":"الزخرف: 36–37","question":"كيف يربط الشرط بين العشو عن الذكر وتقييض الشيطان؟","answer":"يجعل تقييض القرين نتيجة للإعراض؛ فمن يتعام عن القرآن ويصرف بصره عنه يفتح على نفسه باب الملازمة الشيطانية. وهكذا يظهر أن العاقبة متصلة باختياره الأول.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص796–797، تحت عنوان «دلالة أسلوب الشرط»","url":""}]},{"id":"s43-76","number":76,"surah":43,"verses":[37],"references":[{"surah":43,"verses":[37]}],"verseLabel":"الزخرف: 37","question":"ما سر الجمع بين صد الشياطين عن السبيل وحسبان أتباعهم أنهم مهتدون؟","answer":"الشياطين تصدهم عن الطريق، وهم يحسبون أنفسهم على هدى؛ فتجتمع الغواية مع الجهل بها. وجملة الحال تكشف استحكام التضليل، إذ لا يطلب الرجوع من يظن الباطل هداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص13–14، تحت عنوان «بلاغة جملة الحال ﴿ويحسبون أنهم مهتدون﴾»","url":""}]},{"id":"s43-77","number":77,"surah":43,"verses":[38],"references":[{"surah":43,"verses":[38]}],"verseLabel":"الزخرف: 38","question":"كيف تنقل ﴿حتى﴾ مشهد القرينين من وهم الهداية إلى الآخرة؟","answer":"تجعل المجيء للحساب غاية لاستمرار صحبتهما وضلالهما؛ فيمتد المشهد من الدنيا حتى تنكشف الحقيقة فجأة عند اللقاء، وينقلب حسبان الهداية إلى ندم وتمني البعد عن القرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص17، تحت عنوان «بلاغة التعبير بـ﴿حتى﴾»","url":""}]},{"id":"s43-78","number":78,"surah":43,"verses":[38],"references":[{"surah":43,"verses":[38]}],"verseLabel":"الزخرف: 38","question":"لماذا تمنى العاشي أن يكون بينه وبين قرينه ﴿بُعْدَ الْمَشْرِقَيْنِ﴾؟","answer":"لأن المشرقين يصوران أبعد مسافة يتخيلها النادم بينه وبين قرينه؛ ويحتمل اللفظ المشرق والمغرب، أو مشرقي الصيف والشتاء. ففي الحالين يكشف التعبير شدة رغبته في مفارقة من عرف عاقبة صحبته.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص22، تحت عنوان «علة التعبير بـ﴿المشرقين﴾»","url":""}]},{"id":"s43-79","number":79,"surah":43,"verses":[36,38],"references":[{"surah":43,"verses":[36,38]}],"verseLabel":"الزخرف: 36، 38","question":"ما الذي يصوره تنكير ﴿قَرِينٌ﴾ عند تسليط الشيطان على المعرض؟","answer":"يهوّل التنكير شأن القرين في الشر، ويجعل الوعيد متناولًا أي قرين من هذا النوع؛ فليس المقصود اسم شيطان بعينه، بل قرين شديد الملازمة والإفساد.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص804، تحت عنوان «سر تنكير ﴿قرين﴾»","url":""}]},{"id":"s43-182","number":182,"surah":43,"verses":[36,38],"references":[{"surah":43,"verses":[36,38]}],"verseLabel":"الزخرف: 36، 38","question":"لماذا أعيد ذكره معرفًا في قوله ﴿فَبِئْسَ الْقَرِينُ﴾؟","answer":"لأن الندم صار متعلقًا بالقرين المعهود الذي لازمه في الدنيا وظهر له سوء أثره في الآخرة؛ فالتعريف يستحضر تلك الصحبة نفسها ويجعل القرينية موضع الذم والحسرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص24، تحت عنوان «علة التعبير بـ﴿القرين﴾»","url":""}]},{"id":"s43-80","number":80,"surah":43,"verses":[39],"references":[{"surah":43,"verses":[39]}],"verseLabel":"الزخرف: 39","question":"لماذا لا ينفع أهل العذاب اشتراكهم فيه كما يتسلى أهل الدنيا بالمصاب المشترك؟","answer":"لأن مشاركة المصاب قد تخفف ألم الدنيا بالمواساة، أما عذاب الآخرة فلا ينقص منه شيء لاجتماعهم فيه، ولا يجد أحد منهم سلوى نافعة في عذاب صاحبه؛ فلكل واحد نصيبه الذي لا يدفعه الاشتراك.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص26، تحت عنوان «مناسبة الآية لما قبلها»","url":""}]},{"id":"s43-81","number":81,"surah":43,"verses":[40],"references":[{"surah":43,"verses":[40]}],"verseLabel":"الزخرف: 40","question":"لماذا مُثّل المعرضون عن الوحي بالصم والعمي مع سلامة حواسهم؟","answer":"لأنهم عطلوا السمع والبصر عن الانتفاع بالوحي ودلائله، فصاروا في قبول الحق كمن فقد الحاستين. ويواسي هذا التمثيل الرسول ﷺ بأن امتناعهم ناشئ من إصرارهم، لا من قصور في البلاغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص36–37، تحت عنوان «بلاغة التمثيل في الآية»","url":""}]},{"id":"s43-82","number":82,"surah":43,"verses":[40],"references":[{"surah":43,"verses":[40]}],"verseLabel":"الزخرف: 40","question":"لماذا قُدّم إسماع الصم على هداية العمي في تصوير إعراض المكذبين؟","answer":"لأن طريق تلقي الوحي يبدأ بالسماع، وهو الأصل الأقرب إلى الفهم والتلقي؛ ثم جاءت صورة هداية العمي لتصور عجزهم عن رؤية طريق الحق. فترتيب الصورتين يوافق طريق وصول الرسالة إلى القلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص37–38، تحت عنوان «نكتة تقديم الإسماع على الهداية»","url":""}]},{"id":"s43-83","number":83,"surah":43,"verses":[41,42],"references":[{"surah":43,"verses":[41,42]}],"verseLabel":"الزخرف: 41–42","question":"ما دلالة تسوية الوعيد بين ذهاب الرسول قبل وقوع العذاب ورؤيته ما وُعدوا به؟","answer":"تقسم ﴿أو﴾ الحالين: أن يذهب الله بالنبي ﷺ قبل العقوبة أو يريه ما وعدهم به، وفي كليهما ينفذ حكم الله؛ فالانتقام منهم لا يتوقف على بقاء الرسول أو مشاهدته العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص48، تحت عنوان «معنى: ﴿أو﴾، ودلالة التعبير بها»","url":""}]},{"id":"s43-84","number":84,"surah":43,"verses":[41,42],"references":[{"surah":43,"verses":[41,42]}],"verseLabel":"الزخرف: 41–42","question":"ماذا يزيد وصف الله بـ﴿مُقْتَدِرُونَ﴾ في وعيد المكذبين؟","answer":"يقرر كمال القدرة وشدتها، وأن إنفاذ الوعيد لا يعوقه عجز ولا يفلت منه المعاندون. لذلك يجيء الوصف أبلغ في التهديد، وأقوى في تسلية الرسول ﷺ بأن العاقبة بيد الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص50، تحت عنوان «دلالة صيغة الافتعال في لفظ ﴿مقتدرون﴾»","url":""}]},{"id":"s43-85","number":85,"surah":43,"verses":[43],"references":[{"surah":43,"verses":[43]}],"verseLabel":"الزخرف: 43","question":"لماذا جاء الأمر بالاستمساك بالوحي بعد بيان إصرار المعرضين؟","answer":"ليوجَّه الرسول ﷺ إلى طريقه العملي بعد انكشاف عنادهم: يثبت على الوحي ويواصل البلاغ، ولا يحمله إعراضهم على التردد؛ فالله ناصر دينه سواء عوجلوا بالعقوبة أم أمهلوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص52، تحت عنوان «مناسبة الآية لما قبلها»","url":""}]},{"id":"s43-183","number":183,"surah":43,"verses":[43],"references":[{"surah":43,"verses":[43]}],"verseLabel":"الزخرف: 43","question":"هل الأمر في ﴿فَاسْتَمْسِكْ بِالَّذِي أُوحِيَ إِلَيْكَ﴾ ابتداء تمسك أم طلب دوام؟","answer":"هو طلب للمداومة والثبات على ما كان الرسول ﷺ قائمًا به، لا إشعار بأنه ترك الوحي. وفيه تقوية له أمام شدة إعراض قومه، وتثبيت للمؤمنين من ورائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص54–55، تحت عنوان «الغرض البلاغي للأمر في ﴿فاستمسك﴾»","url":""}]},{"id":"s43-86","number":86,"surah":43,"verses":[40,43],"references":[{"surah":43,"verses":[40,43]}],"verseLabel":"الزخرف: 40، 43","question":"ما سر مقابلة ﴿ضَلَالٍ مُبِينٍ﴾ بحال الرسول ﴿عَلَى صِرَاطٍ مُسْتَقِيمٍ﴾؟","answer":"﴿ضلال مبين﴾ يصف انحراف المعرضين الواضح، أما الرسول فعلى صراط مستقيم يبلغ الغاية. و﴿على﴾ تصور تمكنه وثباته على الهدى، ووصف الصراط بالاستقامة ينفي عنه العوج، فتظهر المقابلة بين حاله وحالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص57، تحت عنوان «معنى: ﴿على﴾، ودلالة التعبير بها»","url":""}]},{"id":"s43-87","number":87,"surah":43,"verses":[44],"references":[{"surah":43,"verses":[44]}],"verseLabel":"الزخرف: 44","question":"ما دلالة وصف القرآن بأنه ﴿ذِكْرٌ لَكَ وَلِقَوْمِكَ﴾، وما أوجه معنى الذكر هنا؟","answer":"الذكر هنا يحتمل الشرف والذكر الحسن للنبي ﷺ وقومه، ويحتمل التذكير والوعظ وما به حياة القلوب. وتعرض الموسوعة هذه الوجوه، فيجتمع التنويه بالقرآن والتنبيه إلى وجوب الانتفاع به.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص61–62، تحت عنوان «علة التعبير بالذكر في ﴿لذكر لك﴾»","url":""}]},{"id":"s43-88","number":88,"surah":43,"verses":[44],"references":[{"surah":43,"verses":[44]}],"verseLabel":"الزخرف: 44","question":"عن ماذا سيسأل المخاطبون في قوله ﴿وَسَوْفَ تُسْأَلُونَ﴾؟","answer":"لم يعيّن النص متعلق السؤال ليعم كل ما يتصل بحق القرآن: الإيمان به، وشكر نعمته، واتباع هديه، والقيام بما حمّله أهله من عمل ومسؤولية.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص65، تحت عنوان «سر حذف متعلق السؤال»","url":""}]},{"id":"s43-89","number":89,"surah":43,"verses":[45],"references":[{"surah":43,"verses":[45]}],"verseLabel":"الزخرف: 45","question":"كيف يسأل النبي ﷺ رسلًا مضوا قبله في قوله ﴿وَاسْأَلْ مَنْ أَرْسَلْنَا مِنْ قَبْلِكَ﴾؟","answer":"المقصود الرجوع إلى رسالاتهم وما بقي من كتبهم وشهادة أهل العلم بها؛ فذلك يكشف اتفاق الوحي على توحيد الله. ويجوز أن يكون الأمر كناية عن وضوح الحجة حتى كأن الرسل أنفسهم حاضرون للشهادة بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص68، تحت عنوان «بلاغة التعبير بالسؤال في ﴿واسأل﴾»","url":""}]},{"id":"s43-90","number":90,"surah":43,"verses":[45],"references":[{"surah":43,"verses":[45]}],"verseLabel":"الزخرف: 45","question":"لماذا جُعل الرسل أنفسهم شهودًا على بطلان عبادة غير الله؟","answer":"لأن أتباع الرسل قد يبدلون ويحرفون، أما الرسل فهم الأمناء على ما أرسلوا به. والرجوع إلى كتبهم ورسالاتهم الصحيحة يظهر اتفاقهم على التوحيد، فتقوم الحجة على من نسب الشرك إلى الدين.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص69–70، تحت عنوان «بلاغة كون المسؤول الرسل»","url":""}]},{"id":"s43-184","number":184,"surah":43,"verses":[45],"references":[{"surah":43,"verses":[45]}],"verseLabel":"الزخرف: 45","question":"هل ينتظر الاستفهام في ﴿أَجَعَلْنَا مِنْ دُونِ الرَّحْمَنِ آلِهَةً﴾ جوابًا مجهولًا؟","answer":"لا؛ فهو إنكار يقرر أن الله لم يشرع عبادة آلهة دونه. وصيغة السؤال توقظ الغافل ليفكر في القضية، وتؤكد أنه لن يجد في رسالة صحيحة ما يخالف هذا الأصل.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص70، تحت عنوان «بلاغة الاستفهام في ﴿أجعلنا من دون﴾»","url":""}]},{"id":"s43-91","number":91,"surah":43,"verses":[45,46],"references":[{"surah":43,"verses":[45,46]}],"verseLabel":"الزخرف: 45–46","question":"لماذا انتقل السياق من تقرير اتفاق الرسل على التوحيد إلى قصة موسى مع فرعون؟","answer":"ليعرض مثالًا تاريخيًا لهذا الأصل، ويبين أن أقوامًا سابقين قابلوا الرسالة بالاستهانة مع وضوح آياتها. وفي القصة تسلية للنبي ﷺ وتحذير لقومه من أن يسلكوا طريق فرعون وملئه.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص76، تحت عنوان «مناسبة الآية لما قبلها»","url":""}]},{"id":"s43-92","number":92,"surah":43,"verses":[46],"references":[{"surah":20,"verses":[47]},{"surah":26,"verses":[16]},{"surah":43,"verses":[46]}],"verseLabel":"الزخرف: 46؛ طه: 47؛ الشعراء: 16","question":"كيف يجعل وصف الله بـ﴿رَبِّ الْعَالَمِينَ﴾ رسالة موسى إلى فرعون دعوةً للرحمة لا مجرد تهديد؟","answer":"يدخل الوصف فرعون في جملة العالمين المربوبين، وينبه إلى أن إرسال موسى لم يكن للانتقام وحده، بل ليدعوه وقومه إلى عبودية الرب الحق ورحمته؛ فإن استجابوا تبدل طريق الاستعلاء والإفساد إلى طاعة وإحسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص81، تحت عنوان «علة التعبير بالرب»","url":""}]},{"id":"s43-93","number":93,"surah":43,"verses":[47],"references":[{"surah":43,"verses":[47]}],"verseLabel":"الزخرف: 47","question":"ماذا تصور ﴿إِذَا﴾ في قوله ﴿إِذَا هُمْ مِنْهَا يَضْحَكُونَ﴾؟","answer":"تصور المفاجأة وسرعة مبادرتهم بالضحك عند ظهور الآيات، مع أن المنتظر أمام الحجة الباهرة هو التصديق والخضوع؛ فتبرز انقلاب ردهم عن مقتضى الدليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص86، تحت عنوان «بلاغة التعبير بـ﴿إذا﴾»","url":""}]},{"id":"s43-185","number":185,"surah":43,"verses":[47],"references":[{"surah":43,"verses":[47]}],"verseLabel":"الزخرف: 47","question":"ما الذي كنى عنه ضحك قوم فرعون من آيات موسى؟","answer":"كنى عن الاستخفاف بالآيات والتكذيب بها؛ فالضحك ليس سرورًا عابرًا، بل صورة قريبة محسوسة من سخريتهم بالمعجزات التي كان ينبغي أن تدعوهم إلى الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص87–88، تحت عنوان «بلاغة الكناية في الآية»","url":""}]},{"id":"s43-94","number":94,"surah":43,"verses":[48],"references":[{"surah":43,"verses":[48]}],"verseLabel":"الزخرف: 48","question":"كيف تكون كل آية من آيات موسى ﴿أَكْبَرَ مِنْ أُخْتِهَا﴾؟","answer":"يحتمل أن الآيات تدرجت في قوة الإنذار، فكانت اللاحقة أشد من السابقة. ويحتمل أن كل واحدة بلغت غاية العظمة، فإذا تأملها الناظر استغرقت فكره فبدت أكبر من سائرها؛ فلا يلزم من ذلك تناقض في التفاضل.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص94–95، تحت عنوان «نكتة التعبير باسم التفضيل»","url":""}]},{"id":"s43-95","number":95,"surah":43,"verses":[48],"references":[{"surah":43,"verses":[48]}],"verseLabel":"الزخرف: 48","question":"لماذا سُمّيت كل آية من آيات موسى أختًا للأخرى؟","answer":"لأن الآيات تشترك في القوة والظهور والدلالة على صدق الرسول مع اختلاف صورها؛ فشبّه اشتراكها في أصل واحد ومقصد واحد بأخوة يجمع أفرادها أصل مشترك.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص95–96، تحت عنوان «لطيفة التعبير بلفظ ﴿أختها﴾»","url":""}]},{"id":"s43-96","number":96,"surah":43,"verses":[48],"references":[{"surah":43,"verses":[48]}],"verseLabel":"الزخرف: 48","question":"ما الغاية من أخذ قوم فرعون بالعذاب في قوله ﴿لَعَلَّهُمْ يَرْجِعُونَ﴾؟","answer":"لم يكن العذاب لمجرد العقوبة، بل للتنبيه ودعوتهم إلى الرجوع عن التكذيب قبل الاستمرار إلى عاقبة الاستئصال.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص99، تحت عنوان «علة فصل: ﴿لعلهم يرجعون﴾ عما قبله»","url":""}]},{"id":"s43-97","number":97,"surah":43,"verses":[47,48,49],"references":[{"surah":43,"verses":[47,48,49]}],"verseLabel":"الزخرف: 47–49","question":"ماذا يكشف انتقال قوم فرعون من الضحك بالآيات إلى الاستغاثة بموسى عند العذاب؟","answer":"يكشف أن استهزاءهم لم يكن ناشئًا من ضعف الدليل، بل من العناد؛ فلما مسهم العذاب عرفوا لمن يلجؤون ووعدوا بالاهتداء، ثم عادوا إلى النكث بعد كشفه.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص102، تحت عنوان «مناسبة الآيتين لما قبلهما»","url":""}]},{"id":"s43-186","number":186,"surah":43,"verses":[47,48,49],"references":[{"surah":43,"verses":[47,48,49]}],"verseLabel":"الزخرف: 47–49","question":"لماذا قال قوم فرعون لموسى ﴿ادْعُ لَنَا رَبَّكَ﴾ بصيغة الأمر وهم المستغيثون؟","answer":"لم يخرج الأمر منهم على جهة الاستعلاء، بل إلى التوسل والرجاء وطلب الدعاء؛ فقد ألجأهم العذاب إلى سؤال موسى أن يتضرع إلى ربه ليكشفه عنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص106، تحت عنوان «الغرض من الأمر في ﴿ادع لنا ربك﴾»","url":""}]},{"id":"s43-98","number":98,"surah":43,"verses":[49],"references":[{"surah":43,"verses":[49]}],"verseLabel":"الزخرف: 49","question":"ما سر خطابهم موسى بـ﴿يَا أَيُّهَا السَّاحِرُ﴾ في مقام طلب كشف العذاب؟","answer":"تذكر الموسوعة أنهم قد أرادوا بالساحر العالم الماهر، إذ كان السحر عندهم علمًا عظيمًا، فيكون نداء تعظيم في تصورهم. وتذكر قولًا بأنه استهزاء جار على عادتهم، مع بيان أن مقام الاستغاثة يرجح الوجه الأول عند من ناقش هذه الأقوال.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص105، تحت عنوان «الغرض من النداء بوصف الساحر»","url":""}]},{"id":"s43-100","number":100,"surah":43,"verses":[37,49],"references":[{"surah":43,"verses":[37,49]}],"verseLabel":"الزخرف: 37، 49","question":"ماذا يوحي وصف قوم فرعون أنفسهم بـ﴿مُهْتَدُونَ﴾ إذا كُشف عنهم العذاب؟","answer":"يوحي الاسم بالثبات والدوام؛ فقد وعدوا أن يكون اهتداؤهم راسخًا مستمرًا لا موقفًا عابرًا. ثم فضح نكثهم أن هذا التأكيد لم يكن إيمانًا صادقًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص109، تحت عنوان «دلالة التعبير بـ(مهتدون) مادة وصيغة»","url":""}]},{"id":"s43-102","number":102,"surah":43,"verses":[49,50],"references":[{"surah":43,"verses":[49,50]}],"verseLabel":"الزخرف: 49–50","question":"لماذا بالغ قوم فرعون في توكيد قولهم لموسى ﴿إِنَّنَا لَمُهْتَدُونَ﴾؟","answer":"جمعوا ﴿إن﴾ واللام والجملة الاسمية ليظهروا أنهم جادون في وعدهم، صادقون في طلب الهداية إن كشف العذاب، وليستميلوا موسى إلى الدعاء لهم. ثم فضح نكثهم أن هذا التوكيد كان ادعاءً حملتهم عليه الشدة لا تحولًا ثابتًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص108، تحت عنوان «وجه تتابع المؤكدات في: ﴿إننا لمهتدون﴾»","url":""}]},{"id":"s43-103","number":103,"surah":43,"verses":[51],"references":[{"surah":43,"verses":[51]}],"verseLabel":"الزخرف: 51","question":"لماذا انتقل فرعون بعد انكشاف العذاب ونكث العهد إلى المباهاة بملك مصر؟","answer":"لأنه خشي أن يكشف نجاح دعاء موسى الفرق بين صدق الرسول وزيف سلطانه، فبادر إلى استعادة هيبته أمام قومه. نسب إلى نفوذه ما وقع من كشف العذاب، ثم عرض ملكه ومظاهر قوته ليصرفهم عن دلالة الآيات ويعيدهم إلى طاعته.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص115، تحت عنوان «مناسبة الآيات لما قبلها»","url":""}]},{"id":"s43-104","number":104,"surah":43,"verses":[51],"references":[{"surah":43,"verses":[51]}],"verseLabel":"الزخرف: 51","question":"ماذا أراد فرعون من سؤال قومه ﴿أَلَيْسَ لِي مُلْكُ مِصْرَ﴾؟","answer":"لم يكن يسأل طلبًا للعلم، بل أراد تقريرهم بما يراه حقيقة ظاهرة: أنه صاحب الملك والقوة، ثم بناء أفضليته المزعومة على ذلك. فحوّل أنظارهم من برهان موسى إلى سلطان الدنيا الذي يملكه.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص121، تحت عنوان «الغرض من الاستفهام في: ﴿أليس لي﴾»","url":""}]},{"id":"s43-187","number":187,"surah":43,"verses":[51],"references":[{"surah":43,"verses":[51]}],"verseLabel":"الزخرف: 51","question":"لماذا قال فرعون ﴿وَهَذِهِ الْأَنْهَارُ﴾ وهو يفاخر قومه؟","answer":"ليستحضر أمامهم الأنهار القريبة المرئية كأنها حاضرة تحت أعينهم، فيجعل المشهد المحسوس شاهدًا على سلطانه. فالإشارة تقوي تأثير الصورة في جمهور يعرف تلك الأنهار وفروع النيل ويشاهدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص123، تحت عنوان «دلالة التعبير باسم الإشارة»","url":""}]},{"id":"s43-188","number":188,"surah":43,"verses":[51],"references":[{"surah":43,"verses":[51]}],"verseLabel":"الزخرف: 51","question":"لماذا ختم فرعون مباهااته بقوله ﴿أَفَلَا تُبْصِرُونَ﴾؟","answer":"ليرغم قومه على الإقرار بما يشاهدونه من ملكه وأنهاره، ثم يمرر من هذا المرئي حكمه الباطل بأنه أحق بالطاعة من موسى. فهو يستبدل بصيرة الحق بنظرٍ مادي لا يرى إلا العظمة الظاهرة والثراء.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص125، تحت عنوان «الغرض من الاستفهام في: ﴿أفلا تبصرون﴾»","url":""}]},{"id":"s43-105","number":105,"surah":43,"verses":[52],"references":[{"surah":43,"verses":[52]}],"verseLabel":"الزخرف: 52","question":"لماذا تجنب فرعون اسم موسى وقال عنه ﴿هَذَا الَّذِي﴾؟","answer":"تعمد ألا يسميه ولا يذكر صفته رسولًا، وأشار إليه بما يوحي بالتحقير؛ ليصرف قومه عن الإيمان به ويصوّر صاحب الرسالة شخصًا لا يستحق الاعتداد. فالعبارة تكشف موقف فرعون، لا حقيقة منزلة موسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص127، تحت عنوان «نكتة البيان عن نبي الله باسم الإشارة»","url":""}]},{"id":"s43-189","number":189,"surah":43,"verses":[52],"references":[{"surah":43,"verses":[52]}],"verseLabel":"الزخرف: 52","question":"ما الصورة التي حاول فرعون إلصاقها بموسى حين وصفه بأنه ﴿مَهِينٌ﴾؟","answer":"أراد تصويره ضعيفًا حقيرًا لا مال له ولا جاه ولا أنصار، حتى تبدو الضعة صفة ثابتة فيه. وهذا قلب للميزان؛ إذ جعل قلة متاع الدنيا نقصًا في الرسول، واتخذ السلطان والثراء معيارًا للفضل.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص128، تحت عنوان «وجه التعبير بـ﴿مهين﴾ مادة وصيغة»","url":""}]},{"id":"s43-106","number":106,"surah":43,"verses":[52],"references":[{"surah":43,"verses":[52]}],"verseLabel":"الزخرف: 52","question":"كيف بالغ فرعون في الطعن بموسى بقوله ﴿وَلَا يَكَادُ يُبِينُ﴾؟","answer":"لم يزعم أنه أخفق في بيان مرة، بل نفى عنه حتى مقاربة البيان، وصوّر العجز ملازمًا له في الحاضر والمستقبل. وهذه دعوى فرعونية يراد بها تحقير موسى، لا حكم القرآن على قدرته على تبليغ رسالة ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص128، تحت عنوان «دلالة النفي بـ(لا)»","url":""}]},{"id":"s43-107","number":107,"surah":43,"verses":[53],"references":[{"surah":43,"verses":[53]}],"verseLabel":"الزخرف: 53","question":"لماذا اشترط فرعون لموسى ﴿أَسْوِرَةٌ مِنْ ذَهَبٍ﴾؟","answer":"لأن أساور الذهب كانت عندهم شارة الملك والتشريف، فتوهم فرعون أن الرسول لا بد أن يظهر بمظهر الملوك. وجمعها ونكّرها ليطلب زينة كثيرة عظيمة، محولًا صدق الرسالة إلى امتحان للثراء والوجاهة.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص130، تحت عنوان «دلالة التعبير بـ﴿أسورة﴾ جمعًا نكرة»","url":""}]},{"id":"s43-190","number":190,"surah":43,"verses":[53],"references":[{"surah":43,"verses":[53]}],"verseLabel":"الزخرف: 53","question":"لماذا طلب فرعون أن تأتي الملائكة مع موسى ﴿مُقْتَرِنِينَ﴾؟","answer":"أراد أن يراهم مصاحبين له يمشون معه؛ لتكون صحبتهم المشاهدة في زعمه شهادة على نبوته وقوة له. فاشترط تأييدًا حسيًا تراه العين، وكأن صدق الرسول لا يثبت إلا بموكب من الملائكة.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص132، تحت عنوان «موقع ﴿مقترنين﴾ الإعرابي ودلالته»","url":""}]},{"id":"s43-108","number":108,"surah":43,"verses":[51,52,53],"references":[{"surah":43,"verses":[51,52,53]}],"verseLabel":"الزخرف: 51–53","question":"لماذا بدأ فرعون دعايته لقومه بنداء القرب ﴿يَا قَوْمِ﴾ وهو يفاخر بملكه؟","answer":"ليوهمهم أن بينه وبينهم رابطة قرب ومناصحة، ويستنهض انتماءهم إليه قبل أن يعرض تفوقه المزعوم على موسى؛ فمهّد لاستمالة القلوب قبل حشد مظاهر السلطان.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص121، تحت عنوان «سر التعبير عن المنادى بـ﴿قوم﴾ مضافًا»","url":""}]},{"id":"s43-109","number":109,"surah":43,"verses":[54],"references":[{"surah":43,"verses":[54]}],"verseLabel":"الزخرف: 54","question":"كيف استطاع فرعون أن ﴿يَسْتَخِفَّ قَوْمَهُ﴾؟","answer":"صرف عقولهم عن وزن الحق، وخاطب ما فيهم من طيش وخفة حتى استجابوا لدعايته. فاللفظ يكشف أنه لم يقدم برهانًا، بل استثمر ضعف التفكير وهيبة السلطان ليحملهم على قبول قوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص137، تحت عنوان «دلالة التعبير بفعل الاستخفاف»","url":""}]},{"id":"s43-191","number":191,"surah":43,"verses":[54],"references":[{"surah":43,"verses":[54]}],"verseLabel":"الزخرف: 54","question":"لماذا عللت الآية طاعة فرعون بأنهم ﴿كَانُوا قَوْمًا فَاسِقِينَ﴾؟","answer":"لتبين أن خداع فرعون لم يعمل في فراغ؛ فقد سبق فيهم فسق راسخ وإعراض عن الحق، فتهيؤوا لتصديقه ورفض دعوة موسى. وبذلك لا تُحمَّل مسؤولية ضلالهم لحيلة المستبد وحدها، بل لاختيارهم واستعدادهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص138، تحت عنوان «سر فصل: ﴿إنهم كانوا قومًا فاسقين﴾ عما قبلها»","url":""}]},{"id":"s43-110","number":110,"surah":43,"verses":[55],"references":[{"surah":43,"verses":[55]}],"verseLabel":"الزخرف: 55","question":"ما المراد بقوله عن فرعون وقومه ﴿فَلَمَّا آسَفُونَا﴾؟","answer":"الأسف غضب مشوب بحزن، والمراد أنهم عصوا الله وأصروا على التكذيب حتى فعلوا ما يوجب معاملتهم معاملة من استحق غضب سيده وانتقامه. وليس المراد وصف الله بانفعال البشر، بل بيان ما استدعاه كفرهم من العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص140، تحت عنوان «دلالة التعبير بـ﴿آسفونا﴾»","url":""}]},{"id":"s43-192","number":192,"surah":43,"verses":[55],"references":[{"surah":43,"verses":[55]}],"verseLabel":"الزخرف: 55","question":"كيف اختصرت كلمة ﴿آسَفُونَا﴾ تاريخًا طويلًا من تمرد قوم فرعون؟","answer":"بُني الانتقام عليها مع أن تفاصيل إغضابهم لم تُذكر هنا، فكأن تكرر عصيانهم أمر مسلم معروف لا يحتاج إلى إعادة. وطوى الإيجاز المرات المتتابعة التي نكثوا فيها وكذبوا، ثم أبرز نتيجتها الحاسمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص141، تحت عنوان «بلاغة الإيجاز في: ﴿آسفونا﴾»","url":""}]},{"id":"s43-111","number":111,"surah":43,"verses":[55,56],"references":[{"surah":43,"verses":[55,56]}],"verseLabel":"الزخرف: 55–56","question":"كيف صار قوم فرعون بعد هلاكهم ﴿سَلَفًا﴾ لمن جاء بعدهم؟","answer":"تقدموا المكذبين إلى العقوبة فصار مصيرهم سابقةً تنذر كل من يسلك طريقهم. وتنكير ﴿سلفًا﴾ يعظم شأن هذه السابقة ويبرز قوة التحذير: من يحاكي كفرهم قد يلحق بعاقبتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص143–144، تحت عنوان «دلالة التعبير بـ﴿سلفًا﴾ والغرض من تنكيره»","url":""}]},{"id":"s43-193","number":193,"surah":43,"verses":[55,56],"references":[{"surah":43,"verses":[55,56]}],"verseLabel":"الزخرف: 55–56","question":"ماذا أضاف جعل قوم فرعون ﴿مَثَلًا لِلْآخِرِينَ﴾ بعد وصفهم بالسلف؟","answer":"لم يقتصر أثرهم على أنهم أول من تقدم إلى العذاب، بل صارت قصتهم خبرًا عجيبًا يتداوله الناس للعبرة. فجمع الوصفان بين العقاب المحسوس الذي سبقوا إليه والعظة المعنوية التي بقيت بعدهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص144، تحت عنوان «معنى المثل ونكتة عطفه على السلف»","url":""}]},{"id":"s43-112","number":112,"surah":43,"verses":[57],"references":[{"surah":43,"verses":[57]}],"verseLabel":"الزخرف: 57","question":"لماذا انتقل السياق من عاقبة فرعون إلى جدل مشركي مكة بعيسى عليه السلام؟","answer":"بعد عرض فرعون مثالًا للاستكبار والتكذيب، كشف السياق لونًا جديدًا من العناد عند مشركي مكة: تحويل قصة عيسى إلى أداة خصومة. فالانتقال يجمع صورتين مختلفتين لرد الحق، ويهيئ لفضح الحجة التي افتروها.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص147، تحت عنوان «مناسبة الآيتين لما قبلهما»","url":""}]},{"id":"s43-113","number":113,"surah":43,"verses":[57],"references":[{"surah":43,"verses":[57]}],"verseLabel":"الزخرف: 57","question":"ما سر التعبير عن عيسى بـ﴿ابْنُ مَرْيَمَ﴾ عند ضربه مثلًا دون التصريح باسمه؟","answer":"استعملت الكنية ﴿ابن مريم﴾ لأنه لقب معروف لعيسى يستحضره في مقام الجدال. وتبين الموسوعة أن المقام هنا مقام مناظرة لا مدح وثناء، فلا يجعل الاختيار تعليلًا منحصرًا في تقرير بشريته دون دليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص150، تحت عنوان «وجه التعبير بـ﴿ابن مريم﴾ وتوجيه المتشابه اللفظي»","url":""}]},{"id":"s43-114","number":114,"surah":43,"verses":[57],"references":[{"surah":43,"verses":[57]},{"surah":63,"verses":[5]}],"verseLabel":"الزخرف: 57؛ المنافقون: 5","question":"كيف وسعت قراءتا ﴿يَصِدُّونَ﴾ مشهد جدل المشركين في سورة الزخرف؟","answer":"قرئت بالكسر والضم؛ فحملت على الضجيج والصياح عند ضرب المثل، وعلى الإعراض عن الحق أو صد غيرهم عنه. وبذلك تجمع القراءتان حركة الجدل وصوته وغايتَه.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص152، تحت عنوان «توجيه القراءات المتواترة في: ﴿يصدون﴾»","url":""}]},{"id":"s43-115","number":115,"surah":43,"verses":[57],"references":[{"surah":43,"verses":[57]}],"verseLabel":"الزخرف: 57","question":"ماذا تصور ﴿إِذَا﴾ الفجائية في قوله ﴿إِذَا قَوْمُكَ مِنْهُ يَصِدُّونَ﴾؟","answer":"تصور أن ضرب المثل لم يتبعه نظر هادئ، بل انفجر فورًا ضجيجهم أو إعراضهم على غير ما يقتضيه الحق. فالمفاجأة تكشف سرعة تحولهم إلى الخصومة، مع أن المنتظر من سماع البيان هو التأمل والقبول.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص151، تحت عنوان «دلالة التعبير بـ﴿إذا﴾ الفجائية»","url":""}]},{"id":"s43-116","number":116,"surah":43,"verses":[58],"references":[{"surah":43,"verses":[58]}],"verseLabel":"الزخرف: 58","question":"ما الفخ الذي أراده المشركون بسؤالهم ﴿أَآلِهَتُنَا خَيْرٌ أَمْ هُوَ﴾؟","answer":"لم يقصدوا بحثًا منصفًا، بل أرادوا إحراج الرسول: فإن كان عيسى معبودًا من دون الله ثم ذُمّت معبوداتهم، زعموا أن عبادتها أولى أو أن الجميع سواء. فالسؤال صيغ ليُلزم بحجة باطلة، لا ليطلب جواب الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص153، تحت عنوان «الغرض من الاستفهام في: ﴿أآلهتنا خير أم هو﴾»","url":""}]},{"id":"s43-194","number":194,"surah":43,"verses":[58],"references":[{"surah":43,"verses":[58]}],"verseLabel":"الزخرف: 58","question":"كيف كشف قوله ﴿مَا ضَرَبُوهُ لَكَ إِلَّا جَدَلًا﴾ حقيقة سؤال المشركين؟","answer":"حصر غرضهم في الخصومة، فنفى أن يكون المثل صادرًا عن طلب للحق أو رغبة في الفهم. وبذلك نقل النظر من ظاهر الموازنة بين المعبودات إلى الدافع الخفي: المغالبة والإلزام بالباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص156، تحت عنوان «بلاغة القصر بالنفي والاستثناء»","url":""}]},{"id":"s43-117","number":117,"surah":43,"verses":[58],"references":[{"surah":43,"verses":[58]}],"verseLabel":"الزخرف: 58","question":"ما الذي يفضحه وصف المجادلين بأنهم ﴿قَوْمٌ خَصِمُونَ﴾؟","answer":"يفضح أنهم شديدو اللدد، متمسكون بالمراء رغم ظهور الحق، وأن الخصومة صارت خلقًا راسخًا لا بحثًا عابرًا. وفي الوصف توجيه للنبي إلى الإعراض عن جدل لا يراد به الوصول إلى الهدى.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص157–158، تحت عنوان «دلالة التعبير بـ﴿خصمون﴾»","url":""}]},{"id":"s43-118","number":118,"surah":43,"verses":[59],"references":[{"surah":43,"verses":[59]}],"verseLabel":"الزخرف: 59","question":"ماذا أضاف قوله عن عيسى ﴿أَنْعَمْنَا عَلَيْهِ﴾ بعد تقرير عبوديته؟","answer":"أثبت له منزلةً وفضلًا عظيمين من عند الله: النبوة والآيات والاصطفاء، مع بقاء ذلك كله نعمة موهوبة لا صفة ألوهية مكتسبة. فالجملة ترد الغلو من غير أن تنقص قدر عيسى، وتجمع بين العبودية والتشريف.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص162–163، تحت عنوان «دلالة التعبير بفعل الإنعام مسندًا إلى ضمير العظمة»","url":""}]},{"id":"s43-119","number":119,"surah":43,"verses":[57,59],"references":[{"surah":43,"verses":[57,59]}],"verseLabel":"الزخرف: 57، 59","question":"في أي معنى جعل الله عيسى ﴿مَثَلًا لِبَنِي إِسْرَائِيلَ﴾؟","answer":"جعله آيةً قائمةً تدل ولادته ومعجزاته على قدرة الله، ومثالًا يُقتدى بما جمع من الإيمان والطهر والبر والخير. فهو مثل إلهي للهداية والعبرة، بخلاف المثل الذي استعمله المشركون سلاحًا للخصومة.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص164، تحت عنوان «نوع التشبيه في الآية وبلاغته»","url":""}]},{"id":"s43-120","number":120,"surah":43,"verses":[59,60],"references":[{"surah":43,"verses":[59,60]}],"verseLabel":"الزخرف: 59–60","question":"لماذا أعقب الحديث عن خلق عيسى بقوله ﴿وَلَوْ نَشَاءُ لَجَعَلْنَا مِنْكُمْ مَلَائِكَةً فِي الْأَرْضِ يَخْلُفُونَ﴾؟","answer":"ليبين أن خلق عيسى على صورة غير مألوفة دليل قدرة الخالق لا دليل ألوهية المخلوق؛ فالذي أوجده بلا أب قادر على أن يجعل في الأرض ملائكة يخلفون البشر. اختلاف صور الخلق كله داخل في المشيئة ولا يرفع مخلوقًا إلى مقام الإله.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص166، تحت عنوان «مناسبة الآية لما قبلها»","url":""}]},{"id":"s43-121","number":121,"surah":43,"verses":[61],"references":[{"surah":43,"verses":[61]}],"verseLabel":"الزخرف: 61","question":"لماذا لم يكتفِ بالنهي عن الشك في الساعة، بل أتبعه بالأمر ﴿وَاتَّبِعُونِ﴾؟","answer":"لأن مجرد ترك الشك لا يثبت الإيمان ولا يلزم صاحبه بالطريق؛ فقد يبقى المرء في حياد لا يصدّق ولا يتبع. لذلك انتقل الخطاب من إزالة الباطل إلى إثبات الحق، ومن تصحيح الاعتقاد في القلب إلى الاستقامة العملية باتباع الرسول.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص181، تحت عنوان «نكتة عطف الأمر على النهي في ﴿واتبعون﴾»","url":""}]},{"id":"s43-195","number":195,"surah":43,"verses":[61],"references":[{"surah":43,"verses":[61]}],"verseLabel":"الزخرف: 61","question":"كيف يعلل قوله ﴿هَذَا صِرَاطٌ مُسْتَقِيمٌ﴾ النهي عن الامتراء والأمر بالاتباع؟","answer":"يشير إلى النهي والأمر معًا ويقرر أن اليقين بالساعة واتباع الرسول هما طريق النجاة الواضح. فالجملة تحفّز على امتثالهما: من ضيّع ما نُهي عنه وما أُمر به فقد ضيّع الصراط الذي يوصله إلى الغاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص181، تحت عنوان «موقع ﴿هذا صراط مستقيم﴾ مما قبلها»","url":""}]},{"id":"s43-122","number":122,"surah":43,"verses":[43,61],"references":[{"surah":43,"verses":[43,61]}],"verseLabel":"الزخرف: 43، 61","question":"ما الذي تمنحه عبارة ﴿إِنَّكَ عَلَى صِرَاطٍ مُسْتَقِيمٍ﴾ للنبي وأتباعه بعد الأمر بالاستمساك بالوحي؟","answer":"لأنها تعليل للأمر وتثبيت له: استمسك بالوحي لأنك على طريق حق لا يضل من لزمه. وأكّدها بـ﴿إن﴾ والجملة الاسمية لكمال العناية، ولتطمين الرسول وأتباعه بأن القرآن زاد دائم وأن طريقهم مأمون العاقبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص56، تحت عنوان «سر الفصل والتوكيد في ﴿إنك على صراط مستقيم﴾»","url":""}]},{"id":"s43-123","number":123,"surah":43,"verses":[37,62],"references":[{"surah":43,"verses":[37,62]}],"verseLabel":"الزخرف: 37، 62","question":"ماذا يكشف التشديد في ﴿وَلَا يَصُدَّنَّكُمُ الشَّيْطَانُ﴾ عن طريقة إضلاله؟","answer":"يكشف أن الشيطان لا يكتفي بوسوسة عابرة، بل يقصد قطع الناس عن الصراط ويقيم أمامهم الصوارف والحواجز بإصرار. وجاء المضارع مع نون التوكيد ليقابل استمرار محاولاته بتحذير دائم ويقظة لا تنقطع.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص184، تحت عنوان «وجه استعمال ﴿ولا يصدنكم﴾ دلالة وصيغة»","url":""}]},{"id":"s43-124","number":124,"surah":43,"verses":[61,62],"references":[{"surah":43,"verses":[61,62]}],"verseLabel":"الزخرف: 61–62","question":"كيف يصور قوله ﴿إِنَّهُ لَكُمْ عَدُوٌّ مُبِينٌ﴾ عداوة الشيطان بأنها ليست خطرًا عابرًا؟","answer":"جاء الخبر في بناء اسمي يثبت عداوته للإنسان ويصورها صفة راسخة مستمرة؛ فهو عدو منذ وُجد، ويبقى عدوًا إلى آخر وجوده في الأرض. لذلك لا تُعامل وسوسته كعارض مؤقت، بل تستدعي يقظة دائمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص186، تحت عنوان «دلالة اسمية الجملة في: ﴿إنه لكم عدو مبين﴾»","url":""}]},{"id":"s43-125","number":125,"surah":43,"verses":[57,63],"references":[{"surah":43,"verses":[57,63]}],"verseLabel":"الزخرف: 57، 63","question":"لماذا ذُكر عيسى باسمه مجردًا من ﴿ابن مريم﴾ حين جاء بالبينات؟","answer":"لأن المقام يعرض أداءه النبوي المباشر: جاء رسولًا بالبينات والحكمة ليبلغ قومه، فبرزت شخصيته الرسالية لا نسبه ولا كيفية مولده. أما إضافة ﴿ابن مريم﴾ فتناسب مقام الحديث عن خلقه أو نسبه أو ضرب المثل به.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص191، تحت عنوان «نكتة التعبير باسم ﴿عيسى﴾ من غير إضافته إلى مريم»","url":""}]},{"id":"s43-126","number":126,"surah":43,"verses":[63],"references":[{"surah":43,"verses":[63]}],"verseLabel":"الزخرف: 63","question":"ما دلالة قول عيسى ﴿وَلِأُبَيِّنَ لَكُمْ بَعْضَ الَّذِي تَخْتَلِفُونَ فِيهِ﴾، وما سر اختيار ﴿بَعْضَ﴾؟","answer":"التبعيض يبين أن الرسالة لا تتكفل بحسم كل اختلاف في شؤون الناس، وإنما تبين ما تدعو الحاجة إليه في الدين. وتذكر الموسوعة وجهًا آخر: بيان ما يحتاج إلى اجتهاد منهم، أو بعض المختلف فيه مما يكشف فساد اختلافهم؛ فلا يلزم من ﴿بعض﴾ نقص البيان الذي تحتاج إليه الهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص195–196، تحت عنوان «دلالة التبعيض في بيان عيسى»","url":""}]},{"id":"s43-127","number":127,"surah":43,"verses":[63,64],"references":[{"surah":43,"verses":[63,64]}],"verseLabel":"الزخرف: 63–64","question":"لماذا أمر عيسى قومه بطاعته مع أنه يدعوهم إلى عبادة الله وحده؟","answer":"أمرهم بطاعته لا بوصفه معبودًا، بل بوصفه رسولًا يبلغ عن الله ويوصلهم إلى طاعته؛ فاتباع الرسول جزء أصيل من الدين، ولا يصح ادعاء الإيمان بالله مع رد رسوله. لذلك يجتمع توحيد العبادة لله مع وجوب طاعة من أرسله.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص197، تحت عنوان «دلالة الأمر بالطاعة لنفسه في: ﴿وأطيعون﴾»","url":""}]},{"id":"s43-128","number":128,"surah":43,"verses":[64],"references":[{"surah":43,"verses":[64]}],"verseLabel":"الزخرف: 64","question":"لماذا قال عيسى ﴿رَبِّي﴾ قبل ﴿وَرَبُّكُمْ﴾؟","answer":"ليبدأ بإقرار الحق على نفسه قبل إلزام قومه به؛ فهو مربوب عبد رسول، لا يجاوز مقام العبودية إلى الربوبية. وهذا التقديم أبلغ في رد الغلو فيه، لأن صاحب الحق يشهد به على نفسه أولًا ثم يدعو غيره إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص199، تحت عنوان «دلالة تقديم ﴿ربي﴾ على ﴿وربكم﴾»","url":""}]},{"id":"s43-129","number":129,"surah":43,"verses":[61,64],"references":[{"surah":43,"verses":[61,64]}],"verseLabel":"الزخرف: 61، 64","question":"إلى ماذا تشير ﴿هَذَا﴾ في ختام كلام عيسى ﴿هَذَا صِرَاطٌ مُسْتَقِيمٌ﴾؟","answer":"تشير إلى مجموع ما دعاهم إليه: الحكمة، وبيان مواضع الخلاف، وتقوى الله، وطاعة الرسول، وعبادة الله وحده؛ فكأن هذه التعاليم كلها طريق واحد مستقيم. ويصح أن يتركز مرجعها في عبادة الله خاصة لأنها الأصل الجامع لما قبلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص199–200، تحت عنوان «مرجع الإشارة في ﴿هذا صراط مستقيم﴾»","url":""}]},{"id":"s43-130","number":130,"surah":43,"verses":[65],"references":[{"surah":43,"verses":[65]}],"verseLabel":"الزخرف: 65","question":"لماذا جاء اختلاف الأحزاب عقب مجيء عيسى بالحكمة والبينات؟","answer":"لإبراز المفارقة ومسؤوليتهم: جاءهم بما كان ينبغي أن يحسم الخلاف ويوحّدهم على الحق، لكنهم قابلوا البيان بمزيد من التحزب والانقسام. فكأن وضوح الحجة كشف أن المشكلة ليست نقص الدليل، بل موقف النفوس منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص203، تحت عنوان «موقع ﴿فاختلف الأحزاب من بينهم﴾ مما قبلها»","url":""}]},{"id":"s43-196","number":196,"surah":43,"verses":[65],"references":[{"surah":43,"verses":[65]}],"verseLabel":"الزخرف: 65","question":"ماذا تكشف عبارة ﴿مِنْ بَيْنِهِمْ﴾ عن منشأ اختلاف الأحزاب؟","answer":"تكشف أن الانقسام نشأ من داخلهم ومن تلقاء أنفسهم، لا لأن قوة خارجية فرضته عليهم. ويحتمل التعبير أيضًا توكيد استحكام الخلاف في جماعتهم، فيحمّلهم تبعته ويشير إلى أن علاجه يبدأ من إصلاح الداخل.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص204، تحت عنوان «معنى ﴿من﴾ في ﴿من بينهم﴾»","url":""}]},{"id":"s43-131","number":131,"surah":43,"verses":[65,66],"references":[{"surah":43,"verses":[65,66]}],"verseLabel":"الزخرف: 65–66","question":"كيف يكون اليوم نفسه ﴿أَلِيمًا﴾ مع أن الألم يقع على الناس؟","answer":"أُسند الألم إلى اليوم مجازًا للمبالغة، حتى يبدو الزمن كله مشحونًا بالهول والأوجاع، لا أن الألم حادث منفصل فيه فحسب. فإذا كان اليوم ذاته قد وُصف بالألم، كان ما يقع فيه من العذاب أفظع وأشد.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص208، تحت عنوان «بلاغة المجاز العقلي (الإسناد المجازي)»","url":""}]},{"id":"s43-197","number":197,"surah":43,"verses":[65,66],"references":[{"surah":43,"verses":[65,66]}],"verseLabel":"الزخرف: 65–66","question":"ما اليوم الأليم الذي تُوُعِّد به المختلفون، وكيف بيّنته الآية التالية؟","answer":"هو يوم الساعة؛ فجاء قوله ﴿هَلْ يَنْظُرُونَ إِلَّا السَّاعَةَ﴾ جوابًا لمن يسأل متى يقع ذلك الوعيد وما مآله. ثم تفصّل الآيات آثاره بانقلاب خلة أهل الباطل عداوة وخلود المجرمين في العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص209، تحت عنوان «موقع ﴿هل ينظرون إلا الساعة﴾ مما قبلها»","url":""}]},{"id":"s43-132","number":132,"surah":43,"verses":[67],"references":[{"surah":43,"verses":[67]}],"verseLabel":"الزخرف: 67","question":"لماذا تنقلب صداقة أهل الباطل يوم القيامة عداوة، بينما تبقى خلة المتقين؟","answer":"لأن خلة أهل الباطل قامت على التعاون على الكفر والعصيان؛ فإذا ظهرت العاقبة رأى كل واحد في صاحبه سبب حسرته فخاصمه. أما المتقون فجمعتهم الطاعة ونصرة الحق، فيرون ثمرة صحبتهم وينتفعون بها، فتدوم مودتهم كما دام أصلها الصحيح.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص218، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s43-133","number":133,"surah":43,"verses":[68],"references":[{"surah":43,"verses":[68]}],"verseLabel":"الزخرف: 68","question":"ماذا يصنع النداء الإلهي ﴿يَا عِبَادِ﴾ في مشهد تنقلب فيه الخلة عداوة؟","answer":"يستدعي انتباه المتقين إلى البشرى ويمنحهم تشريفًا وتطمينًا وسط هول الموقف. وفيه مقابلة مؤثرة: أخلاء الباطل يُبعد بعضهم بعضًا، أما هؤلاء فيدنيهم الله بخطاب مباشر ويؤمنهم من الخوف والحزن.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص225، تحت عنوان «دلالة النداء في ﴿يا عباد﴾»","url":""}]},{"id":"s43-198","number":198,"surah":43,"verses":[68],"references":[{"surah":43,"verses":[68]}],"verseLabel":"الزخرف: 68","question":"لماذا اختير للمتقين يوم القيامة وصف ﴿عِبَادِ﴾؟","answer":"لأن اللفظ يكرّمهم بإظهار أنهم عبدوا الله اختيارًا وأخلصوا له بالتقوى، فاستحقوا لطف الخطاب والرضا. وهو أنسب بمقام الرحمة والبشرى من لفظ يوحي بمجرد القهر والملك.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص226، تحت عنوان «دلالة إيثار النداء بلفظ العباد»","url":""}]},{"id":"s43-134","number":134,"surah":43,"verses":[68],"references":[{"surah":43,"verses":[68]}],"verseLabel":"الزخرف: 68","question":"ما دلالة الجمع بين نفي الخوف ونفي الحزن، واختلاف صيغتي النفي في ﴿لا خوف عليكم اليوم ولا أنتم تحزنون﴾؟","answer":"يجمع التعبير بين نفي الخوف مما يستقبل ونفي الحزن على ما مضى، فيقرر كمال الأمن النفسي. ونفي الخوف بالاسم يستأصل وجوده، ونفي الحزن بالفعل ينفي تجدد أسبابه وآثاره؛ فلا يقلقهم آت ولا يؤلمهم ماض.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص229، تحت عنوان «نكتة نفي المصدر في الخوف، ونفي الفعل في الحزن»","url":""}]},{"id":"s43-135","number":135,"surah":43,"verses":[68,69],"references":[{"surah":43,"verses":[68,69]}],"verseLabel":"الزخرف: 68–69","question":"لماذا لم يقل: «الذين آمنوا بآياتنا وأسلموا»، بل قال ﴿وَكَانُوا مُسْلِمِينَ﴾؟","answer":"يجعل الإسلام حالًا متحققة راسخة في كيانهم، لا انقيادًا مؤقتًا يزول؛ فقد داوموا على الخضوع لأحكام الله وثبتوا عليه حتى الموت. ولذلك كان الأمن في الآخرة لمن استمر وأخلص، لا لمن آمن زمنًا ثم ارتد.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص231، تحت عنوان «دلالة فعل الكينونة»","url":""}]},{"id":"s43-136","number":136,"surah":43,"verses":[70],"references":[{"surah":43,"verses":[70]}],"verseLabel":"الزخرف: 70","question":"ما الصورة التي ترسمها كلمة ﴿تُحْبَرُونَ﴾ لفرح أهل الجنة؟","answer":"الحبور سرور عظيم لا يبقى خافيًا في النفس، بل يظهر أثره حسنًا وبهاءً على الوجه والهيئة. فاللفظ يصوّر نعيمًا يملأ الداخل ثم يفيض على الظاهر إشراقًا وسعادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص234، تحت عنوان «شرح المفردات»","url":""}]},{"id":"s43-199","number":199,"surah":43,"verses":[70],"references":[{"surah":43,"verses":[70]}],"verseLabel":"الزخرف: 70","question":"هل يبدأ حبور أهل الجنة بعد دخولها، أم يصاحبهم منذ اللحظة الأولى؟","answer":"تفيد الحالية في ﴿أَنْتُمْ وَأَزْوَاجُكُمْ تُحْبَرُونَ﴾ أنهم يدخلون الجنة وهم في حال السرور والتكريم؛ فلا ينتظرون حتى يبدأ النعيم بعد الدخول، بل يلازمهم الحبور من لحظته الأولى.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص238، تحت عنوان «دلالة الحالية في ﴿أنتم وأزواجكم تحبرون﴾»","url":""}]},{"id":"s43-137","number":137,"surah":43,"verses":[71],"references":[{"surah":43,"verses":[71]}],"verseLabel":"الزخرف: 71","question":"لماذا صُوِّرت ضيافة الجنة بالصحاف لا بأوانٍ صغيرة؟","answer":"الصحاف أوانٍ واسعة، وجمعها يوحي بكثرة الطعام وتنوعه وسعة كرم المضيف؛ فلا نقص ولا نفاد في الضيافة. كما تستحضر حفاوة التكريم، فكأن أهل الجنة في مأدبة إلهية عامرة بكل ما يشتهون.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص245، تحت عنوان «وجه التعبير بلفظ (صحاف) دلالة وصيغة»","url":""}]},{"id":"s43-200","number":200,"surah":43,"verses":[71],"references":[{"surah":43,"verses":[71]}],"verseLabel":"الزخرف: 71","question":"لماذا وُصفت الصحاف بأنها من ذهب، ولم يُعَد الوصف مع الأكواب؟","answer":"حُذف وصف الأكواب اكتفاء بما تقدم في الصحاف، حتى لا يثقل النظم بتكرار معلوم. ويترك الحذف أيضًا باب التنوع مفتوحًا؛ فيُذكر نموذج من فخامة النعيم، وتظل صور أخرى مطوية تزيد النفس تشوقًا إليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص247، تحت عنوان «دلالة حذف وصف الأكواب»","url":""}]},{"id":"s43-201","number":201,"surah":43,"verses":[71],"references":[{"surah":43,"verses":[71]}],"verseLabel":"الزخرف: 71","question":"لماذا جمعت الآية بين ﴿مَا تَشْتَهِيهِ الْأَنْفُسُ﴾ و﴿تَلَذُّ الْأَعْيُنُ﴾؟","answer":"ليكتمل النعيم من داخله وخارجه: تُشبَع رغبات النفس المادية والمعنوية، وتُمتع العين بجمال ما تناله. ففي الدنيا قد يشتهي المرء ما لا يسره منظره، أو يرى جميلًا لا يملكه؛ أما في الجنة فيجتمع الاشتهاء والجمال بلا نقص ولا حرمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص251–252، تحت عنوان «نكتة الجمع بين شهوات الأنفس ولذات الأعين»","url":""}]},{"id":"s43-138","number":138,"surah":43,"verses":[71],"references":[{"surah":43,"verses":[71]}],"verseLabel":"الزخرف: 71","question":"ما الفرق البياني بين شهوة الأنفس ولذة الأعين؟","answer":"الشهوة رغبة باطنة في الشيء، أما اللذة فأثر الاستمتاع به. فأضيفت الشهوة إلى النفس لأنها مصدر الرغبات، واللذة إلى الأعين لأنها آلة إدراك الجمال؛ وبالجمع بينهما يصور النص إشباع الرغبة ومتعة المشاهدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص250، تحت عنوان «نكتة إسناد الشهوة إلى النفس، وإسناد اللذة إلى الأعين»","url":""}]},{"id":"s43-139","number":139,"surah":43,"verses":[71],"references":[{"surah":43,"verses":[71]}],"verseLabel":"الزخرف: 71","question":"ما سر ختم ألوان النعيم بقوله ﴿وَأَنْتُمْ فِيهَا خَالِدُونَ﴾؟","answer":"يأتي الخلود ليتم النعيم؛ فالتلذذ يعرض له التنغيص إذا خيف انقطاعه. لذلك يجمع الختام بين كمال ما ينالونه ودوامه، ويزيل توقع الفقد والزوال.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص253–254، تحت عنوان «دلالة عطف جملة الفاصلة على ما قبلها»","url":""}]},{"id":"s43-140","number":140,"surah":43,"verses":[72],"references":[{"surah":43,"verses":[72]}],"verseLabel":"الزخرف: 72","question":"ما دلالة التعبير عن نيل الجنة بالإرث في قوله ﴿وَتِلْكَ الْجَنَّةُ الَّتِي أُورِثْتُمُوهَا﴾؟","answer":"أوثر لفظ الإرث لأنه من أتم صور التمليك؛ فلا يعقبه نسخ ولا استرجاع ولا إبطال، وفيه تصوير لاستقرار الجنة للمؤمنين وانتقالها إليهم بلا منازع.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص259، تحت عنوان «سر إيثار لفظ الإيراث دون غيره»","url":""}]},{"id":"s43-141","number":141,"surah":43,"verses":[72],"references":[{"surah":43,"verses":[72]}],"verseLabel":"الزخرف: 72","question":"ما وجه الجمع بين كون الجنة فضلًا من الله وقوله ﴿بِمَا كُنْتُمْ تَعْمَلُونَ﴾؟","answer":"الباء سببية؛ فالعمل سبب لنيل الجنة، وليس عوضًا يساوي نعيمها. ودخولها بفضل الله ورحمته لا يلغي اعتبار العمل، بل يجمع بين الوعد للمطيعين ونفي استقلال أعمالهم باستحقاق هذا الفضل.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص260، تحت عنوان «معنى الباء في: ﴿بما كنتم تعملون﴾»","url":""}]},{"id":"s43-142","number":142,"surah":43,"verses":[70,71,72,73],"references":[{"surah":43,"verses":[70,71,72,73]}],"verseLabel":"الزخرف: 70–73","question":"لماذا فُصِّلت ألوان نعيم الجنة بعد بشارة المتقين بالأمن إجمالًا؟","answer":"لأن نفي الخوف والحزن وعد جامع، فجاء التفصيل ليكشف كيف يتحقق هذا الأمن في التكريم والسرور والضيافة وسعة النعيم. وتحويل البشرى من إجمال إلى مشاهد محسوسة يزيد شوق السامع، ويرغّب غير المتقين في اللحاق بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص234، تحت عنوان «مناسبة الآيتين لما قبلهما»","url":""}]},{"id":"s43-143","number":143,"surah":43,"verses":[71,74],"references":[{"surah":43,"verses":[71,74]}],"verseLabel":"الزخرف: 71، 74","question":"لماذا لم يكتفِ السياق بذكر جهنم، بل قال ﴿فِي عَذَابِ جَهَنَّمَ﴾؟","answer":"ليبين أن الوعيد ليس مجرد دخول النار، بل الاستغراق في عذاب عظيم غير مألوف كعذاب الدنيا؛ وإضافة العذاب إلى اسم جهنم تهوّل شأنه بما يحمله الاسم من رهبة وقبح.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص268، تحت عنوان «سر إضافة لفظ ﴿عذاب﴾ إلى ﴿جهنم﴾»","url":""}]},{"id":"s43-144","number":144,"surah":43,"verses":[74,75,76],"references":[{"surah":43,"verses":[74,75,76]}],"verseLabel":"الزخرف: 74–76","question":"ما الصورة التي يرسمها قوله عن المجرمين ﴿فِي عَذَابِ جَهَنَّمَ خَالِدُونَ﴾؟","answer":"يصوّر العذاب محيطًا بهم إحاطة الظرف بما فيه، ويقيد خلودهم به؛ فلا يذكر مجرد بقائهم في جهنم، بل استغراقهم الدائم في عذابها الشديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص268، تحت عنوان «بلاغة تعلق الجار والمجرور ﴿في عذاب﴾ بـ﴿خالدون﴾»","url":""}]},{"id":"s43-202","number":202,"surah":43,"verses":[74,75,76],"references":[{"surah":43,"verses":[74,75,76]}],"verseLabel":"الزخرف: 74–76","question":"لماذا نُفي أن يفتر العذاب عن أهل جهنم؟","answer":"لنفي كل ضعف أو تخفيف يطرأ على عذابهم؛ فكلما نضجت جلودهم تجدد الألم، وبذلك يتأكد استمرار العذاب وخلودهم فيه بلا فترة راحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص269، تحت عنوان «الغرض من التعبير بأسلوب النفي في ﴿لا يفتر عنهم﴾»","url":""}]},{"id":"s43-145","number":145,"surah":43,"verses":[75],"references":[{"surah":43,"verses":[75]}],"verseLabel":"الزخرف: 75","question":"ما الذي يضيفه وصف أهل النار بأنهم ﴿مُبْلِسُونَ﴾ بعد نفي تخفيف العذاب عنهم؟","answer":"يجمع السياق عليهم بين استمرار الألم وانقطاع الأمل؛ فلا يخفف عنهم العذاب، وهم فيه يائسون من الرحمة والخروج. وورود الوصف في جملة اسمية يقوي ثبات هذا اليأس.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص270، تحت عنوان «معنى الواو ودلالتها في ﴿وهم فيه مبلسون﴾»","url":""}]},{"id":"s43-146","number":146,"surah":43,"verses":[76],"references":[{"surah":43,"verses":[76]}],"verseLabel":"الزخرف: 76","question":"كيف يعيد قوله ﴿وَمَا ظَلَمْنَاهُمْ وَلَكِنْ كَانُوا هُمُ الظَّالِمِينَ﴾ تبعة العذاب إلى المجرمين أنفسهم؟","answer":"ينفي أن يكون ما نالهم ظلمًا واقعًا عليهم، ثم يحصر الظلم فيهم هم ويثبته لهم بقوة؛ فقد صنعوا بأعمالهم سبب العذاب وظلموا أنفسهم، فكان الجزاء ثمرة اختيارهم لا جورًا عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص272، تحت عنوان «بلاغة التعبير بأسلوب القصر في: ﴿ولكن كانوا هم الظالمين﴾»","url":""}]},{"id":"s43-147","number":147,"surah":43,"verses":[77],"references":[{"surah":43,"verses":[77]}],"verseLabel":"الزخرف: 77","question":"لماذا كان جواب مالك لأهل النار بكلمة ﴿مَاكِثُونَ﴾؟","answer":"لأن اسم الفاعل يصور مكثهم ثابتًا دائمًا ملازمًا لهم، فلا خلاص منه بموت ولا بغيره. وجاء جمعًا ليبين أن هذا المصير يشمل المجرمين جميعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص282، تحت عنوان «سر التعبير باسم الفاعل مجموعًا ﴿ماكثون﴾»","url":""}]},{"id":"s43-148","number":148,"surah":43,"verses":[77],"references":[{"surah":43,"verses":[77]}],"verseLabel":"الزخرف: 77","question":"ما سر التعبير في قول أهل النار لمالك ﴿لِيَقْضِ عَلَيْنَا رَبُّكَ﴾ دون «ربنا»؟","answer":"أضافوا الرب إلى مالك استعطافًا، لما يتوهمونه من قربه من الله ومكانته عنده، ورجاء أن يشفع لهم في الخلاص بالموت. وليس التعبير إنكارًا لربوبية الله لهم، بل محاولة لاستمالة من يخاطبونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص280، تحت عنوان «سر إضافة لفظ (الرب) إلى ضمير المخاطب في: ﴿ربك﴾»","url":""}]},{"id":"s43-149","number":149,"surah":43,"verses":[77,78],"references":[{"surah":43,"verses":[77,78]}],"verseLabel":"الزخرف: 77–78","question":"كيف تكشف جملة ﴿لَقَدْ جِئْنَاكُمْ بِالْحَقِّ﴾ سبب مكث أهل النار؟","answer":"جاءت بيانًا لعلة مكثهم: بلغهم الحق عن طريق الرسل والكتب، لكنهم أعرضوا عنه وكرهوه. فليست العقوبة لقصور الحجة، بل لموقفهم من الحق بعد مجيئه.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص282، تحت عنوان «دلالة فصل ﴿لقد جئناكم بالحق﴾ عما قبلها»","url":""}]},{"id":"s43-203","number":203,"surah":43,"verses":[77,78],"references":[{"surah":43,"verses":[77,78]}],"verseLabel":"الزخرف: 77–78","question":"لماذا قيل ﴿أَكْثَرُكُمْ لِلْحَقِّ كَارِهُونَ﴾ ولم يقل: كلكم؟","answer":"لأن فيهم رؤساء جاهروا بكراهة الحق وصدوا عنه، وفيهم أتباع لم تكن الكراهية صفة لازمة لهم وإنما انقادوا لسادتهم. وفي التعبير بالأكثر فسحة لأن تتغير قناعة التابع فيقبل الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص284–285، تحت عنوان «نكتة نسبة كراهة الحق لأكثرهم دون لجميعهم»","url":""}]},{"id":"s43-150","number":150,"surah":43,"verses":[79],"references":[{"surah":43,"verses":[79]}],"verseLabel":"الزخرف: 79","question":"ما دلالة اختلاف الصيغة بين ﴿أم أبرموا أمرًا﴾ و﴿فإنا مبرمون﴾؟","answer":"جاء ﴿أبرموا﴾ فعلًا ماضيًا يصور ما أحكموه من مكر، وجاء ﴿مبرمون﴾ اسم فاعل في جملة مؤكدة ليدل على ثبوت ما يقابل تدبيرهم ويبطل أثره. فإحكامهم المحدود يواجه قدرة الله وتدبيره النافذ.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص294، تحت عنوان «نكتة اختلاف الصيغة بين ﴿أبرموا﴾ و﴿مبرمون﴾»","url":""}]},{"id":"s43-151","number":151,"surah":43,"verses":[80],"references":[{"surah":43,"verses":[80]}],"verseLabel":"الزخرف: 80","question":"ما الفرق بين ﴿سِرَّهُمْ﴾ و﴿نَجْوَاهُمْ﴾ في قوله ﴿أَنَّا لَا نَسْمَعُ سِرَّهُمْ وَنَجْوَاهُمْ﴾؟","answer":"السر ما يخفيه الإنسان عن غيره، وقد يكون في نفسه، والنجوى كلام خفي يتبادله المتناجون. والجمع بينهما يقرر إحاطة علم الله بما يضمرونه وما يتحدثون به خفية؛ فلا يحجب الإخفاء شيئًا عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص302–303، تحت عنوان «السر والنجوى»","url":""}]},{"id":"s43-152","number":152,"surah":43,"verses":[79,80],"references":[{"surah":43,"verses":[79,80]}],"verseLabel":"الزخرف: 79–80","question":"لماذا أُتبع سماع سرهم ونجواهم بقوله ﴿وَرُسُلُنَا لَدَيْهِمْ يَكْتُبُونَ﴾؟","answer":"ليعلموا أن إحاطة الله بخفي كلامهم ليست علمًا بلا أثر؛ فالملائكة تسجل ما يسرون وما يعملون ليحاسبوا عليه. وهكذا انتقل التهديد من كشف الخفاء إلى إثبات المؤاخذة.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص299، تحت عنوان «معنى الواو في ﴿ورسلنا لديهم يكتبون﴾»","url":""}]},{"id":"s43-153","number":153,"surah":43,"verses":[81,82],"references":[{"surah":43,"verses":[81,82]}],"verseLabel":"الزخرف: 81–82","question":"هل يفيد قوله ﴿إِنْ كَانَ لِلرَّحْمَنِ وَلَدٌ﴾ احتمال أن يكون لله ولد؟","answer":"لا؛ فالعبارة على أحد الوجهين شرط افتراضي لإلزام الخصم وبيان المحال، وعلى الوجه الآخر تكون ﴿إن﴾ نافية بمعنى: ما كان للرحمن ولد. وكلا الوجهين يبلغ في نفي الولد ولا يقر إمكانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص308، تحت عنوان «معنى ﴿إن﴾ في ﴿إن كان﴾»","url":""}]},{"id":"s43-154","number":154,"surah":43,"verses":[82],"references":[{"surah":43,"verses":[82]}],"verseLabel":"الزخرف: 82","question":"لماذا أُعيد لفظ ﴿رَبِّ﴾ في قوله ﴿رَبِّ السَّمَاوَاتِ وَالْأَرْضِ رَبِّ الْعَرْشِ﴾؟","answer":"لتوكيد ربوبية الله لكل شيء، ولتفخيم شأن العرش والتنويه بعظمته؛ فإذا كان أعظم المخلوقات داخلًا في ملكه وربوبيته، ظهر كمال تنزيهه عن الحاجة إلى ولد أو معين.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص311، تحت عنوان «نكتة تكرير اسم الرب»","url":""}]},{"id":"s43-155","number":155,"surah":43,"verses":[81,82,83],"references":[{"surah":43,"verses":[81,82,83]}],"verseLabel":"الزخرف: 81–83","question":"إلى متى يستمر ترك المشركين يخوضون ويلعبون؟","answer":"إلى أن يلاقوا يومهم الموعود؛ فخوضهم ولهوهم لهما أجل محدود ينتهي بالقيامة والحساب. إنهم يُمهلون ولا يُهملون، وسيواجهون اليوم الذي أنكروه.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص316، تحت عنوان «معنى ﴿حتى﴾ ودلالته في ﴿حتى يلاقوا﴾»","url":""}]},{"id":"s43-156","number":156,"surah":43,"verses":[84],"references":[{"surah":43,"verses":[84]}],"verseLabel":"الزخرف: 84","question":"هل يعني قوله ﴿فِي السَّمَاءِ إِلَهٌ وَفِي الْأَرْضِ إِلَهٌ﴾ أن الله مستقر فيهما؟","answer":"لا؛ فالمعنى أنه المعبود بحق في السماء والمعبود بحق في الأرض، لا أن الظرفين مكان لذاته. فالآية تخبر بألوهيته في العالمين، والمعبود واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص321–322، تحت عنوان «سر تعلق الجار والمجرور في كل من ﴿في السماء﴾ و﴿في الأرض﴾»","url":""}]},{"id":"s43-204","number":204,"surah":43,"verses":[84],"references":[{"surah":43,"verses":[84]}],"verseLabel":"الزخرف: 84","question":"لماذا كُرر لفظ ﴿إِلَهٌ﴾ منكرًا في السماء والأرض؟","answer":"لتأكيد أنه معبود أهل السماء ومعبود أهل الأرض جميعًا. والاختلاف بين موضعي العبادة والعابدين، لا في ذات المعبود؛ لذلك لا يفيد التكرار تعدد الآلهة.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص323، تحت عنوان «نكتة تكرار لفظ ﴿إله﴾ منكرًا»","url":""}]},{"id":"s43-157","number":157,"surah":43,"verses":[84],"references":[{"surah":43,"verses":[84]}],"verseLabel":"الزخرف: 84","question":"لماذا خُتم إثبات ألوهية الله في السماء والأرض بقوله ﴿وَهُوَ الْحَكِيمُ الْعَلِيمُ﴾؟","answer":"لأن من يستحق الألوهية لا بد أن يبلغ كمال الحكمة في تدبير خلقه وكمال العلم بمصالحهم. فالوصفان يؤكدان دليل الألوهية، ويكشفان بطلان عبادة من يفتقر إلى الحكمة أو العلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص324، تحت عنوان «بلاغة التذييل في ﴿وهو الحكيم العليم﴾»","url":""}]},{"id":"s43-205","number":205,"surah":43,"verses":[84],"references":[{"surah":43,"verses":[84]}],"verseLabel":"الزخرف: 84","question":"لماذا قُدِّم ﴿الْحَكِيمُ﴾ على ﴿الْعَلِيمُ﴾ في ختام آية الألوهية؟","answer":"لأن المقام مقام التشريع والحكم والتدبير، فناسب تقديم الحكمة التي تضع الأشياء في مواضعها وتحكم بين العباد على الوجه الصحيح، ثم جاء العلم المحيط أساسًا لذلك الحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص325، تحت عنوان «نكتة تقديم ﴿الحكيم﴾ على ﴿العليم﴾»","url":""}]},{"id":"s43-158","number":158,"surah":43,"verses":[85],"references":[{"surah":43,"verses":[85]}],"verseLabel":"الزخرف: 85","question":"لماذا عُطف قوله ﴿وَعِنْدَهُ عِلْمُ السَّاعَةِ﴾ على ملك السماوات والأرض؟","answer":"ليربط ملك الله للعالم بتدبير مآله؛ فمن يملك الموجودات يملك فناءها وبعثها، ويعلم موعد الساعة التي تنتقل عندها إلى الدار الآخرة. فاجتمع كمال القدرة وكمال العلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص329، تحت عنوان «بلاغة العطف في ﴿وعنده علم الساعة﴾»","url":""}]},{"id":"s43-159","number":159,"surah":43,"verses":[85,86],"references":[{"surah":43,"verses":[85,86]}],"verseLabel":"الزخرف: 85–86","question":"من الذي استثناه قوله ﴿إِلَّا مَنْ شَهِدَ بِالْحَقِّ﴾ من نفي الشفاعة؟","answer":"استثنى من المعبودين من شهد بالتوحيد عن علم وأخلص العبادة لله، كعيسى والملائكة؛ أما الأصنام ومن لم يشهد بالحق فلا يملك شفاعة، وفي ذلك قطع لتعلق المشركين بمعبوداتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص338، تحت عنوان «الغرض من التعبير بأسلوب القصر بطريق النفي والاستثناء»","url":""}]},{"id":"s43-160","number":160,"surah":43,"verses":[87],"references":[{"surah":43,"verses":[87]}],"verseLabel":"الزخرف: 87","question":"ما سر إلزام المشركين بإقرارهم أن الله خلقهم ثم التعجيب ﴿فَأَنَّى يُؤْفَكُونَ﴾؟","answer":"إقرارهم بأن الله خلقهم يلزمهم بتوحيده في العبادة، ثم يأتي الاستفهام إنكارًا وتعجيبًا من انصرافهم عن مقتضى اعترافهم؛ فكيف يعرفون الخالق ثم يعبدون غيره؟","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص344–345، تحت عنوان «الغرض من التعبير بالاستفهام في: ﴿فأنى يؤفكون﴾»","url":""}]},{"id":"s43-161","number":161,"surah":43,"verses":[88],"references":[{"surah":43,"verses":[88]}],"verseLabel":"الزخرف: 88","question":"لماذا عُبِّر عن شكوى الرسول ﷺ بلفظ ﴿قِيلِهِ﴾؟","answer":"لتوكيد وقوع ندائه وشكواه حتى كأنها صارت قولًا ملازمًا له لا ينفك عنه؛ فقد طال إصرار قومه، فكان يشكوهم إلى ربه شفقةً عليهم وطلبًا لتيسير أمرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص352، تحت عنوان «سر التعبير بلفظ القيل في ﴿وقيله﴾»","url":""}]},{"id":"s43-162","number":162,"surah":43,"verses":[88,89],"references":[{"surah":43,"verses":[88,89]}],"verseLabel":"الزخرف: 88–89","question":"لماذا جاء الأمر ﴿فَاصْفَحْ عَنْهُمْ﴾ عقب شكوى الرسول من عدم إيمانهم؟","answer":"لأن الرسول لما فوض أمرهم إلى ربه تولى الله الانتصاف منهم، وأمره أن يعرض عن جدالهم ولا يحزن عليهم. ففي التعقيب تسلية له، ونقل لأمر الجزاء إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص355، تحت عنوان «معنى الفاء ودلالتها في ﴿فاصفح﴾»","url":""}]},{"id":"s43-206","number":206,"surah":43,"verses":[88,89],"references":[{"surah":43,"verses":[88,89]}],"verseLabel":"الزخرف: 88–89","question":"ما الذي يضيفه قوله ﴿وَقُلْ سَلَامٌ﴾ إلى الأمر بالصفح عنهم؟","answer":"يكمل الإعراض بسلام مفارقة لا سلام تحية؛ فيترك الرسول مجادلتهم من غير خصومة، ويبتعد عما ينغص عليه. فجمع التعبيران كمال التخفيف عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص356، تحت عنوان «معنى الواو ودلالتها في ﴿وقل سلام﴾»","url":""}]},{"id":"s43-207","number":207,"surah":43,"verses":[88,89],"references":[{"surah":43,"verses":[88,89]}],"verseLabel":"الزخرف: 88–89","question":"لماذا أُتبع قول السلام للمكذبين بقوله ﴿فَسَوْفَ يَعْلَمُونَ﴾؟","answer":"ليبين أن إعراض الرسول عنهم لا يعني سقوط العاقبة؛ فالله يتولى تهديدهم، وسيعلمون ما أعد لهم حين ينكشف المستور. وفي ذلك وعيد لهم وتسلية للرسول.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص357، تحت عنوان «معنى الفاء ودلالتها في ﴿فسوف يعلمون﴾»","url":""}]},{"id":"s43-163","number":163,"surah":43,"verses":[1],"references":[{"surah":43,"verses":[1]}],"verseLabel":"الزخرف: 1–89","question":"ما دلالة بناء السورة من تعظيم الكتاب وكشف زيف الزخرف إلى ختامها بالصفح والوعيد بالعلم؟","answer":"تجعل السورة الوحي مرجع تقويم القيم، وتكشف فساد الاغترار بزخرف الدنيا واتخاذه معيارًا للحق، ثم تعرض عاقبة المؤمنين والمكذبين. وفي ختامها يأتي الصفح عن المعرضين مقرونًا بالوعيد، فيتصل بيان الحق بما ينتظر من يصر على رده.","sources":[{"label":"موسوعة التفسير البلاغي، ج53، ص527–528، تحت عنوان «موضوعات السورة وخصائصها»","url":""}]},{"id":"s44-1","number":1,"surah":44,"verses":[1],"references":[{"surah":44,"verses":[1]}],"verseLabel":"عنوان السورة","question":"ما مناسبة تسمية السورة بـ«الدخان»، وهو لفظ ورد فيها مرة واحدة؟","answer":"يربط الاسم السورة بمحور إنذار المكذبين: فالدخان علامة عذاب يهددهم ويحيط بهم، ويواجه لعبهم واستهانتهم بالوعيد. ولهذا كان هذا اللفظ مناسبًا لغرضها وإن ورد مرة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص363–364، تحت عنوان «اسم السورة ومناسبة تسميتها»","url":""}]},{"id":"s44-2","number":2,"surah":44,"verses":[1],"references":[{"surah":44,"verses":[1]}],"verseLabel":"مقدمة السورة","question":"ما صلة افتتاح سورة الدخان بالقسم على القرآن بخاتمة سورة الزخرف؟","answer":"لما ختمت الزخرف بوعيد المكذبين، افتتحت الدخان بتعظيم القرآن والقسم به؛ فكأن مطلع السورة الجديدة يقرر أن هذا الكتاب الذي أعرضوا عنه هو الحجة المبينة التي يستحق التكذيب بها الوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص368، تحت عنوان «مناسبة الآيات لما قبلها»","url":""}]},{"id":"s44-3","number":3,"surah":44,"verses":[1,2],"references":[{"surah":44,"verses":[1,2]}],"verseLabel":"الدخان: 1–2","question":"ما سر أن يكون المقسَم به القرآن والمقسَم عليه إنزاله في ليلة مباركة؟","answer":"للتنويه بعظمة القرآن من جهتين: فهو في ذاته أهل لأن يقسم الله به، وإنزاله في الليلة المباركة حدث جليل يستحق أن يؤكد بالقسم؛ فاتحد التعظيم للمقسَم به وللخبر المقسَم عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص372، تحت عنوان «بلاغة الإنشاء باستخدام أسلوب القسم»","url":""}]},{"id":"s44-4","number":4,"surah":44,"verses":[2],"references":[{"surah":44,"verses":[2]}],"verseLabel":"الدخان: 2","question":"ما سر وصف الكتاب بـ﴿الْمُبِينِ﴾، وهل هو مبين في نفسه أم مبين لغيره؟","answer":"يحتمل ﴿المبين﴾ معنى البين الظاهر في هدايته وإعجازه، ومعنى المظهر للحق الذي يبين الهدى والشرع. فاللفظ يجمع وضوح الكتاب في نفسه وقدرته على إيضاح ما يحتاج إليه الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص373، تحت عنوان «دلالة وصف الكتاب بـ﴿المبين﴾»","url":""}]},{"id":"s44-5","number":5,"surah":44,"verses":[3],"references":[{"surah":44,"verses":[3]}],"verseLabel":"الدخان: 3","question":"لماذا جاء إنزال القرآن بصيغة الماضي في ﴿إِنَّا أَنْزَلْنَاهُ﴾؟","answer":"لتحقيق وقوع الإنزال وتثبيته كأمر مقطوع به، مع استحضار شرف ليلة البدء بنزوله؛ فصيغة الماضي تنقل الخبر من الوعد المنتظر إلى الحقيقة الثابتة.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص375–376، تحت عنوان «نكتة التعبير بالمسند الفعلي ﴿أنزلناه﴾، ودلالة مجيئه ماضيًا»","url":""}]},{"id":"s44-6","number":6,"surah":44,"verses":[3],"references":[{"surah":44,"verses":[3]}],"verseLabel":"الدخان: 3","question":"ما دلالة تنكير ﴿ليلة﴾ ووصفها بالمباركة؟","answer":"تنكير الليلة يعظم شأنها ويشوق إلى معرفتها، ووصفها بالمباركة يبين كثرة الخير المتصل بنزول القرآن فيها وابتداء الرسالة. وتعينها الموسوعة بليلة القدر، التي تتجدد فيها بركة العبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص377–378، تحت عنوان «نكتة تنكير ﴿ليلة﴾ ودلالة وصفها بـ﴿مباركة﴾»","url":""}]},{"id":"s44-7","number":7,"surah":44,"verses":[3],"references":[{"surah":44,"verses":[3]}],"verseLabel":"الدخان: 3","question":"ماذا يفيد قوله ﴿إِنَّا كُنَّا مُنْذِرِينَ﴾ في تعليل إنزال القرآن؟","answer":"يفيد أن الإنذار سنة إلهية ماضية مستمرة، لا حادثًا طارئًا؛ فقد اقتضت الرحمة والحكمة أن يرسل الله من يحذر الناس قبل المؤاخذة ويقيم عليهم الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص379، تحت عنوان «نكتة التعبير بالكون الماضي»","url":""}]},{"id":"s44-8","number":8,"surah":44,"verses":[4],"references":[{"surah":44,"verses":[4]}],"verseLabel":"الدخان: 4","question":"ما دلالة تقديم ﴿فِيهَا﴾ في ﴿فِيهَا يُفْرَقُ كُلُّ أَمْرٍ حَكِيمٍ﴾؟","answer":"تقديم ﴿فيها﴾ يعتني بالليلة ويخصها بوقوع الفرق وقضاء الأمور، فيعظم شأنها ويربط ما يفصل فيها ببركتها. وهو أيضًا تمهيد لما سيذكر من حكمة هذا التفريق.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص384، تحت عنوان «نكتة تقديم شبه الجملة على ما تعلق به في ﴿فيها يفرق﴾»","url":""}]},{"id":"s44-9","number":9,"surah":44,"verses":[3,4],"references":[{"surah":44,"verses":[3,4]}],"verseLabel":"الدخان: 3–4","question":"لماذا أعقب وصف الليلة بالمباركة قوله ﴿فِيهَا يُفْرَقُ كُلُّ أَمْرٍ حَكِيمٍ﴾؟","answer":"لأنه يبين وجهًا من بركتها: ففيها يفصل من اللوح المحفوظ ما شاء الله إظهاره من المقادير المحكمة، فانتقل السياق من وصف البركة إجمالًا إلى مظهر من مظاهرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص382–383، تحت عنوان «علة فصل قوله تعالى: ﴿فيها يفرق كل أمر حكيم﴾»","url":""}]},{"id":"s44-10","number":10,"surah":44,"verses":[3,5],"references":[{"surah":44,"verses":[3,5]}],"verseLabel":"الدخان: 3، 5","question":"لماذا جاء قوله ﴿إِنَّا كُنَّا مُرْسِلِينَ﴾ بعد ﴿أَمْرًا مِنْ عِنْدِنَا﴾؟","answer":"ليبين أن إرسال الرسل بالوحي رحمة جارية من الله، وأن الأمر المفروق لا ينفصل عن هداية العباد وإبلاغهم؛ فالإرسال سنة إلهية ثابتة كما أن الإنذار كذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص389–390، تحت عنوان «علة فصل قوله تعالى: ﴿إنا كنا مرسلين﴾»","url":""}]},{"id":"s44-11","number":11,"surah":44,"verses":[5,6],"references":[{"surah":44,"verses":[5,6]}],"verseLabel":"الدخان: 5–6","question":"لماذا سُمّي إرسال الرسل وإنذار الناس ﴿رَحْمَةً﴾؟","answer":"لأن الرسالة تنقذ الناس من الضلال وتدلهم على النجاة قبل نزول العقوبة؛ فهي رحمة بما تحمله من هداية وإقامة للحجة وفتح لباب التوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص391–392، تحت عنوان «نكتة تنكير ﴿رحمة﴾، وبيان وجه نصبها»","url":""}]},{"id":"s44-86","number":86,"surah":44,"verses":[5,6],"references":[{"surah":44,"verses":[5,6]}],"verseLabel":"الدخان: 5–6","question":"لماذا قيل ﴿رَحْمَةً مِنْ رَبِّكَ﴾ باسم الربوبية؟","answer":"لأن الربوبية تستحضر التربية والرعاية والإنعام؛ فإرسال الوحي والرسل من عناية الرب بعباده، وفي إضافة الرب إلى الرسول تشريف له وتطمين بأن الرسالة محاطة بالرعاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص392–393، تحت عنوان «سر التعبير بعنوان الربوبية في ﴿ربك﴾»","url":""}]},{"id":"s44-12","number":12,"surah":44,"verses":[6],"references":[{"surah":44,"verses":[6]}],"verseLabel":"الدخان: 6","question":"لماذا خُتم ذكر الرحمة بقوله ﴿إِنَّهُ هُوَ السَّمِيعُ الْعَلِيمُ﴾؟","answer":"لأن إرسال الرحمة قائم على سمع الله لأقوال العباد وعلمه بأحوالهم وحاجاتهم؛ فيؤكد الختام أن الوحي صدر عن إحاطة كاملة لا عن غفلة عنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص397، تحت عنوان «بلاغة مناسبة ختام الآية بهذين الاسمين الجليلين»","url":""}]},{"id":"s44-87","number":87,"surah":44,"verses":[6],"references":[{"surah":44,"verses":[6]}],"verseLabel":"الدخان: 6","question":"لماذا قُدّم ﴿السَّمِيعُ﴾ على ﴿الْعَلِيمُ﴾؟","answer":"لأن المقام مقام إرسال وإنذار وخطاب مسموع، فناسب تقديم السمع المتعلق بالأقوال، ثم جاء العلم الأعم ليشمل الأقوال والنيات والأحوال كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص397–398، تحت عنوان «سر تقديم صفة السمع على صفة العلم»","url":""}]},{"id":"s44-13","number":13,"surah":44,"verses":[6,7],"references":[{"surah":44,"verses":[6,7]}],"verseLabel":"الدخان: 6–7","question":"لماذا انتقل الخطاب من المفرد في ﴿رَبِّكَ﴾ إلى الجمع في ﴿إِنْ كُنْتُمْ مُوقِنِينَ﴾؟","answer":"لأن ﴿ربك﴾ تشريف للرسول وتثبيت له، ثم وُجه خطاب الجمع إلى المكذبين ليواجههم بالدليل ويستنهض ما يدعونه من يقين؛ فالالتفات ينقل الكلام من التسلية إلى المحاجة المباشرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص403، تحت عنوان «بلاغة الالتفات من خطاب المفرد إلى خطاب الجمع»","url":""}]},{"id":"s44-14","number":14,"surah":44,"verses":[7,8],"references":[{"surah":44,"verses":[7,8]}],"verseLabel":"الدخان: 7–8","question":"لماذا جُمع في الاستدلال بين ﴿رَبُّكُمْ﴾ و﴿رَبُّ آبَائِكُمُ الْأَوَّلِينَ﴾؟","answer":"لإبطال توهم أن الربوبية بدأت بهم أو اختصت بجيلهم؛ فالله ربهم ورب من سبقهم، وبذلك يمتد الدليل عبر الأجيال ويهدم ما ورثوه من الشرك عن الآباء.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص408، تحت عنوان «دلالة عطف قوله تعالى: ﴿رب آبائكم الأولين﴾ على ﴿ربكم﴾»","url":""}]},{"id":"s44-15","number":15,"surah":44,"verses":[8],"references":[{"surah":44,"verses":[8]}],"verseLabel":"الدخان: 8","question":"ما دلالة الاستدلال بقوله ﴿يُحْيِي وَيُمِيتُ﴾ على توحيد الألوهية؟","answer":"الإحياء والإماتة من أعظم دلائل القدرة، وهما مما لا تملكه الأصنام. فإذا أقر المخاطبون بأن خالق السماوات والأرض هو الذي يحيي ويميت لزمهم إفراده بالعبادة، وثبت إمكان إعادة الخلق بعد الموت.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص406–407، تحت عنوان «مناسبة التعبير بالإحياء والإماتة في سياق الاستدلال على التوحيد»","url":""}]},{"id":"s44-16","number":16,"surah":44,"verses":[1,2,3,4,5,6,7,8],"references":[{"surah":44,"verses":[1,2,3,4,5,6,7,8]}],"verseLabel":"الدخان: 1–8","question":"ما أثر الجمع بين الضدين في قوله ﴿يُحْيِي وَيُمِيتُ﴾؟","answer":"يجمع الطباق طرفي الوجود الإنساني ليشمل ما بينهما؛ فالقادر على بدء الحياة وإنهائها هو المحيط بأحوال الخلق كلها، وتظهر قدرته في صورتين متقابلتين لا يملكهما غيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص405، تحت عنوان «بلاغة الطباق بين ﴿يحيي ويميت﴾»","url":""}]},{"id":"s44-17","number":17,"surah":44,"verses":[9],"references":[{"surah":44,"verses":[9]}],"verseLabel":"الدخان: 9","question":"ما الذي تصوره كلمة ﴿فِي﴾ في قوله ﴿بَلْ هُمْ فِي شَكٍّ﴾؟","answer":"تصور الشك كأنه ظرف أحاط بهم وغمرهم، فلا يرون خارجه طريق اليقين؛ وفيها مبالغة في رسوخ حيرتهم مع قيام الأدلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص418، تحت عنوان «معنى ﴿في﴾»","url":""}]},{"id":"s44-88","number":88,"surah":44,"verses":[9],"references":[{"surah":44,"verses":[9]}],"verseLabel":"الدخان: 9","question":"لماذا وُصف الشاكون بأنهم ﴿يَلْعَبُونَ﴾ بصيغة المضارع؟","answer":"لأنهم تعاملوا مع دلائل الحق بلا جد، كمن يلهو عما ينفعه، وصيغة المضارع تصور لعبهم متجددًا مستمرًا كلما جاءهم بيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص418–419، تحت عنوان «نكتة التعبير بالفعل ﴿يلعبون﴾، ودلالة مجيئه مضارعًا»","url":""}]},{"id":"s44-18","number":18,"surah":44,"verses":[10],"references":[{"surah":44,"verses":[10]}],"verseLabel":"الدخان: 10","question":"لماذا قيل ﴿فَارْتَقِبْ﴾ بدل «انتظر» في مقام التهديد؟","answer":"لأن الارتقاب انتظار مشوب بالحذر والتطلع إلى أمر وشيك؛ فالكلمة تجعل العذاب كأنه يُترقب ظهوره، وتثبت الرسول على انتظار تحقق الوعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص421–422، تحت عنوان «نكتة التعبير بلفظ الارتقاب»","url":""}]},{"id":"s44-19","number":19,"surah":44,"verses":[10],"references":[{"surah":44,"verses":[10]}],"verseLabel":"الدخان: 10","question":"ما دلالة تنكير ﴿دُخَانٍ﴾ ووصفه بـ﴿مُبِينٍ﴾؟","answer":"تنكير الدخان يعظم شأنه ويهول أمره، و﴿مبين﴾ تصفه بالظهور والوضوح، فلا يخفى أثره. وتذكر الموسوعة أيضًا إيحاء الوصف بكشفه حال المدخنين وما كانوا عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص424–425، تحت عنوان «نكتة تنكير (دخان) ودلالة وصفه بـ(مبين)»","url":""}]},{"id":"s44-20","number":20,"surah":44,"verses":[10,11],"references":[{"surah":44,"verses":[10,11]}],"verseLabel":"الدخان: 10–11","question":"كيف يُفهم قوله عن الدخان ﴿يَغْشَى النَّاسَ﴾؟","answer":"يحتمل أن يكون غشيانًا حقيقيًا يحيط بالناس ويحجب عنهم الرؤية، ويحتمل على توجيه المجاز أن يصور شدة الجوع أو العذاب كالدخان المحيط؛ وفي الحالين تبرز صورة الكرب الشامل.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص427، تحت عنوان «توجيه قوله تعالى: ﴿يغشى الناس﴾ بين الحقيقة والمجاز»","url":""}]},{"id":"s44-89","number":89,"surah":44,"verses":[10,11],"references":[{"surah":44,"verses":[10,11]}],"verseLabel":"الدخان: 10–11","question":"ماذا تضيف صيغة المضارع في ﴿يَغْشَى النَّاسَ﴾؟","answer":"تستحضر صورة الدخان وهو يتجدد في الإحاطة بهم، حتى يبدو المشهد واقعًا أمام السامع لا خبرًا منقطعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص428، تحت عنوان «دلالة التعبير بالمضارع ﴿يغشى﴾»","url":""}]},{"id":"s44-21","number":21,"surah":44,"verses":[11],"references":[{"surah":44,"verses":[11]}],"verseLabel":"الدخان: 11","question":"ما دلالة حذف فعل القول قبل ﴿هَذَا عَذَابٌ أَلِيمٌ﴾؟","answer":"على وجه حكاية قول المعذبين يقدر: يقولون ﴿هذا عذاب أليم﴾، وحذف القول يبرز شدة إصابتهم ومبادرتهم إلى وصف ما أصابهم. وتذكر الموسوعة وجوهًا أخرى في تعيين القائل، فلا يجزم بأن هذا الوجه هو الوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص429–430، تحت عنوان «تعيين القائل: ﴿هذا عذاب أليم﴾»","url":""}]},{"id":"s44-22","number":22,"surah":44,"verses":[12],"references":[{"surah":44,"verses":[12]}],"verseLabel":"الدخان: 12","question":"لماذا جاء دعاؤهم ﴿رَبَّنَا اكْشِفْ عَنَّا الْعَذَابَ﴾ من غير فعل قول ولا أداة نداء؟","answer":"لإيجاز المشهد واستحضار صرختهم فورًا؛ فحُذف ما يمكن فهمه لتبرز كلمات الاستغاثة نفسها، وكأن شدة العذاب لم تدع لهم مجالًا لتمهيد الكلام.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص431–432، تحت عنوان «بلاغة الإيجاز بحذف فعل القول، وأداة النداء»","url":""}]},{"id":"s44-90","number":90,"surah":44,"verses":[12],"references":[{"surah":44,"verses":[12]}],"verseLabel":"الدخان: 12","question":"لماذا فصلوا وعدهم ﴿إِنَّا مُؤْمِنُونَ﴾ عن طلب كشف العذاب؟","answer":"ليجعلوه تعليلًا لطلبهم ووعدًا مستقلًا: اكشفه عنا لأننا سنؤمن؛ وفصل الجملة يبرز هذا الادعاء الذي سيكشف السياق عدم صدقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص433، تحت عنوان «علة فصل قوله تعالى: ﴿إنا مؤمنون﴾»","url":""}]},{"id":"s44-23","number":23,"surah":44,"verses":[9,10,11,12],"references":[{"surah":44,"verses":[9,10,11,12]}],"verseLabel":"الدخان: 9–12","question":"لماذا انتقل المشهد فجأة من وصفهم في الشك واللعب إلى صرختهم ﴿رَبَّنَا اكْشِفْ عَنَّا الْعَذَابَ﴾؟","answer":"ليصور انقلاب اللهو إلى ضراعة حين صار الوعيد محسوسًا؛ ففُصل الدعاء عما قبله لأنه حكاية حال جديدة كشفت أن الشدة أسقطت تظاهرهم، وإن لم تغيّر عنادهم تغييرًا دائمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص431، تحت عنوان «علة فصل قوله تعالى: ﴿ربنا اكشف عنا العذاب﴾»","url":""}]},{"id":"s44-24","number":24,"surah":44,"verses":[13],"references":[{"surah":44,"verses":[13]}],"verseLabel":"الدخان: 13","question":"ما دلالة الاستفهام في ﴿أَنَّى لَهُمُ الذِّكْرَى﴾؟","answer":"هو استفهام إنكاري يستبعد انتفاعهم بالتذكر بعد أن أعرضوا عن الرسول المبين؛ فكيف يَعِدون بالإيمان عند العذاب وقد جاءتهم قبل ذلك أقوى أسباب التذكر فلم ينتفعوا بها؟","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص441، تحت عنوان «الغرض من الاستفهام، ودلالة تصديره بـ﴿أنى﴾»","url":""}]},{"id":"s44-25","number":25,"surah":44,"verses":[2,13],"references":[{"surah":44,"verses":[2,13]}],"verseLabel":"الدخان: 2، 13","question":"ماذا يضيف تنكير ﴿رَسُولٌ﴾ ووصفه بأنه ﴿مُبِينٌ﴾؟","answer":"يفخم التنكير شأن الرسول الذي جاءهم، ثم يبين الوصف أن رسالته ظاهرة وأنه موضح لما أرسل به؛ فاجتمع تعظيم المبلغ ووضوح حجته، وتعاظم اللوم على الإعراض عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص443–444، تحت عنوان «نكتة تنكير ﴿رسول﴾ ودلالة وصفه بـ﴿مبين﴾»","url":""}]},{"id":"s44-26","number":26,"surah":44,"verses":[14],"references":[{"surah":44,"verses":[14]}],"verseLabel":"الدخان: 14","question":"ما دلالة جمعهم بين تهمتي ﴿مُعَلَّمٌ﴾ و﴿مَجْنُونٌ﴾ مع تناقضهما؟","answer":"التهمتان متناقضتان إذا حملتا على وصف واحد متسق؛ فالمتعلم يتلقى ويضبط، والمجنون لا يضبط. وتوجه الموسوعة الجمع بأن طائفة قالت هذا وأخرى قالت ذاك، أو قالوه في أوقات مختلفة؛ وهو اضطراب في البهتان غايته الطعن في الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص446، تحت عنوان «توجيه الجمع بين الصفتين: ﴿معلم﴾، و﴿مجنون﴾»","url":""}]},{"id":"s44-27","number":27,"surah":44,"verses":[12,13,14,15],"references":[{"surah":44,"verses":[12,13,14,15]}],"verseLabel":"الدخان: 12–15","question":"لماذا أكّدوا وعدهم بقولهم ﴿إِنَّا مُؤْمِنُونَ﴾؟","answer":"ليظهروا أن إيمانهم بعد كشف العذاب أمر محقق لا تردد فيه، فجمعوا المؤكدات استعطافًا ورغبة في النجاة؛ لكن السياق يفضح أنه تأكيد باللسان لا يثبت عند زوال الشدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص433، تحت عنوان «دلالة توالي المؤكدات في: ﴿إنا مؤمنون﴾»","url":""}]},{"id":"s44-91","number":91,"surah":44,"verses":[12,13,14,15],"references":[{"surah":44,"verses":[12,13,14,15]}],"verseLabel":"الدخان: 12–15","question":"لماذا جاء الرد مؤكدًا ﴿إِنَّكُمْ عَائِدُونَ﴾؟","answer":"لمواجهة وعدهم المؤكد بحقيقة يعلمها الله: أنهم سيعودون إلى الكفر إذا كُشف العذاب؛ فقوبل توكيد الدعوى بتوكيد يكشف بطلانها.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص449، تحت عنوان «دلالة توالي المؤكدات في فاصلة الآية»","url":""}]},{"id":"s44-28","number":28,"surah":44,"verses":[15,16],"references":[{"surah":44,"verses":[15,16]}],"verseLabel":"الدخان: 15–16","question":"لماذا قُيّد كشف العذاب بقوله ﴿قَلِيلًا﴾؟","answer":"للدلالة على أن الكشف مؤقت ومحدود، امتحانًا يكشف حقيقتهم لا نجاة نهائية؛ فما إن تزول الشدة قليلًا حتى يعودوا إلى ما كانوا عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص448، تحت عنوان «دلالة التعبير بلفظ القلة»","url":""}]},{"id":"s44-92","number":92,"surah":44,"verses":[15,16],"references":[{"surah":44,"verses":[15,16]}],"verseLabel":"الدخان: 15–16","question":"لماذا سُمّيت الأخذة الآتية ﴿الْبَطْشَةَ الْكُبْرَى﴾؟","answer":"عُرّفت لأنها البطشة المعهودة في الوعيد، ووُصفت بالكبرى لعظمها وشمولها وقوة أخذها؛ فتقابل الكشف القليل بعقوبة لا مجال بعدها للمهلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص451، تحت عنوان «سر تعريف ﴿البطشة﴾ ودلالة وصفها بـ﴿الكبرى﴾»","url":""}]},{"id":"s44-29","number":29,"surah":44,"verses":[17],"references":[{"surah":44,"verses":[17]}],"verseLabel":"الدخان: 17","question":"كيف يحوّل ذكر ابتلاء قوم فرعون قصةً قديمة إلى إنذار لمكذبي مكة؟","answer":"جاء ذكرهم بعد مكذبي مكة ليبين أن التكذيب بالرسول سنة قديمة لها عاقبة معلومة؛ ففي القصة تهديد للمشركين وتسلية للنبي ﷺ بأن ما يلقاه قد لقيه الرسل قبله.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص455، تحت عنوان «مناسبة الآيتين لما قبلهما»","url":""}]},{"id":"s44-93","number":93,"surah":44,"verses":[17],"references":[{"surah":44,"verses":[17]}],"verseLabel":"الدخان: 17","question":"لماذا سُمّي إرسال موسى إلى قوم فرعون ﴿فِتْنَةً﴾؟","answer":"لأنه اختبار يكشف ما استقر في النفوس عند قيام الحجة؛ فظهر بإرسال موسى إيمان من استجاب، وإجرام من استكبر وكذب.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص458، تحت عنوان «بلاغة تسمية الاختبار فتنة»","url":""}]},{"id":"s44-31","number":31,"surah":44,"verses":[17,18],"references":[{"surah":44,"verses":[17,18]}],"verseLabel":"الدخان: 17–18","question":"ما سر وصف موسى أولًا بـ﴿كَرِيمٌ﴾ ثم وصفه في خطابه بـ﴿رَسُولٌ أَمِينٌ﴾؟","answer":"﴿كريم﴾ ثناء على منزلته وخصاله في حكاية مجيئه، و﴿أمين﴾ وصف يذكره موسى في مقام تبليغ الرسالة وإثبات أنه مأمون على ما أرسله الله به. فالأول تنويه بقدر الرسول، والثاني تأكيد صدقه وأمانة بلاغه.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص460–461، تحت عنوان «سر المغايرة في وصف الرسول بين ﴿كريم﴾ و﴿أمين﴾»","url":""}]},{"id":"s44-32","number":32,"surah":44,"verses":[19],"references":[{"surah":44,"verses":[19]}],"verseLabel":"الدخان: 19","question":"ما المراد بنهي فرعون وقومه عن أن يعلوا على الله؟","answer":"المراد ألا يتكبروا على أمر الله ورسوله ولا يرفضوا الانقياد للحق؛ فحذف المضاف يوجز العبارة ويجعل استكبارهم على الأمر كأنه استكبار على الله نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص474، تحت عنوان «بلاغة الإيجاز بحذف المضاف»","url":""}]},{"id":"s44-94","number":94,"surah":44,"verses":[19],"references":[{"surah":44,"verses":[19]}],"verseLabel":"الدخان: 19","question":"ماذا يضيف وصف حجة موسى بأنها ﴿سُلْطَانٌ مُبِينٌ﴾؟","answer":"التنكير يفخم قوة الحجة، ووصفها بالمبين يقرر وضوحها وكشفها للحق؛ فلا يبقى بعد البرهان الظاهر عذر للتعالي أو التكذيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص477–478، تحت عنوان «نكتة تنكير (سلطان) ودلالة وصفه بـ(مبين)»","url":""}]},{"id":"s44-33","number":33,"surah":44,"verses":[20],"references":[{"surah":44,"verses":[20]}],"verseLabel":"الدخان: 20","question":"ما سر الجمع بين ﴿رَبِّي وَرَبِّكُمْ﴾ في استعاذة موسى من أن يرجموه؟","answer":"إضافة الرب إلى موسى تستحضر رعايته له وحفظه، ثم ﴿وربكم﴾ تلزم المخاطبين بالإقرار بأنهم خاضعون للرب نفسه. وفي ذلك تهديد لهم؛ فمن اعتصم بربهم لا تخرجه قدرتهم من حمايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص481، تحت عنوان «نكتة عطف ﴿وربكم﴾ على ﴿ربي﴾»","url":""}]},{"id":"s44-34","number":34,"surah":44,"verses":[19,20],"references":[{"surah":44,"verses":[19,20]}],"verseLabel":"الدخان: 19–20","question":"ماذا يوحي قول موسى ﴿عُذْتُ بِرَبِّي وَرَبِّكُمْ﴾ بصيغة الماضي قبل وقوع الرجم؟","answer":"يصور التجاءه إلى الله أمرًا محققًا ثابتًا قد بادر إليه، فيعلن ثقته بالحماية الإلهية قبل أن يباشروا تهديدهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص479–480، تحت عنوان «دلالة التعبير بالمسند الفعلي ومجيئه ماضيًا»","url":""}]},{"id":"s44-35","number":35,"surah":44,"verses":[21],"references":[{"surah":44,"verses":[21]}],"verseLabel":"الدخان: 21","question":"ماذا يكشف الشرط ﴿وَإِنْ لَمْ تُؤْمِنُوا لِي فَاعْتَزِلُونِ﴾ عن مقصد موسى؟","answer":"يكشف أن غايته الأولى إيمانهم بالرسالة؛ فإن أبوا فالمطلوب الأدنى أن يكفوا أذاهم ويتركوه يبلغ عن ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص483–484، تحت عنوان «نكتة بناء الآية على أسلوب الشرط»","url":""}]},{"id":"s44-95","number":95,"surah":44,"verses":[21],"references":[{"surah":44,"verses":[21]}],"verseLabel":"الدخان: 21","question":"لماذا قال موسى لقوم فرعون ﴿فَاعْتَزِلُونِ﴾؟","answer":"أمرهم أن يتركوه وشأنه وألا يتعرضوا له بالأذى؛ فهو لم يطلب بعد رفضهم إلا أن يخلوا بينه وبين دعوته.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص485، تحت عنوان «الغرض من الأمر بقوله: ﴿فاعتزلون﴾»","url":""}]},{"id":"s44-36","number":36,"surah":44,"verses":[18,19,20,21],"references":[{"surah":44,"verses":[18,19,20,21]}],"verseLabel":"الدخان: 18–21","question":"ما دلالة تدرج خطاب موسى من طلب أداء عباد الله إلى النهي عن العلو ثم الاستعاذة فالاعتزال؟","answer":"افتتح موسى طلبه بأداء عباد الله وأثبت أمانته، ثم نهى عن العلو وأظهر السلطان المبين. وبعد ذلك قرر استعاذته بربه من رجمهم، وختم بطلب المتاركة إن لم يؤمنوا؛ فجمع التبليغ والحجة والثقة بالله وقطع المعاذير.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص485–486، تحت عنوان «بلاغة ترتيب الفواصل على ما جاءت عليه في الآيات»","url":""}]},{"id":"s44-37","number":37,"surah":44,"verses":[21,22],"references":[{"surah":44,"verses":[21,22]}],"verseLabel":"الدخان: 21–22","question":"ماذا تفيد الفاء في انتقال موسى إلى دعاء ربه بعد قوله ﴿فَاعْتَزِلُونِ﴾؟","answer":"تفيد أن الدعاء جاء عقب إصرارهم على التكذيب والأذى؛ فلما استنفد الدعوة ولم يستجيبوا فوّض أمرهم إلى ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص492–493، تحت عنوان «دلالة الفاء في ﴿فدعا ربه أن هؤلاء قوم مجرمون﴾»","url":""}]},{"id":"s44-96","number":96,"surah":44,"verses":[21,22],"references":[{"surah":44,"verses":[21,22]}],"verseLabel":"الدخان: 21–22","question":"لماذا قال موسى ﴿هَؤُلَاءِ قَوْمٌ مُجْرِمُونَ﴾ ولم يقل «هؤلاء مجرمون»؟","answer":"لأن وصفهم بالقوم يصور اجتماعهم على الإجرام ورسوخه في جماعتهم، لا صدوره من أفراد متفرقين أو في موقف عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص494، تحت عنوان «سر التعبير بقوله ﴿قوم مجرمون﴾ دون (هؤلاء مجرمون)»","url":""}]},{"id":"s44-97","number":97,"surah":44,"verses":[21,22],"references":[{"surah":44,"verses":[21,22]}],"verseLabel":"الدخان: 21–22","question":"ماذا يوحي حذف الطلب من دعاء موسى: ﴿أَنَّ هَؤُلَاءِ قَوْمٌ مُجْرِمُونَ﴾؟","answer":"يوحي بأنه اكتفى بعرض حالهم على ربه ثقةً بعلمه وحكمه، وأن وصف إجرامهم يغني عن التصريح بطلب العقوبة ويجعل التفويض أبلغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص495، تحت عنوان «بلاغة الإيجاز بحذف المدعو به»","url":""}]},{"id":"s44-38","number":38,"surah":44,"verses":[23],"references":[{"surah":26,"verses":[52]},{"surah":44,"verses":[23]}],"verseLabel":"الدخان: 23؛ الشعراء: 52","question":"كيف خدم تنكير ﴿لَيْلًا﴾ خطة نجاة موسى وقومه من فرعون؟","answer":"أفاد التنكير أن الرحيل وقع في جزء من الليل لا في الليل كله؛ ليغادروا في غفلة فرعون وجنده، فيبتعد المؤمنون قبل أن يشعروا بهم ويتبعوهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص497–498، تحت عنوان «نكتة تنكير ﴿ليلًا﴾»","url":""}]},{"id":"s44-39","number":39,"surah":44,"verses":[24],"references":[{"surah":44,"verses":[24]}],"verseLabel":"الدخان: 24","question":"لماذا أُمر موسى أن يترك البحر مفتوحًا بعد عبوره؟","answer":"ليدخل فرعون وجنده الطريق نفسه مطمئنين إلى إمكان العبور، ثم يطبق عليهم البحر؛ فتركه على حاله جزء من تدبير هلاكهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص499–500، تحت عنوان «علة وصل قوله تعالى: ﴿واترك البحر رهوًا﴾»","url":""}]},{"id":"s44-98","number":98,"surah":44,"verses":[24],"references":[{"surah":44,"verses":[24]}],"verseLabel":"الدخان: 24","question":"ما الصورة التي ترسمها كلمة ﴿رَهْوًا﴾ للبحر بعد عبور بني إسرائيل؟","answer":"تصوره ساكنًا منفرجًا واسع الطريق، كأن الماء ثبت على جانبيه؛ وهي صورة تغري المطاردين بالدخول قبل أن يعود البحر عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص501–502، تحت عنوان «دلالة التعبير بقوله: ﴿رهوًا﴾ مادة وصيغة»","url":""}]},{"id":"s44-99","number":99,"surah":44,"verses":[24],"references":[{"surah":44,"verses":[24]}],"verseLabel":"الدخان: 24","question":"لماذا جاء الوعد ﴿إِنَّهُمْ جُنْدٌ مُغْرَقُونَ﴾ جملةً مستقلة بعد أمر ترك البحر؟","answer":"ليعلل الأمر ويطمئن موسى إلى أن إبقاء الطريق ليس خطرًا على المؤمنين، بل مقدمة لحكم إلهي محقق بإغراق الجند.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص502، تحت عنوان «علة فصل قوله تعالى: ﴿إنهم جند مغرقون﴾»","url":""}]},{"id":"s44-40","number":40,"surah":44,"verses":[23,24],"references":[{"surah":44,"verses":[23,24]}],"verseLabel":"الدخان: 23–24","question":"لماذا وُصف فرعون وقومه بأنهم ﴿جُنْدٌ مُغْرَقُونَ﴾؟","answer":"يستحضر لفظ الجند قوتهم وعدتهم، ثم يهدم الاغترار بها بوصفهم بالإغراق؛ فكثرتهم وتنظيمهم لا يدفعان قضاء الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص502، تحت عنوان «دلالة ذكر كلمة ﴿جند﴾ وتنكيرها»","url":""}]},{"id":"s44-41","number":41,"surah":44,"verses":[25,26,27],"references":[{"surah":44,"verses":[25,26,27]}],"verseLabel":"الدخان: 25–27","question":"لماذا فُصّلت متروكات قوم فرعون إلى جنات وعيون وزروع ومقام كريم؟","answer":"لإحاطة صور النعمة التي فارقوها: موارد الماء، وأسباب القوت، ومواضع الإقامة والترف؛ فيظهر أن كثرة الممتلكات لم تمنع الهلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص510، تحت عنوان «نكتة عطف الزروع والمقام الكريم كل على سابقه»","url":""}]},{"id":"s44-100","number":100,"surah":44,"verses":[25,26,27],"references":[{"surah":44,"verses":[25,26,27]}],"verseLabel":"الدخان: 25–27","question":"ماذا تضيف كلمة ﴿نَعْمَةٍ﴾ بعد تعداد الجنات والعيون والزروع؟","answer":"تجمع ما سبق تحت معنى التنعم، وتشمل ما لم يُذكر من أسباب الرفاه؛ فتنتقل الآية من الصور المفصلة إلى حقيقة العيش الرغيد كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص512، تحت عنوان «دلالة عطف قوله تعالى: ﴿ونعمة كانوا فيها فاكهين﴾ على سابقه»","url":""}]},{"id":"s44-42","number":42,"surah":44,"verses":[28],"references":[{"surah":44,"verses":[28]}],"verseLabel":"الدخان: 28","question":"لماذا صُوّر انتقال ملك قوم فرعون إلى غيرهم بأنه ﴿إِيرَاثٌ﴾؟","answer":"لأنه انتقل إلى خلفائهم بسهولة بعد زوالهم، كالميراث الذي يملكه الوارث من غير منازعة المالك السابق؛ فتبرز الصورة سرعة تبدل السلطان.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص518، تحت عنوان «دلالة التعبير بالإيراث مادة وصيغة»","url":""}]},{"id":"s44-101","number":101,"surah":44,"verses":[28],"references":[{"surah":44,"verses":[28]}],"verseLabel":"الدخان: 28","question":"ماذا يوحي وصف وارثي ملك فرعون بأنهم ﴿قَوْمًا آخَرِينَ﴾؟","answer":"يجردهم من التعيين ليجعل العبرة في تداول الملك نفسه: زال قوم وجاء آخرون، فلا تدوم النعمة لجماعة تكفر بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص519، تحت عنوان «نكتة تنكير ﴿قومًا﴾ ودلالة وصفه بـ﴿آخرين﴾»","url":""}]},{"id":"s44-43","number":43,"surah":44,"verses":[29],"references":[{"surah":44,"verses":[29]}],"verseLabel":"الدخان: 29","question":"ما الصورة في قوله عن قوم فرعون ﴿فَمَا بَكَتْ عَلَيْهِمُ السَّمَاءُ وَالْأَرْضُ﴾؟","answer":"شُخصت السماء والأرض كأنهما ممن يبكي، ثم نُفي بكاؤهما تهوينًا لشأن الهالكين وبيانًا أن زوالهم لم يكن خسارة للكون؛ وتحتمل العبارة أيضًا نفي بكاء أهلهما عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص521–522، تحت عنوان «بلاغة الاستعارة في قوله تعالى: ﴿فما بكت عليهم السماء والأرض﴾»","url":""}]},{"id":"s44-44","number":44,"surah":44,"verses":[29],"references":[{"surah":44,"verses":[29]}],"verseLabel":"الدخان: 29","question":"ماذا يضيف قوله ﴿وَمَا كَانُوا مُنْظَرِينَ﴾ بعد نفي بكاء السماء والأرض عليهم؟","answer":"يضيف أن سقوط منزلتهم اقترن بعدم إمهالهم؛ فلا أسف عليهم ولا تأخير للعقوبة حين جاء وقتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص523، تحت عنوان «دلالة عطف قوله: ﴿وما كانوا منظرين﴾ على سابقه»","url":""}]},{"id":"s44-45","number":45,"surah":44,"verses":[29,30],"references":[{"surah":44,"verses":[29,30]}],"verseLabel":"الدخان: 29–30","question":"كيف يقابل إنجاء بني إسرائيل ما سبق من هلاك فرعون وقومه؟","answer":"يجمع السياق طرفي الحكم الإلهي: زوال الطاغية بلا إمهال، وخلاص المستضعفين من عذابه؛ فتكتمل صورة العدل بالنكاية من المعتدي والإنعام على المؤمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص527، تحت عنوان «مناسبة الآيات لما قبلها»","url":""}]},{"id":"s44-102","number":102,"surah":44,"verses":[29,30],"references":[{"surah":44,"verses":[29,30]}],"verseLabel":"الدخان: 29–30","question":"لماذا صُدِّر خبر إنجاء بني إسرائيل بالقسم؟","answer":"لتوكيد وقوع النجاة وتعظيمها بعد شدة الاستضعاف، وتثبيت أن وعد الله لأوليائه منجز لا يتخلف.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص529، تحت عنوان «نكتة تصدير الآية بالقسم»","url":""}]},{"id":"s44-46","number":46,"surah":44,"verses":[30,31],"references":[{"surah":44,"verses":[30,31]}],"verseLabel":"الدخان: 30–31","question":"كيف يجعل قوله ﴿مِنْ فِرْعَوْنَ﴾ فرعون نفسه صورةً للعذاب المهين؟","answer":"جاء فرعون بدلًا من العذاب أو بيانًا لمصدره، فكأنه لشدة طغيانه صار هو العذاب الذي نُجوا منه؛ وفي ذلك مبالغة في تقبيح فعله.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص532، تحت عنوان «علة فصل قوله تعالى: ﴿من فرعون﴾ عن سابقه»","url":""}]},{"id":"s44-103","number":103,"surah":44,"verses":[30,31],"references":[{"surah":44,"verses":[30,31]}],"verseLabel":"الدخان: 30–31","question":"لماذا عُللت نجاة بني إسرائيل بوصف فرعون بأنه ﴿عَالِيًا مِنَ الْمُسْرِفِينَ﴾؟","answer":"لبيان أن عذابه لم يكن حادثًا عارضًا، بل ثمرة استعلاء متأصل وتجاوز للحد؛ ولذلك استحق أن ينقذ الله عباده منه ويهلكه.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص532، تحت عنوان «علة فصل قوله تعالى: ﴿إنه كان عاليًا من المسرفين﴾ عن سابقه»","url":""}]},{"id":"s44-47","number":47,"surah":44,"verses":[30,31,32,33],"references":[{"surah":44,"verses":[30,31,32,33]}],"verseLabel":"الدخان: 30–33","question":"لماذا أُتبع اختيار بني إسرائيل بقوله ﴿وَآتَيْنَاهُمْ مِنَ الْآيَاتِ﴾؟","answer":"ليتدرج تعداد النعم من النجاة إلى الاصطفاء ثم تزويدهم بالبراهين والخوارق، فيظهر تمام الإكرام وقيام الحجة عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج54، ص538، تحت عنوان «نكتة عطف قوله تعالى: ﴿وآتيناهم من الآيات﴾»","url":""}]}]);
